window.POOL_DATA={"L": {"1": "Durée du travail, nuit, repos", "2": "Régimes hebdomadaires et cycliques", "3": "Services supplémentaires", "4": "Congés annuels, ARTT, crédit férié, RPS", "5": "Congés familiaux et ASA", "6": "CET, temps partiel, maladie", "7": "Arme individuelle", "8": "Armes d’épaule, sécurité, TSUA", "9": "LBD, GMD, lanceurs, GM2L", "10": "PIE et GAIL", "11": "Maintien de l’ordre", "12": "Interpellation, palpation, menottage", "13": "Pratiques pro en intervention", "14": "Formation TSI et sport", "15": "Sigles"}, "q": [{"t": 1, "s": "Selon l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale), le temps de travail se définit comme le temps pendant lequel les agents :", "o": ["sont à la disposition de leur employeur et doivent se conformer à ses directives sans pouvoir vaquer librement à des occupations personnelles", "sont présents physiquement dans les locaux du service", "effectuent une mission sur la voie publique", "sont inscrits sur un tableau de service, qu'ils soient ou non joignables"], "a": "A", "e": "Définition de la fiche 2 : disposition de l'employeur, directives, impossibilité de vaquer librement à ses occupations. — Source : Fiche APORTT n°2 – Le temps de travail"}, {"t": 1, "s": "Le suivi du temps de travail de chaque agent fait l'objet d'un entretien avec le responsable hiérarchique désigné :", "o": ["au moins deux fois par an", "uniquement à la demande de l'agent", "au moins une fois par an", "à chaque fin de trimestre civil"], "a": "C", "e": "Entretien au moins une fois par an ; le temps est comptabilisé dans GesTT. — Source : Fiche APORTT n°2 – Le temps de travail"}, {"t": 1, "s": "Quelles affirmations sur les régimes de travail en police nationale sont exactes ?", "o": ["Le régime cyclique fonctionne par équipes successives de jour et de nuit, dimanches et jours fériés compris", "Le régime hebdomadaire est calqué sur la semaine civile", "Un chef de service peut créer un régime local non prévu par l'APORTT s'il est validé en comité technique", "La DCCRS utilise un régime mixte hebdomadaire/cyclique"], "a": "ABD", "e": "Les régimes sont limitativement définis par l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) : aucun autre régime n'est admis. — Source : Fiche APORTT n°2 – Le temps de travail"}, {"t": 1, "s": "La durée annuelle de travail effectif, quel que soit le régime, est fixée à :", "o": ["1 645 heures", "1 620 heures", "1 507 heures", "1 607 heures"], "a": "D", "e": "1 607 h, appréciées après déduction des repos, CA, jours fériés et ARTT (aménagement et réduction du temps de travail) ; réduite dans certains départements (Alsace-Moselle, outre-mer). — Source : Fiche APORTT n°3 – La durée du travail"}, {"t": 1, "s": "La moyenne hebdomadaire de 48 heures, services supplémentaires compris, est calculée :", "o": ["sur le semestre révolu, en excluant les congés annuels et les congés maladie de toute nature", "sur le semestre civil, en excluant les seuls congés annuels", "sur l'année civile, en excluant les congés maladie", "sur le trimestre civil, congés compris"], "a": "A", "e": "48 h maximum en moyenne par période de 7 jours, sur le semestre révolu, hors CA et congés maladie de toute nature. — Source : Fiche APORTT n°3 – La durée du travail"}, {"t": 1, "s": "La durée moyenne journalière (DMJ) correspond :", "o": ["en régime cyclique, à la durée de la vacation", "en régime hebdomadaire, à 1/5e de la durée légale hebdomadaire", "en régime cyclique, à 1/5e de la durée hebdomadaire du cycle", "en régime hebdomadaire, à la durée de la plus longue journée de la semaine"], "a": "AB", "e": "Hebdomadaire : 1/5e de la durée hebdomadaire ; cyclique : durée de la vacation. — Source : Fiche APORTT n°3 – La durée du travail"}, {"t": 1, "s": "La durée du travail de nuit ne doit pas dépasser :", "o": ["10 heures en moyenne par 24 heures, sur trois mois civils", "8 heures en moyenne par 24 heures, calculée sur une période de trois mois civils", "8 heures en moyenne par 24 heures, calculée sur le semestre révolu", "12 heures par nuit travaillée, sans moyenne"], "a": "B", "e": "8 h en moyenne par 24 h sur le trimestre civil, suivie par le chef de service. — Source : Fiche APORTT n°4 – Le travail de nuit"}, {"t": 1, "s": "La moyenne de travail de nuit d'un agent dépasse 8 heures sur le trimestre civil. Le chef de service :", "o": ["lui impose de prendre des congés", "saisit le comité médical", "lui attribue des RPS supplémentaires", "le place d'office en régime hebdomadaire"], "a": "A", "e": "En cas de moyenne supérieure à 8 h, le chef de service impose à l'agent de prendre des congés. — Source : Fiche APORTT n°4 – Le travail de nuit"}, {"t": 1, "s": "Concernant le travail de nuit, quelles affirmations sont exactes ?", "o": ["Le travailleur de nuit est défini en incluant les services supplémentaires", "En régime cyclique, le RPS de nuit le dimanche est de 0,1", "Les PATS et autres contractuels doivent être volontaires pour travailler de nuit en cycle", "Les ADS peuvent être employés de jour comme de nuit"], "a": "CD", "e": "Le travailleur de nuit se définit hors services supplémentaires ; coefficients RPS (repos de pénibilité spécifique) cyclique : 0,1 la nuit en semaine, 0,4 le dimanche. — Source : Fiche APORTT n°4 – Le travail de nuit"}, {"t": 1, "s": "Le repos journalier minimal est de :", "o": ["10 heures consécutives", "12 heures consécutives", "11 heures consécutives, qui succèdent directement à une période de travail", "11 heures, fractionnables en deux périodes"], "a": "C", "e": "11 h consécutives au cours de chaque période de 24 h. — Source : Fiche APORTT n°5 – Les repos"}, {"t": 1, "s": "Le début de la période de 24 heures servant au calcul du repos journalier est fixé :", "o": ["à minuit", "à la prise de service effective de la vacation ou de la journée de travail", "à la fin de la vacation précédente", "à 6 heures, fin de la période nocturne"], "a": "B", "e": "Quel que soit le régime, le point de départ est la prise de service effective. — Source : Fiche APORTT n°5 – Les repos"}, {"t": 1, "s": "La période de référence de 7 jours pour le repos hebdomadaire démarre :", "o": ["en régime cyclique, à la prise de service de la première vacation travaillée du début de cycle", "en régime hebdomadaire, à la prise de service du premier jour de travail de la semaine civile", "dans tous les régimes, le lundi à 0 h", "en régime cyclique, au premier repos du cycle"], "a": "AB", "e": "Hebdomadaire : premier jour de travail de la semaine civile ; cyclique : première vacation du cycle. — Source : Fiche APORTT n°5 – Les repos"}, {"t": 1, "s": "Un agent en régime cyclique enchaîne 6 heures de travail quotidien. Quelles affirmations sont exactes ?", "o": ["Ce temps de pause est un temps de repos décompté de sa vacation", "Le temps de pause minimal est de 45 minutes", "Ce temps de pause est considéré comme du temps de travail", "Il bénéficie d'un temps de pause d'au moins 20 minutes"], "a": "CD", "e": "Aucun temps de travail quotidien ne peut atteindre 6 h sans pause de 20 min minimum, considérée comme du temps de travail (agent à disposition). — Source : Fiche APORTT n°5 – Les repos"}, {"t": 1, "s": "En régime hebdomadaire classique, l'interruption de service :", "o": ["est obligatoirement d'une heure, prise à 12 h", "est un temps de repos de 30 minutes à 1 h 30, entre 12 h et 14 h", "est un temps de travail de 20 minutes", "est un temps de repos de 45 minutes à 2 heures, située entre 11 h 30 et 14 h 30"], "a": "D", "e": "À l'inverse de la pause, l'interruption de service est un temps de repos (45 min à 2 h, entre 11 h 30 et 14 h 30). — Source : Fiche APORTT n°5 – Les repos ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 1, "s": "L'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) permet de déroger notamment :", "o": ["au repos hebdomadaire et à la durée hebdomadaire de travail", "à la durée maximale de travail de nuit et aux périodes de référence", "au droit à congé annuel de 5 fois les obligations hebdomadaires", "au repos journalier et au temps de pause"], "a": "ABD", "e": "Les dérogations portent sur les temps de travail et de repos (journalier, pause, hebdomadaire, durée hebdomadaire, nuit, périodes de référence), pas sur les congés annuels. — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Circonstances exceptionnelles ou missions spécifiques : la durée maximale d'engagement à compter du début de la mission est de :", "o": ["12 jours pour les repos journaliers et 21 jours pour les repos hebdomadaires", "10 jours pour les repos journaliers et 14 jours pour les repos hebdomadaires", "21 jours pour les repos journaliers et 12 jours pour les repos hebdomadaires", "14 jours dans les deux cas"], "a": "A", "e": "Neutralisation au plus tard après 12 jours (repos journaliers manqués) et 21 jours (repos hebdomadaires manqués). — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Un agent est en période de neutralisation pour restitution de repos manqués. Il ne peut être rappelé que :", "o": ["avec son accord écrit", "sur décision de son chef de service", "en cas de circonstances exceptionnelles, sur décision du DGPN, du DGSI ou du préfet de police", "sur décision du préfet de département"], "a": "C", "e": "La restitution est un droit ; seules des circonstances exceptionnelles et une décision du DGPN (directeur général de la police nationale), du DGSI (directeur général de la sécurité intérieure) ou du préfet de police permettent un rappel. — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Parmi les situations suivantes, lesquelles relèvent des « missions spécifiques » permettant de déroger ?", "o": ["Les missions de surveillance, de renseignement et d'information", "Les missions judiciaires", "L'accompagnement et la protection des personnalités", "Une catastrophe naturelle"], "a": "ABC", "e": "La catastrophe naturelle relève des circonstances exceptionnelles (événement d'une particulière gravité), pas des missions spécifiques. — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Repos journalier manqué en cadre dérogatoire : si la continuité du service ne permet pas une prise retardée le lendemain :", "o": ["la fin de service peut être anticipée à hauteur du repos manqué", "le repos est versé sur le CET", "l'agent est placé en descente de nuit", "le repos est définitivement perdu et indemnisé"], "a": "A", "e": "Ordre : prise de service retardée, sinon fin anticipée, sinon report sur le repos journalier suivant ; hypothèses cumulables. Coefficient de 0,15 par heure de repos journalier manqué. — Source : Fiche APORTT n°15 – Restitution des repos manqués"}, {"t": 1, "s": "Un repos hebdomadaire manqué, accolé au repos hebdomadaire de la période, est restitué au minimum à hauteur de :", "o": ["35 heures", "59 heures (11 h + 24 h + 24 h)", "70 heures", "48 heures"], "a": "B", "e": "Restitution a minima de 59 h, immédiatement à la fin de la mission, au besoin sur des journées de travail avec des RCSS (repos compensateur pour services supplémentaires). — Source : Fiche APORTT n°15 – Restitution des repos manqués"}, {"t": 1, "s": "Au sens de l'article 10 de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale), la période nocturne couvre l'intervalle compris entre :", "o": ["22 heures et 5 heures", "21 heures et 6 heures", "21 heures et 7 heures", "22 heures et 6 heures"], "a": "B", "e": "La période nocturne couvre l'intervalle 21 h – 6 h (fiche 4). — Source : Fiche APORTT n°4 – Le travail de nuit"}, {"t": 1, "s": "Est « travailleur de nuit », selon son régime de travail habituel et hors services supplémentaires, l'agent qui accomplit :", "o": ["au minimum 300 heures de travail de nuit sur l'année, services supplémentaires compris", "au minimum 2 heures dans la période nocturne, au moins trois fois par semaine", "au minimum 3 heures dans la période nocturne, au moins deux fois par semaine", "au minimum 270 heures de travail de nuit sur une année civile"], "a": "CD", "e": "Deux critères alternatifs : 3 h de nuit au moins deux fois par semaine, ou 270 h de nuit par année civile, toujours hors services supplémentaires. — Source : Fiche APORTT n°4 – Le travail de nuit"}, {"t": 1, "s": "Au cours de chaque période de sept jours, le repos minimal garanti à l'agent est de :", "o": ["48 heures (deux fois 24 heures)", "59 heures (11 heures + 24 heures + 24 heures)", "35 heures (24 heures + 11 heures de repos journalier)", "36 heures (24 heures + 12 heures)"], "a": "C", "e": "Repos hebdomadaire (RL (repos légal) + RC (repos compensateur)) : 35 h minimum garanties. Les 59 h correspondent à la restitution d'un repos hebdomadaire manqué accolé. — Source : Fiche APORTT n°5 – Les repos"}, {"t": 1, "s": "En cadre dérogatoire, quel coefficient multiplicateur est attribué par heure de repos journalier manqué ?", "o": ["0,10, soit 6 minutes pour une heure", "0,40, soit 24 minutes pour une heure", "0,15, soit 9 minutes pour une heure", "0,25, soit 15 minutes pour une heure"], "a": "C", "e": "Coefficient 0,15 par heure de repos journalier manqué, justifié par la pénibilité des services supplémentaires récurrents (9 min pour 1 h). — Source : Fiche APORTT n°15 – Restitution des repos manqués ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 1, "s": "Un agent en régime hebdomadaire travaille habituellement 2 heures dans la période nocturne. Le RPS (repos de pénibilité spécifique) qu'il génère pour ces 2 heures est de :", "o": ["48 minutes", "12 minutes", "6 minutes", "24 minutes"], "a": "B", "e": "Régime hebdomadaire : coefficient 0,1 par heure de travail habituel sur la période nocturne, soit 12 minutes pour deux heures. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 1, "s": "Concernant les repos de pénibilité spécifique (RPS), quelles affirmations sont exactes ?", "o": ["Ils se cumulent avec les compensations des services supplémentaires effectués la nuit", "Ils sont restitués en temps compensés (TC)", "Leurs coefficients multiplicateurs ne sont pas cumulables", "Ils sont exclusifs des services supplémentaires"], "a": "BCD", "e": "Les RPS sont restitués en TC, définis par des coefficients non cumulables, et exclusifs des services supplémentaires. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 1, "s": "La durée annuelle de 1 607 heures est réduite de certains jours, pour tenir compte de particularismes régionaux, notamment :", "o": ["en Alsace-Moselle", "en Île-de-France", "en Corse", "à La Réunion et à Mayotte"], "a": "AD", "e": "Départements cités : Alsace-Moselle, Guadeloupe, Guyane, Martinique, La Réunion et Mayotte. Ni la Corse ni l'Île-de-France. — Source : Fiche APORTT n°3 – La durée du travail"}, {"t": 1, "s": "Les dispositions dérogatoires aux temps de travail et de repos prévues par l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) :", "o": ["concernent notamment les membres du CCD et du CC chefs de service (article 10)", "excluent la DCCRS, soumise à son régime mixte", "concernent toutes les directions d'emploi, y compris la DCCRS", "ne visent que les circonstances exceptionnelles décidées par le ministre"], "a": "AC", "e": "Toutes les directions d'emploi, DCCRS (direction centrale des compagnies républicaines de sécurité) comprise ; elles visent le CCD (corps de conception et de direction) et le CC chefs de service (art. 10), les circonstances exceptionnelles et les missions spécifiques. — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Parmi les situations suivantes, lesquelles constituent des « circonstances exceptionnelles » au sens de la fiche APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) n°14 ?", "o": ["Une mission de surveillance ne pouvant être assurée par l'organisation habituelle", "L'accompagnement et la protection d'une personnalité", "Un événement d'une particulière gravité, comme une catastrophe naturelle", "Un événement durable et d'une gravité exceptionnelle, comme une menace sur la pérennité des institutions"], "a": "CD", "e": "Les deux derniers cas relèvent des missions spécifiques. Les circonstances exceptionnelles supposent un engagement important des forces de sécurité. — Source : Fiche APORTT n°14 – Dérogations"}, {"t": 1, "s": "Dans un cadre dérogatoire, les repos manqués sont :", "o": ["restitués dans un délai de 21 jours dès que le pourcentage de présence le permet", "obligatoirement restitués immédiatement à l'issue de la mission et compensés par des périodes de temps équivalentes", "indemnisés en priorité, la restitution n'étant que subsidiaire", "versés d'office sur le compte épargne-temps de l'agent"], "a": "B", "e": "Principe de la fiche 15 : restitution immédiate à l'issue de la mission, par des périodes de temps équivalentes. — Source : Fiche APORTT n°15 – Restitution des repos manqués"}, {"t": 2, "s": "Le régime hebdomadaire « grande semaine / petite semaine » comporte :", "o": ["6 jours de travail et 1 jour de repos, puis 4 jours et 3 jours de repos", "5 jours de travail et 2 jours de repos, puis 5 jours et 3 jours de repos", "6 jours de travail et 2 jours de repos, puis 4 jours de travail et 2 jours de repos", "4 jours de travail et 2 jours de repos en alternance"], "a": "C", "e": "Grande semaine 6 jours/2 repos, petite semaine 4 jours/2 repos ; le régime classique est 5 jours/2 repos. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "En régime hebdomadaire sans interruption de service, le temps de pause de 20 minutes est obligatoire dès que le travail quotidien atteint :", "o": ["4 heures ininterrompues", "6 heures ininterrompues", "5 heures ininterrompues", "7 heures ininterrompues"], "a": "B", "e": "6 h ininterrompues, sauf nécessités imprévisibles et impérieuses ; pause prise en principe au milieu de la journée. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "En horaires variables, quelles affirmations sont exactes ?", "o": ["L'interruption médiane est de 20 minutes au minimum", "L'agent enregistre ses entrées et sorties 4 fois par jour", "La journée comporte deux plages fixes de deux heures", "La période de référence est de 4 semaines glissantes"], "a": "BCD", "e": "L'interruption médiane va de 45 minutes minimum à 2 heures maximum. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Horaires variables, régime à 39 h 25 : en fin de période de référence, le solde créditeur atteint 1/10e du temps hebdomadaire. L'agent :", "o": ["peut verser ce crédit sur son CET", "bénéficie d'une demi-journée à prendre dans l'année civile", "bénéficie d'une journée ARTT supplémentaire", "bénéficie d'une demi-journée de récupération (RCB) à prendre dans les 4 semaines suivantes"], "a": "D", "e": "RCB à prendre dans les 4 semaines suivantes, sinon le droit s'éteint ; maximum 8 demi-journées par année civile. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Horaires variables (39 h 25) : le solde débiteur est de 5 heures en fin de période de référence. Conséquence :", "o": ["aucune conséquence", "une demi-journée ARTT est décomptée de plein droit", "il doit être compensé au cours des 4 semaines suivantes", "une journée ARTT est décomptée de plein droit"], "a": "B", "e": "Débit entre 1/10e (3 h 57) et 1/5e (7 h 53) : une demi-journée ARTT (aménagement et réduction du temps de travail) décomptée ; au-delà de 1/5e : une journée ; en dessous de 1/10e : compensation sur 4 semaines. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Les fonctionnaires du corps d'encadrement et d'application en régime hebdomadaire effectuent :", "o": ["38 h 00, 39 h 00 ou 40 h 30 par semaine", "38 h 00 ou 39 h 25 par semaine", "39 h 00 ou 40 h 30 par semaine", "35 h 00 ou 38 h 00 par semaine"], "a": "B", "e": "CEA : 38 h ou 39 h 25 ; policiers adjoints : 38 h, 39 h ou 40 h 30. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Un gardien de la paix en régime hebdomadaire à 39 h 25 dispose, après indemnisation d'office et retrait de la journée de solidarité, de combien de jours ARTT (aménagement et réduction du temps de travail) effectivement disponibles ?", "o": ["17", "16", "24", "9"], "a": "B", "e": "39 h 25 : 24 jours attribués, 16 disponibles ; 38 h : 17 attribués, 9 disponibles. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Concernant les jours ARTT (aménagement et réduction du temps de travail) indemnisés d'office, quelles affirmations sont exactes ?", "o": ["Les policiers adjoints bénéficient du rachat de 8 jours", "Les policiers adjoints sont exclus de ce rachat", "8 jours sont indemnisés pour les autres services", "16 jours sont indemnisés pour les unités de service général des CRS"], "a": "BCD", "e": "Les policiers adjoints sont exclus du rachat : leurs jours attribués et disponibles sont identiques. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "La compensation horaire de la journée de solidarité pour un régime hebdomadaire à 39 h 25 est de :", "o": ["+ 1 h 06", "+ 0 h 48", "+ 0 h 36", "+ 0 h 53"], "a": "D", "e": "40 h 30 : +1 h 06 ; 39 h 25 : +0 h 53 ; 39 h : +0 h 48 ; 38 h : +0 h 36. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "En régime hebdomadaire, le repos compensateur (RC) est positionné :", "o": ["le vendredi ou le lundi", "obligatoirement le samedi", "le dimanche", "le samedi ou le lundi, selon les nécessités de service"], "a": "D", "e": "Le RL (repos légal) est par principe le dimanche ; le RC est le samedi ou le lundi. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Les policiers ne peuvent faire l'objet de rappels et/ou reports de repos sur plus de :", "o": ["deux semaines consécutives", "une semaine", "quatre semaines sur le trimestre", "trois semaines consécutives"], "a": "A", "e": "Deux semaines consécutives au plus, quel que soit le nombre d'heures ; dérogation sur décision du ministre de l'Intérieur. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Cycles de jour : à l'issue d'une période de travail, l'agent bénéficie en principe :", "o": ["d'une descente de nuit", "de trois jours de repos dans tous les cas", "d'un RL suivi d'un RC", "d'un repos de cycle de deux jours consécutifs, un RC suivi d'un RL"], "a": "D", "e": "RC (repos compensateur) puis RL (sauf 4/2 compressé). Vacations de forte amplitude : deux RC puis un RL. — Source : Fiche APORTT n°7 – Les régimes cycliques ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Cycles de nuit : quelles affirmations sont exactes ?", "o": ["L'agent bénéficie d'une descente de nuit (DN) calculée de la fin de service à la reprise de service théorique", "Les RL et RC se définissent sur 24 h débutant aux heures habituelles de prise de service", "À l'issue de la dernière DN du cycle, l'agent bénéficie d'un RC puis d'un RL", "La journée calendaire de travail se définit de 0 h à 24 h"], "a": "ABC", "e": "La plage 0 h – 24 h vaut pour les cycles de jour ; en nocturne, la journée débute à l'heure habituelle de prise de service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Le cycle 4/2 panaché correspond à :", "o": ["4 vacations matin / 2 jours de repos / 4 vacations après-midi / 2 jours de repos", "2 vacations matin / 2 vacations après-midi / 2 jours de repos", "2 vacations / 2 jours de repos / 3 vacations / 2 jours de repos", "3 vacations après-midi / 2 jours de repos / 4 vacations matin / 1 jour de repos…"], "a": "B", "e": "Le 1er décrit le 4/2 classique, le 3e le 4/2 compressé. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Concernant les cycles 4/2, quelles affirmations sont exactes ?", "o": ["La vacation moyenne est de 8 h 10", "Ils nécessitent trois brigades de jour et une brigade de nuit de trois groupes", "La prise de service du matin est comprise entre 6 h 00 et 7 h 30, sauf nécessité", "La vacation moyenne est de 9 h 31"], "a": "AB", "e": "Prise de service du matin entre 5 h 20 et 6 h 30. 9 h 31 est la vacation moyenne de la vacation forte. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Les cycles 2/2 – 3/3 – 2/2/3/2/2/3 s'effectuent en vacations de :", "o": ["9 h 31, avec une pause de 20 minutes", "10 h 08 ou 11 h 08, avec une pause de 20 minutes", "11 h 08 ou 12 h 08, avec deux temps de pause de 20 minutes", "12 h 08 uniquement, avec deux pauses de 30 minutes"], "a": "C", "e": "Deux pauses de 20 min divisent la journée en trois parties ; une brigade de jour et une de nuit de deux groupes chacune. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail ; Fiche APORTT n°7 – Les régimes cycliques"}, {"t": 2, "s": "La vacation forte se caractérise par :", "o": ["3 vacations / 3 repos, vacation moyenne de 11 h 08", "2 vacations / 2 repos / 3 vacations / 2 repos / 3 vacations / 2 repos, vacation moyenne de 9 h 31", "4 vacations / 2 repos, vacation moyenne de 8 h 10", "2 vacations / 2 repos / 3 vacations / 2 repos / 2 vacations / 3 repos, vacation de 12 h 08"], "a": "B", "e": "Vacation forte : 2-2-3-2-3-2, 9 h 31 ; deux brigades de jour de deux groupes et une brigade de nuit de deux groupes. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Le cycle 4/2 nuit des unités cynophiles légères (UCL) comporte :", "o": ["deux vacations de nuit de 12 h 08", "trois vacations de nuit de 9 h 30 et une vacation de jour de 4 h 10", "quatre vacations de nuit de 9 h 31", "trois vacations de nuit de 8 h 10 et une de jour de 8 h 10"], "a": "B", "e": "4/2 nuit UCL : 3 nuits de 9 h 30 + 1 jour de 4 h 10, mêmes caractéristiques que le 4/2. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Prise de service décalée en régime cyclique : quelles conditions sont exactes ?", "o": ["Le décalage peut ne porter que sur une partie de la vacation", "Le décalage peut débuter la veille de la journée de travail concernée", "C'est une modalité exceptionnelle de fonctionnement", "Le décalage débute au cours de la même journée de travail"], "a": "CD", "e": "Le décalage débute au cours de la même journée de travail. Le décalage concerne l'ensemble de la plage horaire d'une vacation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail ; Fiche APORTT n°7 – Les régimes cycliques"}, {"t": 2, "s": "Une vacation décalée empiète de 2 heures sur un repos légal (hors services supplémentaires). La compensation créditée au compteur RPS (repos de pénibilité spécifique) est de :", "o": ["48 minutes", "72 minutes", "30 minutes", "2 heures"], "a": "B", "e": "Coefficient 0,60 sur RL ou jour férié : 2 h × 0,60 = 72 min (exemple de la synthèse) ; 0,25 sur un RC (repos compensateur). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Pour un fonctionnaire du CEA (corps d'encadrement et d'application) en régime hebdomadaire à 38 h 00, l'organisation et la durée moyenne de la vacation sont :", "o": ["4 jours à 8 h 00 et 1 jour à 7 h 25, vacation moyenne de 7 h 53", "4 jours à 8 h 00 et 1 jour à 7 h 00, vacation moyenne de 7 h 48", "4 jours à 7 h 45 et 1 jour à 7 h 00, vacation moyenne de 7 h 36", "5 jours à 7 h 36, sans journée courte"], "a": "C", "e": "38 h : 4 × 7 h 45 + 7 h 00 (moyenne 7 h 36). 39 h : 4 × 8 h + 7 h (7 h 48). 39 h 25 : 4 × 8 h + 7 h 25 (7 h 53). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Les cycles 4/2 (classique, panaché ou compressé) nécessitent :", "o": ["trois brigades de jour et une brigade de nuit de trois groupes", "quatre brigades de jour et deux brigades de nuit", "deux brigades de jour de deux groupes et une brigade de nuit de deux groupes", "une brigade de jour et une brigade de nuit de deux groupes chacune"], "a": "A", "e": "4/2 : trois brigades de jour + une brigade de nuit de trois groupes. Vacation forte : deux brigades de jour de deux groupes + une de nuit de deux groupes. 2/2-3/3 : une de jour et une de nuit de deux groupes. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "La vacation moyenne des cycles 4/2 « classique », « panaché » ou « compressé » est de :", "o": ["9 h 31", "7 h 53", "8 h 06", "8 h 10"], "a": "D", "e": "Vacation moyenne du 4/2 : 8 h 10, quelle que soit la version. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Pour les brigades de nuit en vacation forte, le premier jour du cycle peut être décalé pour obtenir une « vacation forte de mardi » ou « de jeudi », afin que :", "o": ["la vacation moyenne soit ramenée à 8 h 10", "chaque week-end soit intégralement non travaillé", "un week-end sur deux de repos débute le vendredi matin et se termine le dimanche soir", "les agents bénéficient de trois RC consécutifs"], "a": "C", "e": "Le week-end de repos débute le vendredi matin (fin de la dernière vacation) et se termine le dimanche soir (prise de service de la première nuit). De jour : vacation forte de lundi, de mercredi ou de vendredi. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – régimes de travail"}, {"t": 2, "s": "Le régime cyclique :", "o": ["s'applique à tous les corps actifs de la police nationale, ADS compris", "est réservé aux gradés et gardiens de la paix", "exclut les policiers adjoints du travail de nuit", "ne concerne les PATS et autres contractuels que dans des cas plus limités, comme les centres de commandement ou les services de diffusion"], "a": "AD", "e": "Tous les corps actifs, ADS (adjoints de sécurité) compris ; PATS (personnels administratifs, techniques et scientifiques) et contractuels de façon limitée (centres de commandement, services de diffusion, volontariat pour la nuit). — Source : Fiche APORTT n°7 – Les régimes cycliques"}, {"t": 3, "s": "L'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) distingue combien de types de services supplémentaires ?", "o": ["2 : astreinte et dépassement horaire", "3 : permanence, astreinte, rappel", "4 : permanence, astreinte, dépassements horaires, rappels et reports de repos", "5 : permanence, astreinte, dépassements, rappels, reports de repos et dérogations"], "a": "C", "e": "Quatre types : permanence, astreinte, dépassements horaires, rappels et reports de repos. — Source : Fiche APORTT n°11"}, {"t": 3, "s": "Les RCSS (repos compensateur pour services supplémentaires) non pris dans l'année civile où ils ont été générés, et qui ne peuvent être versés sur un CET (compte épargne-temps) :", "o": ["sont reportés jusqu'au 1er mai suivant", "sont automatiquement indemnisés", "restent dus", "sont perdus"], "a": "C", "e": "Ils restent dus (fiche 11), y compris s'ils n'ont pu être liquidés pour nécessités de service, maladie ou formation. — Source : Fiche APORTT n°11 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Sur le compte actif, au-delà d'un seuil de 160 heures de RCSS (repos compensateur pour services supplémentaires), l'agent récupère ses repos dans un délai de :", "o": ["21 jours", "fin de l'année civile", "30 jours", "60 jours"], "a": "C", "e": "30 jours, dès que le pourcentage de présence le permet ; à défaut, le chef de service prescrit la récupération par journée. — Source : Fiche APORTT n°11 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Concernant la permanence, quelles affirmations sont exactes ?", "o": ["Elle n'est possible qu'en régime hebdomadaire", "Elle est possible en régime cyclique pour les brigades de nuit", "Les policiers adjoints y participent sur volontariat", "Les tableaux sont diffusés au plus tard 14 jours avant"], "a": "ACD", "e": "La permanence est uniquement possible en régime hebdomadaire. — Source : Fiche APORTT n°12 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Permanence (CEA (corps d'encadrement et d'application)) effectuée lors d'un repos légal ou d'un jour férié : la compensation est de :", "o": ["125 % des heures réellement effectuées", "175 %", "150 %", "200 %"], "a": "B", "e": "Permanence : 175 % sur RL/JF, 125 % sur RC (repos compensateur), 200 % la nuit du samedi au dimanche, 150 % les autres nuits. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Permanence effectuée la nuit du samedi au dimanche : la compensation est de :", "o": ["175 %", "125 %", "150 %", "200 %"], "a": "D", "e": "200 % la nuit du samedi au dimanche, 150 % les autres nuits. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Les compensations horaires d'une permanence (hors repos hebdomadaires manqués et hors dépassement) sont prises dans un délai de :", "o": ["l'année civile", "21 jours", "30 jours", "14 jours"], "a": "B", "e": "21 jours dès que le pourcentage de présence le permet ; les repos hebdomadaires manqués sont restitués immédiatement ou dans les délais les plus courts. — Source : Fiche APORTT n°12"}, {"t": 3, "s": "Concernant l'astreinte, quelles affirmations sont exactes ?", "o": ["Les policiers adjoints et les réservistes en sont exclus", "L'agent doit demeurer à son domicile ou à proximité", "Elle concerne les agents en régime cyclique", "La durée de l'intervention n'est pas du temps de travail effectif"], "a": "AB", "e": "L'intervention est du temps de travail effectif. L'astreinte concerne les trois corps actifs en régime hebdomadaire. — Source : Fiche APORTT n°12 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Rappel sur astreinte nécessitant un déplacement : le temps de travail se comptabilise :", "o": ["dès l'appel téléphonique", "dès le départ du domicile", "après l'arrivée réelle, sans forfait de trajet", "après l'arrivée théorique de l'agent au service, avec une heure forfaitaire de trajet A/R"], "a": "D", "e": "Comptage après l'arrivée théorique ; intervention compensée à 100 % + 1 h forfaitaire de trajet. Pas de forfait en télé-intervention. — Source : Fiche APORTT n°12 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "L'astreinte ouvre droit :", "o": ["obligatoirement et prioritairement à indemnisation dans la limite des crédits, ou à défaut à compensation horaire, exclusives l'une de l'autre", "au choix de l'agent, à indemnisation et compensation cumulées", "uniquement à indemnisation", "uniquement à compensation horaire"], "a": "A", "e": "Indemnisation prioritaire, sinon compensation ; les deux sont exclusives. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Une semaine complète d'astreinte est rémunérée :", "o": ["11,09 €", "149,48 €", "77,37 €", "24,63 €"], "a": "B", "e": "Semaine complète : 149,48 € ou 14 h 27 ; du vendredi 21 h au lundi 6 h : 77,37 € ou 7 h 22. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Le reliquat non indemnisé des heures d'astreinte est basculé sur le compteur « HS (heures supplémentaires) actif » :", "o": ["chaque fin de mois", "au 31 décembre", "automatiquement à chaque fin de trimestre", "sur demande de l'agent"], "a": "C", "e": "Bascule automatique à chaque fin de trimestre, sans ajustement manuel. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Dépassement horaire en régime cyclique : le coefficient de restitution est de :", "o": ["150 % dans tous les cas", "200 % sur RL ou JF, 150 % sur RC, 100 % dans les autres cas", "200 % sur RL ou JF, 150 % sur RC et dans tout autre cas", "175 % sur RL, 125 % sur RC"], "a": "C", "e": "Cyclique : 200 % RL (repos légal)/JF, 150 % ailleurs. Hebdomadaire : 200 % RL/JF, 150 % RC (repos compensateur) et nuit, 100 % autres cas. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Concernant le dépassement horaire, quelles affirmations sont exactes ?", "o": ["Pour les gardiens et gradés, toute heure commencée est due", "Pour les PATS et les ADS, la compensation est temps pour temps sur le temps réel", "Les CCD et CC article 10 sont exclus de sa prise en compte", "Il se calcule sur le temps réellement effectué"], "a": "CD", "e": "PATS (personnels administratifs, techniques et scientifiques) et ADS (adjoints de sécurité) : toute heure commencée est due. Pour les gardiens et gradés, la compensation est temps pour temps sur le temps réel. — Source : Fiche APORTT n°13 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Un agent est en situation de rappel au service lorsqu'il est avisé :", "o": ["par note de service 14 jours avant", "la veille, pendant le service", "pendant sa vacation", "après la fin de sa dernière vacation, alors qu'il a quitté le service"], "a": "D", "e": "Rappel : avisé après avoir quitté le service. Le report de repos, lui, est annoncé pendant le service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Rappel au service en régime cyclique sur un RL (repos légal), pour 3 heures de travail :", "o": ["150 % des heures effectuées", "200 % des heures effectuées", "compensation de deux vacations", "compensation forfaitaire d'une vacation"], "a": "D", "e": "Rappel sur RL n'excédant pas 4 h : 1 vacation ; au-delà : 2 vacations. Sur RC (repos compensateur) et autres cas : 150 %. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Régime hebdomadaire, rappel sans permanence ni astreinte, sur la nuit (21 h – 6 h) d'un jour de semaine :", "o": ["200 %", "175 %", "100 %", "150 %"], "a": "D", "e": "Sans permanence ni astreinte : RL (repos légal)/JF 200 %, RC (repos compensateur) ou nuit 150 %, autres cas 100 %. Avec permanence/astreinte : 200 % hors astreinte, 100 % sur astreinte. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Cycle de nuit à vacation inférieure à 11 h 08 : un agent est rappelé sur sa descente de nuit et le rappel se termine après 13 h. Il :", "o": ["reprend normalement son service", "est exempté de la nuit suivante", "bénéficie d'un repos de 11 h", "bénéficie d'un repos minimal de 8 h avant de reprendre"], "a": "B", "e": "Rappel terminé avant 13 h : 8 h de repos minimum ; après 13 h : exemption de la nuit suivante. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Le report de repos légal :", "o": ["peut être annoncé à l'agent après qu'il a quitté le service", "ouvre droit à une compensation forfaitaire d'une journée de travail", "porte uniquement sur une journée ou une vacation entière", "exclut les PATS, policiers adjoints et autres contractuels"], "a": "CD", "e": "Compensation forfaitaire : deux journées. L'agent est avisé pendant qu'il est au service, le plus tôt possible ou au plus tard avant la fin de sa dernière vacation. — Source : Fiche APORTT n°13 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Parmi ces congés, lesquels ne sont pas rappelables (sauf décision du ministre de l'Intérieur) ?", "o": ["Les ARTT accolés à des jours CET", "Les congés du CET", "Les repos de cycle RC/RL accolés et précédant des congés posés au plan", "Le crédit férié"], "a": "ABC", "e": "Le crédit férié, les repos cycliques, jours fériés, ARTT (aménagement et réduction du temps de travail) et HS (heures supplémentaires) sont rappelables sur décision du chef de service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Comptes de RCSS (fiche APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) n°11) : quelles affirmations sont exactes ?", "o": ["Les RCSS compris entre 120 et 160 heures peuvent également être enregistrés sur le compte historique", "Le compte actif ne peut jamais dépasser 120 heures", "Les RCSS au-delà de 160 heures sont enregistrés sur le compte historique", "Les RCSS du compte historique doivent être récupérés dans un délai de 21 jours"], "a": "AC", "e": "Deux comptes depuis le 1er janvier 2020 : historique (au-delà de 160 h, et possiblement 120-160 h) et actif ; les RCSS du compte actif peuvent être indemnisés. — Source : Fiche APORTT n°11 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Permanence : l'amplitude horaire de la journée de permanence :", "o": ["ne peut excéder 8 heures, quel que soit le corps", "est librement fixée par le chef de service sans limite", "doit correspondre à la DMJ de l'agent, et ne doit pas dépasser 12 h pour les CC hors article 10", "est toujours de 24 heures"], "a": "C", "e": "Amplitude = DMJ (durée moyenne journalière) ; 12 h maximum pour les commissaires hors article 10. Le chef de service organise la permanence par note de service. — Source : Fiche APORTT n°12"}, {"t": 3, "s": "Astreinte : quelle compensation en temps est prévue pour une nuit d'astreinte (21 h – 6 h) un repos légal ou un jour férié ?", "o": ["2 h 23", "1 h 04", "1 h 47", "7 h 22"], "a": "A", "e": "Nuit de semaine : 1 h 04 (11,09 €) ; RC (repos compensateur) : 1 h 47 (18,47 €) ; RL/JF : 2 h 23 (24,63 €) ; vendredi 21 h – lundi 6 h : 7 h 22. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "En semaine (6 h – 21 h), un agent qui travaille 8 heures peut être placé d'astreinte :", "o": ["sur l'intégralité des 15 heures du créneau", "uniquement sur les 7 heures restantes non couvertes par son travail programmé", "uniquement de 21 h à 6 h", "jamais un jour où il a travaillé"], "a": "B", "e": "L'astreinte en journée de semaine ne couvre que les périodes non couvertes par un travail normalement programmé. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Cumul de services supplémentaires : quelles affirmations sont exactes ?", "o": ["Le dépassement sur astreinte est compensé deux fois au titre de la pénibilité", "Une permanence peut être combinée avec une astreinte, la période d'astreinte étant amputée du temps de permanence", "Un dépassement horaire réalisé sur une période d'astreinte ne peut donner lieu à une double compensation", "Permanence et astreinte ne peuvent jamais être combinées"], "a": "BC", "e": "Pas de double compensation dépassement + astreinte ; la combinaison permanence/astreinte est possible avec amputation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Sont exclus de la prise en compte du dépassement horaire :", "o": ["les policiers adjoints", "les CCD", "les CC article 10", "les PATS article 10"], "a": "BCD", "e": "CCD (corps de conception et de direction), CC art. 10 et PATS (personnels administratifs, techniques et scientifiques) art. 10 sont exclus. Les PA (policiers adjoints) y ont droit, avec la règle « toute heure commencée est due ». — Source : Fiche APORTT n°13"}, {"t": 3, "s": "Selon la synthèse, il est de règle de protéger contre le rappel, par analogie :", "o": ["les heures de crédit férié", "le congé de formation professionnelle", "les ASA pour événements de famille (naissance, adoption, paternité…)", "les jours ARTT pris isolément hors plan"], "a": "BC", "e": "Protection par analogie des ASA (autorisation spéciale d'absence) de la fonction publique et du congé de formation professionnelle. ARTT (aménagement et réduction du temps de travail) et crédit férié sont rappelables par le chef de service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Le rappel au service d'un agent est impossible lorsqu'il est placé :", "o": ["en CMO, CLM ou CLD", "en blessure en service (BS/SBS)", "en jour férié travaillé", "en repos de cycle RC/RL hors plan"], "a": "AB", "e": "Impossibilité de rappeler un agent en CMO (congé de maladie ordinaire)/CLD/CLM ou BS/SBS. Les repos de cycle hors plan et JF (jour férié) sont rappelables. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Cycle de nuit à vacation égale ou supérieure à 11 h 08 : un agent est rappelé pour une mission non programmée. Il doit :", "o": ["bénéficier d'un repos de 11 h, faute de quoi il est exempté de deux vacations", "bénéficier d'un repos de 8 h 00, faute de quoi il est exempté de la vacation suivante", "être exempté de la nuit suivante si le rappel se termine après 13 h", "reprendre sa vacation suivante sans condition de repos"], "a": "B", "e": "Vacation ≥ 11 h 08 : repos de 8 h ou exemption de la vacation suivante. La règle des 13 h concerne les cycles à vacation < 11 h 08. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 3, "s": "Sont exclus du dispositif du report de repos légal :", "o": ["les autres contractuels", "les gradés et gardiens en régime cyclique", "les PATS", "les policiers adjoints"], "a": "ACD", "e": "Exclusion des PATS (personnels administratifs, techniques et scientifiques), PA (ADS (adjoints de sécurité)) et autres contractuels ; hors règles propres au report, on applique celles du rappel. — Source : Fiche APORTT n°13 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026) – services supplémentaires"}, {"t": 4, "s": "Le plan prévisionnel annuel des départs en congés, lorsqu'il est établi en une seule fois, couvre la période :", "o": ["du 15 mars de l'année N au 14 mars de l'année N+1", "du 15 février au 15 octobre de l'année N", "du 1er mai au 31 octobre de l'année N", "du 1er janvier au 31 décembre de l'année N"], "a": "A", "e": "Plan en une fois : 15 mars N – 14 mars N+1, validé au plus tard le 15 mars. Plan scindé : 15 février – 15 octobre puis 16 octobre – 14 février. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Lors de l'établissement du plan de départs en congés, le taux de présence des effectifs doit être :", "o": ["au minimum de 50 %, et jusqu'à 75 % si des circonstances particulières ou spécificités locales le justifient", "au minimum de 50 %, sans plafond", "au minimum de 60 %, et jusqu'à 80 % en période estivale", "au minimum de 75 % en toutes circonstances"], "a": "A", "e": "Entre le minimum opérationnel (jamais inférieur à 50 %) et 75 %. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 4, "s": "Selon la fiche APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) n°8, le pourcentage de fonctionnaires présents dans un service :", "o": ["est librement fixé par le chef de service", "ne peut être inférieur à 75 %", "ne peut dépasser 75 %", "ne peut être inférieur à 50 %, ni atteindre 100 % sauf décision du ministre en circonstances exceptionnelles"], "a": "D", "e": "Minimum 50 %, et 100 % seulement sur décision du ministre de l'Intérieur en circonstances exceptionnelles. — Source : Fiche APORTT n°8"}, {"t": 4, "s": "Concernant les priorités de départ pendant les vacances scolaires, quelles affirmations sont exactes ?", "o": ["Une priorité non satisfaite en année N est reportée sur l'année N+1", "À priorité égale, les agents sont départagés d'abord par l'âge", "75 % des départs sont réservés aux fonctionnaires élevant des enfants d'âge scolaire (3-16 ans) ou bénéficiant d'un droit de garde ou de visite", "La priorité des parents d'enfants handicapés est classée en première position et compte dans les 75 %"], "a": "ACD", "e": "Départage : ancienneté de grade, puis ancienneté de présence administrative, enfin l'âge. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 4, "s": "Chef d'équipe, vous gérez l'annulation de congés inscrits au plan. Quelles affirmations sont exactes ?", "o": ["Un agent averti de l'annulation avant le début de ses congés bénéficie de la compensation de l'article 53 de l'APORTT", "Un agent déjà en congés et rappelé bénéficie de la compensation de l'article 53 de l'APORTT", "Les congés posés au plan ne peuvent être annulés ou faire l'objet d'un rappel que sur décision du ministre de l'Intérieur", "Parmi les repos accolés aux congés, seuls les RC et RL achevant une période sont rappelables"], "a": "BCD", "e": "L'agent averti avant son départ voit seulement ses jours recrédités, sans compensation. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 4, "s": "Un jour férié placé APRÈS les RC (repos compensateur)/RL qui suivent des congés posés au plan :", "o": ["est rappelable", "est converti en crédit férié", "ne peut être rappelé que sur décision du DGPN", "est protégé du rappel"], "a": "A", "e": "Un JF placé avant les RC/RL descendants est protégé ; un JF intervenant après est rappelable. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Nombre de CA annuels selon le régime : quelles correspondances sont exactes ?", "o": ["Cycles 2/2, 3/3 : 18 CA", "Vacation forte : 18 CA", "Hebdomadaire : 25 CA", "Cycle 4/2 : 25 CA"], "a": "AC", "e": "Cycle 4/2 : 23 CA. Vacation forte : 20 CA. Le congé annuel vaut 5 fois les obligations hebdomadaires, en jours ouvrés. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "La durée d'absence au titre des congés annuels est limitée, sauf exceptions, à :", "o": ["31 jours calendaires consécutifs, repos compris", "31 jours ouvrés, repos non compris", "30 jours calendaires", "45 jours calendaires"], "a": "A", "e": "31 jours calendaires consécutifs, RC (repos compensateur)/RL/JF compris ; exceptions possibles (CET (compte épargne-temps) cumulé avec CA/ARTT, congé bonifié). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Jours de fractionnement : un agent a pris 6 CA en dehors de la période du 1er mai au 31 octobre. Il obtient :", "o": ["aucun jour", "1 jour", "2 jours", "3 jours"], "a": "B", "e": "1 jour pour 5, 6 ou 7 jours pris hors période ; 2 jours à partir de 8. Ces jours se prennent toute l'année. — Source : Fiche APORTT n°9 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Les CA reportés exceptionnellement pour nécessité de service :", "o": ["doivent être pris avant le 1er mai de l'année suivante", "n'ouvrent pas droit à l'attribution de jours de CA supplémentaires (fractionnement)", "nécessitent l'autorisation du chef de service", "peuvent être pris sur 15 mois"], "a": "ABC", "e": "Les 15 mois (dans la limite de 4 semaines) concernent les CA non pris pour maladie ou maternité. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Fiche APORTT n°9"}, {"t": 4, "s": "Un agent n'a pas pu prendre ses congés annuels du fait d'un congé de maladie. Ces congés peuvent être pris :", "o": ["sans limite de durée, sur 18 mois", "dans la limite de 4 semaines, avant le 1er mai suivant", "dans la limite de 4 semaines, au cours d'une période de 15 mois après le terme de l'année", "dans la limite de 5 semaines, au cours de 12 mois"], "a": "C", "e": "4 semaines maximum, sur 15 mois. — Source : Fiche APORTT n°9"}, {"t": 4, "s": "S'agissant des jours ARTT (aménagement et réduction du temps de travail), quelle affirmation est exacte ?", "o": ["Ils sont reportables jusqu'au 1er mai de l'année suivante", "La journée de solidarité réduit la dotation ARTT d'une journée de 8 heures", "Ils sont définitivement perdus s'ils n'ont pas été versés sur un CET", "En régime cyclique, ils sont exprimés en jours"], "a": "C", "e": "ARTT pris dans l'année civile, sans report. Cyclique : crédit en heures. Journée de solidarité : 7 heures. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Fiche APORTT n°10"}, {"t": 4, "s": "L'attribution des jours ARTT (aménagement et réduction du temps de travail) a pour objet :", "o": ["de ramener la durée annuelle de travail effectif à 1 607 heures", "de compenser les jours fériés en régime cyclique", "de compenser le travail de nuit", "de rémunérer les services supplémentaires"], "a": "A", "e": "ARTT : retour aux 1 607 h. Le crédit férié compense les jours fériés en cyclique ; les RPS (repos de pénibilité spécifique) la pénibilité. — Source : Fiche APORTT n°10"}, {"t": 4, "s": "Sur l'année civile, si moins de 10 jours d'ARTT (aménagement et réduction du temps de travail) et/ou de RPS (repos de pénibilité spécifique) sont positionnés sur le plan prévisionnel :", "o": ["le reliquat est perdu", "le reliquat est protégé, posé en une seule fois", "le reliquat est versé d'office sur le CET", "le reliquat jusqu'à 10 jours est protégé, posé en deux fois maximum avec validation du chef de service"], "a": "D", "e": "Reliquat entre le nombre posé et 10 jours protégé, en deux fois maximum. — Source : Fiche APORTT n°8 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Le crédit férié annuel (régime cyclique) en métropole hors Alsace-Moselle est de :", "o": ["14 jours de 8 h", "116 h 12", "109 h 12", "123 h 12"], "a": "C", "e": "109 h 12 ; 116 h 12 dans les DOM (abolition de l'esclavage) ; 123 h 12 en Alsace-Moselle. Il équivaut à 14 jours de repos. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Concernant le crédit férié, quelles affirmations sont exactes ?", "o": ["Il est librement reportable sur l'année suivante", "Il est réduit de 1/24e (3 h 33) par période de CMO égale ou supérieure à 15 jours consécutifs", "Il ne peut pas alimenter un CET", "Il est proratisé pour un agent prenant ses fonctions en cours d'année, par période de 30 jours"], "a": "BC", "e": "Proratisation par période de 15 jours. Il se prend dans l'année civile ; report seulement sur autorisation du DGPN (directeur général de la police nationale), du préfet de police ou du DGSI (directeur général de la sécurité intérieure). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Fiche APORTT n°8"}, {"t": 4, "s": "Quels coefficients de repos de pénibilité spécifique (RPS) sont exacts ?", "o": ["0,1 pour le travail de nuit en régime cyclique", "0,4 pour le travail du dimanche en régime cyclique", "0,25 par heure de repos journalier manqué", "0,60 pour une prise décalée sur un repos compensateur"], "a": "AB", "e": "0,15 par heure de repos journalier manqué. Prise décalée : 0,25 sur RC (repos compensateur), 0,60 sur RL (repos légal) ou JF (jour férié). — Source : Fiche APORTT n°10 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Les RPS (repos de pénibilité spécifique) non pris en raison de nécessités de service :", "o": ["sont indemnisés", "sont perdus au 31 décembre", "restent dus et sont reportés l'année suivante", "sont versés sur le CET"], "a": "C", "e": "Ils restent dus et sont reportés ; ils ne peuvent pas alimenter le CET (compte épargne-temps). Au plan : 10 journées ou vacations maximum. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Parmi les personnels suivants, lequel bénéficie des RPS (repos de pénibilité spécifique) ?", "o": ["Un commissaire (CCD)", "Un contractuel article 10", "Un agent PATS", "Un gardien de la paix en cycle 4/2"], "a": "D", "e": "CCD (corps de conception et de direction), CC, PATS (personnels administratifs, techniques et scientifiques) et contractuels art. 10 n'en bénéficient pas. — Source : Fiche APORTT n°10"}, {"t": 4, "s": "Le congé bonifié a une durée maximale de :", "o": ["60 jours, tous les deux ans", "45 jours, tous les trois ans", "31 jours consécutifs, tous les deux ans, après 24 mois de services ininterrompus", "31 jours, chaque année, après 12 mois de services"], "a": "C", "e": "31 jours maximum, tous les deux ans, 24 mois de services ininterrompus. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "En régime cyclique, un congé de maladie non imputable au service entraîne une réduction du crédit férié annuel de :", "o": ["1/12e (9 h 06) par mois d'absence", "1/24e (3 h 33) par période d'absence égale ou supérieure à 15 jours consécutifs", "1/24e par période d'absence égale ou supérieure à 30 jours consécutifs", "7 heures par période d'absence de 15 jours, consécutifs ou non"], "a": "B", "e": "Réduction de 1/24e, soit 3 h 33, par période d'absence d'au moins 15 jours consécutifs. — Source : Fiche APORTT n°8 ; Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Le crédit férié de 123 h 12 applicable dans le Haut-Rhin, le Bas-Rhin et la Moselle s'explique par deux jours fériés supplémentaires :", "o": ["la Saint-Étienne et le Vendredi saint", "le lundi de Pentecôte et la Saint-Étienne", "le Vendredi saint et la commémoration de l'abolition de l'esclavage", "l'Ascension et le Vendredi saint"], "a": "A", "e": "Alsace-Moselle : Saint-Étienne et Vendredi saint (123 h 12). DOM : abolition de l'esclavage (116 h 12). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Selon l'exemple chiffré de la synthèse, un dimanche travaillé (créneau 6 h – 21 h) génère, en cycle 4/2 à vacation de 8 h 10, un RPS (repos de pénibilité spécifique) de :", "o": ["3 h 48", "3 h 16", "49 minutes", "4 h 27"], "a": "B", "e": "Dimanche : 3 h 16 (4/2), 3 h 48 (VF), 4 h 27 (11 h 08), 4 h 51 (12 h 08). Nuit : 49 min (4/2), 54 min pour les autres cycles. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Selon l'exemple chiffré de la synthèse, quelles valeurs de RPS (repos de pénibilité spécifique) par nuit travaillée (créneau 21 h – 6 h) sont exactes ?", "o": ["1 h 12 en cycle à vacation de 12 h 08", "54 minutes en cycle à vacation de 12 h 08", "49 minutes en cycle 4/2 (vacation de 8 h 10)", "54 minutes en vacation forte (9 h 31)"], "a": "BCD", "e": "Nuit : 4/2 = 49 min ; vacation forte, 11 h 08 et 12 h 08 = 54 min (créneau 21 h – 6 h de 9 h × 0,1). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Un repos supplémentaire (art. 113-40 du RGEPN (règlement général d'emploi de la police nationale)) peut être accordé à la suite d'événements importants ou de services particuliers :", "o": ["sur décision du préfet de zone, aux seuls effectifs CRS", "sur décision du chef de service, dans la limite de deux jours", "à titre exceptionnel et sur décision ministérielle, à tout ou partie des effectifs engagés", "de droit, à tout agent ayant effectué plus de 12 heures de service"], "a": "C", "e": "Repos exceptionnel sur décision ministérielle, pour tout ou partie des effectifs engagés. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "La différence de temps entre la journée de solidarité (7 h) et la journée ARTT (aménagement et réduction du temps de travail) déduite est abondée en RCSS (repos compensateur pour services supplémentaires). Sont exclus de cet abondement :", "o": ["le régime de la vacation forte", "les agents de l'article 10, quel que soit le régime cyclique", "les régimes cycliques binaires à 12 h 08 et 11 h 08", "les agents en cycle 4/2 classique"], "a": "ABC", "e": "Exclusions de l'abondement issu de la JS en RCSS : cycles binaires 12 h 08 et 11 h 08, vacation forte, et agents article 10 quel que soit le cycle. — Source : Fiche APORTT n°10"}, {"t": 4, "s": "Les congés annuels non pris au cours de l'année civile pour un motif autre que la maladie, la maternité ou une nécessité de service :", "o": ["sont reportés sur une période de 15 mois", "ne peuvent être reportés, mais peuvent être placés sur le CET si l'agent en remplit les conditions", "sont indemnisés à la fin de l'année", "sont reportés de droit jusqu'au 1er mai suivant"], "a": "B", "e": "Pas de report pour les autres motifs ; versement possible sur le CET (compte épargne-temps) si les conditions sont remplies. — Source : Fiche APORTT n°9"}, {"t": 4, "s": "Les jours ARTT (aménagement et réduction du temps de travail) d'un agent n'ayant pas exercé ses fonctions pendant la totalité de la durée normalement déterminée :", "o": ["sont supprimés si l'absence dépasse trois mois", "sont calculés au prorata des services accomplis", "restent intégralement acquis", "sont réduits de moitié"], "a": "B", "e": "Prorata des services accomplis ; les ARTT non pris ni versés sur un CET (compte épargne-temps) sont définitivement perdus. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Pour faciliter la gestion annuelle du dispositif des RPS (repos de pénibilité spécifique) :", "o": ["ils sont versés automatiquement sur le CET en fin d'année", "ils sont crédités uniquement au 31 décembre de l'année écoulée", "des avances sur leur durée prévisionnelle peuvent être consenties dès le début de l'année", "ils sont convertis en jours ARTT au 1er juillet"], "a": "C", "e": "Avances possibles dès le début de l'année ; non positionnés au plan, ils se prennent sur l'année civile ; ils ne peuvent alimenter le CET (compte épargne-temps). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Pour être exclus du report de repos, les RPS (repos de pénibilité spécifique) ne peuvent être positionnés sur le plan prévisionnel qu'à hauteur de 10 jours sur les périodes d'hiver, à savoir :", "o": ["du 1er janvier au 30 avril et du 1er octobre au 31 décembre", "du 15 octobre au 14 février", "du 1er novembre au 31 mars", "du 1er décembre au 28 février"], "a": "A", "e": "Périodes d'hiver : 1er janvier – 30 avril et 1er octobre – 31 décembre. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "En régime cyclique, le crédit annuel horaire d'aménagement et de réduction du temps de travail est désigné sous le sigle :", "o": ["RCB", "RCSS", "ARTC", "ARTT"], "a": "C", "e": "ARTT (aménagement et réduction du temps de travail) en régime hebdomadaire (en jours), ARTC (aménagement et réduction du temps de travail en régime cyclique) en régime cyclique (crédit horaire). — Source : Fiche APORTT n°8"}, {"t": 4, "s": "La durée annuelle de 1 607 heures peut être réduite par arrêté ministériel pour tenir compte de sujétions, notamment :", "o": ["le travail en horaires décalés ou en équipes", "l'éloignement du domicile de l'agent", "le travail de nuit et le travail le dimanche", "les travaux pénibles ou dangereux"], "a": "ACD", "e": "Sujétions citées : nuit, dimanche, horaires décalés, équipes, modulation importante du cycle, travaux pénibles ou dangereux. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 4, "s": "Pour l'établissement du plan prévisionnel des départs en congés, les personnels formulent leurs demandes de dates prévisionnelles au plus tard :", "o": ["15 jours avant la date de validation du plan", "un mois avant la date de validation du plan", "le 1er janvier de l'année concernée", "8 jours avant la date de validation du plan"], "a": "A", "e": "Demandes au plus tard 15 jours avant la validation du plan par le chef de service. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 4, "s": "Calcul du taux de présence pour le plan prévisionnel de congés : quelles règles sont exactes ?", "o": ["Les policiers adjoints sont dissociés du taux de présence des agents du CEA", "Le résultat est arrondi au nombre entier inférieur lorsque la décimale est inférieure ou égale à 0,5", "Le résultat est toujours arrondi au nombre entier supérieur", "PA et CEA sont comptabilisés ensemble pour atteindre le minimum de 50 %"], "a": "AB", "e": "Taux distincts PA (policiers adjoints) / CEA (corps d'encadrement et d'application) ; arrondi à l'entier inférieur si la décimale est ≤ 0,5. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 4, "s": "Le choix d'établir le plan prévisionnel de congés en une ou en deux périodes :", "o": ["fait chaque année l'objet d'un passage en comité technique, puis en comité social d'administration (CSA) à compter du 1er janvier 2023", "est fixé une fois pour toutes par la circulaire", "est décidé par vote des agents du service", "relève de la seule décision du chef de service, sans consultation"], "a": "A", "e": "Passage annuel en CT, puis en CSA à compter du 1er janvier 2023. — Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés"}, {"t": 5, "s": "Pour la naissance du 1er ou du 2e enfant, le congé de maternité :", "o": ["débute 8 semaines avant et se poursuit 18 semaines après", "débute 6 semaines avant et se poursuit 16 semaines après", "débute 4 semaines avant et se poursuit 12 semaines après", "débute 6 semaines avant la date présumée d'accouchement et se poursuit 10 semaines après"], "a": "D", "e": "1er/2e enfant : 6 + 10 semaines. À partir du 3e : 8 + 18 (ou 10 + 16). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "En cas de grossesse gémellaire, le congé de maternité :", "o": ["débute 24 semaines avant et se termine 22 semaines après", "débute 8 semaines avant et se termine 18 semaines après", "débute 10 semaines avant et se termine 16 semaines après", "débute 12 semaines avant la date présumée et se termine 22 semaines après l'accouchement"], "a": "D", "e": "Jumeaux : 12 + 22 semaines ; triplés ou plus : 24 + 22 semaines. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Les congés pathologiques liés à la grossesse :", "o": ["peuvent atteindre 4 semaines au maximum après la naissance", "n'entrent pas dans les absences (CMO) réduisant l'ARTT", "peuvent atteindre 2 semaines pendant la grossesse, en continu ou non", "sont décomptés comme des congés de maladie ordinaire"], "a": "ABC", "e": "Ils sont considérés comme congé de maternité, et non comme CMO (congé de maladie ordinaire). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Congé de paternité : sa durée est de :", "o": ["11 jours calendaires, 18 en cas de naissances multiples", "25 jours ouvrés, 32 en cas de naissances multiples", "25 jours calendaires, 32 en cas de naissances multiples, auxquels s'ajoutent les 3 jours de naissance", "28 jours calendaires, plus 3 jours de naissance"], "a": "C", "e": "25 ou 32 jours calendaires + 3 jours de naissance. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Congé de paternité : quelles affirmations sont exactes ?", "o": ["La demande est formulée au moins quinze jours avant la date présumée de la naissance", "Le reste peut être fractionné en deux périodes maximum d'au moins 5 jours chacune", "Le reste doit être pris dans les quatre mois suivant la naissance", "4 jours doivent être pris consécutivement et immédiatement après le congé de naissance de 3 jours"], "a": "BD", "e": "Le reste se prend dans les six mois suivant la naissance. La demande doit être formulée au moins un mois avant la date présumée de la naissance. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Hospitalisation immédiate du nouveau-né en unité de soins spécialisés : la période de 4 jours consécutifs du congé de paternité peut être prolongée dans la limite de :", "o": ["30 jours consécutifs", "15 jours consécutifs", "la durée de l'hospitalisation sans limite", "45 jours"], "a": "A", "e": "Prolongation pendant l'hospitalisation, dans la limite de 30 jours consécutifs ; les 21 (ou 28) jours restants dans les 6 mois suivant la fin de l'hospitalisation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Congé d'adoption pris par un seul parent n'ayant aucun ou un enfant à charge :", "o": ["18 semaines", "16 semaines à compter de l'arrivée au foyer", "10 semaines", "22 semaines"], "a": "B", "e": "0 ou 1 enfant : 16 semaines ; 2 enfants ou plus : 18 ; adoption multiple : 22. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Congé d'adoption réparti entre les deux parents : quelles affirmations sont exactes ?", "o": ["Il n'ouvre pas droit aux congés annuels", "Les congés de 16 et 18 semaines sont prolongés de 25 jours", "Le congé ne peut être fractionné qu'en deux périodes, dont une d'au moins 25 jours", "Il peut débuter au maximum 7 jours avant l'arrivée de l'enfant au foyer"], "a": "BCD", "e": "Le congé d'adoption est une période de service accompli ouvrant droit aux congés annuels. Plus de deux enfants : 22 semaines + 32 jours. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le congé parental est accordé par périodes de :", "o": ["6 mois à 1 an, demandées trois mois avant", "2 à 6 mois renouvelables, demandées au moins deux mois avant le début", "2 à 6 mois, demandées quinze jours avant", "1 à 3 mois, demandées un mois avant"], "a": "B", "e": "Périodes de 2 à 6 mois renouvelables ; demande au moins 2 mois avant. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le fonctionnaire en congé parental :", "o": ["conserve le bénéfice des droits acquis avant le début du congé", "n'acquiert pas de droit à la retraite, sous réserve des dispositions spécifiques", "conserve ses droits à l'avancement dans la limite de cinq ans sur l'ensemble de sa carrière", "perçoit la moitié de son traitement"], "a": "ABC", "e": "Le congé parental est un congé sans traitement. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Un policier adjoint peut bénéficier d'un congé parental s'il justifie d'une ancienneté d'au moins :", "o": ["aucune condition", "6 mois", "un an", "deux ans"], "a": "C", "e": "Au moins un an à la date de naissance ou d'arrivée au foyer de l'enfant. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "La demande de congé de présence parentale doit être faite par écrit au moins :", "o": ["un mois avant", "15 jours avant le début du congé, avec un certificat médical", "deux mois avant", "48 heures avant"], "a": "B", "e": "Accordé de droit, sur demande écrite au moins 15 jours avant, avec certificat du médecin qui suit l'enfant. Maximum 310 jours ouvrés sur 36 mois pour un même enfant et une même pathologie. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour événements de famille : quelles durées maximales sont exactes ?", "o": ["Mariage d'un parent ou allié jusqu'au 3e degré : 3 jours ouvrables", "Mariage de l'agent : 5 jours ouvrables", "Mariage d'un enfant de l'agent : 5 jours ouvrables", "Décès du père ou de la mère : 3 jours ouvrables"], "a": "BD", "e": "Mariage d'un enfant : 3 jours. Mariage d'un parent ou allié jusqu'au 3e degré : 1 jour ouvrable. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Un agent conclut un PACS puis, l'année suivante, se marie avec la même personne. Les ASA (autorisation spéciale d'absence) au titre de la cérémonie :", "o": ["sont de 3 jours pour le PACS et 5 pour le mariage", "ne sont accordées que pour le mariage", "sont accordées deux fois, 5 jours chacune", "ne sont accordées qu'une seule fois"], "a": "D", "e": "Si le PACS est suivi d'un mariage, les ASA pour la cérémonie ne sont accordées qu'une fois (5 jours ouvrables maximum). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Les durées d'ASA (autorisation spéciale d'absence) pour événement de famille peuvent être majorées de délais de route dans la limite de :", "o": ["72 heures", "48 heures aller et retour", "24 heures", "une journée par trajet"], "a": "B", "e": "Délais de route : 48 h maximum aller et retour. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le décès d'un oncle de l'agent (parent du 3e degré) ouvre droit à une ASA (autorisation spéciale d'absence) de :", "o": ["aucune ASA", "3 jours ouvrables", "5 jours ouvrables", "1 jour ouvrable maximum"], "a": "D", "e": "Décès d'un parent ou allié jusqu'au 3e degré : 1 jour ouvrable. Oncle, tante, neveu, nièce relèvent du 3e degré. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Un agent perd son enfant âgé de 20 ans. Il bénéficie de droit de :", "o": ["12 jours ouvrables", "5 jours ouvrables", "14 jours ouvrables, plus une ASA complémentaire de 8 jours fractionnable dans un délai d'un an", "3 jours ouvrables"], "a": "C", "e": "12 jours, portés à 14 pour un enfant de moins de 25 ans, + 8 jours complémentaires dans l'année. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Autorisations d'absence liées à la grossesse : quelles affirmations sont exactes ?", "o": ["Le conjoint peut bénéficier d'une autorisation pour se rendre à trois de ces examens au maximum", "Les examens médicaux obligatoires sont au nombre de sept pour une grossesse menée à terme", "Les séances préparatoires à l'accouchement donnent droit à une journée complète d'absence", "Des facilités de deux heures par jour peuvent être accordées aux mères allaitant leur enfant"], "a": "AB", "e": "Allaitement : une heure par jour. Les absences pour séances préparatoires ou examens ne peuvent dépasser la demi-journée. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour soigner un enfant malade : un agent à temps plein, sans situation particulière, peut obtenir au maximum par an :", "o": ["6 jours", "5 jours", "10 jours", "12 jours"], "a": "A", "e": "Obligations hebdomadaires + 1 jour : (5 + 1) = 6 jours ; doublement possible (12 jours) si l'agent assume seul la charge de l'enfant, etc. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Un agent à 80 % demande des ASA (autorisation spéciale d'absence) pour garde d'enfant malade, sans situation particulière. Son droit annuel maximal est de :", "o": ["4 jours", "5 jours", "6 jours", "4,8 jours non arrondis"], "a": "B", "e": "(5 + 1) × 4/5 = 4,8, arrondi à 5 jours. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "L'accouchement intervient plus de 6 semaines avant la date présumée et exige l'hospitalisation de l'enfant. Le congé de maternité :", "o": ["débute à la date de sortie de l'enfant de l'hôpital", "est prolongé du nombre de jours courant de la date d'accouchement au début du congé de maternité", "est prolongé forfaitairement de 30 jours", "n'est pas modifié, seul le congé pathologique pouvant être accordé"], "a": "B", "e": "Prolongation du nombre de jours entre l'accouchement et le début théorique du congé ; si l'enfant reste hospitalisé au-delà de la 6e semaine après l'accouchement, la mère peut reporter le reliquat postnatal à la fin de l'hospitalisation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le congé d'adoption peut débuter :", "o": ["uniquement le lendemain de l'arrivée de l'enfant au foyer", "au maximum 15 jours avant l'arrivée de l'enfant au foyer", "à la date d'arrivée de l'enfant au foyer, ou au maximum 7 jours avant cette date", "au maximum un mois avant l'arrivée de l'enfant au foyer"], "a": "C", "e": "Début à l'arrivée au foyer ou jusqu'à 7 jours avant. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Les dispositions relatives au congé d'adoption sont applicables aux policiers adjoints dès lors qu'ils comptent :", "o": ["2 ans de service", "1 an de service", "3 mois de service", "6 mois de service"], "a": "D", "e": "PA : 6 mois de service pour le congé d'adoption (contre un an d'ancienneté pour le congé parental). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Congé de paternité : un mois avant la prise de la 2e période du congé de 21 ou 28 jours, l'agent :", "o": ["doit déposer un certificat de naissance auprès du SGAMI", "sollicite l'avis du médecin de prévention", "n'a aucune démarche à accomplir", "confirme à son chef de service les dates de prise du congé et, en cas de fractionnement, celles de chacune des deux périodes"], "a": "D", "e": "Confirmation des dates au chef de service un mois avant ; la période restante se prend en continu ou en deux périodes d'au moins 5 jours. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "En cas d'adoption d'un enfant âgé de plus de 3 ans et de moins de 16 ans, le congé parental ne peut excéder :", "o": ["une année à compter de l'arrivée au foyer", "la date du 16e anniversaire de l'enfant", "six mois à compter de l'arrivée au foyer", "trois ans à compter de l'arrivée au foyer"], "a": "A", "e": "Enfant adopté de moins de 3 ans : 3 ans au plus ; entre 3 et 16 ans : un an au plus. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Pour des naissances multiples d'au moins trois enfants, le congé parental peut être prolongé :", "o": ["jusqu'à l'entrée à l'école maternelle seulement", "deux fois, jusqu'au 4e anniversaire des enfants", "cinq fois, pour prendre fin au plus tard au 6e anniversaire du plus jeune des enfants", "jusqu'au 3e anniversaire uniquement, sans prolongation"], "a": "C", "e": "Naissances multiples : prolongation jusqu'à l'entrée en maternelle ; au moins 3 enfants : cinq prolongations, fin au 6e anniversaire du plus jeune. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le congé de proche aidant :", "o": ["est rémunéré à demi-traitement", "peut concerner un collatéral jusqu'au 2e degré seulement", "dure 3 mois au maximum, renouvelable dans la limite d'un an sur l'ensemble de la carrière", "peut être pris par périodes fractionnées d'au moins une journée, ou sous forme de temps partiel"], "a": "CD", "e": "Non rémunéré, mais assimilé à du service effectif (droits à pension) ; collatéraux jusqu'au 4e degré. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le congé de solidarité familiale peut être accordé, sur demande écrite, sous la forme :", "o": ["d'une période continue de 3 mois maximum, renouvelable une fois", "d'une période continue d'un an, imputée sur les congés annuels", "d'un temps partiel à 50, 60, 70 ou 80 % pour 3 mois maximum, renouvelable une fois", "de périodes fractionnées d'au moins 7 jours consécutifs, dans la limite cumulée de 6 mois"], "a": "ACD", "e": "Congé non rémunéré, assimilé à du service effectif et non imputable sur le congé annuel. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Le congé pour formation syndicale :", "o": ["se demande par écrit au moins 15 jours à l'avance", "est réputé accordé à défaut de réponse expresse au plus tard le 15e jour précédant le stage", "est d'une durée maximale de 12 jours ouvrables par an, avec traitement", "est ouvert aux fonctionnaires stagiaires"], "a": "BC", "e": "Demande écrite au moins un mois à l'avance ; non ouvert aux stagiaires mais applicable aux policiers adjoints. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) syndicale pour congrès ou réunions d'organismes directeurs (anciennement article 13) : le contingent annuel par agent est de :", "o": ["12 jours ouvrables comme la formation syndicale", "10 jours, cumulables avec 20 jours supplémentaires", "10 jours, porté à 20 jours si le syndicat est représenté au conseil commun de la fonction publique, sans cumul", "20 jours pour tous les syndicats"], "a": "C", "e": "10 jours, ou 20 jours si le syndicat siège au CCFP (conseil commun de la fonction publique) ; ces deux contingents ne se cumulent pas. Demande au moins 3 jours à l'avance. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Rapatriement du corps d'un militaire ou marin « mort pour la France » : l'ASA (autorisation spéciale d'absence) est au maximum de :", "o": ["3 jours ouvrables pour un parent ou allié au 1er degré", "5 jours ouvrables quel que soit le degré", "1 jour ouvrable pour un parent ou allié au 2e ou 3e degré", "2 jours ouvrables pour un parent ou allié au 2e degré"], "a": "AC", "e": "3 jours (1er degré), 1 jour (2e ou 3e degré). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour soigner un enfant malade : l'âge limite des enfants est de :", "o": ["18 ans, quelle que soit la situation de l'enfant", "16 ans, y compris pour les enfants handicapés", "16 ans, sans limite d'âge pour les enfants handicapés", "12 ans, sans limite pour les enfants handicapés"], "a": "C", "e": "16 ans ; aucune limite pour les enfants handicapés. Décompte par année civile, par famille, sans report. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Un seul des conjoints bénéficie des ASA (autorisation spéciale d'absence) pour enfant malade. Si elles ne sont pas fractionnées, elles peuvent être portées à :", "o": ["15 jours consécutifs, et exceptionnellement 28 jours consécutifs", "8 jours consécutifs, et exceptionnellement 15 jours", "12 jours consécutifs au maximum", "28 jours consécutifs de droit"], "a": "A", "e": "15 jours consécutifs, voire 28 dans des cas exceptionnels (au-delà de 2 × OHS + 2 jours, imputation sur CA ou repos). Si les deux conjoints en bénéficient : 8 et 15 jours chacun. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Lors de l'annonce chez l'enfant d'un cancer, d'un handicap ou d'une pathologie chronique nécessitant un apprentissage thérapeutique, les parents peuvent bénéficier d'un congé de :", "o": ["5 jours ouvrables", "8 jours ouvrables", "3 jours ouvrables", "12 jours ouvrables"], "a": "A", "e": "Absence spécifique de 5 jours ouvrables ; liste des pathologies fixée par le décret n° 2023-215 du 27 mars 2023. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "L'ASA (autorisation spéciale d'absence) de 14 jours ouvrables pour le décès d'un enfant (au lieu de 12) est accordée :", "o": ["uniquement si l'enfant vivait au domicile de l'agent", "lorsque l'enfant est âgé de moins de 25 ans", "en cas de décès d'une personne de moins de 25 ans dont l'agent avait la charge effective et permanente", "quel que soit son âge, si l'enfant décédé était lui-même parent"], "a": "BCD", "e": "S'y ajoute une ASA complémentaire de 8 jours, fractionnable, à prendre dans l'année suivant le décès (L 622-2 CGFP). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "En cas de décès ou de maladie grave de la personne avec laquelle il est lié par un PACS, l'agent peut bénéficier d'une ASA (autorisation spéciale d'absence) de :", "o": ["3 jours ouvrables au maximum", "1 jour ouvrable au maximum", "5 jours ouvrables au maximum", "12 jours ouvrables de droit"], "a": "A", "e": "Conclusion d'un PACS : 5 jours ; décès ou maladie grave du partenaire : 3 jours. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Selon le nota de la synthèse sur les degrés de parenté, relèvent du 2e degré :", "o": ["le beau-père et la belle-mère", "les grands-parents et les petits-enfants", "le beau-frère et la belle-sœur", "les arrière-grands-parents"], "a": "BC", "e": "1er degré : père, mère, beau-père, belle-mère, enfants, beaux-enfants. 3e degré : oncle, tante, neveu, nièce, arrière-grands-parents, arrière-petits-enfants. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour fêtes religieuses (circulaire du 10 février 2012) : quelles affirmations sont exactes ?", "o": ["Les fêtes catholiques et protestantes font l'objet d'ASA spécifiques en plus des fêtes légales", "Les fêtes juives commencent le matin du jour concerné", "Roch Hachana (jour de l'an juif) est compté pour deux jours", "Les fêtes musulmanes étant fixées à un jour près, l'absence peut être accordée avec un décalage en plus ou en moins"], "a": "CD", "e": "Fêtes catholiques et protestantes : prises en compte par le calendrier des fêtes légales ; fêtes juives et musulmanes commencent la veille au soir. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Il est mis fin au congé parental :", "o": ["en cas de décès de l'enfant", "dès que l'enfant entre à l'école maternelle, sauf naissances multiples", "en cas de motif grave, laissé à l'appréciation de l'administration", "s'il n'est pas consacré à élever l'enfant"], "a": "ACD", "e": "Le congé parental prend fin au plus tard au 3e anniversaire ; c'est en cas de naissances multiples qu'il peut être prolongé jusqu'à l'entrée en maternelle. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 5, "s": "Après le congé de paternité ou d'adoption, le fonctionnaire a droit à un congé supplémentaire de naissance :", "o": ["de 11 jours, accordé uniquement en cas de naissance multiple", "de 25 jours calendaires, sans délai de prévenance", "de trois mois, renouvelable une fois", "d'un ou de deux mois, au choix, avec un délai de prévenance compris entre quinze jours et un mois"], "a": "D", "e": "Congé supplémentaire de naissance d'un ou deux mois ; délai de prévenance de 15 jours à un mois, réductible s'il suit immédiatement le congé. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences"}, {"t": 6, "s": "Ouverture d'un CET (compte épargne-temps) : quelles affirmations sont exactes ?", "o": ["Il faut avoir accompli au moins une année de service dans la fonction publique d'État", "La demande d'ouverture ne peut être faite qu'entre le 1er et le 31 janvier", "Un agent peut ouvrir plusieurs CET simultanément s'il a changé d'administration", "Les élèves en école, stagiaires et apprentis sont exclus du dispositif"], "a": "AD", "e": "Un seul CET à la fois ; la demande d'ouverture peut être faite à tout moment, c'est l'alimentation qui a lieu en janvier. — Source : Guide des principales règles de gestion du temps de travail (ARTT, CET)"}, {"t": 6, "s": "L'alimentation du CET (compte épargne-temps) s'effectue :", "o": ["entre le 1er et le 31 janvier, pour les congés de l'année précédente", "avant le 1er mai de l'année suivante", "entre le 1er et le 31 décembre de l'année en cours", "à tout moment de l'année"], "a": "A", "e": "Du 1er au 31 janvier pour les congés de l'année précédente, par journées complètes. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET)"}, {"t": 6, "s": "En régime hebdomadaire, verser des CA sur le CET (compte épargne-temps) suppose d'avoir pris dans l'année civile au moins :", "o": ["25 jours de CA", "15 jours de CA", "4/5e de la dotation, quel que soit le régime", "20 jours de CA"], "a": "D", "e": "20 jours (CA, HP, CAA, HPA, CAM compris) ; 4/5e de la dotation en cyclique ; 4 fois les obligations hebdomadaires à temps partiel. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET)"}, {"t": 6, "s": "Parmi les éléments suivants, lesquels peuvent alimenter le CET (compte épargne-temps) ?", "o": ["Les jours RTT, hors jours indemnisés et retenue pour la journée de solidarité", "Les RPS", "Le crédit férié", "L'équivalent de 5 jours maximum de repos compensateurs pour services supplémentaires"], "a": "AD", "e": "Ni le crédit férié, ni les RPS (repos de pénibilité spécifique), ni les jours reçus par don ne peuvent alimenter le CET. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET)"}, {"t": 6, "s": "Le stock du CET (compte épargne-temps) après alimentation est de 12 jours. Ces jours :", "o": ["ne sont utilisables que sous forme de congés", "peuvent être indemnisés dès le 1er jour", "doivent être pris avant le 31 décembre", "peuvent être versés à la RAFP"], "a": "A", "e": "CET ≤ 15 jours : utilisation uniquement en congés ; le droit d'option ne s'ouvre qu'à partir du 16e jour. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "CET (compte épargne-temps) entre 16 et 60 jours : pour les jours excédant 15, l'agent titulaire peut choisir :", "o": ["l'indemnisation à compter du 16e jour, par jours entiers", "le maintien sur le CET, dans la limite de 15 jours par an", "le versement au régime de retraite additionnelle (RAFP)", "l'indemnisation des 15 premiers jours"], "a": "AC", "e": "Maintien limité à 10 jours par an. Les 15 premiers jours ne sont utilisables qu'en congés ; RAFP (régime de retraite additionnelle de la fonction publique) réservée aux titulaires. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET)"}, {"t": 6, "s": "Le plafond global du CET (compte épargne-temps) pérenne (hors dérogations COVID et JOP) est de :", "o": ["40 jours", "70 jours", "80 jours", "60 jours"], "a": "D", "e": "60 jours ; les dérogations COVID/JOP permettent un solde jusqu'à 80 jours, sans nouvelle alimentation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Un agent contractuel a atteint la limite des 60 jours sur son CET (compte épargne-temps). Les jours épargnés au-delà :", "o": ["sont perdus", "peuvent seulement être indemnisés", "peuvent être indemnisés ou versés à la RAFP", "peuvent être maintenus jusqu'à 80 jours"], "a": "B", "e": "Plafond atteint : indemnisation ou RAFP (régime de retraite additionnelle de la fonction publique), mais les contractuels n'ont que l'indemnisation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Indemnisation d'un jour de CET (compte épargne-temps) pour un agent de catégorie B :", "o": ["100 €", "150 €", "125 €", "83 €"], "a": "A", "e": "Catégorie A : 150 €, B : 100 €, C : 83 € par jour. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Lorsque l'agent accole des jours CET (compte épargne-temps) à des CA ou des RTT (réduction du temps de travail), il peut s'absenter plus de 31 jours consécutifs :", "o": ["jamais", "de plein droit", "sous réserve des besoins du service et de l'avis du supérieur hiérarchique", "uniquement pour un congé bonifié"], "a": "C", "e": "Exception à la limite des 31 jours, sous réserve des besoins du service et de l'avis hiérarchique. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le temps partiel de droit pour élever un enfant peut être accordé :", "o": ["à 50, 60, 70 ou 80 %, jusqu'au 6e anniversaire", "à 50 ou 80 % uniquement, sous réserve des nécessités de service", "à 50, 60, 70, 80 ou 90 %, jusqu'au 3e anniversaire", "à 50, 60, 70 ou 80 %, jusqu'au 3e anniversaire de l'enfant"], "a": "D", "e": "Le 90 % n'existe que pour le temps partiel sur autorisation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Temps partiel sur autorisation : quelles affirmations sont exactes ?", "o": ["Les quotités possibles vont de 50 % à 90 %", "Il est accordé de droit, sans condition de service", "Le chef de service peut s'opposer aux modalités d'organisation sollicitées", "Tout refus doit être précédé d'un entretien"], "a": "ACD", "e": "Il est accordé sous réserve des nécessités, de la continuité et du fonctionnement du service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "En régime cyclique, le temps partiel s'organise :", "o": ["au choix de l'agent, quotidiennement ou annuellement", "par diminution de la durée de chaque vacation", "dans un cadre annuel, par l'octroi de jours non travaillés", "uniquement par semaines non travaillées"], "a": "C", "e": "Il est impossible en cyclique de réduire la durée de la vacation ; en hebdomadaire, réduction quotidienne ou du nombre de vacations. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Agent à temps partiel : quelles affirmations sont exactes ?", "o": ["Les droits à congés sont proportionnels à la quotité", "Un jour férié coïncidant avec un jour non travaillé ne donne pas lieu à congé supplémentaire", "Les jours de fractionnement sont attribués comme pour un temps plein", "Un CMO suspend l'autorisation de temps partiel"], "a": "ABC", "e": "CMO (congé de maladie ordinaire), CLM (congé de longue maladie) et CLD (congé de longue durée) n'ont aucun effet sur l'autorisation de temps partiel (ni suspension ni interruption). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Un agent travaillant à temps partiel ne peut pas être placé d'astreinte :", "o": ["la nuit suivant une journée non travaillée", "en aucun cas", "sur la journée ou demi-journée non travaillée du temps partiel (6 h – 21 h)", "un jour férié coïncidant avec son jour non travaillé"], "a": "C", "e": "L'astreinte de nuit (21 h – 6 h) qui suit la journée non travaillée reste possible ; si le jour non travaillé est un JF (jour férié), l'astreinte est possible. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Congé de maladie ordinaire : quelles affirmations sont exactes ?", "o": ["Le certificat médical est transmis au chef de service dans un délai de 48 heures", "L'agent se présente au médecin statutaire à sa reprise s'il totalise 45 jours de maladie sur douze mois", "Après 6 mois consécutifs, le comité médical donne son avis sur la prolongation", "Le traitement est de 90 % pendant trois mois, puis de moitié pendant neuf mois"], "a": "ACD", "e": "Le seuil est de 30 jours de maladie, en une ou plusieurs fois, sur douze mois consécutifs. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "En cas de nouvel envoi tardif d'un arrêt de travail dans les 24 mois suivant un premier retard signalé :", "o": ["le congé n'est pas reconnu", "l'agent perd 1/24e de son crédit férié", "l'agent est sanctionné disciplinairement d'office", "la rémunération de la période entre l'établissement et l'envoi de l'avis est réduite de moitié"], "a": "D", "e": "Réduction de moitié de la rémunération afférente à la période écoulée entre l'établissement et l'envoi. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le congé de longue maladie (CLM) :", "o": ["a une durée maximale de 5 ans : plein traitement trois ans", "a une durée maximale d'un an", "est accordé par périodes de 1 à 3 mois", "a une durée maximale de 3 ans : plein traitement un an, demi-traitement deux ans"], "a": "D", "e": "CLM : 3 ans (1 an plein, 2 ans demi), par périodes de 3 à 6 mois. CLD (congé de longue durée) : 5 ans (3 ans plein, 2 ans demi). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Avant de reprendre ses fonctions à l'issue d'un CLM (congé de longue maladie) ou d'un CLD (congé de longue durée), l'agent doit :", "o": ["seulement présenter un certificat de son médecin traitant", "attendre l'avis du chef de service", "passer un test de tir", "être reconnu apte après examen par un spécialiste agréé et avis favorable du comité médical"], "a": "D", "e": "Aptitude après examen par un spécialiste agréé et avis favorable du comité médical compétent. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Exemption pour don du sang : une femme fonctionnaire de police peut effectuer au maximum dans l'année :", "o": ["6 dons de sang total, espacés d'au moins 8 semaines", "12 dons de sang total, espacés d'au moins 4 semaines", "4 dons de sang total, espacés d'au moins 4 semaines", "4 dons de sang total, espacés d'au moins 8 semaines"], "a": "D", "e": "Sang total : 6 (homme) ou 4 (femme), 8 semaines ; plaquettes 12/an, 4 semaines ; plasma 24/an, 2 semaines. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Utilisation des jours placés sur le CET (compte épargne-temps) pérenne comme congés : quelles affirmations sont exactes ?", "o": ["Ils ne peuvent être pris qu'à partir de 5 jours consécutifs", "Aucun délai de préavis n'est imposé, sous réserve des nécessités de service", "Ils peuvent être pris par demi-journée, sans rendre le solde négatif", "Ils sont utilisables dès le 1er jour épargné, quel que soit le nombre de jours épargnés"], "a": "BCD", "e": "Utilisation toute l'année dès le 1er jour, par demi-journée possible, sans préavis ; accord du supérieur, refus motivé. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le CET (compte épargne-temps) dit « historique » :", "o": ["ne peut plus être alimenté", "n'ouvre droit à l'indemnisation qu'au-delà de 60 jours", "concerne les jours épargnés avant 2009", "peut être fusionné avec un CET pérenne sur demande"], "a": "AC", "e": "La fusion historique/pérenne n'est plus autorisée ; au-delà des 15 premiers jours : congés, indemnisation et/ou RAFP (titulaires). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "En cas de décès d'un agent disposant d'un CET (compte épargne-temps), ses ayants droit bénéficient :", "o": ["d'aucune indemnisation, les jours étant perdus", "d'un versement des jours au RAFP", "d'une indemnisation limitée aux jours excédant 15", "d'une indemnisation de l'ensemble des jours déposés sur le CET"], "a": "D", "e": "L'indemnisation des ayants droit porte sur l'ensemble des jours du CET. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Temps partiel de droit pour raisons familiales : le chef de service est en désaccord avec les modalités d'organisation demandées. Il :", "o": ["peut refuser le temps partiel pour nécessité de service", "transmet la demande au comité médical", "ne peut s'opposer au temps partiel lui-même, mais peut s'opposer aux modalités, et transmet la demande en motivant son opposition et en proposant un changement d'affectation", "doit accepter les modalités demandées sans discussion"], "a": "C", "e": "Après entretien, il transmet la demande en motivant son opposition et en proposant un changement d'affectation. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "La demande de temps partiel doit être déposée :", "o": ["au moins 1 mois avant, directement auprès du chef de service qui décide seul", "au moins 15 jours avant, auprès de la DRHFS", "au moins 2 mois avant le début de la période souhaitée, auprès du SGAMI compétent sous couvert de la voie hiérarchique", "au moins 3 mois avant, auprès du médecin de prévention"], "a": "C", "e": "Délai de 2 mois ; la demande précise la période, la quotité et le mode d'organisation ; avis du chef de service. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Un jour férié coïncide avec un jour non travaillé du fait du temps partiel :", "o": ["le jour férié est reporté sur le jour travaillé suivant", "aucun congé supplémentaire n'est attribué en compensation", "l'agent bénéficie d'un RCSS de 7 heures", "l'agent bénéficie d'un jour de congé supplémentaire"], "a": "B", "e": "Pas de compensation. Les droits à congés sont proportionnels à la quotité. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Un agent à temps partiel est désigné pour une formation organisée par l'administration qui ne peut être suivie à temps partiel (ex. : formation OPJ (officier de police judiciaire)) :", "o": ["la formation lui est refusée en raison de sa quotité", "l'agent est rétabli dans les droits d'un agent à temps plein pendant la formation", "l'autorisation de temps partiel est suspendue pendant la formation", "une journée non travaillée non prise du fait de la formation est décalée avec une majoration de 25 %"], "a": "BC", "e": "La journée non travaillée non prise est décalée sans majoration, dans les plus brefs délais. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Pendant un congé de maternité, de paternité ou d'adoption, l'agent à temps partiel :", "o": ["est rétabli dans les droits d'un agent à temps plein, le temps partiel étant suspendu et reporté à l'issue du congé", "conserve sa quotité, le congé étant proratisé", "doit déposer une nouvelle demande de temps partiel deux mois avant la fin du congé", "perd définitivement son autorisation de temps partiel"], "a": "A", "e": "Temps partiel suspendu et reporté ; il s'apprécie en durée et non de date à date. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "S'agissant des droits à formation d'un agent à temps partiel, quelle affirmation est exacte ?", "o": ["Les droits du compte personnel de formation ne sont pas proratisés", "Les formations ne sont accessibles que sur les jours non travaillés", "Les droits du CPF sont proratisés selon la quotité", "L'agent n'a pas accès aux formations de l'administration"], "a": "A", "e": "Mêmes droits qu'à temps plein, sans proratisation du CPF (compte personnel de formation). — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le don de jours de repos à un agent assumant la charge d'un enfant de moins de 25 ans gravement malade :", "o": ["entraîne une réduction de moitié de la rémunération du bénéficiaire", "est limité à 90 jours par enfant et par année civile pour le bénéficiaire", "oblige l'administration à informer le bénéficiaire dans un délai de 15 jours ouvrables", "peut porter sur des repos compensateurs d'heures supplémentaires, d'astreintes ou de permanences"], "a": "BC", "e": "Les RC (repos compensateur) d'HS (heures supplémentaires), astreintes ou permanences ne peuvent pas être donnés ; rémunération maintenue ; congé fractionnable à la demande du médecin. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Agent à temps partiel placé d'astreinte : la restitution du temps d'astreinte :", "o": ["est impossible, l'astreinte étant interdite à temps partiel", "est calculée sur la base des heures effectuées, donc proratisée", "est identique à celle d'un agent à temps plein, sans proratisation", "est doublée pour compenser la quotité"], "a": "B", "e": "Permanence et astreinte sont possibles indépendamment de la quotité ; restitution proratisée. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le congé pour invalidité temporaire imputable au service (CITIS), une fois accordé :", "o": ["est limité à 1 an renouvelable une fois", "est limité à 3 ans", "n'a pas de durée maximale et se prolonge jusqu'à la reprise du service ou la mise en retraite", "est limité à 6 mois à plein traitement"], "a": "C", "e": "Le CITIS n'a pas de durée maximale ; l'agent conserve l'intégralité de sa rémunération et ses droits à l'avancement. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Le temps partiel pour création ou reprise d'entreprise peut être autorisé pour une durée maximale de :", "o": ["1 an, renouvelable deux fois", "3 ans, renouvelable pour une durée d'un an", "2 ans, non renouvelable", "5 ans, renouvelable une fois"], "a": "B", "e": "Autorisation de l'autorité hiérarchique pour un fonctionnaire à temps complet ; 3 ans + 1 an à compter de la création ou reprise. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "La retraite progressive permet, à compter de :", "o": ["60 ans, de percevoir une fraction de sa pension tout en exerçant une activité réduite à temps partiel", "62 ans, de réduire son activité sans perte de rémunération", "50 ans pour les actifs, de percevoir une pension partielle", "55 ans, de cumuler pension complète et temps plein"], "a": "A", "e": "Dispositif ouvert à compter de 60 ans. — Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026)"}, {"t": 6, "s": "Selon le guide de gestion du temps de travail, l'accident survenu au cours du service de sapeur-pompier volontaire d'un policier :", "o": ["est imputé sur les congés annuels de l'agent", "est reconnu en tant que blessure en service police nationale", "relève du congé de maladie ordinaire", "n'est couvert que par le SDIS, sans incidence pour la police"], "a": "B", "e": "Loi n° 91-1389 du 31 décembre 1991 modifiée (art. 19). — Source : Guide des principales règles de gestion du temps de travail"}, {"t": 7, "s": "Selon l'instruction DGPN (direction générale de la police nationale) n°3/2024, l'arme individuelle est dite « de service » lorsqu'elle est :", "o": ["une arme d'épaule en dotation collective", "remise à titre temporaire à un policier adjoint, un réserviste ou un élève polytechnicien mis à disposition", "utilisée exclusivement en service", "détenue par un fonctionnaire actif tout au long de sa carrière"], "a": "B", "e": "L'arme individuelle est conservée par le policier actif toute sa carrière ; l'arme de service est remise temporairement et déposée à la fin de chaque vacation. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Un policier actif est détaché hors du périmètre du ministère de l'Intérieur. Son arme individuelle :", "o": ["peut être conservée s'il exerce des missions sensibles", "peut être conservée sur autorisation de la DRHFS", "peut être conservée pour le tir sportif uniquement", "doit être restituée à son administration d'origine"], "a": "D", "e": "Détaché hors MI : restitution obligatoire. Le régime d'autorisation concerne les policiers mis à disposition ou affectés hors périmètre DGPN (direction générale de la police nationale), DGSI (direction générale de la sécurité intérieure) ou PP (préfecture de police). — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "En service, quelles règles s'appliquent au port de l'arme individuelle ?", "o": ["Le port dans la boîte à gants du véhicule est autorisé pour les trajets", "Il s'accompagne du port du gilet pare-balles, sauf dispense exceptionnelle et motivée", "En uniforme, l'arme est portée dans un étui administratif", "L'arme est mise en service avec une cartouche chambrée"], "a": "BCD", "e": "Le port et le transport dans des contenants non agréés (sac à dos, sac à main, boîte à gants…) sont proscrits. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "La formation continue à l'emploi de l'arme individuelle consiste en :", "o": ["deux séances de 45 cartouches", "trois séances de 60 cartouches", "quatre séances de 30 cartouches", "trois séances permettant le tir de 90 cartouches minimum par an"], "a": "D", "e": "Trois séances, 90 cartouches minimum, réparties sur l'année, appréciées sur une année glissante. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service ; Arrêté TSI du 27/07/2015 art. 5"}, {"t": 7, "s": "L'obligation de tir annuel s'apprécie sur une année « glissante », c'est-à-dire :", "o": ["les six derniers mois", "les douze derniers mois à compter de la date d'entretien professionnel", "l'année scolaire de septembre à août", "l'année civile"], "a": "B", "e": "Douze derniers mois à compter de l'entretien professionnel (ou de la déclaration de port hors service). — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Un agent n'a effectué aucun tir au cours des douze derniers mois. Que prévoit l'instruction ?", "o": ["Il est convoqué dès le début de l'année suivante à une formation complémentaire dispensée par les FTSI", "En cas d'inaptitude, l'arme lui est retirée par la hiérarchie", "Il est automatiquement sanctionné", "Des séances de manipulation dans le service remplacent les tirs manqués"], "a": "AB", "e": "Les séances de manipulation ne se substituent en aucun cas aux tirs annuels réglementaires. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "L'article L.435-1 du CSI (code de la sécurité intérieure) permet l'usage de l'arme, en cas d'absolue nécessité et de manière strictement proportionnée, notamment :", "o": ["pour interpeller tout auteur de délit en fuite", "lorsque des atteintes à la vie ou à l'intégrité physique sont portées contre les agents ou autrui", "lorsque, après deux sommations faites à haute voix, ils ne peuvent défendre autrement les lieux qu'ils occupent", "pour immobiliser un véhicule dont le conducteur refuse d'obtempérer, quelle que soit la dangerosité des occupants"], "a": "BC", "e": "Le 4° exige que les occupants soient susceptibles de perpétrer, dans leur fuite, des atteintes à la vie ou à l'intégrité physique. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Pour pouvoir faire usage de leurs armes au titre de l'article L.435-1 du CSI (code de la sécurité intérieure), les policiers doivent être :", "o": ["sur ordre d'un officier", "dans l'exercice de leurs fonctions et revêtus de leur uniforme ou des insignes extérieurs et apparents de leur qualité", "porteurs d'un gilet pare-balles", "en service et en uniforme uniquement"], "a": "B", "e": "Exercice des fonctions + uniforme ou insignes apparents ; le cadre s'applique hors service lorsque le policier agit dans le cadre de ses fonctions. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le 5° de l'article L.435-1 du CSI (code de la sécurité intérieure) vise l'usage de l'arme :", "o": ["contre une personne cherchant à échapper à la garde", "dans le but exclusif d'empêcher la réitération, dans un temps rapproché, d'un ou plusieurs meurtres ou tentatives venant d'être commis", "pour défendre les personnes confiées après deux sommations", "contre un véhicule en fuite"], "a": "B", "e": "Le 5° (périple meurtrier) suppose des raisons réelles et objectives d'estimer la réitération probable. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Les tirs volontaires de dissuasion (vers le sol ou en l'air) :", "o": ["sont toujours interdits", "sont autorisés après deux sommations", "ne peuvent être motivés que par une absolue nécessité de protéger l'intégrité physique face à un péril imminent (état de nécessité)", "relèvent de l'article L.435-1 2°"], "a": "C", "e": "Ils relèvent de l'état de nécessité (art. 122-7 CP) ; à défaut, ils peuvent constituer un usage disproportionné de la force. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Après tout usage de l'arme, volontaire ou involontaire, le policier :", "o": ["informe uniquement l'OPJ", "renseigne sans délai la déclaration individuelle via le TSUA, visée par la hiérarchie", "rédige un rapport dans les 8 jours", "ne déclare que les tirs volontaires"], "a": "B", "e": "Déclaration TSUA (traitement relatif au suivi de l'usage des armes) sans délai, visée par la hiérarchie ; le responsable veille à la santé physique et mentale de l'agent (soutien psychologique). — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Tir sportif avec l'arme individuelle (art. R.411-3-1 du CSI (code de la sécurité intérieure)) : quelles conditions sont exactes ?", "o": ["Une limite de 5 000 cartouches par période de douze mois", "Une déclaration écrite préalable au chef de service", "Utiliser exclusivement des munitions manufacturées à balles ordinaires chemisées", "Être à jour de ses obligations de tir réglementaire"], "a": "BCD", "e": "La limite est de 3 000 cartouches par période de douze mois. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service ; Déclaration préalable d'intention de tir sportif"}, {"t": 7, "s": "Lors d'un dépôt ou d'un stockage, la mise en sécurité d'un pistolet automatique impose :", "o": ["de retirer le chargeur, de ne laisser aucune cartouche chambrée et de positionner le témoin de chambre vide de manière apparente", "de retirer le ressort de percussion", "de désarmer le chien et de laisser une cartouche chambrée", "de retirer seulement le chargeur"], "a": "A", "e": "Pour un revolver : cartouches retirées du barillet. À l'armurerie, le SIG SAUER est neutralisé par retrait du canon, le revolver par retrait du ressort de percussion. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "À l'armurerie, les armes stockées sont neutralisées par retrait d'une pièce essentielle. Pour le pistolet SIG SAUER, il s'agit :", "o": ["de la culasse", "du canon", "du chargeur", "du ressort de percussion"], "a": "B", "e": "Canon pour le SIG SAUER, ressort de percussion pour les revolvers, pièce entreposée dans une armoire forte distincte. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Conservation des armes dans un service fermé la nuit : par dérogation décidée par la direction d'emploi, quelles prescriptions s'appliquent ?", "o": ["Munitions des armes d'épaule dans une armoire forte distincte", "Toutes les armes peuvent être regroupées dans une même armoire forte", "Armes individuelles dans des armoires fortes dédiées", "AFI et armes d'épaule dans des armoires fortes distinctes des armes individuelles"], "a": "ACD", "e": "Principe : conservation prohibée ; en dérogation, armoires distinctes + protections mécaniques et électroniques. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le port de l'arme individuelle sur le trajet domicile-travail :", "o": ["nécessite une déclaration écrite à chaque trajet", "est autorisé par principe, sans déclaration spécifique", "nécessite une séance de tir dans le mois précédent", "est interdit sauf autorisation du chef de service"], "a": "B", "e": "Le trajet domicile-travail ne nécessite pas de déclaration ; le port hors service, si. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Port de l'arme hors service : quelles conditions sont exigées ?", "o": ["Avoir effectué les tirs réglementaires au cours des 12 mois précédents", "Une déclaration préalable écrite au chef de service", "Une autorisation renouvelée chaque année par le préfet", "Avoir effectué au moins une séance de tir dans les quatre derniers mois"], "a": "ABD", "e": "La déclaration est faite à la primo-affectation puis à chaque nouvelle affectation ; le chef de service peut s'opposer ou interdire a posteriori. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Lorsqu'il porte son arme hors service, le policier détient obligatoirement :", "o": ["sa carte professionnelle et un brassard police", "un gilet pare-balles", "sa tenue d'uniforme", "une radio"], "a": "A", "e": "Carte professionnelle et brassard ; en intervention, il revêt le brassard et, dans la mesure du possible, le gilet pare-balles. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Hors service, à son domicile, le policier doit conserver son arme :", "o": ["dans la boîte à gants de son véhicule personnel", "en la séparant toujours de ses munitions", "dans un sac fermé à clé", "chargée, à portée de main"], "a": "B", "e": "La responsabilité couvre le port et la conservation hors service ; l'arme est toujours séparée de ses munitions. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le choix d'un étui non fourni par l'administration, en tenue civile, est soumis à :", "o": ["l'accord du RAM", "une autorisation expresse du chef de service, précédée d'une séance de tir organisée par les FTSI", "une simple déclaration", "aucune condition"], "a": "B", "e": "Autorisation expresse + séance de tir FTSI (formateur aux techniques et à la sécurité en intervention) validant l'appropriation de l'accessoire. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le port et la détention de l'arme individuelle sont autorisés :", "o": ["sur le territoire de l'Union européenne sans formalité", "sur le seul territoire national, sauf circonstances particulières prévues par les conventions internationales (droit de suite, patrouilles mixtes, missions à l'étranger)", "partout, dès lors que le policier a déclaré le port hors service", "sur le territoire national et dans les pays de l'espace Schengen"], "a": "B", "e": "Principe : territoire national ; dérogations conventionnelles (droit de suite, patrouilles mixtes, policiers en mission à l'étranger). — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Casiers individuels sécurisés de dépôt des armes : quelles exigences sont exactes ?", "o": ["Les policiers adjoints et réservistes disposent obligatoirement de la clef de leur casier", "Ils comportent au moins deux compartiments, l'un pour l'arme, l'autre pour les chargeurs et/ou munitions", "Ils portent les nom, prénom, matricule et numéro de série de l'arme du policier", "Le RAM ou son représentant dispose d'un double de chacune des clefs"], "a": "BCD", "e": "PA (policiers adjoints), réservistes et élèves polytechniciens, astreints au dépôt, ne doivent pas disposer de la clef ; leurs casiers sont spécialement identifiés. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Dans tous les services, les lieux de dépôt des armes doivent comprendre ou être installés à proximité :", "o": ["d'une zone de neutralisation, avec au minimum un puits balistique souple", "d'un stand de tir agréé", "du bureau du chef de service", "d'une armoire forte distincte pour les munitions des armes de poing"], "a": "A", "e": "Zone de neutralisation avec au minimum un puits balistique souple, permettant dépôt/retrait en sécurité et déploiement rapide. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Pour certaines missions (présentations consulaires, entrée dans un bureau de vote), un policier peut conserver provisoirement son arme dans le coffre sécurisé du véhicule léger de service :", "o": ["à condition que l'arme soit démontée", "sous réserve qu'un policier en assure la surveillance constante et effective", "sans condition, le coffre étant sécurisé", "uniquement avec l'accord écrit du préfet"], "a": "B", "e": "Dérogation provisoire et limitée : coffre sécurisé (VL) ou râtelier adapté (véhicule collectif), sous surveillance constante et effective. Une note de la direction d'emploi précise les missions. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "La traçabilité des mouvements d'armes par registre signé contradictoirement :", "o": ["s'applique aux policiers actifs ne disposant pas de casier individuel", "s'applique aux armes de service des PA, réservistes et élèves polytechniciens, même s'ils disposent d'un casier", "ne concerne pas les armes des policiers actifs qui disposent d'un casier individuel", "est facultative lorsque le service dispose d'une armurerie"], "a": "ABC", "e": "Le registre (papier ou numérique) est signé par un représentant de la hiérarchie et l'agent à chaque dépôt ou retrait. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Les trois types de contrôles hiérarchiques des armes individuelles sont :", "o": ["le contrôle balistique annuel par le service national de police scientifique", "le contrôle physique à partir d'une liste nominative des agents et numéros d'armes", "le contrôle des registres de mouvements d'armes", "le contrôle du bon état de fonctionnement par le RAM ou la personne faisant office"], "a": "BCD", "e": "Contrôles réguliers et inopinés des stocks et des flux ; périodicité fixée par les directions d'emploi ou zonales. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Parmi les situations suivantes, lesquelles imposent la restitution de l'arme individuelle ?", "o": ["Un congé de maladie ordinaire de quinze jours", "Une exclusion temporaire de fonctions, quelle que soit sa durée", "Un congé de maternité ou de paternité", "Un détachement à l'ENSP après réussite à un concours"], "a": "BC", "e": "Restitution notamment : cessation d'activité, exclusion temporaire, contrôle judiciaire, disponibilité, CLM (congé de longue maladie)/CLD, congés parentaux/maternité/paternité/adoption, mutation en COM. Le détachement à l'ENSP (école nationale supérieure de la police) est une exception. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le dispositif « Voyager-Protéger » :", "o": ["est entré en vigueur le 1er janvier 2022", "est ouvert aux gardiens de la paix dès leur nomination en qualité de stagiaire", "impose au policier de se présenter au chef de bord et de porter son arme individuelle", "est ouvert aux policiers adjoints et aux réservistes"], "a": "ABC", "e": "Gratuité sur certains réseaux SNCF (domicile-travail et déplacements privés), réservée aux trois corps actifs, à l'exclusion des PA (policiers adjoints) et réservistes ; étendue aux policiers mis à disposition hors DGPN (direction générale de la police nationale)/DGSI/PP. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Porteur de son arme hors service, un policier accède à un établissement recevant du public soumis à un filtrage :", "o": ["il ne peut à aucun moment se séparer de son arme, qui doit être portée de façon non visible", "l'établissement peut lui refuser l'accès au seul motif qu'il est armé", "il doit la laisser dans son véhicule personnel verrouillé", "il remet son arme au service de sécurité de l'établissement contre un récépissé"], "a": "A", "e": "Le seul port de l'arme ne peut lui être opposé ; il ne s'en sépare jamais ; arme non visible. Hors domicile, il est proscrit de laisser l'arme là où le policier ne se trouve pas. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Un policier en poste à l'étranger, ayant des missions de police, ne peut accéder à aucune infrastructure de tir. Selon l'instruction n°3/2024 :", "o": ["il doit effectuer ses 90 cartouches lors de chaque congé en France", "des séances régulières de manipulation de son arme se substituent, à titre dérogatoire, aux séances annuelles de tir réglementaire", "son arme lui est retirée jusqu'à son retour", "il est dispensé de toute formation continue"], "a": "B", "e": "Seule exception où la manipulation remplace le tir ; dans les autres cas, les séances de manipulation ne se substituent jamais aux tirs réglementaires. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Le suivi des tirs réglementaires :", "o": ["relève exclusivement du RAM, sans incidence sur l'évaluation", "constitue un indicateur de performance des services", "est un critère pris en considération dans l'évaluation annuelle de l'agent et de celui qui encadre", "peut constituer un objectif individuel"], "a": "BCD", "e": "Le nombre de tirs effectués par l'agent ou par les agents qu'il encadre est pris en compte dans l'évaluation et peut devenir un objectif individuel. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Les missions confiées à un policier justifient le port de deux armes de poing ou plus. Il peut les conserver et les utiliser :", "o": ["sur simple déclaration à son chef de service", "sans formalité si les deux armes sont des armes administratives", "par décision expresse, individuelle et écrite de son chef de service", "après accord du préfet de département"], "a": "C", "e": "Exception subordonnée à une décision expresse, individuelle et écrite du chef de service. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 7, "s": "Lors d'une interruption temporaire de travail supérieure au repos de cycle ou au repos hebdomadaire, le policier qui n'a pas déclaré le port hors service :", "o": ["doit la remettre au SGAMI", "peut la conserver à son domicile sans formalité", "peut continuer à la porter sur ses trajets", "doit déposer son arme individuelle au service"], "a": "D", "e": "Le trajet domicile-travail ne nécessite pas de déclaration, mais l'arme est déposée lors d'interruptions supérieures au repos de cycle ou hebdomadaire. — Source : Instruction DGPN n°3/2024 – arme individuelle ou de service"}, {"t": 8, "s": "Le pistolet mitrailleur 9 mm en dotation dans la police nationale est :", "o": ["une arme de poing en dotation individuelle", "une arme individuelle d'épaule en dotation collective, classée en catégorie A2", "une arme d'épaule de catégorie B", "une arme de force intermédiaire"], "a": "B", "e": "PM (pistolet-mitrailleur) : arme individuelle d'épaule en dotation collective, catégorie A2, tirant la cartouche opérationnelle de police 9 x 19 mm. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Selon la position du sélecteur, le PM (pistolet-mitrailleur) 9 mm permet généralement le tir :", "o": ["en rafale contrôlée de quatre ou cinq cartouches", "en semi-automatique (coup par coup)", "en rafale libre (répétition automatique)", "uniquement au coup par coup"], "a": "BC", "e": "Rafale contrôlée de deux ou trois cartouches. Le PM permet les trois modes ; le HK G36, lui, est limité au coup par coup et à la rafale de deux coups. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "L'affectation temporaire d'un PM (pistolet-mitrailleur) 9 mm concerne :", "o": ["exclusivement les policiers actifs et les réservistes statutaires titulaires d'une habilitation en cours de validité", "tous les policiers actifs et les policiers adjoints", "les seuls effectifs de la BAC", "tout policier sur simple autorisation orale"], "a": "A", "e": "Conditions cumulatives : habilitation valide, besoins de la mission, autorisation et contrôle hiérarchique. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "L'emploi du PM (pistolet-mitrailleur) 9 mm en opération de maintien de l'ordre public en unité constituée est :", "o": ["autorisé sur ordre de l'AHEF", "autorisé en cadre de réaction", "proscrit", "autorisé avec binôme superviseur"], "a": "C", "e": "Emploi proscrit en MO en unité constituée. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Le PM (pistolet-mitrailleur) 9 mm est destiné :", "o": ["aux missions courantes à caractère sensible ou présentant une certaine dangerosité", "à la riposte contre des individus porteurs de gilets pare-balles uniquement", "au maintien de l'ordre", "exclusivement aux interventions de 3e niveau"], "a": "A", "e": "Il n'exclut pas la primo-intervention pour faire cesser une tuerie de masse si les policiers ne sont pas dotés du HK G36. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Quelles règles générales de sécurité (RGS) sont rappelées pour les armes d'épaule ?", "o": ["Diriger le canon vers une zone de sécurité lors des manipulations", "Garder l'index le long du pontet tant qu'il n'y a pas nécessité de tirer", "Considérer toujours l'arme comme chargée", "Garder l'index sur la détente dès que l'arme est perçue"], "a": "ABC", "e": "Index le long du pontet tant qu'il n'y a pas nécessité de tirer. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm ; Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Lors de la perception ou de la réintégration, l'arme d'épaule est présentée :", "o": ["sans contrôle des munitions", "chargeur engagé, canon vers le sol", "culasse ouverte, chargeur engagé", "mise en sécurité, culasse refermée sur le témoin de chambre vide ou bloquée à l'arrière, canon vers le haut, puits de chargeur vers le réceptionnaire"], "a": "D", "e": "Dispositifs de mise en sécurité obligatoires dans les locaux (tubes de manipulation, puits balistiques) ; munitions contrôlées à la remise. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm ; Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Le fusil d'assaut HK G36 a été déployé principalement pour :", "o": ["riposter efficacement contre des individus lourdement armés, souvent porteurs de gilets pare-balles pouvant arrêter le 9 mm", "les missions courantes de police-secours", "le maintien de l'ordre", "remplacer le SIG SAUER"], "a": "A", "e": "Réponse aux actes de violence ou de terrorisme à cinétique rapide ; le 9 mm peut être arrêté par certains gilets. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Le HK G36 équipe en priorité :", "o": ["les policiers adjoints", "les unités de maintien de l'ordre", "les intervenants de 2e ou 3e niveau", "tous les primo-intervenants"], "a": "C", "e": "Arme individuelle d'épaule en dotation collective destinée aux intervenants de 2e ou 3e niveau. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Le sélecteur de tir du HK G36 permet :", "o": ["la rafale de trois coups", "la sûreté manuelle, le coup par coup et la rafale limitée à deux coups", "la sûreté, le coup par coup et la rafale libre", "la sûreté et le coup par coup uniquement"], "a": "B", "e": "Le tir en rafale doit rester exceptionnel ; le choix du mode appartient au porteur. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "L'approvisionnement du HK G36 s'effectue par :", "o": ["quatre chargeurs de 30 cartouches", "six boîtiers-chargeurs de 30 cartouches", "trois chargeurs de 30 cartouches", "six chargeurs de 20 cartouches"], "a": "B", "e": "Six boîtiers-chargeurs d'une capacité théorique de 30 cartouches. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Missions courantes : le HK G36 est transporté dans le coffre du véhicule léger. Dans quelles conditions ?", "o": ["Aucune cartouche chambrée et sélecteur sur la sûreté manuelle", "Aucun chargeur engagé", "Chargeur engagé pour gagner du temps", "Culasse ouverte et verrouillée vers l'arrière"], "a": "AB", "e": "Transport culasse fermée, sans chargeur engagé ni cartouche chambrée. En missions courantes, l'arme n'est pas portée mais transportée, non approvisionnée. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Port du HK G36 dans l'habitacle d'un véhicule :", "o": ["sélecteur sur coup par coup, canon vers la portière", "canon dirigé vers le pavillon, sans ceinture", "sélecteur sur sûreté, canon dirigé vers le plancher, ceinture de sécurité interposée entre l'arme et le porteur", "arme posée sur le tableau de bord"], "a": "C", "e": "La ceinture interposée réduit les risques de blessure en cas d'arrêt brutal ; port avec gilet porte-plaques. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "L'emploi du HK G36 en maintien de l'ordre en unité constituée est :", "o": ["proscrit, hors cas de légitime défense ou d'état de nécessité", "toujours interdit, y compris en légitime défense", "autorisé avec binôme", "autorisé sur ordre"], "a": "A", "e": "Proscrit hors légitime défense ou état de nécessité. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Légitime défense des biens : l'usage de l'arme dans l'intention de tuer l'auteur d'une atteinte à un bien est :", "o": ["autorisé après deux sommations", "autorisé si le bien est de grande valeur", "strictement prohibé, même dans le temps de l'atteinte", "autorisé en cas de crime"], "a": "C", "e": "La légitime défense des biens exclut l'homicide volontaire. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Le TSUA (traitement relatif au suivi de l'usage des armes) doit être renseigné :", "o": ["uniquement pour les tirs mortels", "au plus près de l'action caractérisée par une unité de temps, de lieu et d'action", "à la fin du mois", "dans un délai de 30 jours"], "a": "B", "e": "Déclaration au plus près de l'action, appréciée au regard des contraintes opérationnelles. — Source : Instruction DGPN du 19/12/2011 – TSUA"}, {"t": 8, "s": "Concernant le TSUA (traitement relatif au suivi de l'usage des armes), quelles affirmations sont exactes ?", "o": ["Un collègue habilité peut déclarer pour le compte de l'agent indisponible", "Le rapport du déclarant est un champ de texte libre dont l'alimentation est obligatoire", "Les noms des mis en cause doivent figurer dans le rapport", "Les tirs d'entraînement et de formation ne doivent pas y être déclarés"], "a": "ABD", "e": "Aucune donnée nominative concernant des tiers (collègues, victimes, mis en cause) ne doit figurer. — Source : Instruction DGPN du 19/12/2011 – TSUA ; FAQ TSUA"}, {"t": 8, "s": "Quelles armes sont concernées par une déclaration TSUA (traitement relatif au suivi de l'usage des armes) ?", "o": ["Les moyens de force intermédiaire à effet cinétique ou électrique", "Les menottes", "Les armes à feu en dotation collective", "Les armes à feu en dotation individuelle"], "a": "ACD", "e": "Le cas échéant, l'usage d'une autre arme non remise en dotation peut aussi être déclaré. — Source : FAQ TSUA"}, {"t": 8, "s": "Une fois la déclaration TSUA (traitement relatif au suivi de l'usage des armes) validée par son auteur, elle est :", "o": ["transmise automatiquement au parquet", "supprimée après 1 an", "soumise au visa du supérieur hiérarchique disposant du profil « acteur-chef de service »", "définitive et non modifiable"], "a": "C", "e": "Le déclarant ne peut modifier qu'après intervention de l'autorité hiérarchique, qui peut retirer la validation. — Source : Instruction DGPN du 19/12/2011 – TSUA"}, {"t": 8, "s": "L'accès au TSUA (traitement relatif au suivi de l'usage des armes) est subordonné à :", "o": ["une habilitation personnelle délivrée par le gérant du portail sécurisé CHEOPS NG", "l'accord du parquet", "une autorisation du préfet", "une simple connexion intranet"], "a": "A", "e": "Habilitation personnelle et individuelle via CHEOPS NG ; un administrateur local est désigné. — Source : Instruction DGPN du 19/12/2011 – TSUA ; FAQ TSUA"}, {"t": 8, "s": "Peuvent se voir affecter temporairement un pistolet mitrailleur 9 mm, s'ils détiennent l'habilitation en cours de validité :", "o": ["les élèves gardiens de la paix en école", "les policiers adjoints", "les policiers actifs", "les réservistes statutaires"], "a": "CD", "e": "PM (pistolet-mitrailleur) 9 mm : exclusivement policiers actifs et réservistes statutaires habilités. Pour le HK G36, seuls les policiers actifs habilités. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Pistolet mitrailleur 9 mm : quelles affirmations sur ses accessoires et réglages sont exactes ?", "o": ["Les accessoires personnels sont autorisés s'ils sont déclarés au RAM", "Le porteur peut adapter librement les réglages à sa morphologie", "Le recours à un élément non référencé ou la modification des réglages constitue une faute professionnelle", "Il peut recevoir un désignateur d'objectif électronique (DOE), une poignée additionnelle ou une lampe tactique"], "a": "CD", "e": "Seuls les armements, équipements et munitions fournis par l'administration peuvent être employés. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "L'affectation individuelle temporaire d'un PM (pistolet-mitrailleur) 9 mm à l'occasion d'une mission est mentionnée :", "o": ["dans le rapport mensuel d'activité du RAM", "uniquement dans le TSUA", "sur le registre ad hoc et, le cas échéant, sur la main courante informatisée (MCI)", "sur le carnet de tir de l'agent"], "a": "C", "e": "Affectation encadrée, autorisée par la hiérarchie et sous son strict contrôle ; le niveau de décision est fixé par chaque direction d'emploi. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Pour l'ensemble des missions, le PM (pistolet-mitrailleur) 9 mm est porté :", "o": ["sans chargeur engagé, culasse ouverte", "muni de la bretelle, chargeur engagé, cartouche chambrée, culasse fermée, sélecteur sur la sûreté manuelle", "chargeur engagé, sans cartouche chambrée, sélecteur sur le coup par coup", "chargeur engagé, cartouche chambrée, sélecteur sur la rafale contrôlée"], "a": "B", "e": "Port systématique chargé et en sûreté, avec moyens de protection balistique. Le HK G36 n'est porté ainsi qu'en situation exceptionnelle ou pour des missions limitativement énumérées. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Habilitation au PM (pistolet-mitrailleur) 9 mm ou au HK G36 : un agent n'a pas pu suivre son recyclage avant l'échéance. Quelles affirmations sont exactes ?", "o": ["Sans recyclage dans les 24 mois suivant l'habilitation ou le dernier recyclage, une nouvelle habilitation doit être obtenue", "Les séances de recyclage ne peuvent être séparées par plus de 12 mois", "Son habilitation est suspendue jusqu'à ce que le recyclage soit effectué", "Son habilitation est prolongée d'office de 6 mois"], "a": "ABC", "e": "Non habilité ou habilitation caduque : aucune perception ni dotation possible. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm ; Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Un policier non habilité au HK G36 voit son collègue habilité gravement touché lors d'une fusillade. Selon l'instruction :", "o": ["il doit d'abord mettre l'arme en sécurité et la remettre au RAM", "il peut utiliser l'arme de son collègue si l'absolue nécessité et la proportionnalité sont réunies", "il commet une faute en utilisant une arme pour laquelle il n'est pas habilité", "il ne peut s'en servir qu'après autorisation radio de sa hiérarchie"], "a": "B", "e": "Il faut distinguer le droit de percevoir l'arme (habilitation) du droit de l'utiliser, subordonné aux seules règles juridiques. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm ; Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Lors de sa perception ou de sa réintégration, la mise en sécurité du HK G36 implique notamment :", "o": ["la position du sélecteur sur le pictogramme blanc correspondant à la sûreté manuelle", "la culasse refermée sur le témoin de chambre vide ou bloquée à l'arrière, canon vers le haut", "le puits de chargeur orienté vers le réceptionnaire", "le sélecteur positionné sur le coup par coup"], "a": "ABC", "e": "Mise en sécurité préalable ; dispositifs obligatoires dans les locaux (tubes de manipulation, puits balistiques). — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Le sélecteur du HK G36 ne peut quitter la position de sûreté qu'à l'occasion :", "o": ["de la perception de l'arme à l'armurerie", "sur la voie publique, de l'épaulé pour prendre la position « contact » lors de menaces avérées ou d'interventions à risques", "de la vérification du fonctionnement apparent des mécanismes", "du transport de l'arme dans le coffre du véhicule"], "a": "BC", "e": "Trois cas seulement : vérification du fonctionnement, épaulé en position « contact », réalisation d'un tir. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "La mise en sécurité d'un HK G36 chargé s'effectue :", "o": ["sous le contrôle obligatoire d'un officier sur place", "dans le coffre du véhicule léger à l'issue de la mission", "exclusivement dans les locaux de police, sauf circonstances particulières la rendant nécessaire sur la voie publique", "indifféremment sur la voie publique ou dans le véhicule"], "a": "C", "e": "Principe : mise en sécurité dans les locaux de police. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Systèmes de visée électronique du HK G36 :", "o": ["ils peuvent être réglés par le porteur après chaque séance de tir", "ils sont remplacés par des organes de visée mécaniques en milieu urbain", "aucune modification de leurs réglages ne doit être faite par les détenteurs", "leurs caractéristiques de fonctionnement doivent être connues avant la prise en compte de l'arme"], "a": "CD", "e": "Le G36 dispose aussi de rails pour accessoires (lampe tactique) ; tout élément non référencé ou modification constitue une faute professionnelle. — Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm"}, {"t": 8, "s": "Les pistolets mitrailleurs se différencient des fusils d'assaut notamment par :", "o": ["leurs munitions généralement utilisées dans les armes de poing, qui leur confèrent une portée pratique plus courte", "l'absence de mode de tir en rafale", "une portée pratique supérieure grâce à la cartouche 5,56 mm", "leur classement en catégorie B"], "a": "A", "e": "PM (pistolet-mitrailleur) : catégorie A2, cartouche 9 × 19 mm (COP), compacité favorable aux véhicules et milieux clos. — Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm"}, {"t": 8, "s": "Une déclaration TSUA (traitement relatif au suivi de l'usage des armes) a été faite « pour le compte » d'un collègue blessé. Lorsque l'intéressé est en mesure de déclarer lui-même son action :", "o": ["l'intéressé se contente de la valider", "la déclaration provisoire est supprimée par l'autorité hiérarchique et l'auteur renouvelle la procédure dans son intégralité", "la déclaration provisoire engage l'auteur de l'usage", "la déclaration provisoire devient définitive après sa signature"], "a": "B", "e": "La version provisoire n'engage pas l'auteur de l'usage ; la traçabilité de toutes les opérations est assurée. — Source : Instruction DGPN du 19/12/2011 – TSUA"}, {"t": 8, "s": "Concernant le TSUA (traitement relatif au suivi de l'usage des armes), quelles affirmations sont exactes ?", "o": ["Le champ de texte libre réservé au rapport est facultatif", "Sa mise en œuvre a été autorisée par arrêté du 16 novembre 2011, après avis de la CNIL", "Le droit d'accès et de rectification s'exerce auprès de la DGPN, par rapport sous couvert hiérarchique", "Les tirs effectués lors de formations ou d'entraînements n'y sont pas déclarés"], "a": "BCD", "e": "Le champ de rapport est libre mais obligatoire ; il peut constituer l'unique formalité déclarative selon les instructions des directions. — Source : Instruction DGPN du 19/12/2011 – TSUA ; FAQ TSUA"}, {"t": 8, "s": "Profils d'accès au TSUA (traitement relatif au suivi de l'usage des armes) : quelles affirmations sont exactes ?", "o": ["Tout agent dispose par défaut du profil administrateur local", "Un profil administrateur, accordé sous l'autorité du DGPN, autorise un accès illimité aux données", "Le profil « acteur-chef de service » ne permet que la lecture des déclarations", "Un profil « consultation » permet la seule lecture des comptes rendus, pour les personnels des services d'appui et de soutien"], "a": "BD", "e": "Profils : acteur-utilisateur (déclarant), acteur-chef de service (visa), consultation, administrateur. Un administrateur local est désigné par chaque chef de service. — Source : Instruction DGPN du 19/12/2011 – TSUA"}, {"t": 8, "s": "Le TSUA (traitement relatif au suivi de l'usage des armes) concerne les policiers ayant fait usage d'une arme, à savoir :", "o": ["les personnels actifs", "le cas échéant, les réservistes civils", "les adjoints de sécurité, y compris les cadets de la République", "les personnels administratifs non armés témoins de l'usage"], "a": "ABC", "e": "Son renseignement s'inscrit dans l'obligation de compte rendu (code de déontologie, RGEPN (règlement général d'emploi de la police nationale)). — Source : Instruction DGPN du 19/12/2011 – TSUA"}, {"t": 9, "s": "Le LBD (lanceur de balles de défense) de 40 mm est :", "o": ["une AFI classée au 6° de la catégorie A2", "une arme à feu létale de catégorie A1", "une AFI en dotation collective, classée au 4° de la catégorie A2", "une AFI en dotation individuelle de catégorie B"], "a": "C", "e": "LBD : 4° de la catégorie A2, lanceur mono-coup à canon rayé et basculant. La GMD (grenade à main de désencerclement) est au 6° de la A2. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Avec la munition CTS, le LBD (lanceur de balles de défense) de 40 mm a :", "o": ["un tir optimum à 25 m et un intervalle de 3 à 35 m", "un tir optimum à 50 m", "un tir optimum à 30 m et un intervalle opérationnel de 10 à 50 m", "un tir optimum à 10 m et un intervalle de 3 à 30 m"], "a": "C", "e": "CTS : optimum 30 m, 10 à 50 m. MDU (munition de défense unique) : DOE (désignateur d'objectif électronique) réglé pour 25 m, 3 à 35 m. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "En service, le LBD (lanceur de balles de défense) de 40 mm est porté :", "o": ["non approvisionné", "approvisionné à une cartouche, avec un seul type de munition (CTS ou MDU)", "approvisionné, avec panachage CTS/MDU pour s'adapter aux distances", "approvisionné uniquement sur ordre"], "a": "B", "e": "Le panachage des munitions est prohibé ; en véhicule, la sûreté est mise et retirée au débarquement. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Tant que la décision de tirer n'est pas prise, le LBD (lanceur de balles de défense) est maintenu en « position de contact » :", "o": ["épaulé, visée sur la tête", "pointé vers la menace, axe du canon sous l'horizontale, index le long du pontet", "canon vers le ciel, index sur la détente", "en bandoulière, canon vers le sol"], "a": "B", "e": "Position de contact : vers la menace, canon sous l'horizontale, index hors détente. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lors d'un tir de LBD (lanceur de balles de défense) de 40 mm, quelles règles s'appliquent ?", "o": ["Lorsque les circonstances le permettent, le tir est évité sur une personne en état de vulnérabilité manifeste", "Le tireur vise de façon privilégiée le torse", "La tête peut être visée si l'individu porte un casque", "Il peut viser le cou en cas de menace armée"], "a": "AB", "e": "Torse privilégié, membres supérieurs ou inférieurs possibles ; ni tête ni cou. La tête n'est jamais visée ; prise en compte des risques liés à la chute. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Après un tir de LBD (lanceur de balles de défense) suivi d'une interpellation, quelle que soit la zone atteinte :", "o": ["un examen médical n'est requis qu'en cas de tir à la tête", "la personne est remise à l'OPJ sans autre formalité", "un examen n'est requis qu'en cas de plainte", "un examen médical est pratiqué dans les meilleurs délais avec certificat médical descriptif"], "a": "D", "e": "Surveillance permanente, examen médical et certificat ; compte rendu écrit et déclaration TSUA (traitement relatif au suivi de l'usage des armes). — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Binôme superviseur-tireur LBD (lanceur de balles de défense) en maintien de l'ordre : quelles affirmations sont exactes ?", "o": ["Le superviseur est désigné préalablement par le chef d'unité pour la durée de l'opération", "Le binôme est obligatoire, y compris en légitime défense", "Une caméra piéton par binôme est suffisante", "Il a un niveau hiérarchique équivalent ou supérieur au tireur"], "a": "ACD", "e": "Le binôme est obligatoire en MO hors le cas de la légitime défense ; le superviseur a suivi une formation MO. — Source : Télégramme DGPN 2020 – binôme superviseur-tireur LBD"}, {"t": 9, "s": "Le superviseur du binôme LBD (lanceur de balles de défense) est chargé :", "o": ["de tirer en cas d'indisponibilité du tireur", "d'évaluer la situation d'ensemble, de s'assurer de la compréhension des ordres et de désigner l'objectif", "de procéder aux sommations", "de rédiger seul le compte rendu"], "a": "B", "e": "Rôles : situation d'ensemble et mouvements des manifestants, compréhension des ordres, désignation de l'objectif. — Source : Télégramme DGPN 2020 – binôme superviseur-tireur LBD"}, {"t": 9, "s": "La GMD (grenade à main de désencerclement) :", "o": ["projette 18 galets dans un rayon de 30 mètres", "projette 18 galets en caoutchouc dans un rayon maximal d'efficacité de 10 mètres", "projette 12 galets dans un rayon de 10 mètres", "a un retard de 3 secondes"], "a": "B", "e": "Retard 1,5 s, 18 galets, rayon 10 m, lancée jusqu'à 30 m, 6° catégorie A2. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Concernant l'emploi de la GMD (grenade à main de désencerclement), quelles affirmations sont exactes ?", "o": ["Elle peut être tirée au lanceur Cougar à courte distance", "L'utilisateur doit se tenir à découvert pour assurer la précision du lancer", "La décision intègre les risques liés à la chute des personnes près du point d'impact", "Elle ne doit pas être employée à partir d'un lanceur"], "a": "CD", "e": "L'utilisateur doit être protégé ou abrité dans la mesure du possible. Le lancer de GMD au moyen d'un lanceur est totalement proscrit. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lanceur de grenades : l'initiative de son utilisation :", "o": ["appartient au superviseur", "appartient à l'AHEF seule", "appartient au porteur de l'arme", "n'appartient pas au porteur et procède de l'ordre de la hiérarchie"], "a": "D", "e": "L'utilisation procède de l'ordre hiérarchique ; binôme superviseur + lanceur(s). — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Avec un lanceur de grenades, quelles règles s'imposent ?", "o": ["Les tirs dans des locaux de faible capacité sont proscrits sauf circonstances exceptionnelles", "Le tir tendu est autorisé à plus de 50 mètres", "Le lancer de grenade est proscrit envers le conducteur d'un véhicule en mouvement", "Le tir tendu est strictement interdit"], "a": "ACD", "e": "Seul le tir courbe est admis : il évite l'impact direct et le renvoi de la grenade. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Les lanceurs de grenades multi-coups (Penn-Arms PGL6S, MILKOR MSGL 40) disposent :", "o": ["d'un chargeur droit de dix grenades", "d'un canon unique", "d'un magasin rotatif à six chambres", "d'un magasin de quatre chambres"], "a": "C", "e": "Lanceur mono-tube : Cougar ; multi-coups : magasin rotatif à 6 chambres. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "La GM2L (calibre 56 mm) :", "o": ["est classée au 5° de la catégorie A2", "projette 18 galets en caoutchouc", "peut être propulsée à une portée maximale de 300 mètres", "produit un double effet lacrymogène et assourdissant, sans éclat vulnérant"], "a": "AD", "e": "DPR de 50, 100 et 200 m. Les galets sont propres à la GMD (grenade à main de désencerclement). DPR de 50, 100 et 200 m pour la GM2L. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lanceur de balles de défense : les précautions d'emploi de l'instruction ne peuvent être opposées au policier :", "o": ["jamais", "lorsque le LBD est utilisé dans des cas où l'emploi de l'arme à feu létale est légalement justifié", "en maintien de l'ordre", "lorsque l'individu est casqué"], "a": "B", "e": "Elles restent applicables dans un périmètre où l'arme à feu létale ne pourrait être utilisée. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Recyclage de l'habilitation au LBD (lanceur de balles de défense) 40 mm, à la GMD (grenade à main de désencerclement) et au lanceur Cougar :", "o": ["quinquennal", "biennal", "annuel", "triennal"], "a": "D", "e": "Recyclage triennal pour les AFI (arme de force intermédiaire) ; annuel pour le PM (pistolet-mitrailleur) HK UMP et le HK G36. — Source : Tableau « Les AFI et instructions spécifiques »"}, {"t": 9, "s": "Qui peut être habilité au lanceur Cougar ?", "o": ["Tous les personnels y compris cadets", "Les actifs, PA et réservistes", "Les seuls CRS", "Les actifs, sauf policiers adjoints, cadets et réservistes"], "a": "D", "e": "Cougar et grenade à effet sonore CONDOR : actifs sauf PA (policiers adjoints), cadets et réservistes. GMD (grenade à main de désencerclement) : actifs, PA et réservistes sauf cadets. — Source : Tableau « Les AFI et instructions spécifiques »"}, {"t": 9, "s": "Selon l'instruction DGPN (direction générale de la police nationale) n°15/2025, les policiers adjoints et réservistes habilités peuvent être dotés :", "o": ["de pistolets à impulsion électrique", "de lanceurs de grenades multi-coups", "de grenades à main de désencerclement", "de générateurs d'aérosols lacrymogènes ou incapacitants"], "a": "ACD", "e": "Liste : GMD (grenade à main de désencerclement), grenades à main lacrymogènes, PIE (pistolet à impulsions électriques), GAIL (générateur d'aérosol incapacitant ou lacrymogène) et bâtons de défense. — Source : Instruction DGPN n°15/2025 – AFI des policiers adjoints et réservistes"}, {"t": 9, "s": "Un réserviste retraité des corps actifs peut être autorisé à porter un LBD (lanceur de balles de défense) de 40 mm :", "o": ["après un an de réserve", "dans tous les cas", "jamais", "s'il était titulaire de l'habilitation au jour de son intégration dans la réserve opérationnelle"], "a": "D", "e": "Autorisation par le chef de service, sous condition d'habilitation préalable au jour de l'intégration. — Source : Instruction DGPN n°15/2025 – AFI des policiers adjoints et réservistes ; Tableau « Les AFI et instructions spécifiques »"}, {"t": 9, "s": "Les conditions d'habilitation (octroi, maintien, durée) des policiers adjoints et réservistes aux AFI (arme de force intermédiaire) sont :", "o": ["doublées en durée de formation", "fixées par chaque chef de service", "allégées", "identiques à celles des fonctionnaires actifs"], "a": "D", "e": "Conditions identiques à celles des actifs ; prescriptions d'emploi de l'instruction AFI 2017 et de l'instruction PIE (pistolet à impulsions électriques). — Source : Instruction DGPN n°15/2025 – AFI des policiers adjoints et réservistes"}, {"t": 9, "s": "Côté police nationale, l'affectation individuelle temporaire du LBD (lanceur de balles de défense) de 40 mm est réservée aux fonctionnaires actifs habilités, à l'exclusion :", "o": ["des réservistes de la police nationale", "des gradés et gardiens titulaires", "des adjoints de sécurité", "des fonctionnaires actifs stagiaires"], "a": "ACD", "e": "Exclusion des stagiaires, ADS (adjoints de sécurité) et réservistes (sauf autorisation spécifique ultérieure des réservistes retraités habilités). La GMD (grenade à main de désencerclement) et les lanceurs de grenades concernent, eux, les stagiaires et titulaires habilités. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lors de la perception et de la réintégration, le LBD (lanceur de balles de défense) de 40 mm est remis :", "o": ["canon basculé, cartouche engagée pour contrôle du percuteur", "canon fermé, DOE démonté et remis séparément", "canon basculé, sûreté manuelle mise (liséré blanc visible), chambre directement visible par la personne qui le perçoit", "canon fermé, approvisionné à une cartouche, sûreté retirée"], "a": "C", "e": "L'état de l'arme et du DOE (désignateur d'objectif électronique) ainsi que la quantité de munitions sont contrôlés. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Le désignateur d'objectif électronique (DOE) du LBD (lanceur de balles de défense) de 40 mm :", "o": ["autorise des tirs réflexes précis et rapides ou des tirs ajustés par mauvaise visibilité", "peut être réglé par le tireur selon la munition qu'il emporte", "constitue le mode normal de visée", "ne doit en aucun cas être démonté ni ses réglages modifiés, y compris lors du nettoyage"], "a": "ACD", "e": "Aucune manipulation susceptible d'en modifier le fonctionnement, même au nettoyage. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lorsque les circonstances le permettent, le tir de LBD (lanceur de balles de défense) est évité sur une personne présentant un état de vulnérabilité manifeste, par exemple :", "o": ["un état de grossesse apparent", "le port de vêtements épais", "une blessure visible ou une situation de handicap évidente", "une distance de tir de 30 mètres"], "a": "AC", "e": "Vulnérabilités citées : blessure visible, grossesse apparente, handicap évident, âge de la personne visée. Vêtements et distance sont des paramètres d'efficacité. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Lors d'un attroupement (art. 431-3 du code pénal), le LBD (lanceur de balles de défense) de 40 mm peut être employé sans sommations :", "o": ["en cas de violences ou voies de fait commises contre les forces de l'ordre, ou si elles ne peuvent défendre autrement le terrain qu'elles occupent", "sur simple ordre du préfet, sans condition", "uniquement contre un individu armé d'une arme à feu", "dès que l'attroupement refuse de se disperser après une première sommation"], "a": "A", "e": "Articles L. 211-9 al. 6, R. 211-18 et D. 211-19 du CSI (code de la sécurité intérieure). — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Selon l'instruction AFI (arme de force intermédiaire) de 2017, la GMD (grenade à main de désencerclement) :", "o": ["est d'emploi interdit en milieu fermé en toutes circonstances", "ne voit son emploi en milieu fermé admis que dans des situations particulières où les risques liés aux projections et à l'explosion sont réduits", "peut être lancée en cloche au-dessus des manifestants pour éviter l'impact direct", "doit être lancée au ras du sol, en direction du groupe d'éléments hostiles à disperser"], "a": "BD", "e": "La décision intègre aussi les risques liés à la chute des personnes près du lieu d'impact et les particularités environnementales. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Dans le cadre de l'état de nécessité (art. 122-7 du code pénal), la GMD (grenade à main de désencerclement) ou le lanceur de grenades ne peut être utilisé que :", "o": ["pour protéger une valeur supérieure à celle sacrifiée par son usage", "contre une personne armée d'une arme à feu", "après deux sommations à haute voix", "sur ordre du préfet"], "a": "A", "e": "Condition propre à l'état de nécessité, rappelée dans les annexes GMD et lanceurs. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Stockage des GMD (grenade à main de désencerclement) et des grenades : quelles prescriptions sont exactes ?", "o": ["Les grenades et leurs bouchons allumeurs sont entreposés en armurerie sécurisée ou en armoires fortes dans des locaux sécurisés", "Ils font l'objet de contrôles récurrents, notamment de leur état et de leurs dates de péremption", "Leurs points de conservation sont pris en compte dans le plan de protection du service", "Ils peuvent être conservés dans les véhicules de service entre deux vacations"], "a": "ABC", "e": "Règles de sécurité à respecter à chaque étape : perception, transport, mise en service, port, mise en sécurité, réintégration. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Avec un lanceur de grenades, sont proscrits :", "o": ["le tir courbe", "le lancer de grenade envers le conducteur d'un véhicule en mouvement", "les tirs dans des locaux de faible capacité, sauf circonstances exceptionnelles", "l'emploi lors d'une dispersion d'attroupement après sommations"], "a": "BC", "e": "Le tir tendu est strictement interdit ; seul le tir courbe est admis. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Les grenades tirées au moyen des lanceurs peuvent produire des effets, parfois cumulés :", "o": ["incapacitants électriques", "de souffle et assourdissants", "lacrymogènes et fumigènes", "de désencerclement par projection de galets"], "a": "BC", "e": "Les lanceurs sont classés en catégorie A-2 ; certaines grenades sont propres aux multi-coups (magasin plus court). Le lancer de GMD (grenade à main de désencerclement) par lanceur est proscrit. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Le télégramme DGPN (direction générale de la police nationale) sur les nouvelles grenades à main à effet sonore mentionne deux modèles acquis par le SAILMI :", "o": ["la GL-304 CONDOR (Rivolier) et la GR MA EF SON (Alsetex)", "la GM2L et la GLI F4", "la GL-304 et la DMP", "la GMD et la GLI"], "a": "A", "e": "Grenades destinées à déstabiliser tout groupe violent et/ou armé par un effet sonore intense. — Source : Télégramme DGPN (L. Laugier) – grenades à main à effet sonore"}, {"t": 9, "s": "Selon le télégramme DGPN (direction générale de la police nationale), la grenade à main à effet sonore exige notamment :", "o": ["un lancer en cloche au-dessus de l'attroupement", "un lancer à distance du dispositif policier, après appréciation de la trajectoire et du point d'explosion", "un lancer au moyen d'un lanceur Cougar", "un lancer à la main et au ras du sol"], "a": "BD", "e": "Elle minimise les dommages aux tiers (moindre projection d'éléments résiduels) mais impose ces précautions. La GL-304 est utilisable dès formation et habilitation. — Source : Télégramme DGPN (L. Laugier) – grenades à main à effet sonore"}, {"t": 9, "s": "Côté gendarmerie nationale, la collecte des informations relatives à l'utilisation de la GMD (grenade à main de désencerclement) s'effectue via :", "o": ["le TSUA", "la procédure « EVENGRAVE »", "l'application LRPGN", "le registre ARES"], "a": "B", "e": "Police : TSUA (traitement relatif au suivi de l'usage des armes) ; gendarmerie : EVENGRAVE. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 9, "s": "Les militaires de la gendarmerie en service de protection d'une zone de défense hautement sensible peuvent faire usage du LBD (lanceur de balles de défense) de 40 mm (art. L. 4123-12 du code de la défense) :", "o": ["sur décision du préfet de zone", "pour empêcher ou interrompre une intrusion et arrêter son auteur, après les sommations prévues à l'article R. 2363-5", "sans aucune sommation", "uniquement en légitime défense"], "a": "B", "e": "Régime spécifique aux gendarmes, également prévu pour la GMD (grenade à main de désencerclement) et les lanceurs de grenades. — Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) produit, selon le mode utilisé :", "o": ["la perte momentanée du contrôle du système locomoteur en mode tir", "une perte de connaissance systématique", "une sensation de douleur en mode contact", "une brûlure cutanée en mode dissuasif"], "a": "AC", "e": "Mode contact : douleur ; mode tir : perte de contrôle locomoteur pouvant entraîner la chute. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Le mode « dissuasif » du PIE (pistolet à impulsions électriques) repose sur :", "o": ["la lampe uniquement", "les pointeurs laser et, si nécessaire, le déclenchement d'un arc électrique de dissuasion sans retrait des cartouches", "l'application de l'arme sur la personne", "le tir d'une cartouche d'avertissement"], "a": "B", "e": "Si possible, le pointage laser est privilégié : l'arme est alors un moyen dissuasif. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Après déclenchement de l'arc et sans autre intervention du tireur, le PIE (pistolet à impulsions électriques) fonctionne pendant :", "o": ["un cycle continu de cinq secondes, interruptible à tout moment", "trois secondes non interruptibles", "tant que la détente est pressée", "un cycle de dix secondes"], "a": "A", "e": "Cycle de 5 secondes ; l'utilisateur peut l'interrompre par l'interrupteur. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "En service, le PIE (pistolet à impulsions électriques) est porté :", "o": ["dans la poche de la tenue", "approvisionné à une cartouche, sous tension", "dans son étui à rétention mécanique, approvisionné à deux cartouches, en position éteinte", "sans cartouche en toutes circonstances"], "a": "C", "e": "Deux cartouches supplémentaires possibles en étui ; exceptionnellement sans cartouche dans des environnements à risque (métro, gares). — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Lors de l'emploi du PIE (pistolet à impulsions électriques), quelles préconisations sont exactes ?", "o": ["En cas de tir, la tête et le cou ne sont pas visés", "La répétition des cycles est la règle pour garantir la maîtrise", "En cas de pointage laser, la tête n'est pas visée", "La personne est informée oralement, si les circonstances le justifient, de la possibilité d'emploi du PIE"], "a": "ACD", "e": "La répétition de cycles est exceptionnelle, seulement si elle s'avère indispensable. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Parmi ces situations, laquelle ne figure PAS parmi les vulnérabilités particulières à prendre en compte avant l'emploi du PIE (pistolet à impulsions électriques) ?", "o": ["Un malade cardiaque", "Des vêtements imprégnés de liquides ou vapeurs inflammables", "Une personne portant des lunettes", "Une femme enceinte"], "a": "C", "e": "Également les personnes victimes de saignements importants, et les environnements à risque d'incendie, d'explosion ou d'électrocution. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Une sonde du PIE (pistolet à impulsions électriques) atteint malgré tout la personne au cou. Le policier :", "o": ["déclenche un second cycle", "poursuit l'interpellation sans mesure particulière", "avise immédiatement les services de secours", "retire lui-même la sonde sur place"], "a": "C", "e": "Avis immédiat aux secours pour une prise en charge appropriée. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Un examen médical rapide est requis après emploi du PIE (pistolet à impulsions électriques) si la personne :", "o": ["manifeste des signes d'emprise d'alcool, de drogues ou de médicaments", "reste dans un état de stress important ou de choc", "a été seulement visée par le pointeur laser", "a fait l'objet d'un usage réitéré ou d'un cycle supérieur à 5 secondes"], "a": "ABD", "e": "Aussi : problème médical, agitation ou épuisement. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "La déclaration TSUA (traitement relatif au suivi de l'usage des armes) est obligatoire pour un usage du PIE (pistolet à impulsions électriques) :", "o": ["en mode tir uniquement", "en mode tir et contact uniquement", "en mode pointage, même dissuasif, en mode contact et en mode tir", "seulement si la personne est blessée"], "a": "C", "e": "Traçabilité à 3 niveaux : ARES/registres, TSUA (dès le pointage), Log-EVIDENCE. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Les séances de recyclage au PIE (pistolet à impulsions électriques) ne peuvent être séparées par un délai supérieur à :", "o": ["12 mois", "36 mois", "48 mois", "24 mois"], "a": "B", "e": "36 mois au plus ; habilitation individuelle préalable obligatoire (recyclage triennal). — Source : Instruction DPN-1.9.4.1 – emploi du PIE ; Tableau « Les AFI et instructions spécifiques »"}, {"t": 10, "s": "Fiche technique Taser 7 : la cartouche courte portée a un angle d'espacement des sondes de :", "o": ["24°", "7,6°", "12°", "3,5°"], "a": "C", "e": "Courte portée 12° (noire) ; longue portée 3,5° (grise). Cartouche de manipulation rouge, d'entraînement bleue. — Source : Instruction DPN-1.9.4.1 – emploi du PIE (fiche technique)"}, {"t": 10, "s": "Fiche technique Taser 7 : quelles affirmations sont exactes ?", "o": ["Plus la distance entre les sondes est grande, plus l'efficacité est importante", "L'arc peut traverser les vêtements, y compris les gilets pare-balles", "Les effets physiologiques varient selon l'ampérage et non le voltage", "L'intensité électrique se cumule lors de tirs simultanés sur un même individu"], "a": "ABC", "e": "L'intensité ne se cumule pas lors de tirs simultanés ; la batterie fournit jusqu'à 150 cycles. — Source : Instruction DPN-1.9.4.1 – emploi du PIE (fiche technique)"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) est classé :", "o": ["au 6° de la catégorie B", "au 6° de la catégorie A2", "en catégorie D", "au 4° de la catégorie A2"], "a": "A", "e": "PIE : 6° de la catégorie B (« B6 » dans le tableau des AFI (arme de force intermédiaire)). — Source : Instruction DPN-1.9.4.1 – emploi du PIE ; Tableau « Les AFI et instructions spécifiques »"}, {"t": 10, "s": "Les aérosols lacrymogènes CS en dotation permettent d'atteindre instantanément une personne jusqu'à :", "o": ["4 à 5 mètres pour le plus gros conteneur", "1 à 2 mètres", "10 mètres", "15 mètres"], "a": "A", "e": "Trois formats (39 à 650 cm³), CS dosé à 5 %, portée jusqu'à 4-5 m pour le plus gros. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "En milieu fermé, la bombe lacrymogène doit être utilisée :", "o": ["par jets brefs d'environ une seconde, en nombre limité, et arrêtés dès la neutralisation", "par un unique jet de cinq secondes", "uniquement après évacuation du local", "par jets continus pour saturer le local"], "a": "A", "e": "Éviter de saturer le local : risques d'effets irréversibles voire mortels liés à l'inhalation de CS. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Saturer l'atmosphère d'une pièce au CS pour neutraliser des individus est :", "o": ["autorisé à tout policier en légitime défense", "interdit à tous", "autorisé à la BAC", "réservé exclusivement aux unités spécialisées d'intervention (RAID, GIPN)"], "a": "D", "e": "Réservé aux unités spécialisées dans le cadre de leur mission. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Quelles règles d'emploi des GAIL (générateur d'aérosol incapacitant ou lacrymogène) sont exactes ?", "o": ["Ne pas actionner à moins de trois mètres d'une personne, dans la mesure du possible", "Emploi formellement proscrit à l'intérieur d'un véhicule en mouvement", "Emploi recommandé à proximité d'une chaudière pour l'effet de surprise", "Usage simultané ou consécutif du PIE totalement proscrit"], "a": "BD", "e": "Distance minimale : un mètre, dans la mesure du possible. Gaz propulseurs inflammables : pas de flamme ni de source d'étincelle (armoire électrique, chaudière). — Source : Télégramme DGPN du 05/09/2025 – GAIL ; Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Après usage d'un GAIL (générateur d'aérosol incapacitant ou lacrymogène) suivi d'une interpellation :", "o": ["aucun compte rendu n'est nécessaire", "l'usage, les conditions légales et les diligences (décontaminant, secours) font l'objet d'un compte rendu à l'OPJ et sont mentionnés en procédure", "la personne doit obligatoirement être hospitalisée", "seul un compte rendu oral au chef de poste est requis"], "a": "B", "e": "Compte rendu à l'OPJ (officier de police judiciaire) et mention en procédure. — Source : Télégramme DGPN du 05/09/2025 – GAIL"}, {"t": 10, "s": "Décontamination après usage d'un aérosol :", "o": ["le visage est frotté vigoureusement avec un tissu sec", "à défaut, le visage peut être aspergé d'eau claire ou de sérum physiologique", "une solution de décontamination peut être utilisée sur le visage après un test préalable sur le dos de la main", "aucune décontamination n'est prévue"], "a": "BC", "e": "Test préalable sur une zone limitée du dos de la main. — Source : Télégramme DGPN du 05/09/2025 – GAIL"}, {"t": 10, "s": "En dehors du maintien de l'ordre, l'hypothèse principale d'emploi d'une bombe lacrymogène par un policier est :", "o": ["la légitime défense (art. 122-5 CP)", "la flagrance (art. 73 CPP)", "l'exécution d'un mandat de justice", "l'état de nécessité (art. 122-7 CP)"], "a": "A", "e": "Hypothèse principale : légitime défense ; peuvent aussi être envisagés l'art. 73 CPP (code de procédure pénale), les mandats de justice, l'art. 122-4 CP. L'usage reste strictement nécessaire et proportionné ; la dispersion d'attroupement relève du MO avec sommations. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) ne doit pas être employé lorsque le niveau de chargement de sa batterie est inférieur à :", "o": ["10 %, signalé par un bip sonore", "20 %, signalé par l'extinction de l'écran", "50 %, signalé par un voyant rouge", "30 %, signalé par un pictogramme de pile vide clignotant"], "a": "D", "e": "Seuil de 30 % (pictogramme pile vide clignotant sur l'écran de contrôle). — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Le logement de tir du PIE (pistolet à impulsions électriques) en dotation :", "o": ["n'accueille qu'une cartouche à longue portée", "peut accueillir deux cartouches, permettant le tir d'une deuxième immédiatement après la première sans recharger", "n'accueille qu'une cartouche, la seconde étant portée dans l'étui", "accueille trois cartouches tirées simultanément"], "a": "B", "e": "Deux cartouches dans le logement : second tir possible immédiatement. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Le déploiement du PIE (pistolet à impulsions électriques) modèle Taser 7 (T7) intervient :", "o": ["en complément du X26, qui reste l'arme de référence", "dans le cadre du renouvellement des modèles X26 devenus obsolètes", "uniquement dans les unités de maintien de l'ordre", "pour remplacer les GAIL en milieu fermé"], "a": "B", "e": "Objectif également d'accroître le parc de PIE. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Selon la société AXON, la mémoire interne du T7 (8 Mo) permet de sauvegarder :", "o": ["plus de 100 000 évènements/lignes", "environ 10 000 évènements", "les 1 000 derniers tirs seulement", "les vidéos des 50 dernières utilisations"], "a": "A", "e": "Les données d'utilisation sont extraites et télétransmises via la base couplée aux baies de chargement. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Recharge des batteries du PIE (pistolet à impulsions électriques) T7 : quelles affirmations sont exactes ?", "o": ["Le voyant rouge indique une batterie chargée", "La baie de chargement comporte 1 ou 6 logements de batterie", "Le voyant vert indique une batterie chargée à 100 % (6 h de charge maximum)", "La baie et la base doivent être connectées à internet pour transférer les données statistiques"], "a": "BCD", "e": "Le voyant jaune indique la charge en cours. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Pourquoi le PIE (pistolet à impulsions électriques) ne doit-il pas être utilisé en concomitance avec un spray de gaz lacrymogène ou autre ?", "o": ["Parce que les sondes ne peuvent plus se fixer", "Parce que le gaz neutralise l'effet électrique", "Parce que la personne devient insensible à la douleur", "Parce que ces sprays sont hautement inflammables"], "a": "D", "e": "Important risque d'inflammabilité en cas d'emploi simultané ou consécutif d'un aérosol à gaz propulseurs inflammables. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Après la neutralisation par PIE (pistolet à impulsions électriques) en mode tir, l'instruction recommande de :", "o": ["ne pas saisir la personne dans la zone corporelle située entre les deux sondes positive et négative", "saisir la personne à hauteur des sondes pour les maintenir en place", "déclencher un nouveau cycle avant tout menottage", "retirer immédiatement les sondes en tirant d'un coup sec"], "a": "A", "e": "Ne pas toucher la zone entre les sondes ; la répétition des cycles reste exceptionnelle. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "La formation à l'habilitation au PIE (pistolet à impulsions électriques) T7 dure :", "o": ["une demi-journée en e-learning", "2 jours, ou 1 jour pour les fonctionnaires à jour de leur habilitation X26", "1 jour pour tous", "3 jours, ou 2 jours pour les anciens habilités X26"], "a": "B", "e": "1 jour pour les habilités X26, sans qu'il s'agisse à proprement parler d'un recyclage. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "À proximité d'un vecteur de haute tension, notamment en mode tir, l'utilisateur du PIE (pistolet à impulsions électriques) doit :", "o": ["renoncer à tout pointage laser", "prendre des précautions particulières pour éviter tout contact de lui-même, de la personne et des tiers avec le vecteur", "doubler la durée du cycle", "privilégier le mode tir, plus sûr que le mode contact"], "a": "B", "e": "Précaution spécifique liée au risque de contact avec le vecteur. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "L'affectation individuelle temporaire du PIE (pistolet à impulsions électriques) : le niveau hiérarchique de décision est fixé :", "o": ["par des instructions complémentaires de chaque direction et service d'emploi", "par le RAM du service", "par l'instruction nationale, au niveau du commissaire", "par le préfet de département"], "a": "A", "e": "Chaque direction d'emploi établit des instructions complémentaires. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Configuration du PIE (pistolet à impulsions électriques) et accessoires :", "o": ["les armes sont livrées dans une configuration qui ne doit faire l'objet d'aucune modification, sauf instructions explicites", "le recours à des produits non référencés ou modifiés constitue une faute professionnelle", "l'agent peut utiliser des cartouches du commerce compatibles", "le service peut adapter librement la durée du cycle"], "a": "AB", "e": "Seuls les équipements fournis sont autorisés. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) peut également être utilisé sur ordre ou autorisation de la loi, sur le fondement de :", "o": ["l'article 122-7 du code pénal", "l'article 73 du code de procédure pénale", "l'article 122-4 du code pénal", "l'article R. 211-13 du CSI"], "a": "C", "e": "Art. 122-4 CP : acte prescrit ou autorisé par la loi ou commandé par l'autorité légitime ; s'ajoutent légitime défense, état de nécessité et L. 435-1. — Source : Instruction DPN-1.9.4.1 – emploi du PIE"}, {"t": 10, "s": "L'emploi d'un produit lacrymogène à l'intérieur d'un véhicule en mouvement, notamment pour en provoquer l'arrêt, est :", "o": ["formellement proscrit", "autorisé en cas de refus d'obtempérer", "laissé à l'appréciation du chef de bord", "autorisé si le conducteur est seul à bord"], "a": "A", "e": "Interdiction formelle de l'instruction DAPN (direction de l'administration de la police nationale) 2004/40. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Effets du gaz CS (instruction DAPN (direction de l'administration de la police nationale) 2004/40) : quelles affirmations sont exactes ?", "o": ["Paralysie musculaire de quelques secondes", "Irritation des voies respiratoires : toux, difficulté à respirer", "Irritation de la peau, avec allergies possibles en cas d'expositions répétées", "Irritation importante des yeux (douleur, larmoiement, fermeture des yeux) d'une durée de 5 à 10 minutes"], "a": "BCD", "e": "La paralysie musculaire n'est pas un effet du CS (le PIE (pistolet à impulsions électriques) provoque une perte de contrôle locomoteur). — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 10, "s": "Décontamination après usage d'un aérosol lacrymogène en local fermé : quelles mesures sont prévues ?", "o": ["Ne jamais utiliser de crèmes ou d'huiles, qui retiennent le gaz et le rendent plus actif", "Frictionner les yeux avec un linge sec", "Demander au sujet de retirer lui-même ses lentilles après s'être lavé les mains", "Sortir la ou les personnes du local et ouvrir portes et fenêtres"], "a": "ACD", "e": "Rincer abondamment à l'eau froide (yeux, peau du visage), éventuellement décontaminant spécifique, exposer à l'air frais, rassurer. — Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé"}, {"t": 11, "s": "Selon la fiche « Les éléments du maintien de l'ordre », l'attroupement (art. 431-3 CP) est :", "o": ["tout rassemblement de personnes armées", "toute manifestation interdite", "tout rassemblement non déclaré de plus de trois personnes", "tout rassemblement de personnes sur la voie publique ou dans un lieu public susceptible de troubler l'ordre public"], "a": "D", "e": "Définition retenue par la fiche : rassemblement sur la voie publique ou dans un lieu susceptible de troubler l'ordre public. — Source : Les éléments du maintien de l'ordre (fiche)"}, {"t": 11, "s": "La manifestation sur la voie publique est soumise à déclaration préalable au moins :", "o": ["24 heures avant", "15 jours avant", "3 jours francs avant", "8 jours avant"], "a": "C", "e": "3 jours francs au moins, auprès du maire, du préfet de police à Paris ou du préfet en zone de police d'État. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Depuis la loi du 10 avril 2019, la déclaration de manifestation doit être signée par :", "o": ["le maire", "un organisateur", "trois organisateurs", "deux organisateurs"], "a": "B", "e": "Réduction de trois à un organisateur et suppression de l'élection de domicile dans le département. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "L'autorité de police peut interdire le port et le transport sans motif légitime d'objets pouvant constituer une arme :", "o": ["pendant 72 heures", "pendant les 48 heures précédentes", "pendant les 24 heures qui précèdent l'événement et jusqu'à dispersion", "le seul jour de la manifestation"], "a": "C", "e": "24 h avant et jusqu'à dispersion, sur une aire limitée et proportionnée (art. L.211-3 CSI (code de la sécurité intérieure)). — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Concernant l'AHEF (autorité habilitée à décider de l'emploi de la force), quelles affirmations sont exactes ?", "o": ["Elle peut cumuler son rôle avec celui de commandant de la force publique", "Elle doit impérativement être sur place, porteuse de son écharpe tricolore", "Elle est la seule autorité à pouvoir constater le délit d'attroupement", "Elle réalise les sommations"], "a": "BCD", "e": "L'AHEF ne peut pas cumuler son rôle avec celui de CFP (commandant de la force publique). — Source : Les éléments du maintien de l'ordre (fiche)"}, {"t": 11, "s": "Le commandant de la force publique (CFP) :", "o": ["procède aux sommations", "constate le délit d'attroupement", "fixe la mission et les objectifs", "est responsable de la stricte exécution de la réquisition et décide des moyens humains et matériels"], "a": "D", "e": "Le DSO (directeur du service d'ordre)/CSO (AHEF (autorité habilitée à décider de l'emploi de la force)) fixe la mission, conduit la communication et procède aux sommations ; le CFP met en œuvre les moyens. — Source : Les éléments du maintien de l'ordre (fiche) ; Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Selon le SNMO, hors légitime défense, qui décide de l'emploi de la force et de l'usage des armes ?", "o": ["Le préfet uniquement", "Le CFP", "Le chef de section", "Le DSO / CSO"], "a": "D", "e": "Le DSO (directeur du service d'ordre)/CSO décide, hors légitime défense, de l'emploi de la force ; il peut modifier, suspendre ou annuler ses instructions. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Nouvelles sommations du SNMO : la formule de la première sommation est :", "o": ["« Première sommation : on va faire usage de la force »", "« Première sommation : nous allons faire usage de la force. Quittez immédiatement les lieux »", "« Obéissance à la loi. Dispersez-vous »", "« Attention ! Dernier avertissement avant usage de la force »"], "a": "B", "e": "L'avertissement préalable devient : « Attention ! Attention ! Vous participez à un attroupement. Obéissance à la loi. Vous devez vous disperser et quitter les lieux ». — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Après deux sommations restées sans effet, hors cadre de réaction, quels moyens peuvent être employés sur ordre ?", "o": ["Les grenades lacrymogènes lancées à la main", "Les GAIL", "Les lanceurs de grenades avec binôme", "La GMD"], "a": "AB", "e": "GMD (grenade à main de désencerclement), grenade à effet sonore et lanceurs n'arrivent qu'après réitération de la 2e sommation. — Source : Les éléments du maintien de l'ordre (fiche) ; Usage des AFI en maintien de l'ordre (tableau)"}, {"t": 11, "s": "Après réitération de la deuxième et dernière sommation, sur ordre, quelles armes restent interdites ?", "o": ["La grenade à main à effet sonore", "Le LBD", "La GMD", "Le PIE"], "a": "BD", "e": "LBD (lanceur de balles de défense) et PIE (pistolet à impulsions électriques) interdits hors cadre de réaction ; GMD (grenade à main de désencerclement), effet sonore et lanceurs (avec binôme) autorisés. — Source : Les éléments du maintien de l'ordre (fiche)"}, {"t": 11, "s": "En cadre de réaction (voies de fait, violences, terrain impossible à défendre autrement), l'usage de la force est décidé :", "o": ["sur ordre exprès de l'AHEF après sommations", "par le préfet", "sur initiative du commandant de la force publique", "par chaque policier individuellement"], "a": "C", "e": "Cadre de réaction : initiative du CFP (commandant de la force publique), LBD (lanceur de balles de défense) autorisé avec binôme, PIE (pistolet à impulsions électriques) toujours interdit. — Source : Les éléments du maintien de l'ordre (fiche)"}, {"t": 11, "s": "Le SNMO a décidé, s'agissant des grenades :", "o": ["le remplacement de la GMD par un modèle plus récent moins vulnérant", "l'abandon de la GLI-F4 au profit de la GM2L, qui ne contient pas d'explosif", "la suppression de toutes les grenades à main", "l'abandon de la GM2L au profit de la GLI-F4"], "a": "AB", "e": "Il confirme l'intérêt des AFI (arme de force intermédiaire) au MO tout en adaptant leur emploi. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Journalistes au sein d'une manifestation : quelles affirmations sont exactes ?", "o": ["Ils peuvent se positionner, de manière dérogatoire, derrière les cordons des forces de l'ordre", "Ils peuvent continuer leur mission lors de la dispersion d'un attroupement sans être tenus de quitter les lieux", "Ils peuvent circuler librement au sein des dispositifs de sécurité", "Ils ont l'obligation de porter des signes distinctifs"], "a": "ABC", "e": "Ils n'ont pas l'obligation de porter des signes distinctifs ; leurs matériels ne peuvent être confisqués. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Un journaliste peut continuer à filmer pendant la dispersion à condition :", "o": ["de rester à plus de 50 m", "de se placer de manière à ne pas être confondu avec les participants et à ne pas faire obstacle aux forces", "d'obtenir l'accord du CFP", "de présenter sa carte de presse à chaque sommation"], "a": "B", "e": "Valable pour les manifestations déclarées, interdites ou non déclarées. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "L'encerclement d'un groupe de manifestants :", "o": ["peut être maintenu jusqu'au lendemain pour contrôle d'identité", "doit ménager systématiquement, dès que possible, un point de sortie contrôlé", "vise à prévenir ou faire cesser des violences graves et imminentes", "doit être levé au plus tard à la fin de la manifestation ou de l'attroupement"], "a": "BCD", "e": "Durée strictement nécessaire et proportionnée ; communication régulière avec les personnes encerclées. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Le dispositif judiciaire intégré aux opérations d'ordre public est placé sous la direction :", "o": ["du préfet", "du DSO", "du procureur de la République", "du CFP"], "a": "C", "e": "Il vise à identifier et interpeller les auteurs ; interpellation pendant la manifestation ou différée. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Le SNMO prévoit auprès de chaque préfet :", "o": ["un référent chargé de l'appui aux victimes", "un référent journalistes uniquement", "un médiateur des manifestants", "un magistrat de permanence"], "a": "A", "e": "Référent pour l'appui aux victimes n'ayant pas pris part aux affrontements ; un référent est aussi prévu pour les journalistes. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "La grenade à main à effet sonore GL-304 CONDOR doit être lancée :", "o": ["au lanceur, en tir courbe", "à la main et au ras du sol, à distance du dispositif policier", "au lanceur, en tir tendu", "à la main, en cloche au-dessus de la foule"], "a": "B", "e": "Lancer à la main, au ras du sol, après appréciation de la trajectoire et du point d'explosion. — Source : Télégramme DGPN – grenades à main à effet sonore"}, {"t": 11, "s": "Lanceurs de grenades en maintien de l'ordre : la seconde et dernière sommation, avant leur emploi pour disperser un attroupement :", "o": ["doit être réitérée", "n'est pas nécessaire", "doit être faite par le CFP", "doit être faite par écrit"], "a": "A", "e": "Dispersion sur ordre exprès de l'autorité habilitée, après sommations, la seconde et dernière étant réitérée. — Source : Instruction DGPN/DGGN du 2/08/2017 – AFI"}, {"t": 11, "s": "Le SNMO renforce la transparence de l'action des forces notamment par :", "o": ["l'interdiction de toute captation d'images par le public", "la suppression des sommations", "le port de l'uniforme avec une mention de l'unité bien visible et le port du RIO", "l'anonymat des intervenants"], "a": "C", "e": "Les forces ne peuvent s'opposer à la captation d'images dans les lieux publics (sauf personnels spécifiques). — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Selon le SNMO, la grenade GLI-F4 a été retirée du service le :", "o": ["23 janvier 2019", "16 septembre 2021", "1er janvier 2021", "26 janvier 2020"], "a": "D", "e": "Remplacée par la GM2L (grenade assourdissante et lacrymogène) pour les lancers avec lanceur et par une grenade à effet sonore pour les lancers à main. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Outre la carte de presse, les journalistes et leurs accompagnants (technicien, agent de sécurité) peuvent établir leur qualité, depuis le 1er janvier 2022, par :", "o": ["une attestation normalisée d'identification fournie par leur employeur, leur commanditaire ou leur école de journalisme", "une accréditation délivrée par le DSO le jour de la manifestation", "un brassard « presse » délivré par la préfecture", "une simple déclaration sur l'honneur"], "a": "A", "e": "Attestation validée par la profession et reconnue par le ministère de l'Intérieur ; la carte de presse internationale (FIJ (Fédération internationale des journalistes)) est aussi admise. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Pour les manifestations publiques d'importance, le SNMO prévoit depuis le 1er février 2022 :", "o": ["un périmètre réservé aux journalistes, qu'ils ne peuvent quitter", "un canal d'échanges dédié (« boucle » de télécommunications) géré par ce référent", "un référent au sein des forces, présent sur le terrain, dédié aux relations avec les médias", "l'obligation pour les journalistes de s'inscrire 48 heures à l'avance"], "a": "BC", "e": "Le canal permet de fournir des informations opérationnelles, régler les difficultés et signaler les violences contre les journalistes ; l'accès est accordé automatiquement sur demande. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Selon le SNMO, le responsable de l'ordre public (ROP), autorité civile, est :", "o": ["le commandant de la force publique", "le maire de la commune concernée", "le préfet de département, le préfet de police ou le préfet de police des Bouches-du-Rhône", "le directeur du service d'ordre"], "a": "C", "e": "Le ROP définit la stratégie, fixe le cadre juridique et les grandes orientations ; il est présent ou représenté par un membre du corps préfectoral sur les opérations sensibles. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Le directeur du service d'ordre (DSO) est généralement :", "o": ["le commandant de l'unité de force mobile engagée", "le procureur de la République", "le chef territorial de la police ou de la gendarmerie, ou le directeur de l'ordre public et de la circulation à la préfecture de police", "le préfet de département"], "a": "C", "e": "Il dirige et coordonne l'ensemble des opérations, depuis son centre opérationnel ou sur place, et peut disposer d'unités de forces mobiles. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Les chefs de secteur opérationnel (CSO (chef de secteur opérationnel)) désignés par le DSO (directeur du service d'ordre) :", "o": ["transmettent directement leurs ordres aux manifestants", "mettent en œuvre eux-mêmes les moyens à la place du CFP", "ne peuvent pas procéder aux sommations", "disposent d'une marge d'initiative tactique et opérative pour accomplir la mission fixée par le DSO"], "a": "D", "e": "DSO et CSO sont autorités habilitées à procéder aux sommations (R. 211-11 CSI (code de la sécurité intérieure)) ; le CFP (commandant de la force publique) met en œuvre les moyens. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Pour renforcer le dialogue avec les manifestants, le SNMO prévoit notamment :", "o": ["une équipe « Liaison et Information » échangeant, sous l'autorité du DSO, avec les points de contact des organisateurs", "des haut-parleurs de forte puissance et des panneaux à message variable", "l'exploitation des réseaux sociaux et l'envoi de SMS groupés", "la suppression des sommations au profit de messages écrits"], "a": "ABC", "e": "Changement d'itinéraire, imminence d'un appel à la dispersion, présence de fauteurs de troubles… ; la doctrine vaut aussi pour les manifestations sans organisateurs. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "L'instruction du 23 janvier 2019, confirmée par le SNMO, vise à :", "o": ["interdire le LBD en maintien de l'ordre", "prévoir que le tireur LBD filme lui-même avec son téléphone personnel", "rendre le tir de LBD subordonné à l'accord du préfet", "doter dans toute la mesure du possible les porteurs de LBD d'une caméra-piéton, à fixation ventrale de préférence"], "a": "D", "e": "Les porteurs de caméra sont invités à enregistrer les conditions d'utilisation du LBD (lanceur de balles de défense) ; le porteur de caméra est désormais le superviseur. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "La responsabilité sans faute de l'État (art. L. 211-10 CSI (code de la sécurité intérieure)) peut être engagée pour des dommages subis lors d'une manifestation, dès lors que la victime :", "o": ["n'a pas concouru à la réalisation du préjudice subi", "n'a pas été impliquée dans les affrontements directs avec les forces de l'ordre", "a déposé plainte dans les 48 heures", "n'a pas commis de faute"], "a": "ABD", "e": "Un référent est désigné dans chaque département pour faciliter les démarches de ces victimes. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Les opérations majeures de maintien de l'ordre font l'objet de RETEX (retour d'expérience) spécifiques associant :", "o": ["les organisateurs de la manifestation", "uniquement les unités de forces mobiles", "l'ensemble de la chaîne de commandement (DSO-CSO-CFP) et les unités engagées", "le seul DSO et le préfet"], "a": "C", "e": "Les RETEX, sous l'autorité des structures DGPN (direction générale de la police nationale), PP (préfecture de police) et DGGN (direction générale de la gendarmerie nationale), permettent d'améliorer modes d'action, formation et équipement. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Selon la circulaire du 23 décembre 2008 annexée au SNMO (schéma national du maintien de l'ordre), quelles affirmations sont exactes ?", "o": ["Le floutage du visage des policiers avant diffusion est une obligation légale", "Les parties non ouvertes au public d'un local de police sont considérées comme un lieu privé", "En mission sur la voie publique, un policier ne peut en principe s'opposer à l'enregistrement de son image", "Il est exclu d'interpeller une personne pour la seule raison qu'elle filme, ou de lui retirer son matériel"], "a": "BCD", "e": "Aucune contrainte légale de floutage ; les policiers peuvent seulement en indiquer l'utilité. — Source : Circulaire du 23/12/2008 (annexe II du SNMO) – images et paroles des policiers"}, {"t": 11, "s": "L'enregistrement d'images de policiers en intervention peut être limité :", "o": ["dès que le policier refuse d'être filmé", "dans tout lieu public, sur décision du chef de patrouille", "pour la préservation des traces et indices et le respect du secret de l'enquête", "dès qu'un mineur se trouve sur la voie publique"], "a": "C", "e": "Ces limites s'ajoutent aux règles protégeant la dignité des personnes (victimes, personnes menottées non condamnées). — Source : Circulaire du 23/12/2008 (annexe II du SNMO) – images et paroles des policiers"}, {"t": 11, "s": "La diffusion de l'image d'une personne identifiable, mise en cause dans une procédure pénale mais non condamnée, faisant apparaître qu'elle porte des menottes ou entraves, est limitée par :", "o": ["l'article 803 du code de procédure pénale", "l'article L. 211-9 du code de la sécurité intérieure", "l'article 226-16 du code pénal", "l'article 35 ter de la loi du 29 juillet 1881 sur la liberté de la presse"], "a": "D", "e": "Disposition protégeant la dignité, également applicable à la personne placée en détention provisoire. — Source : Circulaire du 23/12/2008 (annexe II du SNMO) – images et paroles des policiers"}, {"t": 11, "s": "Le fait de dissimuler volontairement, sans motif légitime, tout ou partie de son visage dans une manifestation ou à ses abords, au cours ou à l'issue de laquelle des troubles sont commis ou risquent de l'être, est réprimé par :", "o": ["l'article 138 du code de procédure pénale", "l'article 431-9-1 du code pénal", "l'article R. 211-13 du CSI", "l'article 431-3 du code pénal"], "a": "B", "e": "L'article 138 CPP (code de procédure pénale) permet, au titre du contrôle judiciaire, d'interdire de participer à une manifestation. — Source : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 11, "s": "Selon le guide opérationnel des violences urbaines, lors de VU, le recours à la force ne nécessite pas de sommations préalables dès lors que :", "o": ["des voies de fait ou violences sont commises", "l'autorité préfectorale l'a préalablement autorisé par arrêté", "plus de cinquante personnes sont rassemblées", "les policiers ne peuvent défendre autrement les lieux qu'ils occupent"], "a": "AD", "e": "Cadres : légitime défense, état de nécessité, dissipation de l'attroupement (L. 211-9 CSI (code de la sécurité intérieure)), L. 435-1 CSI ; le cadre de réaction est privilégié. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Pendant le temps où ils participent, en unité constituée, à une opération de maintien de l'ordre, les policiers :", "o": ["sont placés sous l'autorité du procureur", "voient l'exercice de leurs attributions d'OPJ et d'APJ momentanément suspendu", "conservent toutes leurs attributions judiciaires", "ne peuvent faire usage d'aucune AFI"], "a": "B", "e": "Point d'attention du guide VU, distinguant le cadre MO (réponse graduée AHEF (autorité habilitée à décider de l'emploi de la force)/CFP) du cadre VU. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "En matière de violences urbaines, la police municipale :", "o": ["peut se substituer à la police nationale en cas de carence", "peut être placée en unité constituée sous l'autorité du CFP", "peut intervenir dans un contexte de violences, à la différence des dispositifs de maintien de l'ordre", "peut être intégrée aux unités constituées de la police nationale"], "a": "C", "e": "Son rôle et ses modalités d'engagement sont définis en amont avec le responsable du service municipal. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Les arrêtés de police dont le champ d'application excède le territoire communal relèvent :", "o": ["du maire de la commune la plus peuplée", "du directeur départemental de la police nationale", "du DGPN", "des préfets de département et, dans l'agglomération parisienne, du préfet de police"], "a": "D", "e": "Le préfet peut aussi se substituer au maire en cas de carence. Les mesures générales et absolues sont proscrites (ex. couvre-feu ciblé, interdiction des artifices). — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Circuits de demande de renforts en violences urbaines : quelles affirmations sont exactes ?", "o": ["Le RAID n'est engagé que sur décision du DGPN", "Les CRS à projection rapide sont engagées sur décision du préfet de zone", "Le déclenchement de la BRI-PP relève du préfet de police de Paris", "Le renfort des unités de force mobile est sollicité auprès du préfet de département, leur emploi étant décidé par l'UCFM"], "a": "ACD", "e": "Renforts départementaux : état-major départemental ; interdépartementaux : état-major zonal ; CRS (compagnies républicaines de sécurité) à projection rapide : décision du DGPN (directeur général de la police nationale). — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "En violences urbaines, la préservation de l'intégrité des policiers impose qu':", "o": ["les policiers interviennent en civil", "l'intervention soit différée jusqu'à l'arrivée du RAID", "un OPJ accompagne chaque équipage", "aucune intervention ne soit menée, sans appui, par un équipage isolé"], "a": "D", "e": "Priorité absolue ; l'intervention coordonnée, notamment en colonne, est privilégiée. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Pour faciliter le traitement judiciaire des violences urbaines, le guide préconise notamment de :", "o": ["interdire aux riverains de filmer les interventions", "positionner un OPJ au centre de supervision urbain (CSU) pour renseigner sur les cibles et les images à extraire", "désigner un effectif responsable du dispositif judiciaire", "veiller au déclenchement des caméras-piétons"], "a": "BCD", "e": "Les policiers ne peuvent faire obstacle à l'enregistrement ou à la diffusion de leur image sur la voie publique. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Concernant l'emploi des chiens et des chevaux en violences urbaines :", "o": ["les chiens défense-intervention peuvent être employés à des fins de dissuasion, en périphérie des violences", "les chiens sont engagés en tête de colonne pour disperser les émeutiers", "leur engagement reste possible quel que soit le risque pour leur intégrité", "les brigades équestres peuvent canaliser les émeutiers et effectuer des bonds offensifs"], "a": "AD", "e": "Les chiens restent en périphérie, à des fins dissuasives. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Les engins lanceurs d'eau de certaines unités de force mobile :", "o": ["constituent un appui utile contre les feux de barricades et incendies", "sont réservés aux seules opérations de maintien de l'ordre", "sont engagés uniquement sur décision du DGPN", "sont employés exclusivement pour disperser les attroupements après sommations"], "a": "A", "e": "Les unités de force mobile « nouvelle génération » sont déployées sur le principe de la modularité (à pied, embarquées, constituées ou fractionnées). — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Les moyens aériens en violences urbaines :", "o": ["ne peuvent être utilisés que de jour", "peuvent transmettre leurs images en direct au centre de commandement, sous la supervision du coordonnateur 3D en cas de moyens multiples", "peuvent être employés dans un cadre administratif (art. L. 242-5 CSI) pour prévenir les atteintes aux personnes et aux biens", "présentent un intérêt majeur, notamment dans l'obscurité, pour une vue d'ensemble et l'identification des fauteurs de troubles"], "a": "BCD", "e": "Ils peuvent aussi réaliser des photographies aériennes des sites. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Remontée d'information « à chaud » via le formulaire « VU » de l'application PRIO (plateforme de remontée des informations opérationnelles) : quelles règles sont exactes ?", "o": ["Les informations sont renseignées dans la demi-heure qui suit les faits", "Les informations ne peuvent plus être modifiées une fois saisies", "Les interpellations, gardes à vue et policiers blessés sont renseignés sur le fait principal, pour éviter une double comptabilité", "Tous les incendies de véhicules, initiaux ou par propagation, y sont inscrits quelle qu'en soit la cause"], "a": "ACD", "e": "Les autres faits ne sont saisis que s'ils s'inscrivent dans un contexte de VU ; le CIPN (centre d'information de la police nationale) est avisé téléphoniquement en temps réel. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Après des violences urbaines, les personnes impliquées peuvent être inscrites, par l'intermédiaire des services de renseignement, au :", "o": ["fichier de prévention des atteintes à la sécurité publique (FPASP)", "fichier des personnes recherchées (FPR)", "fichier national des étrangers", "traitement d'antécédents judiciaires (TAJ) par le seul chef de patrouille"], "a": "A", "e": "Inscription au FPASP (fichier de prévention des atteintes à la sécurité publique) via les services de renseignement. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Le retour d'expérience après des violences urbaines comprend :", "o": ["un RETEX à froid limité au seul service local de sécurité publique", "un unique bilan statistique transmis au préfet", "une enquête administrative systématique de l'IGPN", "un débriefing à chaud, immédiatement après la fin des opérations, prenant en compte le ressenti des agents"], "a": "D", "e": "Deux temps : à chaud et à froid ; une décision opérationnelle fait suite au bilan. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Le procès-verbal de contexte rédigé après des violences urbaines doit :", "o": ["être complété d'un procès-verbal de bilan", "être accompagné de photos et récapituler les moyens de défense engagés et leur cadre juridique, le nombre de blessés et le montant des dégâts", "décrire la séquence et la chronologie des interventions", "être rédigé par le préfet"], "a": "ABC", "e": "Il facilite le traitement judiciaire ; l'alimentation du TSUA (traitement relatif au suivi de l'usage des armes) fait partie du compte rendu des moyens engagés. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Selon le guide VU, les unités spécialisées (RAID (Recherche, assistance, intervention, dissuasion), BRI-PP) ne sont envisagées :", "o": ["qu'en situation très dégradée au regard de la durée, de l'étendue et de l'intensité des violences, et de l'inefficacité des unités conventionnelles", "pour toute interpellation de mineur", "dès le premier soir de violences", "pour assurer la protection des journalistes"], "a": "A", "e": "Elles constituent le niveau 3 du schéma national d'intervention et disposent de moyens de force intermédiaire spécifiques et de capacités de progression sous blindage. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 11, "s": "Selon le guide VU, le cadre d'emploi des moyens de force intermédiaire en violences urbaines :", "o": ["interdit le LBD", "est strictement identique à celui du maintien de l'ordre", "n'est pas aussi limitatif qu'en maintien de l'ordre", "impose des sommations préalables à tout usage"], "a": "C", "e": "Cf. annexe 14 du guide ; vérifier les habilitations et rappeler les règles d'emploi. — Source : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 12, "s": "La palpation de sécurité :", "o": ["implique le retrait de vêtements", "est une mesure administrative ayant pour finalité la sécurité des policiers, de la personne et du public", "ne doit pas revêtir de caractère systématique lors des contrôles d'identité", "nécessite le consentement de la personne lors d'un contrôle d'identité"], "a": "BC", "e": "Pas de consentement nécessaire ; mesure peu intrusive sans fouille ni retrait de vêtement. — Source : Instruction DGPN/DGGN – pratique des palpations de sécurité ; TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "La palpation de sécurité peut être pratiquée de manière plus systématique :", "o": ["lors de tout contrôle d'identité sur réquisition du parquet", "avant la prise en charge d'une personne dans un véhicule administratif", "après l'interpellation d'une personne, quel qu'en soit le motif", "lors des déplacements d'une personne gardée à vue"], "a": "BCD", "e": "Sur réquisitions (78-2 al. 2 et 3), il faut des éléments démontrant une dangerosité potentielle. — Source : TDI – La palpation de sécurité (vs 06-2021) ; Instruction DGPN/DGGN – pratique des palpations de sécurité"}, {"t": 12, "s": "La palpation de sécurité est obligatoirement réalisée par une personne de même sexe s'agissant :", "o": ["de toute personne faisant l'objet d'un contrôle d'identité", "des seules personnes mineures", "de toute personne contrôlée sur la voie publique", "des personnes gardées à vue"], "a": "D", "e": "Obligatoire pour les gardés à vue (et certaines personnes retenues) ; ailleurs « chaque fois que possible ». — Source : Instruction DGPN/DGGN – pratique des palpations de sécurité"}, {"t": 12, "s": "Dans le déroulement d'une palpation de sécurité, la première étape consiste à :", "o": ["effectuer immédiatement la palpation", "inviter la personne à remettre volontairement les objets estimés dangereux", "recourir aux moyens techniques de détection", "informer la personne qu'elle va être palpée"], "a": "B", "e": "Remise volontaire, puis moyens de détection, puis information, puis palpation. — Source : Instruction DGPN/DGGN – pratique des palpations de sécurité"}, {"t": 12, "s": "Lors d'une palpation, la fiche TDI recherche, chaque fois que les circonstances le permettent :", "o": ["une pratique à l'abri du regard du public", "les bras levés de la personne", "la palpation avec appuis", "l'amené au sol préalable"], "a": "A", "e": "Bras levés, appuis, amené au sol : démonstrations ostensibles à éviter. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "Toute dérogation au principe de palpation par une personne de même sexe :", "o": ["doit être signalée à l'IGPN", "nécessite l'accord préalable d'un OPJ", "doit faire l'objet d'une justification détaillée dans les formes administratives ou judiciaires requises", "est interdite en toutes circonstances"], "a": "C", "e": "Hormis situations exceptionnelles (dangerosité, urgence), avec justification détaillée. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "Selon l'article 803 du CPP (code de procédure pénale), le port des menottes n'est possible que si la personne est considérée :", "o": ["comme susceptible de tenter de prendre la fuite", "comme refusant de décliner son identité", "comme auteur d'un crime", "comme dangereuse pour autrui ou pour elle-même"], "a": "AD", "e": "Mesures utiles aussi pour éviter qu'elle soit photographiée ou filmée. — Source : TDI – Menottage (vs 01-2022) ; Note DGPN 13/09/2004 – utilisation des menottes"}, {"t": 12, "s": "Le menottage :", "o": ["doit être motivé et justifié dans le procès-verbal", "ne doit pas être excessivement serré", "relève de la responsabilité personnelle du fonctionnaire", "est systématique lors d'une interpellation"], "a": "ABC", "e": "Il ne doit en aucun cas être systématique ; tout incident (blessure) est mentionné en procédure. — Source : TDI – Menottage (vs 01-2022) ; Note DGPN 13/09/2004 – utilisation des menottes"}, {"t": 12, "s": "Concernant la technique de menottage, quelles affirmations sont exactes ?", "o": ["Après la pose, il est conseillé de verrouiller les bracelets", "L'entrave d'un individu à un point fixe est à proscrire", "Les menottes se placent de préférence au niveau du creux lombaire", "Par principe, le menottage s'effectue toujours dans le dos"], "a": "ABD", "e": "Le creux lombaire est à proscrire (blessures en cas de chute sur le dos). — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Lors de la préhension, la menotte est saisie fermement sur :", "o": ["la chaînette", "sa partie fixe", "sa partie mobile", "la serrure"], "a": "B", "e": "La partie mobile est ensuite apposée sur le poignet, entre la main et l'avant-bras. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "L'agent chargé du menottage s'approche de l'individu debout lorsque :", "o": ["l'individu est adossé à un mur", "son binôme a sorti son arme", "l'individu a les bras levés", "le dispositif est en capacité de passer simultanément en distance d'interaction et l'intérieur des mains est visible"], "a": "D", "e": "Placer l'individu contre un appui peut mettre le dispositif en danger. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Dès les menottes posées, le policier :", "o": ["palpe les zones prioritaires et directement accessibles", "attend l'arrivée au service pour toute palpation", "retire les lacets et la ceinture", "place l'individu face à un mur"], "a": "A", "e": "Même si les circonstances repoussent la palpation complète. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Chef de patrouille, vous devez effectuer un contrôle puis une palpation ; contexte favorable, situation figée. Le placement prescrit est :", "o": ["le binôme contact", "la triangulation latérale", "le binôme éclaté", "le binôme réuni"], "a": "B", "e": "Binôme réuni : analyse/patrouille ; binôme contact : contexte défavorable ou incertain. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "Le binôme réuni est prescrit :", "o": ["pour l'interpellation d'un individu armé", "pour les palpations en situation figée", "en contexte défavorable ou incertain", "pour les phases d'analyse et/ou de patrouille"], "a": "D", "e": "Côte à côte, à environ une longueur de bras ; permet de basculer vers le schéma le plus opérant. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "En binôme contact, l'agent arrière :", "o": ["gère le tiers mais aussi la topographie et la périphérie, et guide les déplacements", "n'a aucun contact physique avec l'agent avant", "focalise toute son attention sur le tiers", "se place en retrait de son côté fort"], "a": "A", "e": "L'agent avant focalise sur le tiers ; l'agent arrière est en retrait de son côté faible, main ou coude sur l'épaule. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "Triangulation latérale : l'individu se déplace. Pour éviter de rendre inopérants les axes de tir :", "o": ["on bascule en binôme réuni", "on le suit dans son sens de déplacement en conservant la configuration", "l'agent arrière passe devant", "on l'immobilise contre un appui"], "a": "B", "e": "Inconvénients : topographie, axes de tir, éloignement. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "Selon la fiche PLI, la répartition des rôles Protection / Liaison / Interpellation :", "o": ["est fixée par le CIC", "n'est requise qu'au-delà de trois policiers", "s'organise une fois l'individu maîtrisé", "doit être effectuée avant tout début d'action"], "a": "D", "e": "Le dispositif peut ensuite évoluer selon la situation. — Source : TI – Protection, liaison, interpellation (PLI)"}, {"t": 12, "s": "Concernant la PLI, quelles affirmations sont exactes ?", "o": ["La liaison se limite aux échanges radio avec le CIC", "L'interpellation s'entend au sens large, d'une prise de contact verbal jusqu'aux techniques coercitives", "Une intervention sans protection est envisageable en cas d'urgence", "Une protection efficace vise une surveillance à 360° autour du dispositif"], "a": "BD", "e": "La liaison ne se limite pas aux échanges radio. « Aucune intervention de police n'est envisageable sans protection ». — Source : TI – Protection, liaison, interpellation (PLI)"}, {"t": 12, "s": "Selon l'article R. 434-16 du CSI (code de la sécurité intérieure), la palpation de sécurité :", "o": ["est exclusivement une mesure de sûreté", "ne revêt pas un caractère systématique", "a pour finalité de vérifier que la personne n'est pas porteuse d'un objet dangereux pour elle-même ou pour autrui", "peut permettre la découverte d'objets utiles à la manifestation de la vérité"], "a": "ABC", "e": "La recherche d'objets utiles à la manifestation de la vérité relève de la fouille de l'art. 63-7 CPP (code de procédure pénale), distincte de la palpation. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "L'instruction DGPN (direction générale de la police nationale)/DGGN distingue la palpation de sécurité :", "o": ["du contrôle visuel des accessoires", "de l'inventaire des objets à l'arrivée en cellule", "de la fouille de sécurité pouvant impliquer le retrait de vêtements (art. 63-6 CPP)", "de la fouille visant à découvrir sur le gardé à vue des objets utiles à la manifestation de la vérité (art. 63-7 al. 1 CPP)"], "a": "CD", "e": "Les mesures de sécurité de l'art. 63-6 ne peuvent consister en une fouille intégrale ; la fouille intégrale (63-7) est décidée par un OPJ (officier de police judiciaire) et réalisée dans un espace fermé par une personne de même sexe. — Source : Instruction DGPN/DGGN – pratique des palpations de sécurité"}, {"t": 12, "s": "Selon la fiche TDI, la palpation est en outre pratiquée de manière plus systématique :", "o": ["lors de tout contrôle d'identité sur la voie publique", "avant de prendre en charge une personne dans un véhicule administratif", "à l'entrée de tout bâtiment public", "lors de tout contrôle routier"], "a": "B", "e": "S'ajoute le cas de l'interpellation, quel qu'en soit le motif. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "Techniquement, la palpation de sécurité s'effectue :", "o": ["du bas du corps vers le haut", "par glissement continu des mains le long du corps", "exclusivement à mains nues pour conserver la sensibilité", "par pressions successives avec la partie interne des mains, non par glissement"], "a": "D", "e": "Le glissement expose aux piqûres et coupures ; le port de gants peut s'imposer (sécurité, hygiène, traces et indices) ; on va du haut vers les membres inférieurs. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "Les zones à palper prioritairement, car directement accessibles et susceptibles de dissimuler une arme, sont :", "o": ["la tête, le cou et les épaules", "les chevilles, les mollets et les chaussures", "les seules poches de poitrine", "le creux lombaire, la ceinture abdominale et les aisselles"], "a": "D", "e": "Après s'être assuré que rien n'est dissimulé dans le creux des mains (MAINS = DANGER). — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "La palpation arrière :", "o": ["s'accompagne d'un contrôle systématique de l'avant-bras", "est le cas de palpation à privilégier", "expose le policier aux coups les plus vulnérants", "est imposée à l'entrée d'un stade"], "a": "B", "e": "La palpation avant, imposée par la situation ou la localisation (stade, tribunal, couloir), s'accompagne du contrôle de l'avant-bras et offre une sécurité minimale. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "La palpation avant :", "o": ["offre au policier une sécurité minimale", "peut être imposée par la palpation systématique d'un grand nombre de personnes (stade, tribunal)", "s'accompagne d'un contrôle systématique du coude", "peut être une alternative lorsque l'on privilégie la collaboration, son apparence étant moins coercitive"], "a": "ABD", "e": "Contrôle systématique de l'avant-bras (et non du coude, propre à la palpation arrière). — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "Une personne maîtrisée et menottée au sol, allongée sur le ventre :", "o": ["reste sur le ventre jusqu'à la fin complète de la palpation", "est ensuite placée sur un flanc puis sur l'autre, pour favoriser la reprise de la respiration et palper la ceinture abdominale", "est palpée sur les autres zones (jambes, torse) en position assise ou debout", "fait l'objet d'une palpation de la zone lombaire et de la ceinture dorsale immédiatement après la pose des entraves"], "a": "BCD", "e": "Toute personne menottée doit être palpée dès que possible et en tout état de cause avant le retrait des entraves. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "La palpation de sécurité et les éléments objectifs qui l'ont motivée :", "o": ["doivent toujours être retranscrits dans un acte administratif ou judiciaire (MCI, rapport, PV), même si aucun objet dangereux n'est découvert", "sont consignés uniquement sur la main courante du poste", "ne sont mentionnés que si un objet dangereux est découvert", "ne sont jamais retranscrits, s'agissant d'une mesure administrative"], "a": "A", "e": "Dans l'action collective, un seul policier palpe pendant que les équipiers assurent la protection. — Source : TDI – La palpation de sécurité (vs 06-2021)"}, {"t": 12, "s": "La note DGPN (direction générale de la police nationale) du 13 septembre 2004 relative aux menottes a été prise après que :", "o": ["l'article 803 du CPP a été créé", "le Défenseur des droits a rendu un avis", "l'IGPN a signalé des pratiques de menottages trop serrés", "un arrêt de la CEDH a condamné la France"], "a": "C", "e": "Elle rappelle que la décision de menotter relève de la responsabilité personnelle du fonctionnaire, avec discernement et proportionnalité (article préliminaire III CPP (code de procédure pénale)). — Source : Note DGPN 13/09/2004 – utilisation des menottes"}, {"t": 12, "s": "Selon la fiche Menottage, l'appréciation de la dangerosité ou du risque de fuite, relatée en procédure, s'appuie notamment sur :", "o": ["l'apparence physique de la personne", "l'heure de l'interpellation", "le comportement de l'individu (fuite, rébellion, menaces, violences…)", "le résultat de la consultation du casier judiciaire, effectuée a posteriori"], "a": "C", "e": "Les juridictions relèvent systématiquement le manque de justification de ces notions. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Selon les principes généraux du menottage :", "o": ["il faut intégrer systématiquement le principe de « non-coopération » de la personne", "le menottage s'effectue par principe toujours dans le dos", "le menottage devant soi est la règle pour les mineurs", "l'entrave d'un individu à un point fixe est à proscrire"], "a": "ABD", "e": "Les menottes pourraient être utilisées comme une arme contre les policiers ; c'est le comportement de l'individu qui détermine la stratégie. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Une fois la seconde menotte passée et ajustée, le policier interpellateur :", "o": ["lève le bras pour signaler la fin du menottage", "annonce à haute et intelligible voix « menotté » et donne une tape significative sur l'épaule de la protection", "retire immédiatement la contrainte sur le bras menotté", "prévient le CIC par radio avant tout autre geste"], "a": "B", "e": "La communication verbale permanente entre policiers est primordiale. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Pour relever ou faire asseoir un individu menotté, il convient :", "o": ["de tirer sur la chaînette des menottes", "de le faire rouler sur le dos", "de soulever l'individu par les deux poignets entravés", "de ne pas saisir ni agir sur les menottes, ce qui peut causer des douleurs ou blessures inutiles"], "a": "D", "e": "Une fois assis, il est maintenu buste incliné vers l'avant par un contrôle de la jambe en appui dans le dos et sur la ligne des épaules. — Source : TDI – Menottage (vs 01-2022)"}, {"t": 12, "s": "Dans le placement en trinôme, le troisième agent :", "o": ["procède à la pose des menottes", "a pour missions prioritaires la liaison et la sécurité périphérique", "se tient au contact direct des deux premiers agents", "procède systématiquement à la palpation"], "a": "B", "e": "Les deux premiers agents se concentrent sur la personne à gérer. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "Le binôme éclaté :", "o": ["est adopté particulièrement quand le tiers exhibe une arme à feu", "impose aux deux policiers de se placer l'un derrière l'autre", "permet de ne pas offrir une seule et même cible", "doit évoluer dans le sens de déplacement du tiers, à distance permettant de reconstituer le binôme contact"], "a": "ACD", "e": "Si la situation n'évolue pas favorablement vers le binôme contact, les policiers temporisent en attente de renfort ou se replient. — Source : TI – Les placements (vs 12-2022)"}, {"t": 12, "s": "Selon la fiche PLI, « appréhender » (art. 73 CPP (code de procédure pénale)), par rapport à « interpeller » :", "o": ["implique une coercition physique et la mise en œuvre de GTPI, alors qu'interpeller implique davantage une coercition verbale", "est un simple synonyme d'interpeller", "implique une coercition verbale, alors qu'interpeller est physique", "est réservé aux OPJ"], "a": "A", "e": "Il existe une progression dans l'approche professionnelle et déontologique entre interpeller et appréhender. — Source : TI – Protection, liaison, interpellation (PLI)"}, {"t": 12, "s": "Selon la fiche PLI, le rôle de protection vise notamment à :", "o": ["assurer une surveillance à 360° autour du dispositif d'interpellation", "protéger le policier lui-même, ses coéquipiers et les tiers, y compris la personne interpellée", "rester figé sur un emplacement défini avant l'action", "protéger, dans la mesure du possible, les objets (matériels, véhicules, traces et indices)"], "a": "ABD", "e": "Le positionnement n'est pas figé et s'adapte constamment ; c'est le responsable qui distribue les rôles initiaux. — Source : TI – Protection, liaison, interpellation (PLI)"}, {"t": 12, "s": "Selon la fiche « Points clés du signalement », les premiers fonctionnaires arrivés sur les lieux d'une infraction doivent :", "o": ["recueillir d'urgence auprès des témoins et victimes les renseignements nécessaires à la recherche des individus en fuite", "transmettre le signalement par écrit au CIC avant toute diffusion radio", "attendre l'audition complète des témoins par un OPJ avant toute diffusion", "ne diffuser que les signalements comportant le type et l'habillement"], "a": "A", "e": "Les caractéristiques recueillies pourront être reprises dans tout acte de la procédure. — Source : TI – Points clés du signalement"}, {"t": 13, "s": "La méthode de raisonnement opérationnel (MRO) s'articule, dans l'ordre, autour de :", "o": ["Renseignement – Protection – Intervention", "Analyse de la situation – Cadre juridique – Tactique d'action", "Analyse – Tactique – Compte rendu", "Cadre juridique – Analyse – Tactique"], "a": "B", "e": "Que se passe-t-il ? Quel cadre légal ? Comment intervenir ? — Source : TI – Conduite à tenir face à un forcené retranché ; PPI – Principes de levée de doute lors d'agressions armées"}, {"t": 13, "s": "Forcené retranché : pour se transporter sur les lieux, les primo-intervenants :", "o": ["arrivent toutes sirènes hurlantes pour dissuader", "établissent dès que possible un périmètre de sécurité", "se rendent sur place sans précipitation", "n'utilisent pas, au moins à proximité, les signaux d'urgence lumineux ou sonores"], "a": "BCD", "e": "Ne pas s'exposer ni exposer les tiers inutilement. — Source : TI – Conduite à tenir face à un forcené retranché"}, {"t": 13, "s": "Forcené retranché : quelles mesures sont préconisées ?", "o": ["Couper le gaz et l'électricité dès l'arrivée sur place", "Maintenir sur place, en lieu sécurisé, les personnes pouvant apporter leur concours (parents, médecin…)", "Tenter immédiatement une interpellation par surprise", "Localiser les arrivées de gaz et compteurs électriques"], "a": "BD", "e": "La coupure se fait en fonction de l'évolution de la situation ; les secours sont avisés par le CIC (centre d'information et de commandement). Sauf urgence et péril immédiat, l'interpellation est confiée à une unité spécialisée (FIPN (force d'intervention de la police nationale)). — Source : TI – Conduite à tenir face à un forcené retranché"}, {"t": 13, "s": "Forcené retranché : sauf urgence et péril immédiat, l'interpellation est confiée :", "o": ["au premier équipage arrivé", "à une unité spécialisée de la FIPN", "à la BAC locale", "à l'OPJ de permanence"], "a": "B", "e": "Les primo-intervenants renseignent, sécurisent et rendent compte. — Source : TI – Conduite à tenir face à un forcené retranché"}, {"t": 13, "s": "Levée de doute après déclenchement d'une alarme dans un établissement financier : que ne faut-il PAS faire ?", "o": ["Exploiter les systèmes de communication sonores ou vidéo", "Traverser une rue dans l'alignement de l'établissement", "Passer devant l'établissement avec un véhicule sérigraphié ou banalisé", "Stationner le véhicule à proximité immédiate"], "a": "BCD", "e": "L'exploitation des systèmes sonores/vidéo est un mode normal de levée de doute (avec l'envoi de patrouille). — Source : PPI – Principes de levée de doute lors d'agressions armées"}, {"t": 13, "s": "Pour le recueil d'informations lors d'une levée de doute, la fiche souligne que :", "o": ["un seul policier doit intervenir", "des policiers en civil peuvent être plus adaptés à la discrétion souhaitée", "il faut pénétrer rapidement dans l'établissement", "les avertisseurs doivent être actionnés"], "a": "B", "e": "Grande discrétion ; ne pas tenter de pénétrer dans l'établissement. — Source : PPI – Principes de levée de doute lors d'agressions armées"}, {"t": 13, "s": "Agression armée à caractère crapuleux en cours : que ne faut-il PAS faire ?", "o": ["Faire obstacle au départ de leur véhicule", "Solliciter la présence de l'OPJ territorialement compétent", "Chercher à bloquer les agresseurs à l'intérieur", "Les interpeller à leur sortie de l'établissement"], "a": "ACD", "e": "Risque de prise d'otages ou d'affrontement armé ; solliciter renforts et OPJ (officier de police judiciaire) est préconisé. — Source : PPI – Agression armée à caractère crapuleux"}, {"t": 13, "s": "Agression crapuleuse : les auteurs prennent la fuite en véhicule. L'usage des armes à feu sur le véhicule pour faire cesser la fuite :", "o": ["relève de la décision du chef de bord", "est proscrit, sauf cas de légitime défense", "est autorisé après sommations", "est autorisé si le véhicule est identifié"], "a": "B", "e": "On avise instantanément le CIC (nombre, description, tenue, véhicule, direction). — Source : PPI – Agression armée à caractère crapuleux"}, {"t": 13, "s": "Agression armée à caractère meurtrier confirmée : les mesures prises par les policiers visent :", "o": ["la négociation prioritaire avec l'auteur", "la prise de renseignements", "l'attente systématique des unités spécialisées avant toute action", "la neutralisation du ou des auteurs en cas d'opportunité"], "a": "BD", "e": "Elles visent aussi la limitation des risques de propagation. Objectif : saisir toute opportunité de faire cesser la tuerie ; aussi l'exfiltration des victimes. — Source : PPI – Agression armée à caractère meurtrier"}, {"t": 13, "s": "Agression armée à caractère meurtrier : la protection balistique la plus efficace offerte par l'environnement urbain est :", "o": ["une portière de véhicule", "le bloc moteur d'un véhicule", "une vitrine", "le coffre d'un véhicule"], "a": "B", "e": "Le bloc moteur, quel que soit le calibre. — Source : PPI – Agression armée à caractère meurtrier"}, {"t": 13, "s": "Dans une tuerie de masse, le rôle des primo-intervenants :", "o": ["est purement informatif", "sera déterminant quant au nombre de victimes", "se limite au bouclage du périmètre", "consiste à attendre la FIPN"], "a": "B", "e": "Il ne s'agit pas d'une intervention spécialisée mais de saisir toute opportunité. — Source : PPI – Agression armée à caractère meurtrier"}, {"t": 13, "s": "Un objet abandonné est déclaré suspect. Le périmètre de sécurité immédiat est de :", "o": ["50 m objet / 100 m véhicule", "100 m objet / 200 m véhicule", "100 m objet / 300 m véhicule", "200 m objet / 400 m véhicule"], "a": "B", "e": "Seuls les démineurs procèdent à la levée de doute. — Source : Instruction DPN-3.1.3 (07/2017) – objet suspect, EEI"}, {"t": 13, "s": "Face à un individu potentiellement porteur d'une charge explosive, les distances minimales sont de :", "o": ["100 m ; 200 m", "30 m à couvert ; 60 m en véhicule", "60 m ; 200 m", "60 m à couvert ; 100 m pour un individu dans un véhicule suspect"], "a": "D", "e": "60 m minimum à couvert ; 100 m pour un individu dans un véhicule suspect. — Source : Instruction DPN-3.1.3 (07/2017) – objet suspect, EEI"}, {"t": 13, "s": "Le refus d'obtempérer simple (art. L.233-1 C. route) est puni de :", "o": ["5 ans et 75 000 €", "1 an et 7 500 €", "3 ans et 45 000 €", "2 ans d'emprisonnement et 15 000 € d'amende"], "a": "D", "e": "Circonstances aggravantes prévues à l'art. L.233-1-1. — Source : Fiche mémo – refus d'obtempérer et véhicules en fuite ; Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "Selon l'instruction du 16/05/2025, la prise en charge d'un véhicule en fuite relève :", "o": ["d'une décision concertée entre le chef de bord et le conducteur du véhicule de police", "de la seule décision du CIC", "du conducteur seul", "de l'officier de permanence uniquement"], "a": "A", "e": "Par principe la poursuite doit être engagée, avec discernement. — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "Au cours d'une poursuite, la salle de commandement / le CIC (centre d'information et de commandement) peut :", "o": ["imposer le silence radio et la discipline sur les ondes", "imposer aux équipages l'arrêt des avertisseurs sonores", "faire cesser sans délai la poursuite", "autoriser l'usage de l'arme hors légitime défense et L.435-1 CSI"], "a": "AC", "e": "Les avertisseurs restent actionnés ; le CIC coordonne renforts et plan d'interception. L'arme reste exclusivement dans les cadres 122-5 CP et L.435-1 CSI (code de la sécurité intérieure). — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025 ; Fiche mémo – refus d'obtempérer et véhicules en fuite"}, {"t": 13, "s": "Lors d'une poursuite, le déclenchement de la caméra-piéton ou de tout autre moyen vidéo est :", "o": ["facultatif", "interdit", "laissé à l'appréciation du CIC", "obligatoire"], "a": "D", "e": "Aussi : ceinture systématique, avertisseurs et géolocalisation. — Source : Fiche mémo – refus d'obtempérer et véhicules en fuite"}, {"t": 13, "s": "Lors de l'interception d'un véhicule en fuite, il faut privilégier :", "o": ["les DIVA lorsqu'ils sont immédiatement disponibles et que la situation le permet", "le tir dans les pneus", "le contact par l'arrière", "le barrage avec véhicule de police occupé"], "a": "A", "e": "DIVA (dispositif d'interception des véhicules automobiles) : dispositifs d'interception de véhicules automobiles. — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "Forcené : dès le premier contact avec le CIC (centre d'information et de commandement) ou la patrouille, la priorité est de :", "o": ["obtenir un maximum de renseignements (lieux, individu, armes, seul ou non)", "pénétrer dans les lieux", "faire venir la presse", "couper le gaz immédiatement"], "a": "A", "e": "Lieux, individu, origine de la crise, isolement, armes, blessés. — Source : TI – Conduite à tenir face à un forcené retranché"}, {"t": 13, "s": "Agression crapuleuse : en cas de sortie des auteurs, on avise instantanément le CIC (centre d'information et de commandement), notamment de :", "o": ["leur nombre, description physique et tenue vestimentaire", "leur adresse", "leur casier", "leur identité exacte"], "a": "A", "e": "Ainsi que le véhicule et la direction de fuite. — Source : PPI – Agression armée à caractère crapuleux"}, {"t": 13, "s": "Dans le glossaire tactique « Attentats », le terme « cerise » désigne :", "o": ["un point de regroupement des victimes", "une grenade lancée par la police", "un tireur isolé", "une grenade lancée par un individu hostile"], "a": "B", "e": "Le terme « grenade » est réservé aux engins lancés par un individu hostile. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Selon le glossaire tactique, un « contact » est :", "o": ["un individu hostile identifié", "une victime à extraire", "une personne qui se trouve à vue mais qui n'est pas identifiée", "un policier en liaison radio"], "a": "C", "e": "À distinguer de l'hostile. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Selon le glossaire tactique, les façades d'un bâtiment :", "o": ["ont pour façade 1 celle comportant l'entrée principale", "sont complétées par des niveaux numérotés à partir de 0, niveau de l'entrée principale", "sont désignées par les lettres A à D", "sont désignées de 1 à 4 dans le sens des aiguilles d'une montre"], "a": "ABD", "e": "Les fenêtres sont numérotées de gauche à droite à partir de 1. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Dans le glossaire tactique, « confiner » signifie :", "o": ["isoler une portion de terrain par un dispositif continu", "rechercher du renseignement sans engager le contact", "forcer à rester dans un espace", "retirer quelqu'un d'un lieu de crise"], "a": "C", "e": "Les primo-intervenants engagent les terroristes afin de les confiner. B = boucler, C = éclairer, D = extraire. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Selon le glossaire tactique, la « bulle tactique » :", "o": ["est un mode opératoire permettant l'étanchéité du dispositif d'interpellation ou d'intervention", "a été mise au point par le seul GIGN", "désigne la zone de regroupement des victimes", "est réservée aux crises d'origine naturelle"], "a": "A", "e": "Elle est mise en œuvre de façon coordonnée entre les différents services. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Selon le glossaire tactique, le COP (commandant des opérations de police) :", "o": ["commande directement l'intervention des unités de 3e niveau", "a la responsabilité de la coordination inter-services lors de crises d'origine criminelle", "a un grade qui peut évoluer dans le temps", "occupe la fonction sommitale de la chaîne de commandement des opérations de police"], "a": "BCD", "e": "L'intervention spécialisée est commandée par le COIS. — Source : Annexe DPN-3.1 – Glossaire tactique « Attentats » (06/2017)"}, {"t": 13, "s": "Tuerie de masse : avant la progression, les moyens radio doivent de préférence :", "o": ["être tenus à la main par le chef d'équipe", "être coupés pour garantir la discrétion", "être portés sur la tenue (ceinture, bandoulière), avec micro déport voire oreillette, pour libérer les mains", "être regroupés sur un seul policier"], "a": "C", "e": "Le déploiement individuel des portatifs est privilégié ; l'équipement se fait sous protection armée et hors vue de la zone de tuerie. — Source : PPI – Gestion tactique d'une tuerie de masse (intervenants 1er niveau, 08-2018)"}, {"t": 13, "s": "Tuerie de masse : dans la répartition des secteurs d'observation et de riposte (SOR) :", "o": ["le chef d'équipe couvre seul le secteur arrière", "la vitesse de progression augmente à l'approche de la zone d'exclusion", "le porteur de l'arme d'épaule couvre l'axe principal de progression", "tous les co-équipiers couvrent l'axe principal"], "a": "C", "e": "Points hauts, fenêtres et terrasses font l'objet d'une attention particulière pendant toute l'intervention. — Source : PPI – Gestion tactique d'une tuerie de masse (intervenants 1er niveau, 08-2018)"}, {"t": 13, "s": "Tuerie de masse : dès le début d'une progression, chaque opérateur :", "o": ["suit le policier qui le précède sans point d'arrêt prédéfini", "attend l'ordre du COS", "détermine son point d'arrêt et l'itinéraire pour y parvenir, chaque point devant permettre d'être posté (VITAL)", "progresse en courant jusqu'à l'auteur"], "a": "C", "e": "La progression débute dans la grande majorité des cas en champ ouvert. — Source : PPI – Gestion tactique d'une tuerie de masse (intervenants 1er niveau, 08-2018)"}, {"t": 13, "s": "Selon la fiche tuerie de masse, la « complémentarité » est :", "o": ["le partage à deux ou plus d'une zone d'intervention en secteurs d'observation et de riposte", "la coopération avec les secours", "l'appui des unités spécialisées", "l'échange d'armes entre équipiers"], "a": "A", "e": "Coordination et ordres adaptés garantissent une progression sécurisée. — Source : PPI – Gestion tactique d'une tuerie de masse (intervenants 1er niveau, 08-2018)"}, {"t": 13, "s": "Selon l'instruction du 16/05/2025, la salle de commandement ou le CORG, lors d'une poursuite :", "o": ["autorise l'usage de herses à pointes fixes", "décide seule de l'usage des armes", "impose le silence radio et la discipline sur les ondes", "lève l'obligation d'enclencher la caméra-piéton"], "a": "C", "e": "Il peut aussi faire cesser sans délai la poursuite. — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "Lors d'une poursuite, l'instruction du 16/05/2025 impose aussi :", "o": ["l'activation systématique, si équipés, des dispositifs de géolocalisation des véhicules et/ou des agents", "le port systématique de la ceinture de sécurité par les forces de l'ordre", "l'extinction des avertisseurs pour ne pas affoler le fuyard", "la prise en compte permanente de l'environnement, du flux de circulation, de l'état de la chaussée et de la météo"], "a": "ABD", "e": "Les avertisseurs sonores et lumineux sont utilisés. — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "L'instruction du 16/05/2025 a notamment abrogé :", "o": ["l'article L. 233-1 du code de la route", "l'instruction DIVA de 2008", "la loi du 23 janvier 2006", "la note du préfet de police du 3 juillet 2020"], "a": "D", "e": "Le délit de refus d'obtempérer reste prévu par le code de la route. — Source : Instruction commune DGGN-PP-DGPN du 16/05/2025"}, {"t": 13, "s": "Les DIVA (dispositif d'interception des véhicules automobiles) mis en dotation dans la police nationale fonctionnent par :", "o": ["diminution progressive de la pression des pneumatiques, grâce à des pointes creuses qui se désolidarisent de leur support", "coupure électronique du moteur", "éclatement immédiat des pneumatiques", "blocage mécanique des roues"], "a": "A", "e": "Seuls les matériels conformes à l'arrêté du 23 octobre 2006 sont mis en dotation. — Source : Instruction DGPN du 22/04/2008 – DIVA"}, {"t": 13, "s": "Selon l'article 25-1 de la loi du 21 janvier 1995 (créé par la loi du 23 janvier 2006), les policiers en uniforme ou porteurs d'insignes peuvent utiliser des matériels d'immobilisation des moyens de transport :", "o": ["lorsque le conducteur ne s'arrête pas à leurs sommations", "en cas de crime ou délit flagrant, si l'immobilisation est nécessaire au regard du comportement du conducteur ou des conditions de fuite", "lorsque le comportement du conducteur ou des passagers met délibérément en danger la vie d'autrui ou d'eux-mêmes", "pour tout contrôle routier de routine"], "a": "ABC", "e": "La loi de 2006 a abrogé l'ordonnance du 23 décembre 1958 ; les herses métalliques à pointes fixes ne peuvent plus être utilisées. — Source : Instruction DGPN du 22/04/2008 – DIVA"}, {"t": 13, "s": "En enquête préliminaire, un APJ (art. 20 CPP (code de procédure pénale)) peut procéder à une perquisition :", "o": ["seul, sur simple accord verbal", "sans assentiment si l'infraction est un délit", "uniquement en flagrance", "sur instruction et sous le contrôle d'un OPJ, avec l'assentiment écrit, manuscrit, daté et signé de la personne"], "a": "D", "e": "L'assentiment précise s'il concerne aussi dépendances et annexes (cave, garage…). — Source : TI FT n°42 – Aspects pratiques de la perquisition"}, {"t": 13, "s": "En flagrant délit, la perquisition :", "o": ["peut être décidée par un APJ adjoint", "nécessite l'assentiment écrit de la personne", "relève des prérogatives de l'OPJ, l'APJ ne pouvant que l'assister", "peut être décidée par l'APJ en l'absence d'OPJ"], "a": "C", "e": "L'OPJ (officier de police judiciaire) respecte les articles 56 et suivants du CPP (code de procédure pénale). — Source : TI FT n°42 – Aspects pratiques de la perquisition"}, {"t": 13, "s": "Sauf dispositions particulières (stupéfiants, proxénétisme, terrorisme…), une perquisition :", "o": ["doit impérativement s'interrompre à 21 h", "peut se poursuivre après 21 h si elle a commencé avant", "peut débuter à toute heure en flagrance", "ne peut débuter avant 6 h ni après 21 h"], "a": "BD", "e": "Exemple cité par la fiche FT n°42. — Source : TI FT n°42 – Aspects pratiques de la perquisition"}, {"t": 13, "s": "Conflits dans les lieux privés : quels principes sont exacts ?", "o": ["Séparer si possible les antagonistes pour qu'ils ne puissent ni se voir ni s'entendre", "N'amener en aucun cas le requérant sur les lieux et ne pas citer son nom devant les antagonistes", "Ne pas arriver sur les lieux avec les avertisseurs sonores ou lumineux", "Entrer dans les lieux dès l'arrivée, sans attendre l'accord des occupants"], "a": "ABC", "e": "On ne pénètre que sur accord d'un occupant ou pour porter secours. — Source : TI – Conflits dans les lieux privés"}, {"t": 13, "s": "Selon la jurisprudence citée par les fiches TI, le domicile est :", "o": ["toute demeure permanente ou temporaire occupée par celui qui y a droit, ou de son consentement par un tiers", "un lieu qui peut inclure caravane ou squat", "le lieu où l'intéressé a le droit de se dire chez lui, quels que soient le titre juridique d'occupation et l'affectation des locaux", "seulement le lieu de résidence principale déclaré"], "a": "ABC", "e": "Le lieu privé est défini comme tout lieu qui n'est pas un lieu public. — Source : TI – Conflits dans les lieux privés"}, {"t": 13, "s": "Cambriolage en cours, en l'absence de l'occupant légal, l'entrée des policiers dans un lieu privé :", "o": ["peut être demandée par n'importe quel témoin", "ne se justifie que pour porter secours ou assurer leur sauvegarde, celle de tiers ou du bien, face à un danger actuel ou imminent", "nécessite un mandat du juge", "est toujours libre dès lors qu'un délit est suspecté"], "a": "B", "e": "Seul l'occupant légal (propriétaire, locataire, chef d'entreprise…) peut requérir l'entrée. — Source : TI FT n°32 – Intervention sur un cambriolage en cours"}, {"t": 13, "s": "Selon l'article 126-1 du code de la construction et de l'habitation, cité par la fiche cambriolage :", "o": ["propriétaires ou exploitants d'immeubles d'habitation peuvent accorder à la police une autorisation permanente de pénétrer dans les parties communes", "l'autorisation vaut aussi pour les caves privatives", "les policiers peuvent entrer de jour dans tout appartement", "le syndic doit être présent à toute intervention"], "a": "A", "e": "Autorisation limitée aux parties communes. — Source : TI FT n°32 – Intervention sur un cambriolage en cours"}, {"t": 13, "s": "Intervention sur un cambriolage en cours : quels principes de sécurité sont préconisés ?", "o": ["Laisser intervenir des policiers en civil sans signe distinctif", "Placer un observateur à l'extérieur assurant la liaison radio avec le CIC", "Pénétrer seul dans les lieux pour gagner du temps", "Arriver avec les avertisseurs pour faire fuir les auteurs"], "a": "B", "e": "Arrivée discrète, sans avertisseurs : la nuit on est plus audible et plus visible. — Source : TI FT n°32 – Intervention sur un cambriolage en cours"}, {"t": 13, "s": "Lors d'une intervention dans un lieu public, la fiche FT n°20 préconise :", "o": ["plusieurs équipes légères de deux ou trois policiers en liaison permanente plutôt qu'un seul groupe compact", "d'intervenir en un groupe compact pour impressionner le public", "d'annoncer au CIC, dès le début de l'engagement, le motif et le lieu de l'intervention", "de positionner les véhicules dans le sens du départ pour faciliter un éventuel repli"], "a": "ACD", "e": "Le principal danger est l'isolement, voire l'encerclement, de policiers. — Source : TI FT n°20 – Les interventions dans les lieux publics"}, {"t": 13, "s": "Selon la fiche FT n°20, le principe des trois niveaux de liaison comprend :", "o": ["la liaison entre les équipes engagées", "la liaison avec le parquet", "la liaison au sein de l'équipe", "la liaison avec le CIC"], "a": "ACD", "e": "À respecter pendant l'opération. — Source : TI FT n°20 – Les interventions dans les lieux publics"}, {"t": 13, "s": "Après une intervention dans un lieu public, l'inventaire des « PAM » porte sur :", "o": ["Patrouilles / Appuis / Médias", "Personnels / Armement / Matériel", "Plaintes / Arrestations / Mains courantes", "Procédure / Auteurs / Moyens"], "a": "B", "e": "Réalisé promptement, sur place ou à proximité, avant d'annoncer à la radio la fin de l'intervention. — Source : TI FT n°20 – Les interventions dans les lieux publics"}, {"t": 13, "s": "Selon la fiche FT n°20, les pouvoirs plus étendus de la police dans un lieu public :", "o": ["ne s'appliquent pas à un rassemblement de personnes à caractère privé dans un lieu public (salle des fêtes louée…)", "s'appliquent aussi au domicile", "s'appliquent à toute voiture particulière", "ne s'appliquent qu'à la voie publique"], "a": "A", "e": "Lieu public : endroit où toute personne est admise indistinctement (voie publique, gare, centre commercial, métro…). — Source : TI FT n°20 – Les interventions dans les lieux publics"}, {"t": 13, "s": "Selon la fiche « facteurs de prise de décision », la mission sur initiative fait appel à trois qualités primordiales :", "o": ["rédaction, mémoire et patience", "observation, analyse et anticipation", "obéissance, discrétion et rapidité", "force, endurance et courage"], "a": "B", "e": "Elle repose souvent sur la connaissance de l'activité du service et de la cartographie de la délinquance. — Source : PPI – Les facteurs de prise de décision (vs 10-2015)"}, {"t": 13, "s": "Selon la fiche « facteurs de prise de décision », la mission sur réquisition :", "o": ["est facultative pour les policiers", "émane exclusivement du CIC", "est une réquisition écrite du procureur", "correspond à la demande formulée par le public pour bénéficier d'une assistance policière"], "a": "D", "e": "Les missions sur instructions émanent des différents échelons hiérarchiques (CIC (centre d'information et de commandement), gradés, chef de service…). — Source : PPI – Les facteurs de prise de décision (vs 10-2015)"}, {"t": 13, "s": "Dans l'analyse de la situation, la rubrique « Qui ? (acteurs) » de la fiche « facteurs de prise de décision » comprend notamment :", "o": ["la capacité opérationnelle de l'effectif intervenant", "le degré d'agressivité et la détermination des agresseurs", "le rapport de force entre agresseurs et policiers", "les conditions atmosphériques"], "a": "ABC", "e": "Les conditions atmosphériques relèvent de l'environnement (ambiance). — Source : PPI – Les facteurs de prise de décision (vs 10-2015)"}, {"t": 14, "s": "Selon l'arrêté du 27/07/2015, la formation continue aux TSI (techniques et sécurité en intervention) :", "o": ["revêt un caractère obligatoire pour les actifs et les policiers adjoints", "relève de la compétence exclusive des formateurs TSI", "est facultative pour les personnels en poste à l'étranger", "peut être dispensée par tout gradé"], "a": "AB", "e": "Les personnels à l'étranger y restent soumis, avec des aménagements fixés par instruction du DGPN (directeur général de la police nationale). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Les TSI (techniques et sécurité en intervention) recouvrent l'emploi des armes et les pratiques professionnelles en intervention, lesquelles regroupent :", "o": ["les techniques d'intervention", "les techniques d'optimisation du potentiel", "les techniques de défense et d'interpellation", "le sport opérationnel"], "a": "AC", "e": "Les PPI regroupent techniques d'intervention, de défense et d'interpellation, et premiers secours ; les TOP relèvent de l'art. 12. Le sport opérationnel fait l'objet d'un titre distinct (titre II). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Le volume horaire minimal annuel d'entraînement aux TSI (techniques et sécurité en intervention) est de :", "o": ["12 heures en une seule séance", "16 heures", "9 heures", "12 heures, fractionnées en plusieurs séances régulièrement réparties"], "a": "D", "e": "Art. 4. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Une séance type de formation TSI (techniques et sécurité en intervention) a une durée effective de :", "o": ["6 heures", "4 heures", "2 heures", "3 heures"], "a": "B", "e": "Simulation, rappel des cadres légaux/déontologiques, tir à balles réelles avec l'arme de poing. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Aménagement du volume annuel : les séances de tir à l'arme individuelle sont au nombre de :", "o": ["4 séances d'1 heure, 90 cartouches", "3 séances de 2 heures, 60 cartouches", "3 séances d'au moins 1 heure, pour un tir minimum annuel de 90 cartouches", "2 séances, 90 cartouches"], "a": "C", "e": "Complétées par au moins 9 heures de pratiques professionnelles en intervention. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Dans l'aménagement du volume annuel, la durée totale minimale des séances de PPI est de :", "o": ["12 heures", "8 heures", "6 heures", "9 heures"], "a": "D", "e": "Le stage de recyclage au port des bâtons de police y est comptabilisé. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Est comptabilisé comme séance d'entraînement réglementaire au tir :", "o": ["le stage « tireur qualifié arme de poing »", "le stage « tireur opérationnel arme de poing »", "le « module emploi de l'arme » de la formation des formateurs TSI", "une séance de manipulation de l'arme sans tir"], "a": "ABC", "e": "Les séances de manipulation ne se substituent pas aux séances de tir (instruction 3/2024). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel ; Instruction DGPN n°3/2024 – arme individuelle"}, {"t": 14, "s": "Lors d'un entraînement au tir, le formateur TSI (techniques et sécurité en intervention) constate une carence. Il met d'abord en place :", "o": ["une suspension de fonctions", "le retrait immédiat de l'arme", "un rapport à l'IGPN", "un parcours de tir normé"], "a": "D", "e": "Si la carence est avérée : fiche d'observations individuelle normalisée, chef de service avisé immédiatement. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Le retrait de l'arme de service pour état de dangerosité (art. 114-6 RGEPN (règlement général d'emploi de la police nationale)) est décidé par :", "o": ["le chef de service", "le formateur TSI", "le directeur départemental uniquement", "le médecin statutaire"], "a": "A", "e": "Art. 7 de l'arrêté. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Concernant le suivi des séances TSI (techniques et sécurité en intervention), quelles affirmations sont exactes ?", "o": ["Se soustraire régulièrement et sans motif légitime aux séances expose à des sanctions disciplinaires", "Les accidents survenus en formation TSI ne sont pas imputables au service", "Chaque séance est enregistrée dans l'application de gestion de la formation", "Le chef de service contrôle la réalité du suivi"], "a": "ACD", "e": "Les accidents en formation TSI sont reconnus imputables au service (art. 3). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Les techniques d'optimisation du potentiel (TOP) :", "o": ["sont réservées aux formateurs TSI", "remplacent le sport opérationnel", "contribuent à la gestion du stress opérationnel et sont autorisées sur le temps de service", "se pratiquent hors temps de service"], "a": "C", "e": "Art. 12. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Concernant le sport opérationnel, quelles affirmations sont exactes ?", "o": ["Sa durée hebdomadaire est de deux heures", "Il est obligatoire et s'effectue sur le temps de travail", "Les restrictions liées aux contraintes opérationnelles ne peuvent être que temporaires", "Il ouvre droit à une compensation horaire"], "a": "ABC", "e": "Aucune compensation horaire, rétribution ou indemnisation ; accidents imputables au service. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Le maintien de la condition physique opérationnelle relève :", "o": ["du seul chef de service", "du seul agent", "du médecin de prévention", "de la responsabilité de l'autorité hiérarchique et de la responsabilité individuelle des agents"], "a": "D", "e": "Art. 13. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Selon l'instruction n°3/2024, un policier qui n'a effectué aucune séance de tir depuis 12 mois :", "o": ["doit suivre une formation par un FTSI et peut se voir retirer son arme", "est dispensé s'il a fait des séances de manipulation", "conserve son arme sans condition", "doit repasser l'habilitation initiale à l'école"], "a": "A", "e": "Le minimum reste 3 séances / 90 cartouches sur une année glissante. — Source : Instruction DGPN n°3/2024 – arme individuelle"}, {"t": 14, "s": "Pour être autorisé à porter son arme hors service, le policier doit avoir effectué au moins une séance de tir dans les :", "o": ["3 derniers mois", "12 derniers mois", "4 derniers mois", "6 derniers mois"], "a": "C", "e": "Condition de l'instruction 3/2024. — Source : Instruction DGPN n°3/2024 – arme individuelle"}, {"t": 14, "s": "Selon le tableau des AFI (arme de force intermédiaire), le recyclage est annuel pour :", "o": ["le LBD 40", "le PIE", "le PM HK UMP et le HK G36", "les bâtons de police"], "a": "C", "e": "LBD (lanceur de balles de défense), PIE (pistolet à impulsions électriques) et bâtons : recyclage triennal. — Source : Les AFI et instructions spécifiques (tableau habilitation/recyclage)"}, {"t": 14, "s": "Concernant le PIE (pistolet à impulsions électriques), le délai maximal entre deux séances de recyclage est de :", "o": ["36 mois", "48 mois", "24 mois", "12 mois"], "a": "A", "e": "Recyclage triennal (tableau AFI (arme de force intermédiaire)). — Source : Instruction DPN-1.9.4.1 – emploi du PIE ; Les AFI et instructions spécifiques (tableau habilitation/recyclage)"}, {"t": 14, "s": "Selon l'article 6 de l'arrêté du 27/07/2015, les séances de formation aux TSI (techniques et sécurité en intervention) sont construites dans le respect des contenus pédagogiques :", "o": ["élaborés par chaque formateur TSI", "validés par l'IGPN", "fixés par le préfet de zone", "élaborés par l'académie de police et validés par le DGPN"], "a": "D", "e": "Art. 6. — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Les conditions de sélection, de formation et les compétences des formateurs TSI (techniques et sécurité en intervention) sont fixées :", "o": ["par décret en Conseil d'État", "par circulaire du ministre de l'intérieur", "par l'arrêté du 27/07/2015 lui-même, en annexe", "par note du chef de service"], "a": "B", "e": "Art. 11 (version en vigueur au 01/10/2024). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 14, "s": "Le bilan annuel du suivi de l'entraînement réglementaire aux TSI (techniques et sécurité en intervention) est établi par :", "o": ["l'académie de police seule", "la DGPN et la préfecture de police", "chaque formateur TSI", "le préfet de département"], "a": "B", "e": "Art. 10 ; le contrôle de la réalité du suivi des séances appartient au chef de service (art. 9). — Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel"}, {"t": 1, "s": "La durée moyenne hebdomadaire maximale de 48 heures, services supplémentaires compris, s'apprécie sur :", "o": ["le semestre révolu", "le trimestre civil", "l'année civile", "le cycle de travail"], "a": "A", "e": "48 h en moyenne par période de 7 jours, sur le semestre révolu. (Source : Fiches APORTT)"}, {"t": 1, "s": "La durée du travail de nuit est limitée à 8 heures en moyenne par 24 heures, appréciée sur :", "o": ["le trimestre civil", "le semestre révolu", "le mois civil", "la période de 7 jours"], "a": "A", "e": "8 h en moyenne sur le trimestre civil ; au-delà, le chef de service impose des congés. (Source : Fiches APORTT)"}, {"t": 1, "s": "Quelles affirmations relatives au repos et à la pause sont exactes ?", "o": ["Le repos journalier minimal est de 12 heures consécutives par période de 24 heures", "La période de 24 heures part de la prise de service effective, quel que soit le régime", "La pause de 20 minutes est un temps de travail", "L'interruption de service est un temps de travail"], "a": "BC", "e": "Repos journalier : 11 h consécutives. L'interruption de service (45 min à 2 h) est un temps de repos, à la différence de la pause. (Source : Fiches APORTT)"}, {"t": 1, "s": "En cadre dérogatoire, la neutralisation pour restitution doit intervenir au plus tard après :", "o": ["12 jours pour les repos journaliers manqués et 21 jours pour les hebdomadaires", "10 jours pour les repos journaliers manqués et 21 jours pour les hebdomadaires", "12 jours pour les repos journaliers manqués et 14 jours pour les hebdomadaires", "14 jours pour les repos journaliers manqués et 28 jours pour les hebdomadaires"], "a": "A", "e": "12 jours / 21 jours. (Source : Fiches APORTT)"}, {"t": 1, "s": "Un repos journalier manqué en cadre dérogatoire ouvre droit à une compensation au coefficient de :", "o": ["0,15 par heure manquée", "0,25 par heure manquée", "0,10 par heure manquée", "0,60 par heure manquée"], "a": "A", "e": "0,15 ; restitution par prise de service retardée, sinon fin anticipée, sinon report. (Source : Fiches APORTT)"}, {"t": 1, "s": "Pendant une période de neutralisation, un agent ne peut être rappelé que sur décision :", "o": ["du DGPN, du DGSI ou du préfet de police, en circonstances exceptionnelles", "du chef de service, en circonstances exceptionnelles", "du préfet de département, pour nécessités de service", "du directeur zonal, pour missions spécifiques"], "a": "A", "e": "La restitution est un droit. (Source : Fiches APORTT)"}, {"t": 2, "s": "En horaires variables à 39 h 25, un solde débiteur de 5 heures en fin de période entraîne :", "o": ["le décompte d'une demi-journée ARTT", "le décompte d'une journée ARTT", "une compensation sur les 4 semaines suivantes", "une retenue sur traitement"], "a": "A", "e": "Entre 1/10e (3 h 57) et 1/5e (7 h 53) : demi-journée ARTT (aménagement et réduction du temps de travail). (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 2, "s": "La compensation horaire de la journée de solidarité est de 0 h 48 pour un régime hebdomadaire à :", "o": ["39 h", "39 h 25", "38 h", "40 h 30"], "a": "A", "e": "40 h 30 : 1 h 06 ; 39 h 25 : 0 h 53 ; 39 h : 0 h 48 ; 38 h : 0 h 36. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 2, "s": "Après indemnisation d'office, un CEA (corps d'encadrement et d'application) à 38 h dispose de :", "o": ["9 jours ARTT disponibles sur 17 attribués", "16 jours ARTT disponibles sur 24 attribués", "9 jours ARTT disponibles sur 16 attribués", "17 jours ARTT disponibles sur 24 attribués"], "a": "A", "e": "38 h : 17 attribués / 9 disponibles ; 39 h 25 : 24 / 16. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 2, "s": "Concernant les cycles de travail, quelles affirmations sont exactes ?", "o": ["La vacation forte a une durée moyenne de 9 h 31", "Les cycles 2/2, 3/3 et 2/2/3 s'effectuent en vacations de 12 h 08", "En cycle de jour, l'agent bénéficie en principe d'un RC puis d'un RL", "En cycle de nuit, la journée débute à 0 h"], "a": "ABC", "e": "En nocturne, la journée débute à l'heure habituelle de prise de service. Les 2/2, 3/3 et 2/2/3 se font en vacations de 12 h 08. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 2, "s": "Une vacation décalée empiète de 2 heures sur un repos compensateur. La compensation est de :", "o": ["30 minutes", "72 minutes", "48 minutes", "2 heures"], "a": "A", "e": "Coefficient 0,25 sur RC (2 h × 0,25 = 30 min) ; 0,60 sur RL (repos légal)/JF. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 2, "s": "Sauf décision du ministre de l'Intérieur, les rappels et/ou reports de repos ne peuvent porter sur plus de :", "o": ["deux semaines consécutives", "trois semaines consécutives", "quatre repos consécutifs", "un cycle complet"], "a": "A", "e": "Deux semaines consécutives quel que soit le nombre d'heures. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 3, "s": "Permanence effectuée un repos compensateur : la compensation est de :", "o": ["125 %", "150 %", "175 %", "200 %"], "a": "A", "e": "RL (repos légal)/JF 175 %, RC 125 %, nuit sam./dim. 200 %, autres nuits 150 %. (Source : Fiches APORTT)"}, {"t": 3, "s": "Quelles affirmations relatives à l'astreinte sont exactes ?", "o": ["Elle ouvre droit à indemnisation ou, à défaut, à compensation, les deux étant exclusives", "Le reliquat non indemnisé bascule sur le compteur HS actif à chaque fin de trimestre", "Un rappel avec déplacement est compensé à 100 % plus 2 heures forfaitaires de trajet", "La télé-intervention ouvre droit au forfait trajet"], "a": "AB", "e": "Le forfait trajet est d'1 h. Pas de forfait trajet en télé-intervention. (Source : Fiches APORTT ; Synthèse DocPro temps de travail (avril 2026))"}, {"t": 3, "s": "Une astreinte du vendredi 21 h au lundi 6 h est rémunérée :", "o": ["77,37 € ou 7 h 22", "149,48 € ou 14 h 27", "77,37 € ou 7 h 48", "74,74 € ou 7 h 13"], "a": "A", "e": "Semaine complète : 149,48 € ou 14 h 27. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 3, "s": "Rappel au service sur un repos légal, d'une durée de 3 heures :", "o": ["1 vacation est restituée", "2 vacations sont restituées", "l'agent récupère 3 h à 200 %", "l'agent récupère 3 h à 150 %"], "a": "A", "e": "RL ≤ 4 h : 1 vacation ; au-delà : 2. (Source : Fiches APORTT)"}, {"t": 3, "s": "Un rappel au service se termine à 14 h. L'agent bénéficie :", "o": ["d'une exemption de la nuit suivante", "d'un repos minimum de 8 heures", "d'un repos minimum de 11 heures", "d'une demi-journée de récupération"], "a": "A", "e": "Avant 13 h : 8 h de repos minimum ; après 13 h : exemption de la nuit suivante. (Source : Fiches APORTT)"}, {"t": 3, "s": "Concernant le report de repos et les RCSS (repos compensateur pour services supplémentaires), quelles affirmations sont exactes ?", "o": ["Le report de repos est annoncé à l'agent pendant son service", "Les RCSS non pris dans l'année civile restent dus", "Au-delà de 160 heures de RCSS, la récupération intervient dans les 21 jours", "Le crédit férié ne peut jamais être rappelé"], "a": "AB", "e": "Au-delà de 160 h : 30 jours (21 jours concerne la permanence). Le crédit férié est rappelable sur décision du chef de service. (Source : Fiches APORTT)"}, {"t": 4, "s": "Plan de congés scindé en deux : la première période s'étend :", "o": ["du 15 février au 15 octobre", "du 15 mars au 14 octobre", "du 1er février au 31 octobre", "du 15 février au 14 septembre"], "a": "A", "e": "Puis 16 octobre – 14 février ; plan unique : 15 mars N – 14 mars N+1. (Source : Circulaire DGPN 26/01/2022 – congés)"}, {"t": 4, "s": "Départage entre agents pour les congés : quel est l'ordre des critères ?", "o": ["Ancienneté de grade, ancienneté de présence administrative, âge", "Ancienneté de service, ancienneté de grade, âge", "Ancienneté de présence administrative, ancienneté de grade, situation familiale", "Âge, ancienneté de grade, ancienneté de présence administrative"], "a": "A", "e": "Circulaire du 26/01/2022. (Source : Circulaire DGPN 26/01/2022 – congés)"}, {"t": 4, "s": "Un agent prend 7 jours de CA hors période. Il obtient :", "o": ["1 jour de fractionnement", "2 jours de fractionnement", "1,5 jour de fractionnement", "aucun jour"], "a": "A", "e": "1 jour pour 5 à 7 jours hors période ; 2 jours à partir de 8. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 4, "s": "Le crédit férié en Alsace-Moselle s'élève à :", "o": ["123 h 12", "116 h 12", "109 h 12", "130 h 12"], "a": "A", "e": "109 h 12 en métropole ; 116 h 12 DOM ; 123 h 12 Alsace-Moselle. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 4, "s": "Quelles affirmations relatives aux congés annuels sont exactes ?", "o": ["L'absence ne peut excéder 31 jours calendaires consécutifs, RC/RL/JF compris", "Un agent en vacation forte dispose de 23 CA", "Les CA non pris pour maladie peuvent être reportés sur 15 mois, dans la limite de 4 semaines", "Le taux de présence pendant les congés ne peut jamais dépasser 75 %"], "a": "AC", "e": "Vacation forte : 20 CA (23 en 4/2). 100 % possible sur décision du ministre en circonstances exceptionnelles. (Source : Synthèse DocPro temps de travail (avril 2026) ; Circulaire DGPN 26/01/2022 – congés)"}, {"t": 4, "s": "Les RPS (repos de pénibilité spécifique) non pris :", "o": ["restent dus, sont reportés et ne peuvent pas alimenter le CET", "sont perdus au 31 décembre sauf versement au CET", "sont indemnisés d'office", "sont convertis en crédit férié"], "a": "A", "e": "Au plan : 10 journées ou vacations maximum. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "Congé de maternité pour un troisième enfant : la durée est de :", "o": ["8 semaines avant et 18 semaines après", "6 semaines avant et 10 semaines après", "10 semaines avant et 22 semaines après", "12 semaines avant et 22 semaines après"], "a": "A", "e": "Option 10 + 16 possible ; jumeaux 12 + 22. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "Concernant le congé de paternité et d'accueil de l'enfant, quelles affirmations sont exactes ?", "o": ["Il est de 25 jours calendaires, 32 en cas de naissances multiples", "Il s'ajoute aux 3 jours de naissance", "La demande est formulée au moins deux mois avant la date présumée", "Il est fractionnable sans limite de délai"], "a": "AB", "e": "Demande au moins un mois avant. Les 21 (ou 28) jours restants se prennent dans les 6 mois suivant la naissance (ou l'hospitalisation). (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "Congé de présence parentale : le maximum est de :", "o": ["310 jours ouvrés sur 36 mois", "310 jours calendaires sur 36 mois", "240 jours ouvrés sur 24 mois", "365 jours ouvrés sur 36 mois"], "a": "A", "e": "Demande écrite au moins 15 jours avant, certificat médical. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour garde d'enfant malade, agent à temps plein en régime hebdomadaire de 5 jours :", "o": ["6 jours, pouvant être doublés s'il assume seul la charge", "5 jours, pouvant être doublés s'il assume seul la charge", "6 jours, non doublables", "12 jours d'office"], "a": "A", "e": "Obligations hebdomadaires + 1 jour. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "Décès d'un enfant de moins de 25 ans : l'agent bénéficie de :", "o": ["14 jours ouvrables + 8 jours complémentaires", "12 jours ouvrables + 8 jours complémentaires", "14 jours ouvrables + 5 jours complémentaires", "12 jours ouvrables + 10 jours complémentaires"], "a": "A", "e": "12 jours, portés à 14 pour un enfant de moins de 25 ans, + 8 jours fractionnables. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 5, "s": "Quelles affirmations relatives au congé parental et aux ASA (autorisation spéciale d'absence) sont exactes ?", "o": ["Le congé parental est accordé par périodes de 2 à 6 mois renouvelables", "Le congé parental est un congé sans traitement", "Le décès d'un oncle ouvre droit à 3 jours ouvrables", "Les délais de route peuvent atteindre 72 heures aller-retour"], "a": "AB", "e": "Oncle (3e degré) : 1 jour ouvrable. Délais de route : 48 h maximum aller et retour. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 6, "s": "Pour alimenter son CET (compte épargne-temps), un agent cyclique doit avoir pris au moins :", "o": ["les 4/5e de sa dotation annuelle de congés", "20 jours de congés", "25 jours de congés", "4 fois ses obligations hebdomadaires"], "a": "A", "e": "20 jours en hebdomadaire ; 4 fois les obligations hebdomadaires à temps partiel. (Source : Synthèse DocPro temps de travail (avril 2026) ; Guide ARTT/CET)"}, {"t": 6, "s": "Quelles affirmations relatives au CET (compte épargne-temps) sont exactes ?", "o": ["Le droit d'option s'ouvre à partir du 16e jour", "Le plafond global est de 60 jours", "Les RPS peuvent alimenter le CET", "L'alimentation a lieu du 1er au 31 janvier"], "a": "ABD", "e": "Ni le crédit férié, ni les RPS (repos de pénibilité spécifique), ni les jours reçus par don. (Source : Synthèse DocPro temps de travail (avril 2026) ; Guide ARTT/CET)"}, {"t": 6, "s": "Indemnisation d'un jour de CET (compte épargne-temps) pour un agent de catégorie B :", "o": ["100 €", "83 €", "150 €", "110 €"], "a": "A", "e": "A : 150 € ; B : 100 € ; C : 83 €. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 6, "s": "La demande de temps partiel doit être adressée au moins :", "o": ["2 mois avant, au SGAMI par la voie hiérarchique", "1 mois avant, au chef de service", "3 mois avant, au SGAMI", "2 mois avant, au chef de service directement"], "a": "A", "e": "Avec justificatifs. (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 6, "s": "Le congé de longue maladie (CLM) a une durée maximale de :", "o": ["3 ans, dont 1 an à plein traitement", "5 ans, dont 3 ans à plein traitement", "3 ans, dont 2 ans à plein traitement", "1 an, à plein traitement"], "a": "A", "e": "CLD (congé de longue durée) : 5 ans (3 plein, 2 demi). (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 6, "s": "Exemption pour don de plaquettes : le nombre maximum de dons et l'intervalle sont de :", "o": ["12 par an, 4 semaines d'intervalle", "24 par an, 2 semaines d'intervalle", "6 par an, 8 semaines d'intervalle", "12 par an, 2 semaines d'intervalle"], "a": "A", "e": "Sang total 6/4 par an (8 semaines) ; plasma 24/an (2 semaines). (Source : Synthèse DocPro temps de travail (avril 2026))"}, {"t": 7, "s": "Pour être en règle, le policier doit effectuer au minimum, sur une année glissante :", "o": ["3 séances de tir et 90 cartouches", "3 séances de tir et 60 cartouches", "4 séances de tir et 90 cartouches", "2 séances de tir et 90 cartouches"], "a": "A", "e": "Les séances de manipulation ne s'y substituent pas. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Quelles affirmations relatives à l'arme individuelle sont exactes ?", "o": ["Elle est conservée par le policier actif pendant toute sa carrière", "Le trajet domicile-travail nécessite une déclaration de port", "La déclaration de port hors service est faite à la primo-affectation puis à chaque nouvelle affectation", "Le chef de service peut s'opposer au port hors service ou l'interdire a posteriori"], "a": "ACD", "e": "Le trajet domicile-travail ne nécessite pas de déclaration. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Le tir sportif avec l'arme individuelle est limité à :", "o": ["3 000 cartouches par période de douze mois", "2 000 cartouches par période de douze mois", "3 000 cartouches par année civile", "1 500 cartouches par semestre"], "a": "A", "e": "Déclaration préalable d'intention. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "À l'armurerie, un pistolet SIG SAUER est neutralisé par retrait :", "o": ["du canon", "du ressort de percussion", "de la culasse", "du chargeur"], "a": "A", "e": "Revolver : ressort de percussion ; pièce dans une armoire forte distincte. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "L'article L.435-1 4° CSI (véhicule refusant de s'arrêter) exige que les occupants soient susceptibles de perpétrer dans leur fuite :", "o": ["des atteintes à leur vie ou à leur intégrité physique ou à celles d'autrui", "des atteintes graves aux biens", "un crime ou un délit puni de 5 ans", "une nouvelle infraction routière"], "a": "A", "e": "Conditions cumulatives d'absolue nécessité et de proportionnalité. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Un policier hors service intervient avec son arme. Il doit notamment :", "o": ["revêtir son brassard", "porter dans la mesure du possible un gilet pare-balles", "être en possession de sa carte professionnelle", "avoir effectué un tir dans les 12 derniers mois seulement"], "a": "ABC", "e": "Le port hors service suppose une séance de tir dans les 4 derniers mois. (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "Le sélecteur de tir du HK G36 permet :", "o": ["le coup par coup et la rafale de deux coups", "le coup par coup et la rafale libre", "le coup par coup, la rafale de trois coups et la rafale libre", "la rafale de deux coups uniquement"], "a": "A", "e": "Le PM (pistolet-mitrailleur) 9 mm permet coup par coup, rafale limitée et rafale libre selon modèle. (Source : Instruction HK G36)"}, {"t": 8, "s": "L'approvisionnement du HK G36 comprend :", "o": ["6 boîtiers-chargeurs de 30 cartouches", "4 boîtiers-chargeurs de 30 cartouches", "6 boîtiers-chargeurs de 25 cartouches", "5 boîtiers-chargeurs de 30 cartouches"], "a": "A", "e": "Capacité théorique 30 cartouches. (Source : Instruction HK G36)"}, {"t": 8, "s": "Quelles affirmations relatives au PM (pistolet-mitrailleur) 9 mm et au HK G36 sont exactes ?", "o": ["Leur emploi en maintien de l'ordre en unité constituée est proscrit", "Ce sont des armes individuelles d'épaule en dotation collective", "Le recyclage de leur habilitation est triennal", "Le HK G36 est destiné aux intervenants de 1er niveau en priorité"], "a": "AB", "e": "Recyclage annuel (triennal pour les AFI (arme de force intermédiaire)). Le G36 vise les intervenants de 2e ou 3e niveau. (Source : Instruction PM 9 mm ; Instruction HK G36 ; Tableau AFI habilitation/recyclage)"}, {"t": 8, "s": "Une déclaration TSUA (traitement relatif au suivi de l'usage des armes) validée par son auteur peut ensuite être modifiée :", "o": ["après intervention de l'autorité hiérarchique qui retire la validation", "librement par son auteur pendant 48 heures", "uniquement par l'administrateur national", "uniquement par l'IGPN"], "a": "A", "e": "Aucune donnée nominative de tiers ne doit figurer. (Source : Instruction/FAQ TSUA)"}, {"t": 8, "s": "Concernant le TSUA (traitement relatif au suivi de l'usage des armes), quelles affirmations sont exactes ?", "o": ["L'accès suppose une habilitation personnelle via CHEOPS NG", "La déclaration se fait au plus près de l'action", "Le nom des collègues présents doit être mentionné", "Un administrateur local est désigné"], "a": "ABD", "e": "Aucune donnée nominative concernant des tiers. (Source : Instruction/FAQ TSUA)"}, {"t": 9, "s": "Avec la munition CTS, le LBD (lanceur de balles de défense) 40 a une zone d'efficacité de :", "o": ["10 à 50 m, optimum à 30 m", "3 à 35 m, DOE réglé pour 25 m", "10 à 35 m, optimum à 25 m", "3 à 50 m, optimum à 30 m"], "a": "A", "e": "MDU (munition de défense unique) : 3 à 35 m, DOE (désignateur d'objectif électronique) 25 m. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "La GMD (grenade à main de désencerclement) est munie d'un retard de :", "o": ["1,5 seconde", "3 secondes", "2 secondes", "1 seconde"], "a": "A", "e": "18 galets, rayon d'efficacité 10 m, lancée jusqu'à 30 m. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Quelles affirmations relatives au lanceur de grenades sont exactes ?", "o": ["Seul le tir courbe est admis", "Son utilisation procède de l'ordre hiérarchique", "Le tir tendu est admis à courte distance", "Il peut servir à lancer une GMD à distance"], "a": "AB", "e": "Seul le tir courbe est admis ; binôme superviseur/lanceur. Le lancer de GMD (grenade à main de désencerclement) au moyen d'un lanceur est proscrit. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Le superviseur du binôme LBD (lanceur de balles de défense) en maintien de l'ordre est chargé notamment :", "o": ["de la situation d'ensemble et de la désignation de l'objectif", "du tir lorsque le tireur est menacé", "de la déclaration TSUA à la place du tireur", "de l'interpellation de la personne atteinte"], "a": "A", "e": "Il suit les mouvements des manifestants et s'assure de la compréhension des ordres. (Source : Télégramme 2020 – binôme LBD)"}, {"t": 9, "s": "Habilitation au lanceur Cougar : elle est ouverte :", "o": ["aux seuls actifs, à l'exclusion des PA, cadets et réservistes", "aux actifs et réservistes, à l'exclusion des cadets", "aux actifs, PA et réservistes, à l'exclusion des cadets", "à tous les personnels habilités au LBD"], "a": "A", "e": "GMD (grenade à main de désencerclement) : actifs, PA (policiers adjoints) et réservistes sauf cadets. (Source : Tableau AFI habilitation/recyclage)"}, {"t": 9, "s": "Selon l'instruction n°15/2025, les policiers adjoints habilités peuvent utiliser :", "o": ["la GMD", "le PIE", "les GAIL", "le LBD 40"], "a": "ABC", "e": "Liste : GMD (grenade à main de désencerclement), grenades à main lacrymogènes, PIE (pistolet à impulsions électriques), GAIL (générateur d'aérosol incapacitant ou lacrymogène) et bâtons de défense. (Source : Instruction DGPN n°15/2025)"}, {"t": 10, "s": "Taser 7 : l'angle d'espacement des sondes de la cartouche longue portée est de :", "o": ["3,5°", "12°", "7°", "5°"], "a": "A", "e": "Courte portée 12° (noire) ; longue portée 3,5° (grise). (Source : Fiche technique Taser 7)"}, {"t": 10, "s": "Concernant le PIE (pistolet à impulsions électriques), quelles affirmations sont exactes ?", "o": ["Il est classé en catégorie A2, 6°", "La déclaration TSUA est due dès le pointage", "Le cycle dure 5 secondes et peut être interrompu", "La répétition des cycles est la règle en cas de résistance"], "a": "BC", "e": "PIE : catégorie B 6°. La répétition de cycles reste exceptionnelle. (Source : Instruction DPN-1.9.4.1 – PIE)"}, {"t": 10, "s": "Les aérosols lacrymogènes CS en dotation sont dosés à :", "o": ["5 %", "2 %", "10 %", "1 %"], "a": "A", "e": "Trois formats de 39 à 650 cm³, portée jusqu'à 4-5 m. (Source : Télégramme 05/09/2025 – GAIL ; Instr. DAPN 2004/40)"}, {"t": 10, "s": "Selon le télégramme du 05/09/2025, l'usage du PIE (pistolet à impulsions électriques) après emploi d'un GAIL (générateur d'aérosol incapacitant ou lacrymogène) est :", "o": ["totalement proscrit, simultanément ou consécutivement", "possible après un délai de 30 secondes", "possible si la personne est hors du nuage", "laissé à l'appréciation du chef de bord"], "a": "A", "e": "Gaz propulseurs inflammables. (Source : Télégramme 05/09/2025 – GAIL ; Instr. DAPN 2004/40)"}, {"t": 10, "s": "Saturer au CS l'atmosphère d'une pièce pour neutraliser des individus est :", "o": ["réservé aux unités spécialisées dans le cadre de leur mission", "autorisé en légitime défense pour tout policier", "autorisé sur ordre de l'OPJ", "autorisé après évacuation des tiers"], "a": "A", "e": "Risques d'effets irréversibles voire mortels. (Source : Télégramme 05/09/2025 – GAIL ; Instr. DAPN 2004/40)"}, {"t": 11, "s": "Quelles affirmations relatives à l'autorité habilitée à l'emploi de la force (AHEF) sont exactes ?", "o": ["Elle fixe la mission et les objectifs", "Elle réalise les sommations", "Elle doit être porteuse de son écharpe tricolore", "Elle décide des moyens humains et matériels"], "a": "ABC", "e": "Le CFP (commandant de la force publique) décide des moyens humains et matériels. (Source : Les éléments du maintien de l'ordre)"}, {"t": 11, "s": "Après réitération de la seconde sommation, sur ordre, quelles AFI (arme de force intermédiaire) peuvent être employées ?", "o": ["La GMD", "La grenade à main à effet sonore", "Les lanceurs avec binôme superviseur/tireur", "Le LBD avec binôme superviseur/tireur"], "a": "ABC", "e": "LBD (lanceur de balles de défense) et PIE (pistolet à impulsions électriques) interdits hors cadre de réaction. (Source : Les éléments du maintien de l'ordre)"}, {"t": 11, "s": "La déclaration de manifestation doit être déposée au moins :", "o": ["3 jours francs avant", "5 jours francs avant", "3 jours ouvrés avant", "8 jours avant"], "a": "A", "e": "Auprès du maire, du préfet de police à Paris ou du préfet en zone PN. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "L'interdiction de port et transport d'objets pouvant constituer une arme peut couvrir :", "o": ["les 24 heures précédant l'événement et jusqu'à dispersion", "les 48 heures précédant l'événement et jusqu'à dispersion", "la seule durée de la manifestation", "les 24 heures précédant l'événement et les 24 heures suivantes"], "a": "A", "e": "Art. L.211-3 CSI (code de la sécurité intérieure). (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "L'encerclement d'un groupe de manifestants doit :", "o": ["ménager dès que possible un point de sortie contrôlé", "être levé au plus tard à la fin de la manifestation", "être maintenu jusqu'au contrôle d'identité de chaque personne", "être autorisé par le procureur de la République"], "a": "AB", "e": "Communication régulière avec les personnes encerclées ; levée au plus tard en fin de manifestation. Durée strictement nécessaire et proportionnée. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "En cadre de réaction, le LBD (lanceur de balles de défense) est utilisable :", "o": ["avec binôme superviseur/tireur, sur initiative du CFP", "sans binôme, sur initiative du CFP", "avec binôme, sur ordre exprès de l'AHEF après sommations", "sans binôme, en légitime défense seulement"], "a": "A", "e": "PIE (pistolet à impulsions électriques) toujours interdit. (Source : Les éléments du maintien de l'ordre)"}, {"t": 12, "s": "Selon l'instruction DGPN (direction générale de la police nationale)/DGGN, la palpation est justifiée notamment :", "o": ["lors d'un contrôle d'identité motivé par le comportement (78-2 al. 1 CPP)", "à la suite d'une interpellation, quel qu'en soit le motif", "lors d'un contrôle sur réquisitions, en présence d'éléments de dangerosité", "lors de tout contrôle de titre de séjour, de manière systématique"], "a": "ABC", "e": "Elle ne revêt jamais un caractère systématique lors des contrôles. (Source : Palpation (instruction + TDI))"}, {"t": 12, "s": "Ordre des étapes de la palpation :", "o": ["remise volontaire, moyens de détection, information, palpation", "information, remise volontaire, moyens de détection, palpation", "moyens de détection, remise volontaire, information, palpation", "remise volontaire, information, moyens de détection, palpation"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale)/DGGN. (Source : Palpation (instruction + TDI))"}, {"t": 12, "s": "Le placement de la menotte est à proscrire au niveau :", "o": ["du creux lombaire", "des poignets, entre main et avant-bras", "du dos, mains jointes", "des avant-bras croisés"], "a": "A", "e": "Risque de blessures graves en cas de chute sur le dos. (Source : TDI Menottage)"}, {"t": 12, "s": "En binôme contact, l'agent arrière est placé :", "o": ["légèrement en retrait de son côté faible", "légèrement en retrait de son côté fort", "à une longueur de bras à côté de l'agent avant", "en 3/4 arrière par rapport au tiers"], "a": "A", "e": "Main ou coude sur l'épaule de l'agent avant. (Source : TI Placements)"}, {"t": 12, "s": "Selon la fiche PLI, la liaison permet :", "o": ["le contact avec le CIC", "le contact entre intervenants, y compris visuel ou gestuel", "d'assurer la surveillance à 360° du dispositif", "de désigner l'auteur à interpeller"], "a": "AB", "e": "La liaison permet aussi de rendre compte et de demander des renforts. Elle ne se limite pas aux échanges radio. (Source : TI PLI)"}, {"t": 12, "s": "Signalement : la rubrique 11 concerne :", "o": ["la voix", "le visage", "l'habillement", "la démarche"], "a": "A", "e": "09 visage, 10 démarche, 11 voix, 12 habillement, 13 autres. (Source : TI Signalement)"}, {"t": 13, "s": "Levée de doute sur une agression armée : quelles conduites sont à proscrire ?", "o": ["Stationner à proximité immédiate de l'établissement", "Approcher avec avertisseurs sonores ou lumineux", "Traverser la rue dans l'alignement de l'établissement", "Recourir à des policiers en civil pour le recueil d'informations"], "a": "ABC", "e": "Le recours à des policiers en civil est préconisé. (Source : PPI Levée de doute)"}, {"t": 13, "s": "Agression crapuleuse en cours : il est préconisé :", "o": ["de solliciter la présence de l'OPJ territorialement compétent", "d'interpeller les auteurs à la sortie de l'établissement", "de bloquer les auteurs à l'intérieur", "de faire obstacle au départ de leur véhicule"], "a": "A", "e": "Risque de prise d'otages ou d'affrontement armé. (Source : PPI Agression crapuleuse)"}, {"t": 13, "s": "Véhicule suspect susceptible d'être piégé : périmètre immédiat de :", "o": ["200 m", "100 m", "300 m", "150 m"], "a": "A", "e": "Objet : 100 m ; véhicule : 200 m. (Source : Instruction DPN-3.1.3)"}, {"t": 13, "s": "Lors d'une poursuite, le CIC (centre d'information et de commandement) / la salle de commandement peut :", "o": ["faire cesser sans délai la poursuite", "imposer le silence radio", "faire converger d'autres patrouilles", "autoriser le tir sur le véhicule pour l'immobiliser"], "a": "ABC", "e": "L'arme reste dans les cadres 122-5 CP et L.435-1 CSI (code de la sécurité intérieure). (Source : Instruction 16/05/2025 ; fiche mémo RO)"}, {"t": 13, "s": "La circonstance aggravante du refus d'obtempérer est prévue par l'article :", "o": ["L.233-1-1 du code de la route", "L.233-2 du code de la route", "L.234-1 du code de la route", "L.435-1 du CSI"], "a": "A", "e": "Exposition directe d'autrui à un risque de mort ou de blessures graves. (Source : Instruction 16/05/2025 ; fiche mémo RO)"}, {"t": 14, "s": "Quelles affirmations relatives à la formation TSI (techniques et sécurité en intervention) sont exactes ?", "o": ["Le volume minimal annuel est de 12 heures", "La séance type a une durée effective de 4 heures", "Les accidents survenus en formation TSI relèvent de la vie privée", "La formation peut être dispensée par tout gradé"], "a": "AB", "e": "Accidents en formation TSI : imputables au service. Compétence exclusive des formateurs TSI. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Aménagement des 12 heures : la durée minimale de chaque séance de tir est de :", "o": ["1 heure", "2 heures", "45 minutes", "1 h 30"], "a": "A", "e": "3 séances, 90 cartouches ; au moins 9 h de PPI. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Est comptabilisé comme temps d'entraînement réglementaire aux PPI :", "o": ["le stage de recyclage au port des bâtons de police", "le stage de recyclage au PIE", "la séance de sport opérationnel", "la séance de manipulation de l'arme"], "a": "A", "e": "Ainsi que tout stage dont la fiche séquentielle le prévoit. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Une carence est constatée au tir et confirmée. Le formateur TSI (techniques et sécurité en intervention) :", "o": ["renseigne une fiche d'observations individuelle normalisée", "retire l'arme du policier", "saisit le conseil de discipline", "inscrit le policier à un recyclage d'office de 12 heures"], "a": "A", "e": "Le chef de service est avisé ; lui seul peut décider du retrait de l'arme. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Le sport opérationnel :", "o": ["est d'une durée hebdomadaire de 2 heures", "s'effectue sur le temps de travail", "ne donne lieu à aucune compensation horaire", "peut être supprimé durablement pour contraintes opérationnelles"], "a": "ABC", "e": "Les restrictions ne peuvent être que temporaires. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 1, "s": "Pour des vacations comprises entre 11 h et 12 h effectuées de nuit, l'indemnité de travail de nuit est de :", "o": ["82 € par mois", "35 € par mois", "105 € par mois", "128 € par mois"], "a": "A", "e": "Montant mensuel fonction de la durée de la vacation de nuit. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Une majoration de 105 € par mois de l'indemnité de nuit est prévue en cas de travail continu :", "o": ["de 0 h à 5 h", "de 22 h à 6 h", "de 21 h à 6 h", "de 23 h à 4 h"], "a": "A", "e": "Majoration +105 €/mois pour un travail continu de 0 h à 5 h. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "L'indemnité de travail de nuit est versée :", "o": ["après chaque trimestre échu", "mensuellement avec le traitement", "après chaque semestre échu", "une fois par an en janvier"], "a": "A", "e": "Versement trimestriel à terme échu. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Un agent de nuit (vacations inférieures à 11 h 08) suit une formation le matin, entre deux nuits, sans dépasser 13 h. Il :", "o": ["reprend son service le soir même après un repos de 8 h", "reprend son service le soir même après un repos de 11 h", "reprend son service le soir même après un repos de 6 h", "est exempté de la nuit suivante"], "a": "A", "e": "Code STG sur la nuit précédente, puis reprise le soir après 8 h de repos. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Concernant la formation continue et le temps de travail, quelles affirmations sont exactes ?", "o": ["Un fonctionnaire absent au titre d'une formation n'entre pas dans les ratios d'absences", "Un repos minimum de 8 h est prévu entre une fin de mission et le début d'une vacation", "Les personnels de l'article 10 bénéficient d'une compensation des dépassements horaires en formation", "Le repos minimum entre une fin de mission et une vacation est de 11 h"], "a": "AB", "e": "Les personnels de l'article 10 sont exclus de la compensation. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "En régime hebdomadaire avec prise de service décalée, l'interruption méridienne :", "o": ["peut être réduite jusqu'à 45 min ou remplacée par une pause de 20 min, sans pouvoir être augmentée", "peut être portée jusqu'à 2 h 30 sur décision du chef de service", "doit obligatoirement être supprimée", "peut être augmentée jusqu'à 3 h en accord avec l'agent"], "a": "A", "e": "Diminution possible, augmentation exclue. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 2, "s": "Pour un agent à temps complet, le nombre maximal de jours flottants de télétravail est de :", "o": ["156 jours par an", "104 jours par an", "208 jours par an", "130 jours par an"], "a": "A", "e": "Plafond annuel de jours flottants : 156 jours. (Source : Guide – télétravail)"}, {"t": 2, "s": "L'allocation forfaitaire de télétravail s'élève à :", "o": ["2,88 € par jour, dans la limite de 282,24 € par an", "2,50 € par jour, dans la limite de 250 € par an", "2,88 € par jour, dans la limite de 250 € par an", "3,00 € par jour, dans la limite de 282,24 € par an"], "a": "A", "e": "2,88 €/jour, plafond 282,24 €/an. (Source : Guide – télétravail)"}, {"t": 2, "s": "Parmi les principes du télétravail figurent :", "o": ["le volontariat", "la réversibilité", "l'alternance entre travail sur site et télétravail", "l'obligation d'un jour fixe par semaine"], "a": "ABC", "e": "Volontariat, alternance, réversibilité, usage des outils numériques. (Source : Guide – télétravail)"}, {"t": 2, "s": "Le chef de service se prononce sur une demande de télétravail dans un délai de :", "o": ["un mois", "15 jours", "deux mois", "8 jours"], "a": "A", "e": "Réponse écrite dans un délai d'un mois. (Source : Guide – télétravail)"}, {"t": 2, "s": "Peuvent bénéficier d'une dérogation à la quotité maximale de télétravail :", "o": ["l'agent dont l'état de santé le justifie, pour 6 mois renouvelables, après avis du médecin du travail", "la femme enceinte", "le proche aidant, pour 6 mois renouvelables", "l'agent nouvellement affecté"], "a": "AB", "e": "Le proche aidant : 3 mois renouvelables. (Source : Guide – télétravail)"}, {"t": 2, "s": "Parmi ces activités, laquelle est éligible au télétravail ?", "o": ["la rédaction de notes et de synthèses", "l'accueil physique du public", "les activités opérationnelles de voie publique", "la représentation de l'État auprès des usagers"], "a": "A", "e": "Les activités opérationnelles, d'accueil physique et de représentation sont exclues. (Source : Guide – télétravail)"}, {"t": 3, "s": "Un agent logé par nécessité absolue de service est placé d'astreinte :", "o": ["l'astreinte s'applique sans rémunération ni compensation", "l'astreinte est compensée à 100 %", "l'astreinte est uniquement indemnisée", "l'astreinte lui est interdite"], "a": "A", "e": "La concession de logement NAS exclut rémunération et compensation. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 3, "s": "Un agent réalise un dépassement horaire pendant une période d'astreinte :", "o": ["il ne peut cumuler la compensation du dépassement et celle de la période d'astreinte correspondante", "il cumule les deux compensations", "seule l'astreinte est compensée", "le dépassement est payé en heures supplémentaires de nuit"], "a": "A", "e": "Pas de double compensation pour une même période. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 3, "s": "Lorsqu'une permanence est effectuée pendant une période d'astreinte :", "o": ["la période d'astreinte est amputée du temps de travail découlant de la permanence", "l'astreinte s'ajoute intégralement à la permanence", "la permanence est interdite pendant l'astreinte", "la permanence est amputée de la durée de l'astreinte"], "a": "A", "e": "Pas de double décompte. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 3, "s": "Concernant l'astreinte d'un agent à temps partiel, quelles affirmations sont exactes ?", "o": ["Elle est possible indépendamment de la quotité de travail", "Sa compensation est proratisée au regard des heures réellement réalisées", "L'agent peut être placé d'astreinte sur sa demi-journée non travaillée", "L'agent à temps partiel est exclu de l'astreinte"], "a": "AB", "e": "Pas d'astreinte sur la période non travaillée. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 3, "s": "La permanence des officiers ne relevant pas de l'article 10 :", "o": ["ne peut dépasser 12 h et est compensée temps pour temps", "ne peut dépasser 10 h et est compensée à 150 %", "ne peut dépasser 12 h et est compensée à 150 %", "ne peut dépasser 14 h et est compensée temps pour temps"], "a": "A", "e": "Durée maximale 12 h, compensation 1 pour 1. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 3, "s": "Un fonctionnaire admis à travailler à temps partiel :", "o": ["peut être soumis aux règles du rappel au service", "ne peut jamais être rappelé au service", "ne peut être rappelé que sur sa journée non travaillée", "ne peut être rappelé qu'avec son accord écrit"], "a": "A", "e": "Le TP n'exclut ni l'astreinte ni le rappel (hors période non travaillée pour l'astreinte). (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "En régime cyclique, la base horaire d'une journée ARTT (aménagement et réduction du temps de travail) versée au CET (compte épargne-temps) est de :", "o": ["8 h 21", "7 h", "8 h 10", "9 h 31"], "a": "A", "e": "Conversion sur la base de 8 h 21 par jour. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Après proratisation, le calcul des ARTT (aménagement et réduction du temps de travail) d'un agent donne 12,6 jours. Il bénéficie de :", "o": ["12,5 jours", "13 jours", "12 jours", "12,6 jours"], "a": "A", "e": "Décimale entre 0,25 et 0,74 : entier inférieur + une demi-journée. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Réduisent le crédit ARTT (aménagement et réduction du temps de travail) :", "o": ["les jours de grève", "l'autorisation d'absence pour garde d'enfant malade", "la disponibilité", "l'ASA pour événement familial"], "a": "ABC", "e": "Les ASA (autorisation spéciale d'absence) pour événements familiaux sont sans incidence. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "En cas de solde ARTT (aménagement et réduction du temps de travail) négatif, l'administration ne peut pas opérer de retrait sur :", "o": ["les congés annuels", "le compteur RCSS", "les RPS", "le crédit férié"], "a": "A", "e": "Retrait sur RCSS (repos compensateur pour services supplémentaires), RPS (repos de pénibilité spécifique) ou CF, à l'exclusion des CA ; à défaut, imputation sur l'année suivante. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Hors plan prévisionnel, le taux de présence minimal à respecter est en principe de :", "o": ["60 % des effectifs, sans descendre sous 50 %", "50 % des effectifs, sans descendre sous 40 %", "75 % des effectifs, sans descendre sous 60 %", "66 % des effectifs, sans descendre sous 50 %"], "a": "A", "e": "Taux de 60 %, plancher de 50 %. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Un agent est suspendu de ses fonctions. S'agissant de ses ARTT (aménagement et réduction du temps de travail) :", "o": ["il n'en génère pas pendant la suspension (prorata du service accompli)", "il conserve l'intégralité de ses droits", "il perd tous ses ARTT de l'année", "ses ARTT sont convertis en congés annuels"], "a": "A", "e": "Droits calculés au prorata du service effectivement accompli. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Le congé de solidarité familiale peut être pris pour une période continue de :", "o": ["3 mois, renouvelable une fois", "6 mois, non renouvelable", "3 mois, renouvelable deux fois", "1 mois, renouvelable une fois"], "a": "A", "e": "3 mois renouvelable une fois. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Le congé de proche aidant est d'une durée de :", "o": ["3 mois renouvelable, dans la limite d'un an sur la carrière", "6 mois renouvelable, dans la limite de 2 ans sur la carrière", "3 mois renouvelable, dans la limite de 2 ans sur la carrière", "1 an, dans la limite de 3 ans sur la carrière"], "a": "A", "e": "Limite d'un an sur l'ensemble de la carrière. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Concernant le congé de maternité, quelles affirmations sont exactes ?", "o": ["Une partie du congé prénatal peut être reportée sur le postnatal, sur avis médical, dans la limite de 3 semaines", "Le seuil de viabilité retenu est de 22 semaines d'aménorrhée ou 500 g", "La policière adjointe en bénéficie sans réduction de traitement dès 3 mois de service", "En cas de décès de la mère, le père peut bénéficier du congé postnatal restant"], "a": "ABD", "e": "Pour une PA (policiers adjoints) : 6 mois de service. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "L'ASA (autorisation spéciale d'absence) accordée de droit pour une activité dans la réserve opérationnelle est limitée à :", "o": ["10 jours ouvrés par année civile, avec un préavis d'un mois", "30 jours par année civile, avec un préavis de 15 jours", "15 jours ouvrés par année civile, avec un préavis de 15 jours", "5 jours ouvrés par année civile, avec un préavis d'un mois"], "a": "A", "e": "Au-delà, accord de l'employeur. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "L'ASA (autorisation spéciale d'absence) pour garde d'enfant malade est accordée pour un enfant âgé au plus de :", "o": ["16 ans, sauf enfant handicapé", "12 ans, sauf enfant handicapé", "18 ans, sans exception", "14 ans, sauf enfant handicapé"], "a": "A", "e": "Pas de limite d'âge pour un enfant handicapé. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Concernant les absences pour motif syndical, quelles affirmations sont exactes ?", "o": ["L'ASA de l'article 13 est de 10 jours par an et par agent pour tous les syndicats", "Elle est portée à 20 jours si le syndicat est représenté au conseil commun de la fonction publique", "Le congé de formation syndicale est de 15 jours au maximum", "Une absence de l'article 13 posée sur un repos de cycle ouvre droit à compensation"], "a": "AB", "e": "Congé de formation syndicale : 12 jours au maximum. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Pour ouvrir un CET (compte épargne-temps), un agent contractuel doit avoir été employé de manière continue ; l'interruption maximale tolérée entre deux contrats est de :", "o": ["4 mois", "2 mois", "6 mois", "3 mois"], "a": "A", "e": "Au moins 1 an de service, interruption entre contrats de 4 mois au plus. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Un agent part à la retraite avec 40 jours sur son CET (compte épargne-temps). Quelles affirmations sont exactes ?", "o": ["Les 15 premiers jours doivent être pris en congés avant la cessation de fonctions", "Les 15 premiers jours peuvent être indemnisés à la date de départ", "Les jours au-delà des 15 premiers sont indemnisés à la date de cessation des fonctions", "Les jours peuvent faire l'objet d'un don"], "a": "ACD", "e": "Les 15 premiers jours ne sont pas indemnisables. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Le jour de carence ne s'applique pas en cas de rechute lorsque la reprise entre deux arrêts pour la même cause n'excède pas :", "o": ["48 heures", "72 heures", "24 heures", "7 jours"], "a": "A", "e": "Rechute à moins de 48 h : pas de nouvelle carence. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Un policier adjoint justifiant de 2 ans de service peut bénéficier d'un congé maladie rémunéré de :", "o": ["2 mois à plein traitement et 2 mois à demi-traitement", "1 mois à plein traitement et 1 mois à demi-traitement", "3 mois à plein traitement et 3 mois à demi-traitement", "2 mois à plein traitement et 1 mois à demi-traitement"], "a": "A", "e": "4 mois : 1+1 ; 2 ans : 2+2 ; 3 ans : 3+3. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Le temps partiel thérapeutique est accordé par période de :", "o": ["1 à 3 mois renouvelable, dans la limite d'un an", "6 mois renouvelable, dans la limite de 2 ans", "1 à 6 mois renouvelable, dans la limite d'un an", "3 mois renouvelable, dans la limite de 18 mois"], "a": "A", "e": "Durée maximale d'un an. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Concernant le temps partiel thérapeutique, quelles affirmations sont exactes ?", "o": ["L'agent ne peut pas effectuer d'heures supplémentaires", "Les policiers adjoints peuvent en bénéficier", "Il est réservé aux agents sortant d'un CLD", "Une expertise par un médecin agréé est requise dès le premier mois"], "a": "AB", "e": "Expertise seulement au-delà de 3 mois. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 7, "s": "Les casiers individuels de conservation des armes comportent :", "o": ["au moins deux compartiments, l'un pour l'arme, l'autre pour les chargeurs et munitions", "au moins trois compartiments", "un compartiment unique fermé à clé", "quatre compartiments dont un pour l'étui"], "a": "A", "e": "Arme et munitions séparées. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Ne doivent pas disposer de la clé de leur casier individuel :", "o": ["les policiers adjoints", "les réservistes", "les gardiens de la paix stagiaires", "les officiers en formation"], "a": "AB", "e": "Ainsi que les polytechniciens. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "L'arme peut être conservée dans le coffre sécurisé du véhicule (bureaux de vote, présentations consulaires) à condition :", "o": ["qu'un policier en assure la surveillance constante et effective", "que le véhicule soit stationné dans une enceinte administrative", "que l'arme soit démontée", "que le chef de service l'ait autorisé par écrit pour l'année"], "a": "A", "e": "Surveillance constante et effective obligatoire. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Les contrôles hiérarchiques relatifs aux armes portent notamment sur :", "o": ["la tenue des registres", "le bon état de fonctionnement des armes", "un contrôle physique à partir d'une liste", "un contrôle balistique annuel par l'INPS"], "a": "ABC", "e": "Pas de contrôle balistique annuel prévu. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Dans le dispositif « Voyager-Protéger », le policier :", "o": ["doit se présenter au chef de bord et porter son arme individuelle", "doit déposer son arme au service avant tout déplacement privé", "voyage gratuitement sur le seul trajet domicile-travail", "peut transporter l'arme dans un bagage verrouillé"], "a": "A", "e": "En vigueur depuis le 1er janvier 2022. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Pour le tir sportif, l'autorisation d'acquisition de munitions porte sur :", "o": ["1 000 cartouches, valable 3 mois", "500 cartouches, valable 1 mois", "1 000 cartouches, valable 6 mois", "3 000 cartouches, valable 3 mois"], "a": "A", "e": "1 000 cartouches pour 3 mois. (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "Ne doivent pas faire l'objet d'une déclaration dans TSUA (traitement relatif au suivi de l'usage des armes) les usages d'armes :", "o": ["réalisés au cours de séances pédagogiques", "effectués dans le cadre d'une tentative de suicide", "de bâtons de police", "du dispositif balistique de désencerclement (DBD)"], "a": "ABC", "e": "Le DBD (dispositif balistique de désencerclement)/DMP est la seule grenade proposée par le traitement. (Source : Instruction/FAQ TSUA)"}, {"t": 8, "s": "Une déclaration TSUA (traitement relatif au suivi de l'usage des armes) a été faite à titre provisoire par un collègue habilité, l'auteur étant blessé. Lorsque l'auteur peut déclarer lui-même :", "o": ["la déclaration provisoire est supprimée par l'autorité hiérarchique et l'auteur renouvelle la procédure", "la déclaration provisoire devient définitive après son visa", "l'auteur complète simplement la déclaration provisoire", "les deux déclarations sont fusionnées par le traitement"], "a": "A", "e": "La version provisoire n'engage pas l'auteur des usages. (Source : Instruction/FAQ TSUA)"}, {"t": 8, "s": "Lors d'un événement impliquant plusieurs unités (violences urbaines), les usages d'armes sont déclarés dans TSUA (traitement relatif au suivi de l'usage des armes) :", "o": ["individuellement par chaque policier pour ses propres usages", "collectivement par le chef de l'unité engagée", "globalement par le directeur du service d'ordre", "uniquement s'il y a eu un blessé"], "a": "A", "e": "Le traitement ne permet pas la déclaration d'usage collectif. (Source : Instruction/FAQ TSUA)"}, {"t": 8, "s": "Concernant l'affectation temporaire du PM (pistolet-mitrailleur) 9 mm, quelles affirmations sont exactes ?", "o": ["Elle concerne les policiers actifs et les réservistes statutaires habilités", "Son emploi en maintien de l'ordre en unité constituée est proscrit", "Elle est ouverte aux policiers adjoints habilités", "Elle peut être permanente sur décision du chef de service"], "a": "AB", "e": "Affectation temporaire, sur autorisation hiérarchique. (Source : Instruction PM 9 mm)"}, {"t": 8, "s": "Sauf circonstances particulières, la mise en sécurité d'un fusil d'assaut HK G36 chargé s'effectue :", "o": ["exclusivement dans les locaux de police", "sur la voie publique dès la fin de la mission", "dans le véhicule, avant le retour au service", "uniquement par l'armurier du service"], "a": "A", "e": "Le port impose aussi le gilet porte-plaques. (Source : Instruction HK G36)"}, {"t": 9, "s": "Lors de sa perception, le LBD (lanceur de balles de défense) de 40 mm sécurisé est remis :", "o": ["canon basculé", "sûreté manuelle mise, liséré blanc visible", "chambre du canon directement visible par la personne qui le perçoit", "approvisionné d'une cartouche"], "a": "ABC", "e": "L'approvisionnement intervient lors de la mise en service. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Le LBD (lanceur de balles de défense) de 40 mm est approvisionné avec :", "o": ["des cartouches pyrotechniques amorcées, initiées par l'action du percuteur", "des cartouches à gaz comprimé", "des projectiles propulsés par air comprimé", "des cartouches à amorçage électrique"], "a": "A", "e": "Projectile en caoutchouc à effet cinétique. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "La grenade à main de désencerclement est aussi désignée sous l'appellation :", "o": ["« dispositif balistique de désencerclement » (DBD) ou « dispositif manuel de protection » (DMP)", "« dispositif de propulsion à retard » (DPR)", "« grenade assourdissante et lacrymogène » (GM2L)", "« munition de défense unique » (MDU)"], "a": "A", "e": "DBD (dispositif balistique de désencerclement) ou DMP (dispositif manuel de protection). (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Le module interne pyrotechnique de la GM2L (grenade assourdissante et lacrymogène) se compose :", "o": ["d'un bouchon retard, d'une gaine centrale à composition sonore et d'une enveloppe souple contenant de la poudre CS", "d'un bouchon allumeur, de galets en caoutchouc et d'une charge lacrymogène", "d'une charge explosive, d'éclats métalliques et de poudre CS", "d'un bouchon retard et d'une capsule de gaz comprimé"], "a": "A", "e": "Effet assourdissant et lacrymogène. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Au titre de l'état de nécessité, le LBD (lanceur de balles de défense) de 40 mm ne peut être utilisé que pour protéger :", "o": ["une valeur supérieure à celle sacrifiée", "une valeur au moins égale à celle sacrifiée", "toute valeur, sans condition", "exclusivement une vie humaine"], "a": "A", "e": "Article 122-7 du code pénal. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 9, "s": "Concernant le LBD (lanceur de balles de défense) de 40 mm, quelles affirmations sont exactes ?", "o": ["Il n'est ni conçu ni destiné à tuer", "L'emploi du DOE constitue le mode normal de visée", "C'est une AFI en dotation individuelle", "Ses munitions sont conçues pour pénétrer afin d'optimiser le choc"], "a": "AB", "e": "Dotation collective ; munitions à déformation limitant la pénétration. (Source : Instruction DGPN/DGGN 2/08/2017 – AFI)"}, {"t": 10, "s": "Pour le PIE (pistolet à impulsions électriques) T7, l'écart des sondes par mètre linéaire avec la cartouche courte portée est de :", "o": ["24 cm", "9,5 cm", "12 cm", "3,5 cm"], "a": "A", "e": "Longue portée : 9,5 cm. (Source : Instruction DPN-1.9.4.1 et synthèse PIE T7)"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) ne doit pas être employé lorsque le niveau de la batterie est inférieur à :", "o": ["30 %", "20 %", "10 %", "50 %"], "a": "A", "e": "Seuil de 30 %. (Source : Instruction DPN-1.9.4.1 et synthèse PIE T7)"}, {"t": 10, "s": "Les sondes du PIE (pistolet à impulsions électriques) peuvent être efficaces jusqu'à une distance de la peau de :", "o": ["2,54 cm", "1 cm", "5,08 cm", "0,5 cm"], "a": "A", "e": "Efficacité à travers les vêtements jusqu'à 2,54 cm. (Source : Instruction DPN-1.9.4.1 et synthèse PIE T7)"}, {"t": 10, "s": "Concernant le PIE (pistolet à impulsions électriques) T7, quelles affirmations sont exactes ?", "o": ["C'est une arme à 2 coups (2 cartouches)", "La cartouche longue portée est grise, avec un angle de 3,5°", "La cartouche courte portée est efficace de 3,5 m à 7,6 m", "L'étui porte-cartouches contient 3 cartouches supplémentaires"], "a": "AB", "e": "Courte portée : 1,2 m à 7,6 m ; étui de 2 cartouches. (Source : Instruction DPN-1.9.4.1 et synthèse PIE T7)"}, {"t": 10, "s": "La traçabilité des mouvements et de l'usage du PIE (pistolet à impulsions électriques) s'effectue sur :", "o": ["3 niveaux", "2 niveaux", "4 niveaux", "5 niveaux"], "a": "A", "e": "Trois niveaux de traçabilité. (Source : Instruction DPN-1.9.4.1 et synthèse PIE T7)"}, {"t": 11, "s": "Selon le SNMO (schéma national du maintien de l'ordre), les forces étatiques disposent seules du pouvoir légitime d'emploi de la force en maintien de l'ordre, sous la direction :", "o": ["du préfet", "du maire", "du procureur de la République", "du commandant de la force publique"], "a": "A", "e": "Le préfet est responsable de l'ordre public. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "La participation à une manifestation interdite est sanctionnée :", "o": ["d'une contravention", "d'un délit puni d'un an d'emprisonnement", "d'aucune sanction pénale", "d'un délit puni de 7 500 € d'amende"], "a": "A", "e": "Décret 2019-208 du 20 mars 2019. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Le référent « journalistes » est désigné pour les manifestations à compter du :", "o": ["1er février 2022", "1er janvier 2022", "1er juillet 2022", "1er mars 2021"], "a": "A", "e": "Désigné à compter du 1er février 2022. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Concernant le dispositif de liaison et d'information en manifestation, quelles affirmations sont exactes ?", "o": ["L'équipe chargée de cette mission n'a pas d'autre fonction", "L'organisateur désigne des points de contact en lien avec cette équipe", "L'équipe participe aussi aux interpellations ciblées", "L'équipe est placée sous l'autorité du commandant de la force publique"], "a": "AB", "e": "Équipe placée sous l'autorité du DSO (directeur du service d'ordre), mission exclusive. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Sur la période 2017-2022, les effectifs des CRS sont renforcés de :", "o": ["215 ETP", "300 ETP", "88 ETP", "250 ETP"], "a": "A", "e": "Bonne réponse : 215 ETP. ETP signifie « équivalent temps plein » : c'est l'unité qui sert à compter les effectifs en temps de travail, et non en nombre de personnes. Un policier à temps plein = 1 ETP ; deux policiers à mi-temps = 1 ETP à eux deux ; un policier à 80 % = 0,8 ETP. « 215 ETP » veut donc dire l'équivalent de 215 policiers à temps plein. Le SNMO prévoit, sur 2017-2022, de renforcer les unités spécialisées en maintien de l'ordre pour augmenter leur capacité d'engagement : 215 ETP pour les CRS (compagnies républicaines de sécurité) → bonne réponse ; 300 ETP pour les escadrons de gendarmerie mobile (EGM), pas pour les CRS → faux ; 88 ETP pour les compagnies d'intervention de la préfecture de police (PP) → faux ; 250 ETP n'apparaît nulle part dans le texte → faux. Astuce : les CRS sont au milieu (88 < 215 < 300). (Source : Schéma national du maintien de l'ordre (SNMO, déc. 2021), § 24.5 ; le cours emploie le sigle ETP sans le développer, « équivalent temps plein » est son sens administratif usuel.)"}, {"t": 11, "s": "Les réquisitions du procureur aux fins de fouille de bagages et de visite de véhicules sur l'itinéraire d'une manifestation visent l'article :", "o": ["78-2-5 du CPP", "78-2-2 du CPP", "78-2-4 du CPP", "78-3 du CPP"], "a": "A", "e": "Complétées le cas échéant par l'article 78-2 al. 7. (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "Lors d'une palpation, les objets découverts :", "o": ["imposent une nouvelle palpation après la découverte d'un objet dangereux", "sont, s'ils sont écartés, représentés au détenteur avant la remise à l'OPJ", "sont, s'ils ne présentent aucun danger, restitués au terme de la palpation complète", "sont, s'ils ne présentent aucun danger, restitués immédiatement"], "a": "ABC", "e": "Objet sans danger : restitution en fin de palpation. (Source : TDI Palpation de sécurité)"}, {"t": 12, "s": "La palpation de sécurité est définie par l'article :", "o": ["R. 434-16 du CSI", "R. 434-17 du CSI", "R. 434-18 du CSI", "78-2 du CPP"], "a": "A", "e": "Code de déontologie, article R. 434-16. (Source : TDI Palpation de sécurité)"}, {"t": 12, "s": "La palpation de sécurité s'effectue :", "o": ["par pressions successives avec la partie interne des mains", "par glissement de la paume sur les vêtements", "du bout des doigts par glissement", "avec le dos de la main"], "a": "A", "e": "Pas de glissement, pour éviter piqûre ou coupure. (Source : TDI Palpation de sécurité)"}, {"t": 12, "s": "La technique de palpation à privilégier est :", "o": ["la palpation arrière", "la palpation de face", "la palpation latérale", "la palpation au sol"], "a": "A", "e": "Position la plus sécurisante pour le palpeur. (Source : TDI Palpation de sécurité)"}, {"t": 12, "s": "Concernant le menottage, quelles affirmations sont exactes ?", "o": ["En fin de menottage, l'interpellateur annonce « menotté » et donne une tape sur l'épaule de la protection", "Les menottes à l'étui doivent être accessibles rapidement, côté main forte", "Saisir les menottes pour relever l'individu est la technique recommandée", "Le serrage doit être maximal pour prévenir toute fuite"], "a": "AB", "e": "Agir sur les menottes est source de douleurs inutiles. (Source : TDI Menottage)"}, {"t": 12, "s": "Avant un menottage, le dispositif doit intégrer systématiquement dans son analyse le principe de :", "o": ["non-coopération de la personne", "coopération présumée de la personne", "moindre contrainte", "menottage dans le dos"], "a": "A", "e": "Capacité à maîtriser l'individu en conservant une protection environnementale. (Source : TDI Menottage)"}, {"t": 13, "s": "Selon le glossaire tactique « Attentats », les façades d'un bâtiment sont désignées :", "o": ["de 1 à 4 dans le sens des aiguilles d'une montre, la façade 1 comportant l'entrée principale", "de 1 à 4 dans le sens inverse des aiguilles d'une montre, la façade 1 comportant l'entrée principale", "de 1 à 4 dans le sens des aiguilles d'une montre, la façade 1 étant orientée au nord", "de A à D, la façade A comportant l'entrée principale"], "a": "A", "e": "Annexe DPN-3.1 G. (Source : Glossaire tactique « Attentats » (DPN-3.1 G))"}, {"t": 13, "s": "Selon le glossaire tactique « Attentats », quelles affirmations sont exactes ?", "o": ["Le niveau 0 est celui de l'entrée principale", "Les fenêtres sont numérotées de gauche à droite, en partant de 1", "Le niveau 1 est toujours le rez-de-chaussée sur rue", "Les fenêtres sont numérotées de droite à gauche"], "a": "AB", "e": "Annexe DPN-3.1 G. (Source : Glossaire tactique « Attentats » (DPN-3.1 G))"}, {"t": 13, "s": "Lors d'une perquisition (FT n°42), quelles règles sont exactes ?", "o": ["Les clés d'accès du domicile sont conservées par le policier dirigeant l'opération, dans sa poche", "La fouille se fait pièce par pièce, en présence permanente de l'occupant", "La personne visée ne doit ni fouiller elle-même les lieux ni communiquer avec des tiers", "Plusieurs pièces sont fouillées simultanément pour gagner du temps"], "a": "ABC", "e": "Ne jamais fouiller plusieurs pièces à la fois. (Source : TI Perquisition (FT n°42))"}, {"t": 13, "s": "Face à un forcené, le représentant de la hiérarchie, renseigné :", "o": ["se transporte sur les lieux sans délai", "peut y être rejoint par l'autorité judiciaire et l'autorité préfectorale", "dirige l'intervention depuis le CIC sans se déplacer", "n'intervient qu'après l'arrivée de l'unité spécialisée"], "a": "AB", "e": "Il confirme ou adapte les premières mesures, déploie des renforts. (Source : TI Forcené)"}, {"t": 13, "s": "Sauf dispositions particulières (stupéfiants, terrorisme…), une perquisition ne peut débuter :", "o": ["avant 6 h et après 21 h", "avant 7 h et après 20 h", "avant 6 h et après 22 h", "avant 5 h et après 21 h"], "a": "A", "e": "FT n°42 – perquisition. (Source : TI Perquisition (FT n°42))"}, {"t": 14, "s": "Faute de recyclage, une nouvelle habilitation au PM (pistolet-mitrailleur) 9 mm est exigée au-delà de :", "o": ["24 mois après l'habilitation ou le dernier recyclage", "12 mois après l'habilitation ou le dernier recyclage", "36 mois après l'habilitation ou le dernier recyclage", "18 mois après l'habilitation ou le dernier recyclage"], "a": "A", "e": "Recyclages espacés de 12 mois au plus ; suspension au-delà. (Source : Instruction PM 9 mm)"}, {"t": 14, "s": "Les contenus pédagogiques des séances TSI (techniques et sécurité en intervention) sont :", "o": ["élaborés par l'académie de police et validés par le DGPN", "élaborés par chaque chef de service", "élaborés par les formateurs TSI et validés par le préfet", "fixés par circulaire du ministre de l'intérieur"], "a": "A", "e": "Article 6 de l'arrêté. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Un policier échoue à l'évaluation organisée lors du recyclage HK G36 :", "o": ["son habilitation est suspendue jusqu'à ce que le recyclage soit effectué", "il perd définitivement son habilitation", "il conserve l'arme trois mois", "il doit repasser immédiatement l'habilitation initiale"], "a": "A", "e": "Sans recyclage, il ne peut percevoir l'arme. (Source : Instruction HK G36)"}, {"t": 14, "s": "Les conditions de sélection, de formation et les compétences des formateurs TSI (techniques et sécurité en intervention) sont fixées par :", "o": ["circulaire du ministre de l'intérieur", "arrêté du directeur général de la police nationale", "instruction de l'académie de police", "décret en Conseil d'État"], "a": "A", "e": "Article 11 de l'arrêté du 27/07/2015. (Source : Arrêté du 27/07/2015 (TSI))"}, {"t": 14, "s": "Un policier non habilité au PM (pistolet-mitrailleur) 9 mm :", "o": ["peut, en cas d'absolue nécessité, utiliser l'arme d'un collègue habilité blessé", "peut percevoir l'arme sous le contrôle d'un collègue habilité", "ne peut en aucun cas utiliser l'arme", "peut la percevoir s'il est habilité au G36"], "a": "A", "e": "Distinction entre droit de percevoir et droit d'utiliser. (Source : Instruction PM 9 mm)"}, {"t": 4, "s": "Concernant le crédit férié, quelles affirmations sont exactes ?", "o": ["Il ne peut pas alimenter un CET", "Il est réduit de 1/24e (3 h 33) par période de CMO égale ou supérieure à 15 jours consécutifs", "Il est proratisé pour un agent prenant ses fonctions en cours d'année, par période de 30 jours", "Il est librement reportable sur l'année suivante"], "a": "AB", "e": "Proratisation par période de 15 jours. Il se prend dans l'année civile ; report seulement sur autorisation du DGPN (directeur général de la police nationale), du préfet de police ou du DGSI (directeur général de la sécurité intérieure). (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Fiche APORTT n°8)"}, {"t": 4, "s": "Concernant les priorités de départ pendant les vacances scolaires, quelles affirmations sont exactes ?", "o": ["75 % des départs sont réservés aux fonctionnaires élevant des enfants d'âge scolaire (3-16 ans) ou bénéficiant d'un droit de garde ou de visite", "À priorité égale, les agents sont départagés d'abord par l'âge", "La priorité des parents d'enfants handicapés est classée en première position et compte dans les 75 %", "Une priorité non satisfaite en année N est reportée sur l'année N+1"], "a": "ACD", "e": "Départage : ancienneté de grade, puis ancienneté de présence administrative, enfin l'âge. (Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés)"}, {"t": 4, "s": "Nombre de CA annuels selon le régime : quelles correspondances sont exactes ?", "o": ["Hebdomadaire : 25 CA", "Cycle 4/2 : 25 CA", "Vacation forte : 18 CA", "Cycles 2/2, 3/3 : 18 CA"], "a": "AD", "e": "Cycle 4/2 : 23 CA. Vacation forte : 20 CA. Le congé annuel vaut 5 fois les obligations hebdomadaires, en jours ouvrés. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 4, "s": "L'attribution des jours ARTT (aménagement et réduction du temps de travail) a pour objet :", "o": ["de ramener la durée annuelle de travail effectif à 1 607 heures", "de compenser le travail de nuit", "de rémunérer les services supplémentaires", "de compenser les jours fériés en régime cyclique"], "a": "A", "e": "ARTT : retour aux 1 607 h. Le crédit férié compense les jours fériés en cyclique ; les RPS (repos de pénibilité spécifique) la pénibilité. (Source : Fiche APORTT n°10)"}, {"t": 4, "s": "Le congé bonifié a une durée maximale de :", "o": ["31 jours consécutifs, tous les deux ans, après 24 mois de services ininterrompus", "45 jours, tous les trois ans", "31 jours, chaque année, après 12 mois de services", "60 jours, tous les deux ans"], "a": "A", "e": "31 jours maximum, tous les deux ans, 24 mois de services ininterrompus. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 4, "s": "Un jour férié placé APRÈS les RC (repos compensateur)/RL qui suivent des congés posés au plan :", "o": ["est rappelable", "est protégé du rappel", "ne peut être rappelé que sur décision du DGPN", "est converti en crédit férié"], "a": "A", "e": "Un JF placé avant les RC/RL descendants est protégé ; un JF intervenant après est rappelable. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 4, "s": "Selon la fiche APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) n°8, le pourcentage de fonctionnaires présents dans un service :", "o": ["ne peut être inférieur à 50 %, ni atteindre 100 % sauf décision du ministre en circonstances exceptionnelles", "ne peut être inférieur à 75 %", "est librement fixé par le chef de service", "ne peut dépasser 75 %"], "a": "A", "e": "Minimum 50 %, et 100 % seulement sur décision du ministre de l'Intérieur en circonstances exceptionnelles. (Source : Fiche APORTT n°8)"}, {"t": 4, "s": "Le plan prévisionnel annuel des départs en congés, lorsqu'il est établi en une seule fois, couvre la période :", "o": ["du 15 mars de l'année N au 14 mars de l'année N+1", "du 1er janvier au 31 décembre de l'année N", "du 1er mai au 31 octobre de l'année N", "du 15 février au 15 octobre de l'année N"], "a": "A", "e": "Plan en une fois : 15 mars N – 14 mars N+1, validé au plus tard le 15 mars. Plan scindé : 15 février – 15 octobre puis 16 octobre – 14 février. (Source : Circulaire DGPN du 26/01/2022 – plan prévisionnel des congés ; Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 4, "s": "Le crédit férié annuel (régime cyclique) en métropole hors Alsace-Moselle est de :", "o": ["109 h 12", "116 h 12", "123 h 12", "14 jours de 8 h"], "a": "A", "e": "109 h 12 ; 116 h 12 dans les DOM (abolition de l'esclavage) ; 123 h 12 en Alsace-Moselle. Il équivaut à 14 jours de repos. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 5, "s": "ASA (autorisation spéciale d'absence) pour événements de famille : quelles durées maximales sont exactes ?", "o": ["Mariage de l'agent : 5 jours ouvrables", "Mariage d'un enfant de l'agent : 5 jours ouvrables", "Décès du père ou de la mère : 3 jours ouvrables", "Mariage d'un parent ou allié jusqu'au 3e degré : 3 jours ouvrables"], "a": "AC", "e": "Mariage d'un enfant : 3 jours. Mariage d'un parent ou allié jusqu'au 3e degré : 1 jour ouvrable. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Le fonctionnaire en congé parental :", "o": ["conserve ses droits à l'avancement dans la limite de cinq ans sur l'ensemble de sa carrière", "n'acquiert pas de droit à la retraite, sous réserve des dispositions spécifiques", "perçoit la moitié de son traitement", "conserve le bénéfice des droits acquis avant le début du congé"], "a": "ABD", "e": "Le congé parental est un congé sans traitement. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Congé de paternité : quelles affirmations sont exactes ?", "o": ["4 jours doivent être pris consécutivement et immédiatement après le congé de naissance de 3 jours", "Le reste peut être fractionné en deux périodes maximum d'au moins 5 jours chacune", "Le reste doit être pris dans les quatre mois suivant la naissance", "La demande est formulée au moins quinze jours avant la date présumée de la naissance"], "a": "AB", "e": "Le reste se prend dans les six mois suivant la naissance. La demande doit être formulée au moins un mois avant la date présumée de la naissance. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Les congés pathologiques liés à la grossesse :", "o": ["peuvent atteindre 2 semaines pendant la grossesse, en continu ou non", "peuvent atteindre 4 semaines au maximum après la naissance", "n'entrent pas dans les absences (CMO) réduisant l'ARTT", "sont décomptés comme des congés de maladie ordinaire"], "a": "ABC", "e": "Ils sont considérés comme congé de maternité, et non comme CMO (congé de maladie ordinaire). (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "La demande de congé de présence parentale doit être faite par écrit au moins :", "o": ["15 jours avant le début du congé, avec un certificat médical", "un mois avant", "deux mois avant", "48 heures avant"], "a": "A", "e": "Accordé de droit, sur demande écrite au moins 15 jours avant, avec certificat du médecin qui suit l'enfant. Maximum 310 jours ouvrés sur 36 mois pour un même enfant et une même pathologie. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "En cas de grossesse gémellaire, le congé de maternité :", "o": ["débute 12 semaines avant la date présumée et se termine 22 semaines après l'accouchement", "débute 24 semaines avant et se termine 22 semaines après", "débute 8 semaines avant et se termine 18 semaines après", "débute 10 semaines avant et se termine 16 semaines après"], "a": "A", "e": "Jumeaux : 12 + 22 semaines ; triplés ou plus : 24 + 22 semaines. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Un agent perd son enfant âgé de 20 ans. Il bénéficie de droit de :", "o": ["3 jours ouvrables", "12 jours ouvrables", "14 jours ouvrables, plus une ASA complémentaire de 8 jours fractionnable dans un délai d'un an", "5 jours ouvrables"], "a": "C", "e": "12 jours, portés à 14 pour un enfant de moins de 25 ans, + 8 jours complémentaires dans l'année. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Un agent à 80 % demande des ASA (autorisation spéciale d'absence) pour garde d'enfant malade, sans situation particulière. Son droit annuel maximal est de :", "o": ["6 jours", "4,8 jours non arrondis", "5 jours", "4 jours"], "a": "C", "e": "(5 + 1) × 4/5 = 4,8, arrondi à 5 jours. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Le décès d'un oncle de l'agent (parent du 3e degré) ouvre droit à une ASA (autorisation spéciale d'absence) de :", "o": ["1 jour ouvrable maximum", "3 jours ouvrables", "5 jours ouvrables", "aucune ASA"], "a": "A", "e": "Décès d'un parent ou allié jusqu'au 3e degré : 1 jour ouvrable. Oncle, tante, neveu, nièce relèvent du 3e degré. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 5, "s": "Le congé parental est accordé par périodes de :", "o": ["2 à 6 mois renouvelables, demandées au moins deux mois avant le début", "1 à 3 mois, demandées un mois avant", "6 mois à 1 an, demandées trois mois avant", "2 à 6 mois, demandées quinze jours avant"], "a": "A", "e": "Périodes de 2 à 6 mois renouvelables ; demande au moins 2 mois avant. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) – congés et absences)"}, {"t": 6, "s": "CET (compte épargne-temps) entre 16 et 60 jours : pour les jours excédant 15, l'agent titulaire peut choisir :", "o": ["le maintien sur le CET, dans la limite de 15 jours par an", "l'indemnisation à compter du 16e jour, par jours entiers", "le versement au régime de retraite additionnelle (RAFP)", "l'indemnisation des 15 premiers jours"], "a": "BC", "e": "Maintien limité à 10 jours par an. Les 15 premiers jours ne sont utilisables qu'en congés ; RAFP (régime de retraite additionnelle de la fonction publique) réservée aux titulaires. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET))"}, {"t": 6, "s": "Temps partiel sur autorisation : quelles affirmations sont exactes ?", "o": ["Les quotités possibles vont de 50 % à 90 %", "Tout refus doit être précédé d'un entretien", "Le chef de service peut s'opposer aux modalités d'organisation sollicitées", "Il est accordé de droit, sans condition de service"], "a": "ABC", "e": "Il est accordé sous réserve des nécessités, de la continuité et du fonctionnement du service. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Ouverture d'un CET (compte épargne-temps) : quelles affirmations sont exactes ?", "o": ["Il faut avoir accompli au moins une année de service dans la fonction publique d'État", "Un agent peut ouvrir plusieurs CET simultanément s'il a changé d'administration", "Les élèves en école, stagiaires et apprentis sont exclus du dispositif", "La demande d'ouverture ne peut être faite qu'entre le 1er et le 31 janvier"], "a": "AC", "e": "Un seul CET à la fois ; la demande d'ouverture peut être faite à tout moment, c'est l'alimentation qui a lieu en janvier. (Source : Guide des principales règles de gestion du temps de travail (ARTT, CET))"}, {"t": 6, "s": "En régime cyclique, le temps partiel s'organise :", "o": ["dans un cadre annuel, par l'octroi de jours non travaillés", "par diminution de la durée de chaque vacation", "uniquement par semaines non travaillées", "au choix de l'agent, quotidiennement ou annuellement"], "a": "A", "e": "Il est impossible en cyclique de réduire la durée de la vacation ; en hebdomadaire, réduction quotidienne ou du nombre de vacations. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Lorsque l'agent accole des jours CET (compte épargne-temps) à des CA ou des RTT (réduction du temps de travail), il peut s'absenter plus de 31 jours consécutifs :", "o": ["de plein droit", "sous réserve des besoins du service et de l'avis du supérieur hiérarchique", "jamais", "uniquement pour un congé bonifié"], "a": "B", "e": "Exception à la limite des 31 jours, sous réserve des besoins du service et de l'avis hiérarchique. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Le temps partiel de droit pour élever un enfant peut être accordé :", "o": ["à 50, 60, 70 ou 80 %, jusqu'au 3e anniversaire de l'enfant", "à 50, 60, 70, 80 ou 90 %, jusqu'au 3e anniversaire", "à 50, 60, 70 ou 80 %, jusqu'au 6e anniversaire", "à 50 ou 80 % uniquement, sous réserve des nécessités de service"], "a": "A", "e": "Le 90 % n'existe que pour le temps partiel sur autorisation. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Exemption pour don du sang : une femme fonctionnaire de police peut effectuer au maximum dans l'année :", "o": ["6 dons de sang total, espacés d'au moins 8 semaines", "4 dons de sang total, espacés d'au moins 8 semaines", "4 dons de sang total, espacés d'au moins 4 semaines", "12 dons de sang total, espacés d'au moins 4 semaines"], "a": "B", "e": "Sang total : 6 (homme) ou 4 (femme), 8 semaines ; plaquettes 12/an, 4 semaines ; plasma 24/an, 2 semaines. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Le stock du CET (compte épargne-temps) après alimentation est de 12 jours. Ces jours :", "o": ["ne sont utilisables que sous forme de congés", "peuvent être indemnisés dès le 1er jour", "peuvent être versés à la RAFP", "doivent être pris avant le 31 décembre"], "a": "A", "e": "CET ≤ 15 jours : utilisation uniquement en congés ; le droit d'option ne s'ouvre qu'à partir du 16e jour. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "Un agent contractuel a atteint la limite des 60 jours sur son CET (compte épargne-temps). Les jours épargnés au-delà :", "o": ["peuvent seulement être indemnisés", "peuvent être indemnisés ou versés à la RAFP", "sont perdus", "peuvent être maintenus jusqu'à 80 jours"], "a": "A", "e": "Plafond atteint : indemnisation ou RAFP (régime de retraite additionnelle de la fonction publique), mais les contractuels n'ont que l'indemnisation. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026))"}, {"t": 6, "s": "En régime hebdomadaire, verser des CA sur le CET (compte épargne-temps) suppose d'avoir pris dans l'année civile au moins :", "o": ["15 jours de CA", "20 jours de CA", "25 jours de CA", "4/5e de la dotation, quel que soit le régime"], "a": "B", "e": "20 jours (CA, HP, CAA, HPA, CAM compris) ; 4/5e de la dotation en cyclique ; 4 fois les obligations hebdomadaires à temps partiel. (Source : Synthèse DocPro « Gestion du temps de travail » (avril 2026) ; Guide des principales règles de gestion du temps de travail (ARTT, CET))"}, {"t": 7, "s": "Après tout usage de l'arme, volontaire ou involontaire, le policier :", "o": ["renseigne sans délai la déclaration individuelle via le TSUA, visée par la hiérarchie", "rédige un rapport dans les 8 jours", "informe uniquement l'OPJ", "ne déclare que les tirs volontaires"], "a": "A", "e": "Déclaration TSUA (traitement relatif au suivi de l'usage des armes) sans délai, visée par la hiérarchie ; le responsable veille à la santé physique et mentale de l'agent (soutien psychologique). (Source : Instruction DGPN n°3/2024 – arme individuelle ou de service)"}, {"t": 7, "s": "Pour pouvoir faire usage de leurs armes au titre de l'article L.435-1 du CSI (code de la sécurité intérieure), les policiers doivent être :", "o": ["dans l'exercice de leurs fonctions et revêtus de leur uniforme ou des insignes extérieurs et apparents de leur qualité", "en service et en uniforme uniquement", "porteurs d'un gilet pare-balles", "sur ordre d'un officier"], "a": "A", "e": "Exercice des fonctions + uniforme ou insignes apparents ; le cadre s'applique hors service lorsque le policier agit dans le cadre de ses fonctions. (Source : Instruction DGPN n°3/2024 – arme individuelle ou de service)"}, {"t": 7, "s": "La formation continue à l'emploi de l'arme individuelle consiste en :", "o": ["trois séances permettant le tir de 90 cartouches minimum par an", "deux séances de 45 cartouches", "quatre séances de 30 cartouches", "trois séances de 60 cartouches"], "a": "A", "e": "Trois séances, 90 cartouches minimum, réparties sur l'année, appréciées sur une année glissante. (Source : Instruction DGPN n°3/2024 – arme individuelle ou de service ; Arrêté TSI du 27/07/2015 art. 5)"}, {"t": 8, "s": "Selon la position du sélecteur, le PM (pistolet-mitrailleur) 9 mm permet généralement le tir :", "o": ["en semi-automatique (coup par coup)", "en rafale contrôlée de quatre ou cinq cartouches", "en rafale libre (répétition automatique)", "uniquement au coup par coup"], "a": "AC", "e": "Rafale contrôlée de deux ou trois cartouches. Le PM permet les trois modes ; le HK G36, lui, est limité au coup par coup et à la rafale de deux coups. (Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm)"}, {"t": 8, "s": "Le PM (pistolet-mitrailleur) 9 mm est destiné :", "o": ["aux missions courantes à caractère sensible ou présentant une certaine dangerosité", "exclusivement aux interventions de 3e niveau", "au maintien de l'ordre", "à la riposte contre des individus porteurs de gilets pare-balles uniquement"], "a": "A", "e": "Il n'exclut pas la primo-intervention pour faire cesser une tuerie de masse si les policiers ne sont pas dotés du HK G36. (Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm)"}, {"t": 8, "s": "Le pistolet mitrailleur 9 mm en dotation dans la police nationale est :", "o": ["une arme individuelle d'épaule en dotation collective, classée en catégorie A2", "une arme de poing en dotation individuelle", "une arme d'épaule de catégorie B", "une arme de force intermédiaire"], "a": "A", "e": "PM (pistolet-mitrailleur) : arme individuelle d'épaule en dotation collective, catégorie A2, tirant la cartouche opérationnelle de police 9 x 19 mm. (Source : Instruction DPN-1.9.2 du 13/03/2017 – pistolets mitrailleurs 9 mm)"}, {"t": 8, "s": "Légitime défense des biens : l'usage de l'arme dans l'intention de tuer l'auteur d'une atteinte à un bien est :", "o": ["strictement prohibé, même dans le temps de l'atteinte", "autorisé si le bien est de grande valeur", "autorisé après deux sommations", "autorisé en cas de crime"], "a": "A", "e": "La légitime défense des biens exclut l'homicide volontaire. (Source : Instruction de mars 2016 – fusil d'assaut HK G36 5,56 mm)"}, {"t": 9, "s": "La GM2L (calibre 56 mm) :", "o": ["produit un double effet lacrymogène et assourdissant, sans éclat vulnérant", "peut être propulsée à une portée maximale de 300 mètres", "est classée au 5° de la catégorie A2", "projette 18 galets en caoutchouc"], "a": "AC", "e": "DPR de 50, 100 et 200 m. Les galets sont propres à la GMD (grenade à main de désencerclement). DPR de 50, 100 et 200 m pour la GM2L. (Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI)"}, {"t": 9, "s": "Les conditions d'habilitation (octroi, maintien, durée) des policiers adjoints et réservistes aux AFI (arme de force intermédiaire) sont :", "o": ["identiques à celles des fonctionnaires actifs", "allégées", "doublées en durée de formation", "fixées par chaque chef de service"], "a": "A", "e": "Conditions identiques à celles des actifs ; prescriptions d'emploi de l'instruction AFI 2017 et de l'instruction PIE (pistolet à impulsions électriques). (Source : Instruction DGPN n°15/2025 – AFI des policiers adjoints et réservistes)"}, {"t": 9, "s": "Un réserviste retraité des corps actifs peut être autorisé à porter un LBD (lanceur de balles de défense) de 40 mm :", "o": ["s'il était titulaire de l'habilitation au jour de son intégration dans la réserve opérationnelle", "dans tous les cas", "jamais", "après un an de réserve"], "a": "A", "e": "Autorisation par le chef de service, sous condition d'habilitation préalable au jour de l'intégration. (Source : Instruction DGPN n°15/2025 – AFI des policiers adjoints et réservistes ; Tableau « Les AFI et instructions spécifiques »)"}, {"t": 9, "s": "En service, le LBD (lanceur de balles de défense) de 40 mm est porté :", "o": ["approvisionné à une cartouche, avec un seul type de munition (CTS ou MDU)", "non approvisionné", "approvisionné, avec panachage CTS/MDU pour s'adapter aux distances", "approvisionné uniquement sur ordre"], "a": "A", "e": "Le panachage des munitions est prohibé ; en véhicule, la sûreté est mise et retirée au débarquement. (Source : Instruction DGPN/DGGN du 2/08/2017 – usage et emploi des AFI)"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) produit, selon le mode utilisé :", "o": ["une sensation de douleur en mode contact", "la perte momentanée du contrôle du système locomoteur en mode tir", "une brûlure cutanée en mode dissuasif", "une perte de connaissance systématique"], "a": "AB", "e": "Mode contact : douleur ; mode tir : perte de contrôle locomoteur pouvant entraîner la chute. (Source : Instruction DPN-1.9.4.1 – emploi du PIE)"}, {"t": 10, "s": "Une sonde du PIE (pistolet à impulsions électriques) atteint malgré tout la personne au cou. Le policier :", "o": ["avise immédiatement les services de secours", "retire lui-même la sonde sur place", "poursuit l'interpellation sans mesure particulière", "déclenche un second cycle"], "a": "A", "e": "Avis immédiat aux secours pour une prise en charge appropriée. (Source : Instruction DPN-1.9.4.1 – emploi du PIE)"}, {"t": 10, "s": "Après déclenchement de l'arc et sans autre intervention du tireur, le PIE (pistolet à impulsions électriques) fonctionne pendant :", "o": ["un cycle continu de cinq secondes, interruptible à tout moment", "un cycle de dix secondes", "trois secondes non interruptibles", "tant que la détente est pressée"], "a": "A", "e": "Cycle de 5 secondes ; l'utilisateur peut l'interrompre par l'interrupteur. (Source : Instruction DPN-1.9.4.1 – emploi du PIE)"}, {"t": 10, "s": "En milieu fermé, la bombe lacrymogène doit être utilisée :", "o": ["par jets brefs d'environ une seconde, en nombre limité, et arrêtés dès la neutralisation", "par jets continus pour saturer le local", "par un unique jet de cinq secondes", "uniquement après évacuation du local"], "a": "A", "e": "Éviter de saturer le local : risques d'effets irréversibles voire mortels liés à l'inhalation de CS. (Source : Instruction DAPN 2004/40 – produits incapacitants en milieu fermé)"}, {"t": 11, "s": "Après deux sommations restées sans effet, hors cadre de réaction, quels moyens peuvent être employés sur ordre ?", "o": ["Les grenades lacrymogènes lancées à la main", "Les GAIL", "La GMD", "Les lanceurs de grenades avec binôme"], "a": "AB", "e": "GMD (grenade à main de désencerclement), grenade à effet sonore et lanceurs n'arrivent qu'après réitération de la 2e sommation. (Source : Les éléments du maintien de l'ordre (fiche) ; Usage des AFI en maintien de l'ordre (tableau))"}, {"t": 11, "s": "Le dispositif judiciaire intégré aux opérations d'ordre public est placé sous la direction :", "o": ["du procureur de la République", "du DSO", "du préfet", "du CFP"], "a": "A", "e": "Il vise à identifier et interpeller les auteurs ; interpellation pendant la manifestation ou différée. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Lanceurs de grenades en maintien de l'ordre : la seconde et dernière sommation, avant leur emploi pour disperser un attroupement :", "o": ["doit être réitérée", "n'est pas nécessaire", "doit être faite par écrit", "doit être faite par le CFP"], "a": "A", "e": "Dispersion sur ordre exprès de l'autorité habilitée, après sommations, la seconde et dernière étant réitérée. (Source : Instruction DGPN/DGGN du 2/08/2017 – AFI)"}, {"t": 11, "s": "La grenade à main à effet sonore GL-304 CONDOR doit être lancée :", "o": ["à la main et au ras du sol, à distance du dispositif policier", "au lanceur, en tir courbe", "à la main, en cloche au-dessus de la foule", "au lanceur, en tir tendu"], "a": "A", "e": "Lancer à la main, au ras du sol, après appréciation de la trajectoire et du point d'explosion. (Source : Télégramme DGPN – grenades à main à effet sonore)"}, {"t": 12, "s": "Selon l'article 803 du CPP (code de procédure pénale), le port des menottes n'est possible que si la personne est considérée :", "o": ["comme dangereuse pour autrui ou pour elle-même", "comme susceptible de tenter de prendre la fuite", "comme auteur d'un crime", "comme refusant de décliner son identité"], "a": "AB", "e": "Mesures utiles aussi pour éviter qu'elle soit photographiée ou filmée. (Source : TDI – Menottage (vs 01-2022) ; Note DGPN 13/09/2004 – utilisation des menottes)"}, {"t": 12, "s": "Triangulation latérale : l'individu se déplace. Pour éviter de rendre inopérants les axes de tir :", "o": ["on le suit dans son sens de déplacement en conservant la configuration", "on bascule en binôme réuni", "on l'immobilise contre un appui", "l'agent arrière passe devant"], "a": "A", "e": "Inconvénients : topographie, axes de tir, éloignement. (Source : TI – Les placements (vs 12-2022))"}, {"t": 12, "s": "Dans le déroulement d'une palpation de sécurité, la première étape consiste à :", "o": ["informer la personne qu'elle va être palpée", "recourir aux moyens techniques de détection", "inviter la personne à remettre volontairement les objets estimés dangereux", "effectuer immédiatement la palpation"], "a": "C", "e": "Remise volontaire, puis moyens de détection, puis information, puis palpation. (Source : Instruction DGPN/DGGN – pratique des palpations de sécurité)"}, {"t": 12, "s": "Selon la fiche PLI, la répartition des rôles Protection / Liaison / Interpellation :", "o": ["doit être effectuée avant tout début d'action", "s'organise une fois l'individu maîtrisé", "est fixée par le CIC", "n'est requise qu'au-delà de trois policiers"], "a": "A", "e": "Le dispositif peut ensuite évoluer selon la situation. (Source : TI – Protection, liaison, interpellation (PLI))"}, {"t": 13, "s": "Agression armée à caractère meurtrier confirmée : les mesures prises par les policiers visent :", "o": ["la prise de renseignements", "la neutralisation du ou des auteurs en cas d'opportunité", "la négociation prioritaire avec l'auteur", "l'attente systématique des unités spécialisées avant toute action"], "a": "AB", "e": "Elles visent aussi la limitation des risques de propagation. Objectif : saisir toute opportunité de faire cesser la tuerie ; aussi l'exfiltration des victimes. (Source : PPI – Agression armée à caractère meurtrier)"}, {"t": 13, "s": "Lors d'une poursuite, le déclenchement de la caméra-piéton ou de tout autre moyen vidéo est :", "o": ["obligatoire", "facultatif", "interdit", "laissé à l'appréciation du CIC"], "a": "A", "e": "Aussi : ceinture systématique, avertisseurs et géolocalisation. (Source : Fiche mémo – refus d'obtempérer et véhicules en fuite)"}, {"t": 13, "s": "Lors de l'interception d'un véhicule en fuite, il faut privilégier :", "o": ["les DIVA lorsqu'ils sont immédiatement disponibles et que la situation le permet", "le tir dans les pneus", "le barrage avec véhicule de police occupé", "le contact par l'arrière"], "a": "A", "e": "DIVA (dispositif d'interception des véhicules automobiles) : dispositifs d'interception de véhicules automobiles. (Source : Instruction commune DGGN-PP-DGPN du 16/05/2025)"}, {"t": 13, "s": "La méthode de raisonnement opérationnel (MRO) s'articule, dans l'ordre, autour de :", "o": ["Analyse de la situation – Cadre juridique – Tactique d'action", "Cadre juridique – Analyse – Tactique", "Analyse – Tactique – Compte rendu", "Renseignement – Protection – Intervention"], "a": "A", "e": "Que se passe-t-il ? Quel cadre légal ? Comment intervenir ? (Source : TI – Conduite à tenir face à un forcené retranché ; PPI – Principes de levée de doute lors d'agressions armées)"}, {"t": 14, "s": "Le maintien de la condition physique opérationnelle relève :", "o": ["de la responsabilité de l'autorité hiérarchique et de la responsabilité individuelle des agents", "du seul chef de service", "du seul agent", "du médecin de prévention"], "a": "A", "e": "Art. 13. (Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel)"}, {"t": 14, "s": "Le retrait de l'arme de service pour état de dangerosité (art. 114-6 RGEPN (règlement général d'emploi de la police nationale)) est décidé par :", "o": ["le chef de service", "le formateur TSI", "le médecin statutaire", "le directeur départemental uniquement"], "a": "A", "e": "Art. 7 de l'arrêté. (Source : Arrêté du 27/07/2015 – formation continue TSI et sport opérationnel)"}, {"t": 4, "s": "Un service compte 13 agents et le taux de présence fixé est de 60 %. Le nombre minimal de présents est de :", "o": ["8", "7", "9", "6"], "a": "A", "e": "13 × 0,6 = 7,8 : la décimale étant supérieure à 0,5, on arrondit à l'entier supérieur. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Les RPS (repos de pénibilité spécifique) ne sont pas applicables :", "o": ["aux membres du CCD", "aux PATS", "aux membres du CC", "aux gardiens de la paix en régime cyclique"], "a": "ABC", "e": "Ni aux contractuels de l'article 10. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un agent en régime hebdomadaire travaille 4 heures un dimanche. Le crédit octroyé est de :", "o": ["1 h 36", "24 minutes", "48 minutes", "2 heures"], "a": "A", "e": "Coefficient de 0,4 le dimanche (4 × 0,4 = 1,6 h). (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Dans le plan de congés, un agent dont la priorité n'a pas été satisfaite en année N :", "o": ["voit sa priorité reportée sur l'année N+1", "perd définitivement sa priorité", "bénéficie de deux priorités en N+1", "doit renouveler sa demande auprès de la DRH"], "a": "A", "e": "Une seule priorité par agent et par année civile. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un agent cyclique part à la retraite le 30 juin. Quelles affirmations sont exactes ?", "o": ["Son crédit férié est proportionnel à son temps de présence", "Ce calcul s'effectue par période de 15 jours", "Il conserve l'intégralité des 109 h 12 de crédit férié", "Son crédit férié est calculé par mois entier"], "a": "AB", "e": "Proratisation par quinzaine. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un agent en régime hebdomadaire travaille 5 heures entre 21 h et 6 h. Le crédit octroyé est de :", "o": ["30 minutes", "50 minutes", "1 heure", "2 heures"], "a": "A", "e": "Coefficient de 0,1 la nuit (5 × 0,1 = 0,5 h). (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "En régime cyclique, le volume horaire annuel du crédit férié est fixé forfaitairement à :", "o": ["109 h 12", "96 h", "112 h", "104 h 48"], "a": "A", "e": "Toutes catégories de cycles confondues. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un agent souhaite partir 35 jours consécutifs en congés annuels en métropole. Sa demande :", "o": ["ne peut être acceptée, l'absence ne pouvant excéder 31 jours consécutifs", "est acceptée s'il a assez de jours", "est acceptée si le plan de congés le permet", "est acceptée à condition de fractionner sur deux mois civils"], "a": "A", "e": "Sauf cumul autorisé pour se rendre dans le pays d'origine. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 5, "s": "Un agent élu municipal souhaite utiliser son crédit d'heures. Il informe sa hiérarchie par écrit au moins :", "o": ["3 jours avant son absence", "48 heures avant son absence", "8 jours avant son absence", "un mois avant son absence"], "a": "A", "e": "En précisant le crédit restant pour le trimestre. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Un agent passe un concours de la fonction publique. Il bénéficie :", "o": ["d'une autorisation d'absence égale à la durée des épreuves et des délais de route, sans incidence ARTT", "d'une journée de congé annuel imputée", "d'une autorisation d'absence d'une journée forfaitaire", "d'aucune autorisation d'absence"], "a": "A", "e": "RGEPN (règlement général d'emploi de la police nationale), annexe II, section 6, art. 37. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "L'incompatibilité entre le mandat de conseiller municipal et le statut des CCD (corps de conception et de direction) ou CC cesse lorsqu'ils ne sont plus en activité dans le ressort depuis plus de :", "o": ["6 mois", "un an", "3 mois", "2 ans"], "a": "A", "e": "Code électoral, article L237. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Pour une ASA (autorisation spéciale d'absence) de l'article 15, le temps de préparation et de compte rendu ajouté est :", "o": ["égal à la durée prévisible de la réunion, entre une demi-journée et 2 journées", "fixé à une journée", "égal au double de la durée de la réunion", "limité à une demi-journée"], "a": "A", "e": "S'ajoutent aussi les délais de route. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Les agents titulaires d'un mandat électif ont droit à un congé de formation non rémunéré de :", "o": ["18 jours", "12 jours", "20 jours", "10 jours"], "a": "A", "e": "Pour tous les types de mandats. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Avant leur prise de fonction, les agents de prévention suivent une formation à la santé et sécurité au travail de :", "o": ["5 jours", "3 jours", "10 jours", "2 jours"], "a": "A", "e": "Puis formation continue. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Concernant le congé de formation syndicale, quelles affirmations sont exactes ?", "o": ["Les délais de route s'ajoutent à sa durée sans imputer le contingent de 12 jours", "À défaut de réponse au plus tard le 15e jour avant le stage, il est réputé accordé", "Un RC tombant pendant le stage est reporté avec compensation majorée", "Il peut être refusé pour un simple motif d'opportunité"], "a": "AB", "e": "Le RC (repos compensateur) est reporté sans compensation majorée. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Une nouvelle naissance intervient pendant un congé parental en cours. L'agent :", "o": ["a droit à un nouveau congé parental, dans les mêmes conditions que le premier", "doit reprendre ses fonctions", "voit son congé en cours prolongé de 6 mois seulement", "ne peut bénéficier que d'un congé de présence parentale"], "a": "A", "e": "Nouveau congé pour le nouvel enfant. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Le congé parental pour un même enfant peut être pris :", "o": ["par l'un des deux parents", "par l'un puis par l'autre", "par les deux parents simultanément", "uniquement par la mère pour la première période"], "a": "ABC", "e": "Souplesse d'utilisation entre les parents. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Concernant le congé de solidarité familiale, quelles affirmations sont exactes ?", "o": ["Il peut être fractionné en périodes d'au moins 7 jours consécutifs, dans la limite de 6 mois cumulés", "Il peut prendre la forme d'un temps partiel", "Il prend fin dans les 3 jours qui suivent le décès de la personne accompagnée", "Il est rémunéré à plein traitement"], "a": "ABC", "e": "Congé non rémunéré, allocation possible. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Une demande de réunion d'information syndicale est adressée au responsable au moins :", "o": ["une semaine avant la date", "48 heures avant la date", "15 jours avant la date", "3 jours avant la date"], "a": "A", "e": "Elle doit émaner d'une organisation syndicale. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Le temps d'absence cumulé (autorisations d'absence et crédit d'heures) d'un élu local ne peut dépasser par année civile :", "o": ["803 h 30", "1 607 heures", "535 heures", "400 heures"], "a": "A", "e": "La moitié de la durée légale annuelle. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Un accident survenu au cours du service de sapeur-pompier volontaire d'un policier est reconnu :", "o": ["comme blessure en service police nationale", "comme accident de la vie privée", "comme accident du travail du SDIS uniquement", "comme congé de maladie ordinaire"], "a": "A", "e": "Loi n°91-1389 du 31/12/1991. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Concernant le congé de proche aidant, quelles affirmations sont exactes ?", "o": ["Il n'est pas rémunéré, une allocation journalière pouvant être versée par la CAF", "Il peut être fractionné par période d'au moins une journée", "La demande est formulée au moins un mois avant son début", "Il est limité à 3 mois sur toute la carrière"], "a": "ABC", "e": "Limite d'un an sur la carrière. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Les facilités de service accordées à un assistant de prévention ne peuvent être inférieures à :", "o": ["20 % du temps de travail", "10 % du temps de travail", "30 % du temps de travail", "50 % du temps de travail"], "a": "A", "e": "50 % pour les conseillers de prévention. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Le nourrisson reste hospitalisé au-delà d'une certaine date après l'accouchement : la mère peut alors reporter le reliquat du congé postnatal à la fin de l'hospitalisation. Cette date est :", "o": ["la 6e semaine", "la 3e semaine", "la 8e semaine", "la 4e semaine"], "a": "A", "e": "Sans incidence sur le congé de paternité. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Concernant le contrôle des arrêts de maladie, quelles affirmations sont exactes ?", "o": ["En l'absence d'horaires fixés, les heures de sortie sont celles du droit commun de la sécurité sociale", "L'absence du domicile hors des heures autorisées expose à des sanctions disciplinaires", "Un certificat médical suffit à lui seul à déroger aux heures de sortie", "Le refus du contrôle médical est sans conséquence sur le traitement"], "a": "AB", "e": "Le refus expose à l'interruption du traitement. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un agent travaille le matin, consulte son médecin et obtient un arrêt de travail daté du même jour. Le jour de carence s'applique :", "o": ["le 1er jour suivant l'absence au travail réellement constatée", "le jour même", "le 2e jour suivant", "pas du tout"], "a": "A", "e": "Règle du jour de carence. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "La réduction de rémunération pour envoi tardif de l'arrêt de travail n'est pas appliquée lorsque :", "o": ["le fonctionnaire est hospitalisé", "il justifie dans les 8 jours de son incapacité à transmettre l'avis dans les délais", "le retard est inférieur à 72 heures", "l'arrêt concerne un CLM"], "a": "AB", "e": "Les CLM (congé de longue maladie), CLD (congé de longue durée) et congés pathologiques sont exclus du dispositif. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un arrêt de travail avec des horaires de sortie libres doit être confirmé par :", "o": ["le médecin de la police nationale", "le médecin traitant", "la CPAM", "le chef de service"], "a": "A", "e": "Circulaire du 21/07/2004. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Les jours placés sur le CET (compte épargne-temps) peuvent être utilisés comme congés :", "o": ["dès le 1er jour épargné, y compris par demi-journée", "seulement au-delà de 15 jours épargnés", "seulement par journées entières", "seulement après accord de la DRH"], "a": "A", "e": "Sans rendre négatif le solde. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "À l'issue de quels congés l'agent bénéficie-t-il de plein droit, s'il le demande, des jours accumulés sur son CET (compte épargne-temps) ?", "o": ["Congé de paternité et d'accueil de l'enfant", "Congé de solidarité familiale", "Congé de proche aidant", "Congé de formation syndicale"], "a": "ABC", "e": "Décret n°2020-287 du 20/03/2020. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "De retour d'un poste à l'étranger avec une dotation de CA supérieure, un agent peut épargner sur son CET (compte épargne-temps) :", "o": ["la totalité des CA restants au-delà des 20 jours réglementaires", "au plus 5 jours de CA", "les seuls jours ARTT", "aucun CA"], "a": "A", "e": "Cas d'un agent ayant exercé à l'étranger. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "En cas d'accident du travail, un apprenti informe son employeur dans un délai de :", "o": ["24 heures", "48 heures", "72 heures", "8 jours"], "a": "A", "e": "Les apprentis relèvent du droit commun. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Le fonctionnaire qui refuse de se présenter au contrôle médical s'expose à :", "o": ["l'interruption de son traitement", "un simple avertissement oral", "une mutation d'office", "aucune conséquence financière"], "a": "A", "e": "Article 25 du décret n°86-442. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un agent en congé de maladie ordinaire demande à suivre une formation. En principe :", "o": ["il ne peut y être autorisé, sauf formation au titre du CPF", "il peut la suivre librement", "il peut la suivre si elle a lieu à distance", "il peut la suivre avec l'accord de son médecin traitant"], "a": "A", "e": "TA Nice, 5/02/2010. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Parmi les seuils de postes des fonctionnaires actifs, le seuil III correspond aux :", "o": ["postes sédentaires", "postes physiques", "postes médians", "postes opérationnels de voie publique"], "a": "A", "e": "Seuil I : physiques ; seuil II : médians. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Une demande de contrôle doit être effectuée pour tout arrêt de maladie ordinaire ou de blessure en service d'une durée égale ou supérieure à :", "o": ["15 jours", "8 jours", "21 jours", "30 jours"], "a": "A", "e": "Contrôle réalisé avant l'expiration de l'arrêt. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Le congé de maladie d'un policier adjoint ne peut être attribué :", "o": ["au-delà de la période d'engagement restant à courir", "au-delà de 3 mois", "pendant la première année d'engagement", "sans avis du comité médical"], "a": "A", "e": "Article 27 du décret n°86-83. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Pour utiliser des jours de CET (compte épargne-temps) en congés, le délai de préavis est :", "o": ["inexistant, sous réserve des nécessités de service", "de 15 jours", "d'un mois", "de 8 jours"], "a": "A", "e": "Règles de gestion fixées localement. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un agent en CMO (congé de maladie ordinaire) est placé rétroactivement en CLM (congé de longue maladie). S'agissant de la retenue du jour de carence :", "o": ["elle lui est remboursée", "elle est maintenue", "elle est doublée", "elle est convertie en jour ARTT"], "a": "A", "e": "Également en cas de CLD (congé de longue durée) ou de blessure en service. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Concernant le jour de carence, quelles affirmations sont exactes ?", "o": ["Il concerne les titulaires, stagiaires, élèves et contractuels", "Les apprentis en sont exclus", "Il peut être compensé par un jour ARTT", "Il ne s'applique pas aux agents à temps partiel"], "a": "AB", "e": "Il ne peut jamais être compensé ; il s'applique au temps partiel. (Source : Guide temps de travail / DocPro)"}, {"t": 7, "s": "Concernant la conservation des armes, quelles affirmations sont exactes ?", "o": ["Le dépôt consiste à remettre l'arme dans un lieu sécurisé sous le contrôle d'un responsable", "Le stockage est la conservation de l'arme par le chef de service lorsque l'agent n'en dispose plus", "Les lieux de dépôt sont des pièces fermées dont l'accès est réservé aux agents armés", "Le dépôt n'est possible que pendant le temps de travail"], "a": "ABC", "e": "Dépôt hors ou pendant le temps de travail. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Une étude de sûreté des locaux de dépôt des armes est conduite par :", "o": ["un référent sûreté police nationale", "le RAM du service", "l'inspecteur santé et sécurité au travail", "le médecin de prévention"], "a": "A", "e": "Les directions d'emploi valident la conformité. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Les protections électroniques des locaux de dépôt des armes doivent assurer une durée d'inviolabilité :", "o": ["supérieure au temps d'intervention des effectifs les plus proches", "d'au moins 15 minutes", "d'au moins une heure", "égale à la durée d'une vacation"], "a": "A", "e": "Vidéoprotection, détection, alarmes reliées au CIC (centre d'information et de commandement). (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Le chef de service constate des carences importantes au tir chez un policier. Il :", "o": ["procède au retrait temporaire de l'arme dans l'attente d'un stage de remise à niveau", "saisit le conseil de discipline", "prononce un blâme", "impose un recyclage TSI sans retirer l'arme"], "a": "A", "e": "Remise à niveau conforme à l'habilitation initiale. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Les lieux de dépôt des armes individuelles doivent comprendre ou être installés à proximité d'une zone de neutralisation comportant au minimum :", "o": ["un puits balistique souple", "un bac à sable", "un tube de manipulation", "une armoire forte"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "Les informations entrées dans TSUA (traitement relatif au suivi de l'usage des armes) :", "o": ["ne préjugent en rien des suites judiciaires et administratives", "valent procès-verbal de constatation", "engagent la responsabilité pénale du déclarant", "sont transmises d'office au parquet"], "a": "A", "e": "Elles peuvent toutefois documenter des enquêtes. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Pour l'ensemble des missions, le PM (pistolet-mitrailleur) 9 mm est porté :", "o": ["chargeur engagé et cartouche chambrée", "culasse fermée, sélecteur sur la sûreté manuelle", "muni de la bretelle en dotation", "chambre vide, chargeur dans la poche"], "a": "ABC", "e": "Avec les protections balistiques en dotation. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Après une première connexion au portail CHEOPS NG, TSUA (traitement relatif au suivi de l'usage des armes) mémorise et propose à l'identique :", "o": ["le matricule et le lieu d'affectation du déclarant", "l'arme et les munitions habituellement utilisées", "l'historique judiciaire des usages", "le nom de l'autorité qui vise"], "a": "A", "e": "Données personnelles du déclarant. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Pour le HK G36, le choix du mode de tir appartient :", "o": ["au porteur de l'arme, selon le degré de dangerosité", "au chef de dispositif", "à l'autorité préfectorale", "au CIC"], "a": "A", "e": "Le tir en rafale doit rester exceptionnel. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "L'affectation temporaire du PM (pistolet-mitrailleur) 9 mm pour une mission est mentionnée :", "o": ["sur le registre ad hoc et, le cas échéant, sur la main courante informatisée", "uniquement sur le livret individuel de formation", "dans TSUA", "sur le carnet de bord du véhicule"], "a": "A", "e": "Instruction PM 9 mm. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 9, "s": "Pour la gendarmerie, la collecte des informations relatives à l'utilisation de la GMD (grenade à main de désencerclement) s'effectue via la procédure :", "o": ["EVENGRAVE", "TSUA", "CHEOPS", "PULSAR"], "a": "A", "e": "La police utilise TSUA (traitement relatif au suivi de l'usage des armes). (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "Dans tous les cadres juridiques, l'emploi de la GM2L (grenade assourdissante et lacrymogène) est subordonné à la présence :", "o": ["d'un binôme constitué d'un superviseur et d'un ou plusieurs lanceurs", "d'un officier de police judiciaire", "de l'autorité civile sur place", "d'un médecin"], "a": "A", "e": "Précautions d'emploi de la GM2L. (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "Les GMD (grenade à main de désencerclement) et leurs bouchons allumeurs sont entreposés :", "o": ["dans des armureries sécurisées ou des armoires fortes en locaux sécurisés", "dans le coffre des véhicules d'intervention", "dans les casiers individuels", "dans le local de garde à vue"], "a": "A", "e": "Points de conservation pris en compte dans le plan de protection. (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "Concernant le LBD (lanceur de balles de défense) de 40 mm, quelles affirmations sont exactes ?", "o": ["Il est approvisionné avec des cartouches pyrotechniques amorcées", "Seules les munitions fournies par l'administration doivent être utilisées", "Il tire un projectile en caoutchouc à effet cinétique", "Il peut être utilisé avec des munitions du commerce homologuées"], "a": "ABC", "e": "Instruction AFI (arme de force intermédiaire). (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "La GM2L (grenade assourdissante et lacrymogène) peut être lancée à la main après :", "o": ["le retrait de la goupille solidarisant la cuillère de sécurité au bouchon allumeur", "l'armement d'un percuteur", "la rotation du bouchon allumeur", "la fixation d'un DPR"], "a": "A", "e": "Ou au moyen d'un lanceur. (Source : Instruction AFI 2/08/2017)"}, {"t": 10, "s": "Le logement de tir du PIE (pistolet à impulsions électriques) en dotation accueille deux cartouches, ce qui permet :", "o": ["le tir d'une deuxième cartouche immédiatement après la première sans recharger", "deux tirs simultanés sur deux cibles", "un cycle de 10 secondes", "le tir d'une cartouche de longue portée seulement"], "a": "A", "e": "Instruction PIE. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Le diffuseur lacrymogène le plus important permet d'atteindre une personne située jusqu'à :", "o": ["4 à 5 mètres", "1 à 2 mètres", "8 à 10 mètres", "15 mètres"], "a": "A", "e": "Note DAPN (direction de l'administration de la police nationale) 2004/40. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Les cartouches du PIE (pistolet à impulsions électriques) T7 comportent :", "o": ["une date d'expiration", "un numéro d'identification (flash-code)", "un angle d'espacement des sondes (3,5° ou 12°)", "une puce de géolocalisation"], "a": "ABC", "e": "Synthèse PIE T7. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "La formation à l'habilitation PIE (pistolet à impulsions électriques) T7 dure :", "o": ["2 jours, ou 1 jour pour les agents à jour de leur habilitation X26", "1 jour pour tous", "3 jours, ou 2 jours pour les agents habilités X26", "une demi-journée"], "a": "A", "e": "Synthèse PIE T7. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Les bombes lacrymogènes en dotation existent essentiellement en :", "o": ["trois formats (petit, moyen, grand)", "un format unique", "deux formats", "cinq formats"], "a": "A", "e": "Note DAPN (direction de l'administration de la police nationale) 2004/40. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 11, "s": "Au titre du contrôle judiciaire, le juge peut prononcer une interdiction de participer à une manifestation sur le fondement de l'article :", "o": ["138 du CPP", "78-2 du CPP", "431-9 du code pénal", "L. 211-4 du CSI"], "a": "A", "e": "SNMO (schéma national du maintien de l'ordre) – dispositif judiciaire. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Des équipes judiciaires de constatation sont intégrées aux dispositifs de maintien de l'ordre afin :", "o": ["de caractériser les infractions et d'identifier les auteurs", "de procéder aux sommations", "de remplacer les OPJ du service", "de filmer les manifestants pacifiques"], "a": "A", "e": "SNMO (schéma national du maintien de l'ordre), point 3.2.3. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Pour procéder à des interpellations ciblées, les forces mobiles peuvent engager :", "o": ["les SPI 4G des CRS", "les pelotons d'intervention des EGM", "les sections de protection du GIGN", "les brigades anticriminalité nationales"], "a": "AB", "e": "SNMO (schéma national du maintien de l'ordre) – mobilité et réactivité. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "En l'absence de risque de trouble à l'ordre public, l'option privilégiée pour préserver l'intégrité des manifestants est :", "o": ["le maintien à distance de la foule", "le contact immédiat", "l'interpellation préventive", "la dispersion"], "a": "A", "e": "SNMO (schéma national du maintien de l'ordre), point 2.5. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Concernant les acteurs du maintien de l'ordre, quelles affirmations sont exactes ?", "o": ["Le DSO assure la direction opérationnelle du service d'ordre", "Le DSO et les CSO conduisent la communication avec les manifestants", "Le commandant de la force publique fixe la stratégie de l'ordre public", "Le CSO est désigné par le préfet"], "a": "AB", "e": "Le préfet fixe la stratégie ; le DSO (directeur du service d'ordre) désigne les CSO (chef de secteur opérationnel). (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "Lors d'une palpation, quelles affirmations sont exactes ?", "o": ["Les policiers avisent la personne de la palpation et de sa finalité", "Le port de gants peut s'imposer pour des raisons de sécurité ou d'hygiène", "Elle s'effectue par glissement des mains", "Les accessoires portés (sac, parapluie) en sont exclus"], "a": "AB", "e": "Pressions successives ; les accessoires sont concernés. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Lors du menottage, la zone du poignet où se pose le bracelet est :", "o": ["la partie la plus fine du bras, entre la main et les têtes du radius et de l'ulna", "le milieu de l'avant-bras", "au-dessus de la tête du radius", "sur le dos de la main"], "a": "A", "e": "Zone corporelle cible après ajustement correct. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Lors d'une palpation, palper prioritairement :", "o": ["le creux lombaire", "la ceinture abdominale", "les aisselles, en fonction de la tenue", "les chevilles"], "a": "ABC", "e": "Puis du haut du corps vers les membres inférieurs. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Selon la fiche PLI, la liaison permet notamment de maintenir le contact des personnels engagés avec :", "o": ["le Centre d'Information et de Commandement (CIC)", "le parquet de permanence", "la presse", "les services de secours uniquement"], "a": "A", "e": "Moyens radio. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Au sol, lors du retournement d'un individu sur le ventre, le poignet non menotté :", "o": ["reste impérativement au ras du sol", "est ramené immédiatement dans le dos", "est relevé à hauteur d'épaule", "est laissé libre"], "a": "A", "e": "TDI menottage. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 13, "s": "Lors d'une perquisition, quelles règles sont exactes ?", "o": ["Tous les occupants sont regroupés et maintenus sous la surveillance d'un policier", "Les occupants et tout nouvel arrivant font l'objet d'une palpation", "En l'absence de l'occupant, deux témoins peuvent être choisis parmi les policiers", "Une saisie incidente n'a pas à être localisée précisément"], "a": "AB", "e": "Témoins autres que les policiers ; emplacement noté. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Face à un objet suspect, il ne faut pas :", "o": ["utiliser d'appareil de radiocommunication à proximité", "jeter de l'eau ou tout autre produit dessus", "laisser une garde ou un véhicule de police à proximité", "collecter des renseignements pour les démineurs"], "a": "ABC", "e": "Les renseignements sont transmis aux démineurs dès leur arrivée. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "La levée de doute sur un objet suspect est mise en œuvre :", "o": ["exclusivement par les services de déminage", "par les primo-intervenants équipés de détecteurs", "par une équipe cynotechnique privée", "par l'exploitant des lieux"], "a": "A", "e": "Les autres moyens ne sont que des outils de détection. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Face à une personne soupçonnée de porter une arme d'épaule, les policiers :", "o": ["gardent l'individu à distance et à vue, en le tenant en joue", "lui font jeter son arme et s'agenouiller à distance, bras écartés", "invitent les personnes présentes à quitter la zone immédiatement", "s'approchent pour le palper sans délai"], "a": "ABC", "e": "Annexe DPN-3.1.3 D. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Face au porteur d'un EEI (engin explosif improvisé), pour limiter les effets de fragmentation, les policiers lui font prendre la position :", "o": ["allongé au sol, face contre terre, mains écartées", "debout, mains sur la tête", "assis dos à un mur", "à genoux, mains dans le dos"], "a": "A", "e": "Face avant contre le sol. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 14, "s": "L'autorité hiérarchique est responsable de la mise en place du suivi des actions de formation continue, qui vise à s'assurer que les policiers sont :", "o": ["aptes au port et à l'emploi des armes individuelles dont ils disposent", "à jour de leurs congés", "titulaires du permis de conduire", "habilités au maintien de l'ordre"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024)"}, {"t": 14, "s": "La direction chargée d'élaborer les contenus pédagogiques et le mode d'évaluation de la formation au PM (pistolet-mitrailleur) 9 mm est :", "o": ["la DCRFPN", "la DGSI", "l'IGPN", "le SGAMI"], "a": "A", "e": "Instruction PM 9 mm. (Source : Instruction PM 9 mm)"}, {"t": 14, "s": "L'organisation de la formation continue au tir s'effectue en lien avec :", "o": ["l'administration de rattachement et le service territorial de l'académie de police", "la fédération française de tir", "le SGAMI seul", "le médecin de prévention"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024)"}, {"t": 14, "s": "Concernant l'habilitation au PM (pistolet-mitrailleur) 9 mm, quelles affirmations sont exactes ?", "o": ["Les recyclages ne peuvent être séparés de plus de 12 mois", "Faute de recyclage à échéance, l'habilitation est suspendue", "Un agent dont l'habilitation est caduque peut percevoir l'arme sous contrôle", "Le recyclage ne porte que sur le volet technique"], "a": "AB", "e": "Volets technique et juridique. (Source : Instruction PM 9 mm)"}, {"t": 14, "s": "Une habilitation individuelle préalable sanctionne la parfaite maîtrise, sur les plans technique et juridique :", "o": ["du LBD de 40 mm", "de la GMD", "du lanceur de grenades", "du bâton de défense en dotation de chaque agent"], "a": "ABC", "e": "Instruction AFI (arme de force intermédiaire). (Source : Instruction AFI 2/08/2017)"}, {"t": 4, "s": "Pour un agent présent une partie de l'année seulement (sortie d'école, retraite), le crédit férié est proportionnel au temps de présence, calculé par période de :", "o": ["15 jours", "un mois", "une semaine", "30 jours"], "a": "A", "e": "Proratisation par quinzaine. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un agent passe d'un régime cyclique à un régime hebdomadaire. S'agissant de ses RPS (repos de pénibilité spécifique) :", "o": ["il peut utiliser le prorata de son crédit RPS non pris", "il perd l'intégralité de son crédit RPS", "son crédit RPS est doublé", "son crédit RPS est versé d'office au CET"], "a": "A", "e": "Remarque de gestion RPS. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 5, "s": "Est un parent au 2e degré :", "o": ["le grand-père", "l'oncle", "le cousin germain", "le neveu"], "a": "A", "e": "2e degré : frère, sœur, grands-parents, petits-enfants, beau-frère, belle-sœur. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Concernant les autorisations d'absence pour motif familial, quelles affirmations sont exactes ?", "o": ["Les agents liés par un PACS en bénéficient", "Le décès d'un enfant de moins de 25 ans ouvre droit à 12 jours ouvrables", "Elles peuvent être reportées si l'agent était en congé de maladie", "Le beau-frère est un parent au 1er degré"], "a": "AB", "e": "Beau-frère : 2e degré. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un policier adjoint en arrêt pour maladie ordinaire transmet dans les 48 h :", "o": ["les volets 1 et 2 à sa caisse de sécurité sociale et le volet 3 à son service", "les trois volets à son service", "les volets 1 et 2 à son service et le volet 3 à la caisse", "le seul volet 3 au SGAMI"], "a": "A", "e": "Dispositions propres aux PA (policiers adjoints). (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "La retraite progressive, qui permet de percevoir une fraction de la pension tout en travaillant à temps partiel, est ouverte à compter de :", "o": ["60 ans", "62 ans", "55 ans", "57 ans"], "a": "A", "e": "Dispositif de retraite progressive. (Source : Guide temps de travail / DocPro)"}, {"t": 1, "s": "Une journée de travail est dite continue lorsqu'elle n'est pas divisée en deux parties quasi égales entre matin et après-midi, à un écart maximal de :", "o": ["plus ou moins une heure", "plus ou moins 30 minutes", "plus ou moins deux heures", "plus ou moins 15 minutes"], "a": "A", "e": "Définition de la journée continue (APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale)). (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "Après une permanence de week-end (+24 h HS (heures supplémentaires) en CEA (corps d'encadrement et d'application)), l'agent peut récupérer les 35 h de repos hebdomadaire manqué en utilisant le lundi :", "o": ["8 h d'HS issues du crédit de la permanence", "11 h d'HS issues du crédit de la permanence", "24 h d'HS issues du crédit de la permanence", "une journée ARTT"], "a": "A", "e": "Ou restitution au cours du week-end suivant. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "S'agissant des repos journaliers manqués, les CCD (corps de conception et de direction) et CC de l'article 10 :", "o": ["ne sont pas concernés par la restitution mais font l'objet d'un suivi par leur supérieur", "bénéficient d'une restitution au coefficient 0,15", "sont neutralisés au plus tard après 12 jours", "sont compensés en heures supplémentaires"], "a": "A", "e": "Suivi hiérarchique de leur santé et sécurité. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Les volumes horaires des régimes hebdomadaires à temps plein peuvent être fixés à :", "o": ["40 h 30", "39 h 25", "38 h", "37 h 30"], "a": "ABC", "e": "Ainsi que 39 h. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Le dossier de demande de télétravail (demande, justificatifs, lettre de mission) est transmis pour décision :", "o": ["au N+2", "au N+1", "à la DRH zonale", "au SGAMI"], "a": "A", "e": "Circuit de la demande de télétravail. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 3, "s": "Concernant les compteurs d'heures supplémentaires, quelles affirmations sont exactes ?", "o": ["Le compteur HSE comptabilise les HS issues d'une astreinte ayant vocation à être indemnisées", "L'agent ne peut pas poser directement les heures du compteur HSE", "Le compteur « HS actif » n'est plus approvisionné depuis 2020", "Le compteur « HS historique » est alimenté par les HS générées depuis 2020"], "a": "AB", "e": "C'est le compte historique qui n'est plus approvisionné. (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "En principe, les heures supplémentaires doivent être prises :", "o": ["dans l'année au titre de laquelle elles ont été générées", "dans les 3 ans", "avant le 30 avril de l'année suivante", "sans limite de délai"], "a": "A", "e": "Article 56 de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale). (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "Pour les CCD (corps de conception et de direction) et CC de l'article 10, la permanence :", "o": ["ne donne lieu à aucun crédit d'HS mais à un décalage de leurs repos", "est compensée temps pour temps", "est indemnisée forfaitairement", "n'ouvre droit à aucun décalage"], "a": "A", "e": "Article 79 de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale). (Source : Guide temps de travail / DocPro)"}, {"t": 7, "s": "En cas de négligence avérée d'un agent dans la conservation de son arme, sa responsabilité disciplinaire peut être engagée sur le fondement de l'article :", "o": ["R. 434-5 du CSI", "R. 434-18 du CSI", "L. 435-1 du CSI", "R. 411-3-1 du CSI"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Une arme placée en stockage par le chef de service peut être récupérée par son détenteur :", "o": ["sur autorisation du chef de service, sous le contrôle du RAM, du gradé ou du faisant fonction", "sur simple demande auprès du chef de poste", "après avis du médecin de prévention seulement", "jamais : elle est reversée d'office au SGAMI"], "a": "A", "e": "Elle peut aussi être reversée à l'armurerie du SGAMI (secrétariat général pour l'administration du ministère de l'intérieur). (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "Le TSUA (traitement relatif au suivi de l'usage des armes) a une double finalité :", "o": ["opérationnelle et administrative", "judiciaire et disciplinaire", "statistique et pénale", "opérationnelle et pénale"], "a": "A", "e": "Instruction TSUA. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Concernant les profils d'accès à TSUA (traitement relatif au suivi de l'usage des armes), quelles affirmations sont exactes ?", "o": ["Un profil en consultation permet la seule lecture des comptes rendus", "Un profil administrateur, accordé sous l'autorité du DGPN, autorise un accès illimité", "Tout agent dispose par défaut du profil administrateur", "Le profil consultation permet de modifier les déclarations"], "a": "AB", "e": "Le profil consultation est destiné aux services d'appui et de soutien. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 9, "s": "Le principal risque spécifique lié à l'emploi de la GM2L (grenade assourdissante et lacrymogène) justifiant des précautions particulières est :", "o": ["l'inflammation de la charge déflagrante qu'elle contient", "la projection d'éclats métalliques", "l'effet de souffle à 50 m", "l'intoxication au monoxyde de carbone"], "a": "A", "e": "Instruction AFI (arme de force intermédiaire). (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "Après l'usage d'une GMD (grenade à main de désencerclement) suivi d'une interpellation, il convient dès que possible :", "o": ["de s'assurer de l'état de santé de la personne et de la garder sous surveillance", "de procéder à une palpation puis de la relâcher", "de photographier les blessures avant tout soin", "de la transporter immédiatement à l'hôpital sans autre formalité"], "a": "A", "e": "Conduite à tenir après emploi. (Source : Instruction AFI 2/08/2017)"}, {"t": 10, "s": "L'usage d'un aérosol lacrymogène pour réduire une résistance manifeste à une intervention légale permet notamment :", "o": ["d'éviter l'utilisation de l'armement ou d'autres moyens de neutralisation", "de se dispenser de toute justification", "de remplacer la palpation", "de procéder sans sommation à une dispersion"], "a": "A", "e": "Article 122-4 du code pénal. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Concernant la gestion de la batterie du PIE (pistolet à impulsions électriques) T7, quelles affirmations sont exactes ?", "o": ["La charge s'effectue sur une baie de chargement connectée à internet", "Le voyant jaune indique que la batterie est en charge", "Le voyant vert indique une batterie chargée à 50 %", "Le PIE peut être employé avec une batterie à 20 %"], "a": "AB", "e": "Vert = 100 % ; ne pas employer sous 30 %. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 11, "s": "Le DSO (directeur du service d'ordre) est généralement :", "o": ["le chef territorial de la police ou de la gendarmerie", "le préfet de département", "le commandant de la force publique", "le maire de la commune"], "a": "A", "e": "Ou le DOPC à la préfecture de police. (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Les sommations marquent :", "o": ["un changement de cadre juridique de la manifestation", "une évolution dans la gestion de l'ordre public", "une simple information sans effet juridique", "la fin de la présence des journalistes"], "a": "AB", "e": "SNMO (schéma national du maintien de l'ordre), point 2.6.2. (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "Une personne menottée doit être palpée :", "o": ["dès que possible et en tout état de cause avant le retrait des entraves", "uniquement à son arrivée au service", "seulement si elle est placée en garde à vue", "jamais une fois menottée"], "a": "A", "e": "TDI palpation. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Une personne a été menottée au sol, allongée sur le ventre. Juste après la pose des entraves, le policier palpe :", "o": ["la zone lombaire et la ceinture dorsale", "les chevilles", "les poches de poitrine", "les cheveux et le col"], "a": "A", "e": "Puis la personne est placée sur le flanc. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 13, "s": "Selon le glossaire « Attentats », « boucler » une zone consiste à :", "o": ["l'isoler par un dispositif continu le long d'une ligne définie, pour interdire ou signaler tout franchissement", "rechercher du renseignement sur l'adversaire sans engager le contact", "figer des individus par une intervention dosée", "se repositionner en sécurité sur une position arrière"], "a": "A", "e": "« Éclairer », « fixer » et « se replier » sont les autres définitions. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Selon l'instruction DPN-3.1.3, un objet abandonné devient suspect lorsque :", "o": ["les premières recherches ne permettent pas d'en identifier le légitime propriétaire", "il est laissé sans surveillance plus de 5 minutes", "il est signalé par un tiers", "il se trouve dans une gare"], "a": "A", "e": "Recherches par l'exploitant ou les primo-intervenants. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Selon le glossaire « Attentats », l'expression « primo-arrivant » est écartée au profit de « primo-intervenant » car :", "o": ["elle introduit un doute sur la nature de la tâche", "elle désigne les unités de 3e niveau", "elle est réservée aux services de secours", "elle désigne la hiérarchie"], "a": "A", "e": "Le primo-intervenant est le premier effectif présent. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 14, "s": "Une séance type de formation TSI (techniques et sécurité en intervention) comprend notamment :", "o": ["des exercices de simulation développant des stratégies individuelles et collectives", "un rappel des cadres légaux et déontologiques", "un tir avec l'arme individuelle", "un test d'aptitude physique noté"], "a": "ABC", "e": "Article 5 de l'arrêté. (Source : Arrêté TSI 27/07/2015 et instructions d'habilitation)"}, {"t": 4, "s": "Les ARTT (aménagement et réduction du temps de travail) sont une avance sur congés compensant notamment un volume annuel de travail supérieur à :", "o": ["1 607 heures", "1 600 heures", "1 594 heures", "1 820 heures"], "a": "A", "e": "Ou la pénibilité du travail en cycle. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Concernant le calcul du taux de présence, quelles affirmations sont exactes ?", "o": ["Les policiers adjoints n'entrent pas dans le calcul du taux de présence des agents du CEA", "Les absences pour droit syndical ou formation sont comptées parmi les présents", "Les congés de maladie sont exclus du calcul des absences", "Hors plan prévisionnel, le taux peut descendre à 40 %"], "a": "AB", "e": "Calcul « toutes causes d'absence confondues », plancher de 50 %. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 5, "s": "Un parent bénéficie d'un congé parental à la suite de la naissance de triplés. Ce congé peut être prolongé :", "o": ["5 fois, jusqu'au 6e anniversaire des enfants au plus tard", "3 fois, jusqu'au 3e anniversaire au plus tard", "5 fois, jusqu'au 4e anniversaire au plus tard", "2 fois, jusqu'au 6e anniversaire au plus tard"], "a": "A", "e": "Naissances d'au moins 3 enfants. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Les autorisations d'absence pour événements familiaux :", "o": ["sont des mesures de bienveillance facultatives", "ne peuvent pas être reportées à une autre date", "ne peuvent pas être accordées pendant un congé de maladie", "sont dues de droit dès la survenue de l'événement"], "a": "ABC", "e": "Instruction FP n°7 du 23/03/1950. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Pour une maladie professionnelle, la déclaration doit intervenir au plus tard :", "o": ["2 ans après la première constatation médicale", "1 an après la première constatation médicale", "5 ans après la première constatation médicale", "6 mois après la première constatation médicale"], "a": "A", "e": "Délais de déclaration du CITIS (congé pour invalidité temporaire imputable au service). (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Faute de choix exprimé avant le 31 janvier, les jours épargnés au-delà de 15 sur le CET (compte épargne-temps) sont :", "o": ["pris en compte au sein de la RAFP pour les titulaires", "indemnisés pour les contractuels", "maintenus sur le CET pour tous", "perdus"], "a": "AB", "e": "Option par défaut selon le statut. (Source : Guide temps de travail / DocPro)"}, {"t": 1, "s": "Concernant la formation et le temps de travail des agents de nuit, quelles affirmations sont exactes ?", "o": ["Un stage nocturne de 6 h ou plus donne lieu à la saisie forfaitaire du code STG", "Après une formation le matin terminée avant 13 h, l'agent reprend la nuit après 8 h de repos", "Un stage nocturne de 6 h ou plus est compensé en heures supplémentaires", "L'agent de nuit en formation le matin est exempté de la nuit suivante"], "a": "AB", "e": "Mesures protectrices des travailleurs de nuit. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "Pour un agent de nuit, un stage nocturne d'une durée égale ou supérieure à 6 h :", "o": ["donne lieu à la saisie forfaitaire du code STG pour toute la vacation", "est décompté au prorata des heures de stage", "est compensé en heures supplémentaires", "n'est pas pris en compte dans le temps de travail"], "a": "A", "e": "Saisie forfaitaire STG. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "Peuvent déroger aux garanties minimales de repos :", "o": ["les membres du corps de conception et de direction (art. 10)", "les membres du corps de commandement chefs de service (art. 10)", "les gradés et gardiens en régime cyclique", "les personnels administratifs à horaires variables"], "a": "AB", "e": "Dérogations réservées aux CCD (corps de conception et de direction) et CC chefs de service relevant de l'article 10. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "La visite d'une délégation de la FS-SSCT sur le lieu de télétravail suppose un délai de prévenance de l'agent d'au moins :", "o": ["10 jours", "5 jours", "15 jours", "8 jours"], "a": "A", "e": "Information écrite de l'agent. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Lors d'une prise de service décalée, un agent effectue 2 heures sur un repos légal (RL). Il est crédité de :", "o": ["1 h 12", "30 minutes", "2 heures", "aucune compensation"], "a": "A", "e": "Coefficient 0,60 sur RL ou JF (2 × 0,60 = 1,2 h). (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 3, "s": "Un jour de semaine, un agent travaille 8 h. L'astreinte de jour (6 h – 21 h) peut couvrir :", "o": ["les 7 h restantes de la période", "15 heures", "16 heures", "8 heures"], "a": "A", "e": "L'astreinte ne couvre que les périodes non couvertes par un travail programmé. (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "La permanence assure une présence effective au service :", "o": ["lors des repos compensateurs", "lors des jours fériés", "la nuit, entre 21 h et 6 h", "pendant la pause méridienne"], "a": "ABC", "e": "Ainsi que lors des repos légaux. (Source : Guide temps de travail / DocPro)"}, {"t": 7, "s": "Concernant l'armurerie d'un service, quelles affirmations sont exactes ?", "o": ["Elle relève de la compétence du RAM, sous la responsabilité du chef de service", "Les agents n'y accèdent qu'en présence du RAM ou d'un représentant désigné", "Le RAM dispose d'un inventaire à jour des matériels stockés et affectés", "Tout agent armé peut y accéder librement avec sa carte agent"], "a": "ABC", "e": "Accès strictement contrôlé. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Le policier est responsable de son arme administrative en tous temps et tous lieux, dès lors qu'elle :", "o": ["n'a pas été entreposée à l'armurerie ou dans un lieu sécurisé du service", "est rangée à son domicile", "est hors de son étui", "n'est pas approvisionnée"], "a": "A", "e": "Responsabilité permanente. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Il est interdit à tout fonctionnaire de police de porter en service un armement et des munitions différents de ceux dont il est doté par l'administration, selon l'article :", "o": ["114-7 du RGEPN", "113-45 du RGEPN", "R. 434-16 du CSI", "122-4 du code pénal"], "a": "A", "e": "Rappelé par l'instruction AFI (arme de force intermédiaire). (Source : Instruction AFI 2/08/2017)"}, {"t": 8, "s": "Pour l'emploi du HK G36, les policiers s'équipent obligatoirement :", "o": ["du gilet porte-plaques", "du casque balistique", "du bouclier balistique souple", "de la cagoule ignifugée"], "a": "A", "e": "Et, selon la situation, des autres protections en dotation. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Concernant TSUA (traitement relatif au suivi de l'usage des armes), quelles affirmations sont exactes ?", "o": ["Un usage de l'arme hors service doit être déclaré s'il existe un lien avec le service", "Le rapport intégré au compte rendu peut constituer l'unique formalité déclarative exigée", "Les usages lors de séances d'entraînement doivent être enregistrés", "Il permet de déclarer l'usage collectif d'une unité entière"], "a": "AB", "e": "Formation et usage collectif exclus. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 9, "s": "Est cité comme exemple légitime de recours au LBD (lanceur de balles de défense) de 40 mm :", "o": ["une personne suicidaire menaçant d'attenter à sa vie avec une arme", "un individu refusant de présenter ses papiers", "un automobiliste en fuite sans danger pour autrui", "un manifestant pacifique refusant de se disperser"], "a": "A", "e": "Légitime défense d'autrui (la personne elle-même). (Source : Instruction AFI 2/08/2017)"}, {"t": 10, "s": "L'irritation oculaire provoquée par les aérosols lacrymogènes dure environ :", "o": ["5 à 10 minutes", "1 à 2 minutes", "30 à 45 minutes", "plusieurs heures"], "a": "A", "e": "Douleur, larmoiement, fermeture des yeux. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Le PIE (pistolet à impulsions électriques) peut être utilisé sur le fondement de l'article 122-4 du code pénal, c'est-à-dire :", "o": ["sur ordre ou autorisation de la loi", "au titre de la légitime défense", "au titre de l'état de nécessité", "au titre de la contrainte"], "a": "A", "e": "Instruction PIE. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "L'écran de contrôle du PIE (pistolet à impulsions électriques) T7 affiche notamment :", "o": ["la présence des cartouches", "le niveau de charge de la batterie", "la durée du cycle lors d'un tir", "la distance de la cible"], "a": "ABC", "e": "Synthèse PIE T7. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 11, "s": "Les chefs de secteur opérationnel (CSO (chef de secteur opérationnel)) :", "o": ["sont désignés par le DSO", "disposent d'une marge d'initiative tactique et opérative", "sont habilités à procéder aux sommations", "sont désignés par le maire"], "a": "ABC", "e": "Article R. 211-11 du CSI (code de la sécurité intérieure). (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Peuvent être intégrées au dispositif du service d'ordre pour disposer d'une capacité d'extinction des feux :", "o": ["des équipes des services d'incendie et de secours", "des unités de la sécurité civile militaire uniquement", "des sociétés privées", "des agents de police municipale"], "a": "A", "e": "SNMO (schéma national du maintien de l'ordre), point 2.4.7. (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "Concernant le menottage, quelles affirmations sont exactes ?", "o": ["Tout menottage s'inscrit dans une action collective", "Les policiers s'assurent que les mains de la personne sont vides avant d'aller au contact", "La pose doit être lente pour rassurer la personne", "Il peut être systématique pour toute interpellation"], "a": "AB", "e": "Discret, rapide et ferme ; jamais systématique. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Pour relever ou faire asseoir un individu menotté, il est déconseillé :", "o": ["de saisir ou d'agir sur les menottes", "de contrôler la nuque", "de le faire passer par la position à genou", "de reconstituer le binôme contact"], "a": "A", "e": "Risque de douleurs ou blessures inutiles. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 13, "s": "Face à un véhicule suspect, les policiers :", "o": ["ne tentent pas d'ouvrir une portière ou le coffre", "vérifient s'il s'agit d'un véhicule volé ou abandonné (fichiers)", "ouvrent le coffre pour vérifier son contenu", "déplacent le véhicule hors de la zone"], "a": "AB", "e": "Annexe DPN-3.1.3 B. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Le bon état de fonctionnement et l'intégrité des DIVA (dispositif d'interception des véhicules automobiles) sont vérifiés au minimum :", "o": ["une fois par semestre", "une fois par mois", "une fois par an", "après chaque vacation"], "a": "A", "e": "Fiche d'inspection à renseigner. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Après l'emploi d'un DIVA (dispositif d'interception des véhicules automobiles), les pointes qui se seraient détachées :", "o": ["doivent être ramassées avant le rétablissement de la circulation", "peuvent rester sur la chaussée", "sont ramassées par les services de voirie le lendemain", "sont signalées au parquet"], "a": "A", "e": "Instruction DIVA. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 14, "s": "Un policier non recyclé au HK G36 doit utiliser l'arme d'un collègue habilité touché, en situation d'absolue nécessité :", "o": ["il peut l'utiliser, son usage étant subordonné aux seules règles juridiques", "il ne peut en aucun cas l'utiliser", "il doit d'abord obtenir l'accord du CIC", "il commet une faute disciplinaire"], "a": "A", "e": "Distinction entre droit de percevoir et droit d'utiliser. (Source : Instruction HK G36)"}, {"t": 4, "s": "Un agent PATS (personnels administratifs, techniques et scientifiques) entre en école de gardien de la paix :", "o": ["il doit avoir épuisé ses jours de repos avant son départ, sinon ils sont perdus", "ses jours de repos sont reportés sur son compteur d'élève", "ses jours de repos sont versés d'office sur son CET", "ses jours de repos sont indemnisés"], "a": "A", "e": "Ses compteurs sont gelés pendant la scolarité. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Concernant la proratisation et les droits ARTT (aménagement et réduction du temps de travail), quelles affirmations sont exactes ?", "o": ["Les droits ARTT sont proratisés à hauteur de la quotité de travail", "Un agent suspendu acquiert ses droits au prorata du service accompli", "La quotité de temps partiel s'applique au seuil plancher de 15 jours du CET", "La quotité de temps partiel s'applique au plafond de 60 jours du CET"], "a": "AB", "e": "Seuil plancher et plafond du CET (compte épargne-temps) sont conservés. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 5, "s": "L'examen médical postnatal obligatoire doit être effectué dans les :", "o": ["8 semaines qui suivent l'accouchement", "4 semaines qui suivent l'accouchement", "12 semaines qui suivent l'accouchement", "6 semaines qui suivent l'accouchement"], "a": "A", "e": "Le 1er examen prénatal a lieu avant la fin du 3e mois. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Pour un congé de réserve opérationnelle compris entre le 11e et le 30e jour ouvré de l'année, quelles affirmations sont exactes ?", "o": ["L'accord de la hiérarchie est nécessaire", "Le préavis est d'un mois", "Le congé est accordé de droit", "Un refus n'a pas à être motivé"], "a": "AB", "e": "Un refus est motivé et notifié dans les 15 jours. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Peut bénéficier d'un don de jours de repos l'agent qui :", "o": ["assume la charge d'un enfant de moins de 20 ans gravement malade", "est parent d'un enfant décédé avant 25 ans", "vient en aide à un proche en perte d'autonomie", "souhaite prolonger un congé annuel"], "a": "ABC", "e": "Décrets 2015-580 et 2015-573. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Un CET (compte épargne-temps) dit « historique » concerne les jours épargnés :", "o": ["avant 2009", "avant 2002", "avant 2015", "avant 2020"], "a": "A", "e": "Code GesTT C08. (Source : Guide temps de travail / DocPro)"}, {"t": 1, "s": "Un agent est convoqué à une mission programmée dans la journée qui précède sa 1re nuit de cycle. Cette mission constitue :", "o": ["un rappel au service, l'agent étant sur son RL", "un dépassement horaire", "une permanence", "une prise de service décalée"], "a": "A", "e": "Application de l'article 53 de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale). (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "Un dépassement empêche un agent CEA (corps d'encadrement et d'application) de bénéficier de son repos journalier de 11 h. Quelles affirmations sont exactes ?", "o": ["Un départ avancé de 2 h peut lui être accordé, avec l'accord du chef de service", "Les 2 h de départ avancé sont posées parmi les heures créditées au titre du dépassement", "Le départ avancé s'ajoute aux heures créditées sans les diminuer", "Les 2 h manquées ne peuvent être restituées qu'au repos hebdomadaire"], "a": "AB", "e": "Autre option : lissage des 2 h sur le repos journalier suivant. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "Les compteurs « RJM » et « RHM » permettent :", "o": ["de suivre au N+1 le volume des repos manqués pour fixer la durée de neutralisation", "de comptabiliser les heures supplémentaires à indemniser", "de suivre les jours ARTT non pris", "de comptabiliser les astreintes de nuit"], "a": "A", "e": "RJM = repos journalier manqué ; RHM = repos hebdomadaire manqué. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Un agent bénéficiant d'un aménagement de service thérapeutique préconisé par la médecine de prévention ne peut pas travailler :", "o": ["en régime hebdomadaire à horaires variables", "en régime hebdomadaire à horaires fixes", "en cycle de jour", "à temps partiel"], "a": "A", "e": "Note DGPN (direction générale de la police nationale) du 20/04/2017. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Sont exclus de l'abondement issu de la journée de solidarité en RCSS (repos compensateur pour services supplémentaires) :", "o": ["les régimes cycliques binaires à 12 h 08 et 11 h 08", "la vacation forte", "le cycle 4/2", "le régime hebdomadaire à 39 h"], "a": "AB", "e": "Ainsi que les agents de l'article 10. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 3, "s": "Concernant la permanence, quelles affirmations sont exactes ?", "o": ["Un agent à temps partiel peut y être soumis", "Elle peut être assurée en tout lieu de travail déterminé par les nécessités du service", "Elle ouvre aux CCD et CC de l'article 10 un crédit d'heures supplémentaires", "Elle ne peut jamais être programmée un jour férié"], "a": "AB", "e": "Art. 10 : décalage de repos sans crédit d'HS (heures supplémentaires). (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "Pour les gardiens et gradés, le principe général de compensation des services supplémentaires est :", "o": ["la compensation temps pour temps", "l'indemnisation systématique", "la compensation à 150 %", "la compensation à 125 %"], "a": "A", "e": "DocPro – services supplémentaires. (Source : Guide temps de travail / DocPro)"}, {"t": 7, "s": "Un service peu nombreux ne dispose pas d'armurerie. L'armement peut alors être stocké :", "o": ["dans une armoire forte dont l'accès est strictement contrôlé", "dans les casiers individuels des agents", "dans le bureau du chef de service fermé à clé", "au domicile du RAM"], "a": "A", "e": "Exception prévue par l'instruction. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Les armes individuelles peuvent, sous conditions, être stockées dans les locaux sécurisés d'un service partenaire armé, par exemple :", "o": ["la SUGE", "la police municipale", "une société de sécurité privée", "une mairie"], "a": "AB", "e": "Services dont les agents sont dotés d'une arme pour leurs missions. (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "La décision de porter le fusil d'assaut HK G36 est prise :", "o": ["par la hiérarchie, selon des critères de contexte et de mission", "par le porteur de l'arme", "par le préfet", "par le chef de bord"], "a": "A", "e": "Contexte exceptionnel ou nature de la mission. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Le PM (pistolet-mitrailleur) 9 mm se différencie des fusils d'assaut notamment par :", "o": ["ses munitions généralement utilisées dans les armes de poing, d'où une portée pratique plus courte", "sa classification en catégorie B", "l'absence de mode rafale", "son emploi réservé aux unités d'intervention spécialisée"], "a": "A", "e": "Instruction PM 9 mm. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 9, "s": "Le SNMO (schéma national du maintien de l'ordre) prévoit le retrait des anciens modèles de GMD (grenade à main de désencerclement) et leur remplacement par un modèle moins vulnérant à compter de :", "o": ["septembre 2020", "janvier 2022", "mars 2019", "décembre 2021"], "a": "A", "e": "Nouveau modèle issu du marché de 2019. (Source : SNMO (déc. 2021))"}, {"t": 9, "s": "L'article R. 211-13 du CSI (code de la sécurité intérieure) prévoit qu'en maintien de l'ordre l'emploi de la force :", "o": ["n'est possible que si les circonstances le rendent absolument nécessaire", "est possible dès la première sommation", "est laissé à l'appréciation de chaque policier", "est réservé aux unités de forces mobiles"], "a": "A", "e": "Emploi proportionné de la force. (Source : Instruction AFI 2/08/2017)"}, {"t": 10, "s": "Selon la société AXON, la mémoire interne du T7 permet de sauvegarder :", "o": ["plus de 100 000 événements", "plus de 10 000 événements", "plus de 1 million d'événements", "environ 5 000 événements"], "a": "A", "e": "Mémoire de 8 Mo. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Selon l'instruction PIE (pistolet à impulsions électriques), la cartouche dite de courte portée est efficace :", "o": ["à partir de 1,20 m jusqu'à plus de 3 m", "à partir de 3,50 m jusqu'à plus de 7 m", "à partir de 0,50 m jusqu'à 2 m", "à partir de 2 m jusqu'à 5 m"], "a": "A", "e": "La longue portée : de 3,50 m à plus de 7 m. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 11, "s": "La publication de fichiers recensant des policiers ou des gendarmes constitue :", "o": ["une infraction pénale", "une simple faute civile", "une contravention de 1re classe", "un fait non répréhensible"], "a": "A", "e": "Rappel du SNMO (schéma national du maintien de l'ordre). (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Concernant les journalistes en manifestation, quelles affirmations sont exactes ?", "o": ["Ils peuvent présenter leur carte d'identité de journaliste professionnel", "Un document ad hoc est prévu pour les cas où les autres moyens ne sont pas possibles", "Ils doivent obligatoirement porter un brassard fourni par la préfecture", "Ils doivent se faire accréditer auprès du DSO la veille"], "a": "AB", "e": "Carte de presse ou carte de la FIJ (Fédération internationale des journalistes). (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "Le préfet, responsable de l'ordre public :", "o": ["définit la stratégie de gestion de l'ordre public", "fixe le cadre juridique et les grandes orientations du service d'ordre", "commande directement les unités sur le terrain", "procède lui-même aux sommations"], "a": "AB", "e": "Le DSO (directeur du service d'ordre) assure la direction opérationnelle. (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "Selon la fiche PLI, « appréhender » au sens de l'article 73 du CPP (code de procédure pénale) implique :", "o": ["une coercition physique et la mise en œuvre de GTPI", "un simple contrôle d'identité", "une convocation au service", "une vérification d'identité sans contrainte"], "a": "A", "e": "TI PLI. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Un serrage excessif des menottes est susceptible :", "o": ["d'entraîner, par réaction à la douleur, une modification du comportement de l'individu", "d'améliorer la coopération de l'individu", "d'être sans conséquence s'il est bref", "d'être exigé pour un individu dangereux"], "a": "A", "e": "Ajustement au diamètre du poignet. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 13, "s": "Face au porteur d'un EEI (engin explosif improvisé) sur le point de procéder au déclenchement, les tirs de neutralisation s'effectuent :", "o": ["autant que possible hors de la zone corporelle où se situe l'EEI", "prioritairement sur la zone de l'EEI", "uniquement dans les jambes", "uniquement après sommation"], "a": "A", "e": "Pour éviter la mise à feu de la charge. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Selon l'instruction DIVA (dispositif d'interception des véhicules automobiles), les dispositifs ne doivent pas être utilisés :", "o": ["dans des courbes ou des virages", "de nuit", "sur chaussée humide", "en agglomération"], "a": "A", "e": "Interdiction énoncée au point 4.1. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Les membres de commandos sont généralement dotés de ceintures ou gilets explosifs à emport limité, de l'ordre de :", "o": ["1 à 5 kg d'équivalent TNT", "2 à 10 kg d'équivalent TNT", "10 à 20 kg d'équivalent TNT", "moins de 500 g"], "a": "A", "e": "Les « kamikazes » : 2 à 10 kg en moyenne. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 14, "s": "Les séances d'entraînement au tir prévues par l'instruction n°3/2024 consacrent une large part :", "o": ["aux exercices de mise en situation travaillant le discernement", "au tir de précision sur cible fixe", "à la manipulation à vide", "au démontage de l'arme"], "a": "A", "e": "Formation continue au tir. (Source : Instruction DGPN n°3/2024)"}, {"t": 4, "s": "En congés annuels, le fonctionnaire :", "o": ["doit indiquer l'adresse précise où il peut être joint en cas de nécessité", "doit rester dans son département de résidence", "doit se présenter au service une fois par semaine", "est dispensé de toute obligation d'information"], "a": "A", "e": "RIPN, article 75. (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 4, "s": "Un repos supplémentaire peut être accordé, à titre exceptionnel, à la suite d'événements importants, sur décision :", "o": ["ministérielle", "du chef de service", "du préfet de département", "du directeur zonal"], "a": "A", "e": "Article 113-40 du RGEPN (règlement général d'emploi de la police nationale). (Source : Guide temps de travail / DocPro / circulaire congés)"}, {"t": 5, "s": "L'allocation journalière d'accompagnement d'une personne en fin de vie est versée au maximum pendant :", "o": ["21 jours, ou 42 jours en cas de temps partiel", "14 jours, ou 28 jours en cas de temps partiel", "21 jours, ou 30 jours en cas de temps partiel", "30 jours, ou 60 jours en cas de temps partiel"], "a": "A", "e": "Congé de solidarité familiale non rémunéré. (Source : Guide temps de travail / DocPro)"}, {"t": 5, "s": "Une réunion d'information spéciale peut être organisée pendant la campagne électorale, c'est-à-dire pendant les :", "o": ["6 semaines précédant le scrutin", "4 semaines précédant le scrutin", "8 semaines précédant le scrutin", "2 semaines précédant le scrutin"], "a": "A", "e": "Par toute organisation candidate. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "La procédure d'abandon de poste peut être engagée lorsque le fonctionnaire :", "o": ["ne prend pas son service aux jour et heure fixés", "ne fournit pas de certificat médical", "ne se soumet pas au contrôle administratif ou médical", "n'a posé aucun congé depuis 2 mois"], "a": "ABC", "e": "Conditions cumulatives. (Source : Guide temps de travail / DocPro)"}, {"t": 6, "s": "Peut bénéficier d'un don de jours de repos l'agent qui assume la charge d'un enfant gravement malade âgé de moins de :", "o": ["20 ans", "16 ans", "18 ans", "25 ans"], "a": "A", "e": "25 ans en cas de décès de l'enfant. (Source : Guide temps de travail / DocPro)"}, {"t": 1, "s": "Le code GesTT d'une e-formation suivie à domicile est :", "o": ["EFD", "E-F", "STG", "FHP"], "a": "A", "e": "E-F pour l'e-formation sur site. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 1, "s": "L'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) s'applique depuis le 1er janvier 2020 à tous les services de police, à l'exception partielle :", "o": ["de la DCCRS et de ses personnels", "de la DGSI", "de la préfecture de police", "des services de police judiciaire"], "a": "A", "e": "Application partielle pour la DCCRS (direction centrale des compagnies républicaines de sécurité). (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Lors d'une prise de service décalée, un agent effectue 3 heures sur un repos compensateur (RC). Il est crédité de :", "o": ["45 minutes", "1 h 48", "3 heures", "aucune compensation"], "a": "A", "e": "Coefficient 0,25 sur RC (3 × 0,25 = 0,75 h). (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 2, "s": "Lors d'une prise de service décalée, quelles affirmations sont exactes ?", "o": ["Elle n'octroie aucune compensation sur la durée habituelle de service", "Les heures effectuées sur un RC sont créditées au coefficient 0,25", "Les heures effectuées sur un RL ou un JF sont créditées au coefficient 0,60", "Les coefficients 0,25 et 0,60 se cumulent pour une même heure"], "a": "ABC", "e": "Coefficients non cumulables, hors services supplémentaires. (Source : Fiches APORTT / Guide temps de travail)"}, {"t": 3, "s": "Le compteur « HS (heures supplémentaires) historique » correspond :", "o": ["au stock d'HS au-delà de 160 h au 31/12/2019", "au stock d'HS au-delà de 120 h au 31/12/2019", "à toutes les HS générées depuis 2020", "au stock d'HS au-delà de 200 h au 31/12/2019"], "a": "A", "e": "Ce compteur n'est plus approvisionné. (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "N'ont droit ni à la rémunération des périodes d'astreinte ni à une compensation horaire :", "o": ["les CCD et CC de l'article 10", "les gradés et gardiens", "les policiers adjoints", "les personnels administratifs"], "a": "A", "e": "APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) – astreinte. (Source : Guide temps de travail / DocPro)"}, {"t": 3, "s": "Les tableaux d'astreinte sont diffusés :", "o": ["dans un délai minimum de 14 jours, modifiables pour motifs exceptionnels", "dans un délai minimum de 7 jours, non modifiables", "dans un délai minimum d'un mois", "la veille au plus tard"], "a": "A", "e": "Délai de diffusion de 14 jours. (Source : Guide temps de travail / DocPro)"}, {"t": 7, "s": "Les policiers en poste à l'étranger sans accès à des infrastructures de tir sont soumis de manière régulière à :", "o": ["des séances de manipulation de leur arme", "des tirs dans un stand privé à leurs frais", "une suspension du port de l'arme", "un recyclage annuel en France"], "a": "A", "e": "Exception à la formation continue au tir. (Source : Instruction DGPN n°3/2024)"}, {"t": 7, "s": "Les officiers et commissaires en formation peuvent être autorisés à porter l'arme hors service :", "o": ["individuellement, par le directeur de l'ENSP, dès leur formation pratique en qualité de stagiaire", "dès leur entrée en scolarité, de plein droit", "seulement après leur titularisation", "sur autorisation du préfet"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024)"}, {"t": 8, "s": "Peuvent être ajoutés au PM (pistolet-mitrailleur) 9 mm, s'ils sont référencés :", "o": ["un désignateur d'objectif électronique (DOE)", "une poignée additionnelle", "une lampe tactique", "un silencieux personnel acheté par l'agent"], "a": "ABC", "e": "Tout élément non référencé constitue une faute professionnelle. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 8, "s": "Le PM (pistolet-mitrailleur) 9 mm permet le tir de la cartouche :", "o": ["opérationnelle de police (COP) de calibre 9 × 19 mm", "5,56 × 45 mm", "9 × 21 mm", "7,62 × 39 mm"], "a": "A", "e": "Instruction PM 9 mm. (Source : Instructions PM 9 mm, HK G36, TSUA)"}, {"t": 9, "s": "Le LBD (lanceur de balles de défense) de 40 mm doit être nettoyé :", "o": ["après chaque tir et après toute manipulation dans des conditions météorologiques défavorables", "une fois par mois", "après chaque vacation", "une fois par trimestre lors du contrôle RAM"], "a": "A", "e": "Instruction AFI (arme de force intermédiaire). (Source : Instruction AFI 2/08/2017)"}, {"t": 9, "s": "Les militaires de la gendarmerie peuvent faire usage du LBD (lanceur de balles de défense), de la GMD (grenade à main de désencerclement) ou du lanceur de grenades pour interrompre une intrusion dans une zone de défense hautement sensible, sur le fondement :", "o": ["de l'article L. 4123-12 du code de la défense", "de l'article L. 435-1 du CSI", "de l'article 122-7 du code pénal", "de l'article R. 211-13 du CSI"], "a": "A", "e": "Cadre spécifique à la gendarmerie. (Source : Instruction AFI 2/08/2017)"}, {"t": 10, "s": "Concernant les aérosols lacrymogènes, quelles affirmations sont exactes ?", "o": ["Ils constituent des moyens de force intermédiaire", "Ils peuvent être employés pour réduire une résistance manifeste à une intervention légale", "Ils sont classés en catégorie A", "Leur effet oculaire dure plusieurs heures"], "a": "AB", "e": "Effets de 5 à 10 minutes. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 10, "s": "Le voyant vert de la baie de chargement du T7 indique une batterie chargée à 100 %, pour une durée de charge maximale de :", "o": ["6 heures", "2 heures", "12 heures", "4 heures"], "a": "A", "e": "Le voyant jaune indique la charge en cours. (Source : Instruction PIE DPN-1.9.4.1 / note GAIL 2004/40)"}, {"t": 11, "s": "Le comité de liaison entre le ministère de l'intérieur et la presse est installé à partir du 1er janvier 2022 avec une périodicité :", "o": ["mensuelle", "hebdomadaire", "trimestrielle", "annuelle"], "a": "A", "e": "SNMO (schéma national du maintien de l'ordre). (Source : SNMO (déc. 2021))"}, {"t": 11, "s": "L'interdiction de port d'objets pouvant servir d'arme lors d'une manifestation s'applique à une aire géographique :", "o": ["limitée aux lieux de la manifestation, aux lieux avoisinants et à leurs accès", "couvrant tout le département", "couvrant toute la commune", "fixée librement par le DSO"], "a": "A", "e": "Étendue proportionnée aux nécessités. (Source : SNMO (déc. 2021))"}, {"t": 12, "s": "La palpation de sécurité s'effectue :", "o": ["par un seul policier, pendant qu'un ou plusieurs équipiers assurent la protection", "par deux policiers simultanément", "par l'ensemble de l'équipage", "par le chef de bord uniquement"], "a": "A", "e": "Les rôles peuvent évoluer. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Le contrôle visuel des objets portés par la personne :", "o": ["peut exonérer le policier qui le décide d'un contrôle tactile", "est interdit en palpation", "doit toujours être suivi d'une fouille", "est réservé aux OPJ"], "a": "A", "e": "TDI palpation. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 12, "s": "Lors d'une palpation, en cas de découverte d'un objet présentant un danger vital immédiatement accessible par la personne, le policier :", "o": ["appréhende l'objet pour l'écarter et le remettre ultérieurement à l'OPJ", "laisse l'objet en place et appelle un OPJ", "demande à la personne de le jeter au sol", "met fin à la palpation"], "a": "A", "e": "TDI palpation. (Source : TDI palpation, menottage, TI PLI/placements)"}, {"t": 13, "s": "Un porteur d'EEI (engin explosif improvisé) se rend. Les policiers :", "o": ["conservent une distance de sécurité dans l'attente du déminage", "procèdent immédiatement au menottage", "le palpent pour neutraliser la charge", "l'emmènent au service"], "a": "A", "e": "Instruction DPN-3.1.3. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 13, "s": "Les procédures de sécurité des gestionnaires d'emprises privées ou des opérateurs de transport :", "o": ["engagent leur seule responsabilité et ne sont pas opposables aux policiers", "s'imposent aux policiers primo-intervenants", "remplacent l'intervention du déminage", "sont validées par le préfet"], "a": "A", "e": "Instruction DPN-3.1.3. (Source : Pratiques pro / instruction DPN-3.1.3 / TI)"}, {"t": 14, "s": "La mallette pédagogique réalisée par l'académie de police concerne l'emploi, l'habilitation et le recyclage de la grenade :", "o": ["GL-304", "GM2L", "GMD", "ASSD"], "a": "A", "e": "Télégramme DGPN (direction générale de la police nationale). (Source : Télégramme DGPN – GL-304)"}, {"t": 14, "s": "Lors de l'usage du HK G36, le tireur doit dans la mesure du possible prendre en compte les particularités environnementales afin :", "o": ["de prévenir tout dommage collatéral, particulièrement en rafale", "de choisir le mode rafale", "de raccourcir la procédure TSUA", "d'éviter le recyclage"], "a": "A", "e": "Formation et doctrine HK G36. (Source : Instruction HK G36)"}, {"t": 5, "s": "À l'issue d'un stage de formation syndicale, l'agent :", "o": ["remet au chef de service l'attestation d'assiduité délivrée par le centre ou l'institut", "n'a aucun justificatif à produire", "doit produire un compte rendu écrit du stage", "doit faire viser sa présence par l'organisation syndicale"], "a": "A", "e": "L'attestation d'assiduité est remise au moment de la reprise de fonctions. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Les réunions mensuelles d'information syndicale pendant les heures de service :", "o": ["ne peuvent être tenues que par les organisations syndicales représentatives", "permettent de s'absenter 3 heures par mois", "sont ouvertes aux agents de tous les services", "donnent lieu à compensation si elles se prolongent au-delà de la fin de service"], "a": "A", "e": "Seuls les personnels du service concerné y participent ; la prolongation au-delà de la fin de service n'est pas compensée. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Les réunions statutaires d'information syndicale :", "o": ["peuvent être tenues par toutes les organisations syndicales, représentatives ou non", "sont décomptées sur le quota de l'heure mensuelle d'information", "sont réservées aux organisations représentatives", "imposent la présence de tous les agents du service"], "a": "A", "e": "Pendant les heures de service, seuls les agents hors service ou bénéficiant d'une ASA (autorisation spéciale d'absence)/crédit de temps syndical peuvent y assister. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Pendant une campagne électorale, chaque agent peut assister à une réunion d'information spéciale dans la limite de :", "o": ["une heure par organisation syndicale candidate, en plus des 12 heures annuelles", "une heure au total pour toute la campagne", "trois heures par organisation syndicale", "12 heures, qui incluent cette réunion"], "a": "A", "e": "Cette heure s'ajoute aux 12 heures par année civile. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Concernant l'activité syndicale, quelles affirmations sont exactes ?", "o": ["Elle ne génère pas d'heures supplémentaires", "Les ASA syndicales ne peuvent pas être reportées sur l'année suivante", "Un stagiaire peut bénéficier d'une décharge partielle d'activité de service", "Les ASA syndicales non utilisées alimentent le CET"], "a": "AB", "e": "Un stagiaire ne peut bénéficier d'aucune décharge d'activité de service. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Une demande d'absence au titre du crédit d'heures syndical doit être adressée au chef de service :", "o": ["au moins 3 jours à l'avance, exprimée en demi-journées", "la veille au plus tard", "au moins 15 jours à l'avance", "au moins un mois à l'avance"], "a": "A", "e": "Un refus pour nécessités de service doit être motivé de façon circonstanciée. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Un agent ne reprend pas son service à la date de fin de sa décharge d'activité de service. Il est :", "o": ["placé en position irrégulière", "automatiquement placé en congé annuel", "placé en disponibilité d'office", "maintenu en décharge jusqu'à sa reprise"], "a": "A", "e": "L'absence de reprise à la date prévue place l'agent en position irrégulière. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Une absence syndicale non confirmée par une décision de l'autorité compétente :", "o": ["est une absence irrégulière", "est régularisée d'office en congé annuel", "est régularisée d'office en crédit de temps syndical", "est imputée sur les jours ARTT sans formalité"], "a": "A", "e": "Elle est considérée comme irrégulière et signalée au SGAMI (bilan mensuel). (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Pour les ASA (autorisation spéciale d'absence) accordées aux représentants syndicaux convoqués à une réunion par l'administration :", "o": ["l'administration ne peut pas invoquer la nécessité de service pour refuser", "aucune limite de jours n'est fixée", "la durée comprend un temps égal à celui de la réunion pour sa préparation et son compte rendu", "elles sont plafonnées à 12 jours par an"], "a": "ABC", "e": "La durée inclut aussi les délais de route ; l'agent justifie de sa participation effective. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Une convocation à une réunion à l'initiative de l'administration, ouvrant droit à ASA (autorisation spéciale d'absence) pour un représentant syndical, peut prendre la forme :", "o": ["d'un message électronique mentionnant l'objet, la date et l'autorité qui convoque", "uniquement d'un courrier recommandé", "uniquement d'une convocation orale", "d'un simple appel de l'organisation syndicale"], "a": "A", "e": "Le courriel suffit s'il précise l'objet, la date et l'autorité. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Le conjoint, partenaire de PACS ou concubin d'une femme enceinte peut bénéficier d'une ASA (autorisation spéciale d'absence) pour l'accompagner à :", "o": ["trois des examens médicaux obligatoires", "tous les examens médicaux obligatoires", "un seul examen médical", "aucun examen, seule la future mère étant concernée"], "a": "A", "e": "Trois examens, y compris en cas de PMA. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Concernant le congé de paternité, quelles affirmations sont exactes ?", "o": ["Il est ouvert à la personne vivant en couple avec la mère même si elle n'est pas le père", "Il ne peut pas se cumuler avec les 3 jours de naissance", "Il doit être pris en entier dans les 8 jours suivant la naissance", "Il remplace les 3 jours de naissance"], "a": "A", "e": "Les jours restants peuvent être pris plus tard dans le délai prévu. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Peut ouvrir droit au congé de solidarité familiale la pathologie grave :", "o": ["d'un ascendant ou d'un descendant", "d'un frère ou d'une sœur", "d'une personne partageant le domicile de l'agent", "d'un collègue de travail"], "a": "ABC", "e": "Également la personne qui a désigné l'agent comme personne de confiance. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Le fonctionnaire convoqué, hors de ses heures de service et pour une affaire liée au service, par un tribunal ou un médecin de la police :", "o": ["bénéficie d'un repos récupérateur en temps égal ou équivalent", "n'a droit à aucune compensation", "perçoit des heures supplémentaires au coefficient 1,5", "bénéficie d'une ASA d'une journée forfaitaire"], "a": "A", "e": "Article 113-39 du RGEPN (règlement général d'emploi de la police nationale). (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Les ASA (autorisation spéciale d'absence) pour participer à un concours ou un examen professionnel :", "o": ["ne sont pas imputées sur les droits à repos ou congés", "ne couvrent pas les délais de route", "sont accordées sans condition de durée", "sont imputées sur les jours ARTT"], "a": "A", "e": "Pour les concours ouverts par le ministre de l'Intérieur, une journée supplémentaire peut être accordée la veille. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Pour un concours dont l'ouverture a été autorisée par le ministre de l'Intérieur, l'autorisation exceptionnelle d'absence d'une journée est prise :", "o": ["la veille du concours", "le lendemain du concours", "au choix dans le mois précédant", "le jour des résultats"], "a": "A", "e": "Journée de préparation la veille. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Concernant le don de sang, quelles affirmations sont exactes ?", "o": ["Les agents non titulaires peuvent aussi bénéficier de l'exemption de service", "L'exemption est forfaitaire d'une demi-journée", "Le nombre de dons est limité à 6 par an tous types confondus", "L'exemption est forfaitaire d'une journée"], "a": "A", "e": "Le temps accordé est le temps utile, pas un forfait. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Les ASA (autorisation spéciale d'absence) pour soigner un enfant malade ou en assurer la garde :", "o": ["sont des mesures de bienveillance et non un droit", "sont accordées après un examen individuel de la situation", "doivent rester compatibles avec la continuité du service", "sont un droit qui ne peut être refusé"], "a": "ABC", "e": "Le chef de service apprécie selon les nécessités du service. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Pour un agent à temps partiel, le nombre d'ASA (autorisation spéciale d'absence) pour enfant malade :", "o": ["est rapporté à sa quotité de travail", "est identique à celui d'un agent à temps plein", "est doublé", "est supprimé"], "a": "A", "e": "Les autres autorisations d'absence restent accordées comme pour un temps plein. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Pour bénéficier d'un don de jours en qualité d'aidant familial, l'agent fournit notamment :", "o": ["une déclaration sur l'honneur de l'aide effective qu'il apporte", "un avis du comité médical", "l'accord écrit de tous ses collègues", "une attestation de la CAF"], "a": "A", "e": "Avec une demande écrite et les justificatifs requis. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Concernant le don de jours de repos, quelles affirmations sont exactes ?", "o": ["Les repos compensateurs d'heures supplémentaires, d'astreintes ou de permanences ne peuvent pas être donnés", "Le don est fait en jours entiers", "Le don devient définitif après accord du chef de service du donneur", "Le donneur peut reprendre ses jours tant qu'ils ne sont pas utilisés"], "a": "ABC", "e": "Le donneur informe par écrit son service gestionnaire. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "En cas de mutation ou de déménagement, un policier :", "o": ["ne bénéficie d'aucune ASA ni d'aucun délai de route réglementaire", "bénéficie de 2 jours d'ASA", "bénéficie de 48 heures de délai de route", "bénéficie d'une journée par tranche de 500 km"], "a": "A", "e": "Aucun texte ne le prévoit pour la police. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Les facilités d'horaires pour la rentrée scolaire :", "o": ["concernent l'entrée en maternelle, en école élémentaire et en 6e", "ne peuvent jamais donner lieu à récupération", "sont un droit sans condition de service", "concernent l'entrée au lycée"], "a": "A", "e": "Elles sont accordées si le fonctionnement du service le permet. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Une absence fondée sur une situation qu'aucun texte ne prévoit :", "o": ["est imputée sur les congés de l'agent (CA, ARTT…)", "fait l'objet d'une ASA de droit", "est réputée être une ASA syndicale", "est compensée en heures supplémentaires"], "a": "A", "e": "Une autorisation d'absence suppose un texte ou une justification. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 5, "s": "Une fonctionnaire enceinte ou qui allaite et qui travaille en police technique et scientifique :", "o": ["doit informer au plus vite sa hiérarchie", "doit en informer sa hiérarchie seulement au 6e mois", "peut continuer toutes ses tâches sans formalité", "est automatiquement placée en congé de maternité"], "a": "A", "e": "Elle peut être exposée à des substances chimiques dangereuses. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Peuvent ouvrir droit à un congé de longue durée :", "o": ["la tuberculose", "une affection cancéreuse", "une maladie mentale", "une fracture simple"], "a": "ABC", "e": "Aussi la poliomyélite et le déficit immunitaire grave et acquis. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Un congé de longue maladie peut être accordé pour une affection qui n'est pas sur la liste indicative :", "o": ["oui, après avis du comité médical compétent", "non, jamais", "oui, sur simple certificat du médecin traitant", "oui, sur décision du chef de service"], "a": "A", "e": "La liste fixée par arrêté du ministre chargé de la santé n'est qu'indicative. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "La demande de renouvellement d'un congé de longue maladie ou de longue durée est adressée à l'administration :", "o": ["un mois avant la fin de la période en cours", "8 jours avant la fin de la période", "le jour de la fin du congé", "trois mois avant la fin de la période"], "a": "A", "e": "Par l'intéressé ou son représentant légal. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Un congé de longue durée accordé à la suite d'un premier CLD pour la même affection :", "o": ["est un nouveau congé de longue durée qui s'ajoute au précédent", "ouvre de nouveau 3 ans à plein traitement", "est requalifié en congé de maladie ordinaire", "n'est pas possible"], "a": "A", "e": "Les durées s'additionnent. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Au-delà de 3 mois de temps partiel pour raison thérapeutique, la prolongation :", "o": ["impose un examen sans délai par un médecin agréé", "est refusée d'office", "est accordée de droit sans examen", "relève du seul chef de service"], "a": "A", "e": "Le médecin agréé se prononce sur la justification médicale, la quotité et la durée. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Pendant un temps partiel pour raison thérapeutique, le fonctionnaire perçoit :", "o": ["l'intégralité de son traitement", "un traitement proportionnel à sa quotité", "la moitié de son traitement", "90 % de son traitement"], "a": "A", "e": "Ainsi que le SFT et l'indemnité de résidence en totalité. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Après avoir épuisé ses droits au temps partiel thérapeutique, un fonctionnaire peut en obtenir un nouveau :", "o": ["après un délai minimal d'un an", "immédiatement", "après trois ans", "jamais"], "a": "A", "e": "Nouvelle autorisation au même titre après au moins un an. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Concernant le temps partiel, quelles affirmations sont exactes ?", "o": ["Les CMO, CLM et CLD ne suspendent pas l'autorisation de temps partiel", "Le régime cyclique est compatible avec le temps partiel", "Une formation obligatoire ne pouvant être suivie à temps partiel suspend l'autorisation de temps partiel", "Le temps partiel est incompatible avec les horaires variables"], "a": "ABC", "e": "Pendant cette formation (ex. OPJ (officier de police judiciaire)), l'agent retrouve les droits d'un agent à temps plein. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Un agent à temps partiel ne peut pas prendre sa journée non travaillée à cause d'une formation. Cette journée :", "o": ["est décalée sans majoration et prise au plus tôt", "est perdue", "est payée en heures supplémentaires", "est majorée de 25 %"], "a": "A", "e": "Elle est prise dès que les nécessités de service le permettent. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "L'organisation du travail des agents à temps partiel :", "o": ["ne doit créer aucune disparité de traitement entre les agents", "peut prévoir des tâches moins valorisantes", "peut supprimer la bonification hors période des congés", "est libre, sans principe d'égalité"], "a": "A", "e": "Les jours de bonification sont accordés comme pour un temps plein. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Un policier adjoint qui entre en école de police avec un CET (compte épargne-temps) alimenté :", "o": ["ne doit avoir aucune interruption entre la fin de son contrat et l'entrée en école, sinon le CET est soldé", "voit ses HS restantes perdues lors de son entrée en école", "perd toujours son CET", "voit son CET versé à la RAFP"], "a": "A", "e": "Les droits sont proratisés selon la période de présence. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Le congé maternité d'une policière :", "o": ["n'entraîne pas le retrait de sa carte d'agent", "entraîne la remise de sa carte d'agent", "entraîne la suspension de son habilitation OPJ", "impose la restitution de son arme et de sa carte"], "a": "A", "e": "Circulaire du 30/04/2015. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Un actif qui a totalisé 30 jours de congé de maladie en 12 mois consécutifs :", "o": ["passe devant le médecin statutaire à sa reprise", "reprend sans formalité", "passe en comité médical supérieur", "est placé en disponibilité"], "a": "A", "e": "Même règle après un CITIS (congé pour invalidité temporaire imputable au service). (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Le certificat médical qui indique la nature de la maladie :", "o": ["relève du secret médical", "est adressé au chef de service en pli ouvert", "peut être lu par le chef de service", "est joint au dossier administratif"], "a": "A", "e": "Il peut passer par le service de l'intéressé, sous pli fermé. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Un fonctionnaire convoqué par le médecin de l'administration ne peut pas se déplacer pour raison de santé. Il :", "o": ["prévient son chef de service dès réception de la convocation", "n'a pas à prévenir le praticien", "n'a rien à faire", "peut se contenter de son arrêt de travail"], "a": "A", "e": "Ou avant l'heure du rendez-vous en cas de force majeure. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "L'arrêt de travail établi par son médecin peut-il être opposé à l'administration pour ne pas se rendre à une convocation médicale ?", "o": ["Non, et l'agent engage sa responsabilité administrative", "Oui, toujours", "Oui, s'il est de plus de 15 jours", "Oui, s'il mentionne « sorties interdites »"], "a": "A", "e": "L'agent qui ne se présente pas volontairement s'expose à des sanctions. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 6, "s": "Pour un policier adjoint, des congés de maladie fréquents :", "o": ["ne justifient pas à eux seuls un licenciement", "justifient à eux seuls un licenciement après trois arrêts", "prolongent son contrat", "entraînent un licenciement automatique"], "a": "A", "e": "Le congé de maladie ne prolonge pas le contrat. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "La priorité des parents d'enfants handicapés pour les congés annuels :", "o": ["vaut quel que soit l'âge de l'enfant", "sert à leur accorder des jours de congé supplémentaires", "est classée en dernière position, dans les 25 %", "ne s'applique qu'aux enfants de moins de 16 ans"], "a": "A", "e": "Note DGFP du 17/11/1987. (Source : Circulaire DGPN 26/01/2022 – plan prévisionnel des congés)"}, {"t": 4, "s": "Pour un congé bonifié, le chef de service peut accorder une ASA (autorisation spéciale d'absence) :", "o": ["d'une vacation pour l'aller et d'une pour le retour, accolées aux 31 jours", "de 48 heures", "de 5 jours", "d'aucune durée"], "a": "A", "e": "Décret n°2020-851 du 2 juillet 2020. (Source : Circulaire DGPN 26/01/2022 – plan prévisionnel des congés)"}, {"t": 4, "s": "Pour partir en congés à l'étranger, un policier :", "o": ["n'a plus besoin d'une autorisation préalable, sauf pour les pays à zones à risques", "consulte la liste des pays à risques du ministère des Affaires étrangères", "rédige un compte rendu après le séjour en cas d'incident", "doit toujours avoir l'autorisation écrite du chef de service"], "a": "ABC", "e": "Le policier reste policier en dehors du service. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Au-delà de 31 jours d'absence consécutifs (CET (compte épargne-temps) seul ou avec des CA/ARTT, ou maladie), le fonctionnaire :", "o": ["est placé en position « d'indisponibilité » pour ne plus peser sur les pourcentages", "est placé en disponibilité", "perd ses droits ARTT", "est radié des cadres"], "a": "A", "e": "Pour éviter d'accumuler des repos qui gêneraient le service. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 4, "s": "Les jours ARTT (aménagement et réduction du temps de travail) :", "o": ["sont pris dans l'année civile au titre de laquelle ils sont accordés", "peuvent être reportés jusqu'au 31 janvier suivant", "peuvent être reportés jusqu'au 31 mars suivant", "sont payés s'ils ne sont pas pris"], "a": "A", "e": "Ils peuvent alimenter le CET (compte épargne-temps) selon les règles du CET. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 4, "s": "Le crédit ARTT (aménagement et réduction du temps de travail) dépend :", "o": ["du corps d'appartenance", "du régime de travail", "du grade seulement", "de l'ancienneté"], "a": "AB", "e": "Il est accordé si l'agent travaille plus de 1607 h/an, hors services supplémentaires. (Source : L'APORTT en bref (bilan 2020))"}, {"t": 1, "s": "En raison de la pénibilité des services supplémentaires répétés, chaque heure de repos journalier manqué en cadre dérogatoire est majorée d'un coefficient de :", "o": ["0,15", "0,25", "0,5", "1"], "a": "A", "e": "Fiche 15 de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale). (Source : Fiches APORTT)"}, {"t": 1, "s": "Le décret qui prévoit les dérogations aux garanties minimales de durée du travail et de repos de la police nationale est :", "o": ["le décret n°2002-1279 du 23 octobre 2002", "le décret n°2000-815 du 25 août 2000", "le décret n°95-654 du 9 mai 1995", "le décret n°82-447 du 28 mai 1982"], "a": "A", "e": "Présentation de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale). (Source : Fiches APORTT)"}, {"t": 1, "s": "Est considéré en mission l'agent qui se déplace pour le service :", "o": ["hors de ses résidences administrative et familiale", "hors de sa circonscription seulement", "à plus de 100 km de son domicile", "pour plus de 24 heures"], "a": "A", "e": "Un ordre de mission préalable est nécessaire, sauf fonctions particulières. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Pendant une mission, quelles affirmations sont exactes ?", "o": ["Les trajets aller et retour vers le lieu de mission sont du temps de travail", "La durée quotidienne de travail est doublée", "Le temps de trajet donne droit à des heures supplémentaires majorées", "La durée quotidienne est portée à 12 heures"], "a": "A", "e": "Mission ou service : même durée quotidienne. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Un fonctionnaire a l'autorisation de résider loin de son lieu d'affectation. Cette autorisation :", "o": ["ne peut jamais justifier une absence ou un retard à la prise de service", "donne droit à un délai de route quotidien", "dispense de tout rappel inopiné", "vaut pour l'étranger"], "a": "A", "e": "Un refus doit être notifié par écrit, en signalant le risque pour l'imputabilité d'un accident de trajet. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Les fonctionnaires de police :", "o": ["n'ont pas le droit d'avoir leur domicile à l'étranger", "doivent informer l'administration de leur lieu de résidence et de tout changement", "peuvent résider à l'étranger s'ils sont affectés près d'une frontière", "n'ont aucune obligation de résidence"], "a": "AB", "e": "Le port de l'arme est impossible sur le trajet domicile-travail depuis l'étranger. (Source : Guide des règles de gestion du temps de travail)"}, {"t": 1, "s": "Le cadre dérogatoire de l'APORTT (arrêté portant organisation relative au temps de travail dans les services de la police nationale) concerne notamment :", "o": ["les missions judiciaires, de surveillance, de renseignement et d'information", "les seules missions de police administrative", "les vacations ordinaires du cycle de l'agent", "toutes les vacations de nuit"], "a": "A", "e": "Les repos manqués sont alors restitués à la fin de la mission. (Source : L'APORTT en bref (bilan 2020))"}, {"t": 3, "s": "Pendant une astreinte, l'agent :", "o": ["est hors temps de travail", "n'est pas à la disposition permanente et immédiate de son supérieur", "doit rester chez lui ou à proximité pour pouvoir intervenir", "est au service et en tenue"], "a": "ABC", "e": "Définition de l'astreinte. (Source : L'APORTT en bref (bilan 2020))"}, {"t": 14, "s": "L'arrêté du 27 juillet 2015 sur la formation continue TSI (techniques et sécurité en intervention) et le sport opérationnel concerne :", "o": ["les personnels actifs de la police nationale", "les agents de surveillance de la voie publique", "les personnels administratifs", "les agents de police municipale"], "a": "A", "e": "NOR INTC1518574A. (Source : Arrêté TSI du 27/07/2015 consolidé)"}, {"t": 11, "s": "Une personne filme des policiers pendant une manifestation. Selon le SNMO :", "o": ["il est exclu de l'interpeller pour ce seul motif", "il est interdit de lui retirer son matériel ou de détruire l'enregistrement", "elle peut être interpellée si elle n'est pas journaliste", "son téléphone peut être saisi à titre préventif"], "a": "AB", "e": "Le faire exposerait son auteur à des poursuites disciplinaires et judiciaires. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, un fonctionnaire de police soumis à des règles déontologiques strictes :", "o": ["ne doit pas craindre l'enregistrement d'images ou de sons", "doit s'opposer à tout enregistrement", "peut demander l'effacement des images", "doit masquer son visage"], "a": "A", "e": "Principe fondamental posé par le SNMO. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Tout enregistrement connu d'images ou de paroles de policiers dans l'exercice de leurs fonctions :", "o": ["fait dès que possible l'objet d'une information de la hiérarchie", "est signalé au parquet sans délai", "n'appelle aucune démarche", "entraîne une plainte systématique"], "a": "A", "e": "SNMO. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "La gestion de l'ordre public repose d'abord sur des unités spécialisées :", "o": ["les escadrons de gendarmerie mobile (EGM)", "les brigades de protection des familles", "les brigades anticriminalité", "les polices municipales"], "a": "A", "e": "EGM (escadrons de gendarmerie mobile) et CRS (compagnies républicaines de sécurité) forment la réserve générale à la disposition du Gouvernement. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Les EGM (escadrons de gendarmerie mobile) et les CRS (compagnies républicaines de sécurité) constituent :", "o": ["la réserve générale à la disposition du Gouvernement", "une force sous l'autorité du maire", "une réserve du préfet de zone seulement", "des unités de police judiciaire"], "a": "A", "e": "La préfecture de police dispose en plus de ses propres compagnies d'intervention. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, la maîtrise de la 3e dimension :", "o": ["est essentielle au maintien de l'ordre moderne", "repose sur des moyens aériens comme les hélicoptères et les drones", "sert à conduire les opérations et à identifier les fauteurs de troubles", "est réservée à la gendarmerie"], "a": "ABC", "e": "Avec un effort sur les capteurs optiques et la retransmission, dans un cadre juridique adapté. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Les sommations plus intelligibles en vigueur ont été introduites par :", "o": ["le décret 2021-556 du 5 mai 2021", "la loi du 28 février 2017", "le décret du 23 octobre 2002", "l'arrêté du 27 juillet 2015"], "a": "A", "e": "Elles commencent par « Attention ! Attention ! Vous participez à un attroupement… ». (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "L'annonce qui précède les sommations insiste sur :", "o": ["le caractère d'attroupement du rassemblement", "la légitimité de l'ordre de dispersion", "le recours imminent à la force si la foule ne se disperse pas", "l'identité du commissaire"], "a": "ABC", "e": "« Obéissance à la loi. Vous devez vous disperser et quitter les lieux. » (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Lors de la dispersion d'un attroupement, les journalistes :", "o": ["peuvent continuer leur mission sans devoir quitter les lieux", "doivent se placer de façon à ne pas être confondus avec les participants", "ne doivent pas faire obstacle à l'action des forces de l'ordre", "doivent quitter les lieux comme les autres personnes"], "a": "ABC", "e": "SNMO § 2.2.3.3. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Le canal d'échange avec les médias prévu par le SNMO pour les manifestations importantes :", "o": ["est une « boucle » de télécommunications gérée par un référent", "permet de signaler les violences contre les journalistes", "n'est ouvert qu'aux agences de presse", "sert à diffuser les ordres de dispersion"], "a": "AB", "e": "Les journalistes peuvent en demander l'accès librement. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, l'embarquement de journalistes au plus près des forces :", "o": ["est possible", "est interdit", "est réservé aux opérations judiciaires", "est soumis à l'accord du procureur"], "a": "A", "e": "SNMO § 3.5.3. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, la sécurité physique des journalistes :", "o": ["doit être garantie", "relève de leur seule responsabilité", "n'est assurée qu'avec un brassard officiel", "dépend de leur accréditation préfectorale"], "a": "A", "e": "SNMO. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "La communication externe sur les opérations d'ordre public doit notamment :", "o": ["expliquer l'action de l'État", "se limiter aux réseaux sociaux", "cesser dès le début de la manifestation", "être réservée au ministre"], "a": "A", "e": "SNMO § 3.5. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Face aux casseurs infiltrés dans les cortèges, le SNMO prévoit :", "o": ["de développer des tactiques qui mettent fin aux exactions en distinguant les manifestants selon leur comportement", "de renforcer le volet judiciaire des opérations", "de disperser systématiquement tout le cortège", "de renoncer aux interpellations"], "a": "AB", "e": "SNMO, partie III. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Pour empêcher les éléments violents d'agir, le SNMO prévoit des mesures préventives visant notamment à :", "o": ["empêcher leur venue", "empêcher l'entrée d'objets dangereux dans le périmètre", "interdire toute manifestation", "fermer les transports en commun"], "a": "AB", "e": "SNMO § 2.3. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Depuis mars 2019, la police et la gendarmerie ont lancé des formations spécifiques au maintien de l'ordre destinées :", "o": ["aux forces territoriales", "aux seules CRS", "aux réservistes uniquement", "aux élèves en école"], "a": "A", "e": "Les forces territoriales sont souvent seules engagées. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, le partage d'expériences (RETEX (retour d'expérience)) entre forces de l'ordre :", "o": ["doit être plus largement développé", "est piloté par les seuls préfets", "est réservé à la gendarmerie", "est interdit pour des raisons de confidentialité"], "a": "A", "e": "Pour adapter pratiques et moyens à l'adversaire. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le guide des violences urbaines, les renforts (polices municipales, etc.) :", "o": ["sont intégrés au dispositif et guidés par les effectifs locaux", "ne peuvent pas remplacer la police nationale ni intervenir en unités constituées", "prennent le commandement des opérations", "interviennent sans coordination"], "a": "AB", "e": "Guide opérationnel des violences urbaines, 2.2.3. (Source : Guide opérationnel des violences urbaines (sept. 2025))"}, {"t": 11, "s": "Le guide des violences urbaines recommande, avec les hôpitaux :", "o": ["une prise en charge prioritaire et séparée des policiers blessés", "l'hospitalisation systématique des interpellés", "l'interdiction des soins sur place", "une réquisition générale des urgences"], "a": "A", "e": "Accompagnement des policiers mobilisés et blessés. (Source : Guide opérationnel des violences urbaines (sept. 2025))"}, {"t": 11, "s": "Selon le guide opérationnel des violences urbaines, l'enquête judiciaire est de préférence confiée :", "o": ["à des groupes d'enquête dédiés", "aux seules unités de voie publique", "au service le plus proche", "aux CRS"], "a": "A", "e": "Avec recueil et exploitation des traces et indices. (Source : Guide opérationnel des violences urbaines (sept. 2025))"}, {"t": 13, "s": "Les dispositifs d'interception de véhicules (DIVA (dispositif d'interception des véhicules automobiles)) ne doivent jamais servir à arrêter :", "o": ["un deux-roues", "un véhicule à trois roues", "un quad", "une voiture de tourisme"], "a": "ABC", "e": "Ils sont conçus pour les véhicules d'au moins quatre roues, hors quads. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Sauf exception, les DIVA (dispositif d'interception des véhicules automobiles) s'utilisent sur :", "o": ["des surfaces dures comme l'asphalte, le béton ou le bitume", "des chemins de terre", "le sable ou la neige", "toute surface"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) 2008, point 4.1. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Les DIVA (dispositif d'interception des véhicules automobiles) sont conçus pour :", "o": ["arrêter la progression d'un véhicule automobile", "crever les pneus des deux-roues", "neutraliser le conducteur", "bloquer un piéton en fuite"], "a": "A", "e": "Point 4.2 : préconisations d'emploi. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Après chaque utilisation dynamique d'un DIVA (dispositif d'interception des véhicules automobiles), qu'un véhicule ait roulé dessus ou non :", "o": ["un formulaire-type d'utilisation est rempli, toutes rubriques comprises", "le dispositif est vérifié immédiatement, même sans passage de véhicule", "aucune formalité n'est requise", "seule une mention en main courante est faite"], "a": "AB", "e": "La vérification après emploi ne modifie pas la date de l'inspection semestrielle. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Les DIVA (dispositif d'interception des véhicules automobiles) sont inspectés :", "o": ["tous les six mois, avec une fiche d'inspection", "une fois par an", "tous les trois ans", "uniquement après usage"], "a": "A", "e": "La date, le nom, le grade et le service de l'inspecteur sont notés. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Les copies des formulaires d'utilisation des DIVA (dispositif d'interception des véhicules automobiles) sont transmises à la DFPN (direction de la formation de la police nationale) :", "o": ["au moins tous les trimestres", "une fois par an", "chaque mois", "seulement en cas d'accident"], "a": "A", "e": "Exploitation en liaison avec la DAPN (direction de l'administration de la police nationale). (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Lorsqu'un DIVA (dispositif d'interception des véhicules automobiles) vise un véhicule précis, il faut tenir compte :", "o": ["des conséquences possibles sur les autres véhicules tout proches", "de la seule vitesse du véhicule visé", "de la couleur du véhicule", "de la marque des pneus"], "a": "A", "e": "Pour le choix du matériel comme pour son emploi. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Le DIVA (dispositif d'interception des véhicules automobiles) peut être inefficace contre :", "o": ["les pneus à affaissement limité", "les pneus neige", "les poids lourds", "les véhicules diesel"], "a": "A", "e": "Les échecs s'expliquent aussi par un mauvais emploi du matériel. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Pour bien mener une perquisition, il faut être au moins :", "o": ["trois fonctionnaires", "deux fonctionnaires", "cinq fonctionnaires", "un OPJ seul"], "a": "A", "e": "Un trop grand nombre est déconseillé, sauf situation particulière. (Source : TI FT n°42 – perquisition)"}, {"t": 13, "s": "Après une perquisition, les policiers :", "o": ["restent très vigilants car la tension retombe", "quittent les lieux discrètement", "verrouillent toutes les entrées et ouvertures", "laissent les lieux ouverts pour l'occupant"], "a": "ABC", "e": "Phase « après » : clôture et retour au service. (Source : TI FT n°42 – perquisition)"}, {"t": 13, "s": "Un objet est dit « abandonné » :", "o": ["dès qu'il est laissé sans surveillance par son propriétaire", "quand il est resté plus d'une heure au même endroit", "quand le déminage l'a examiné", "quand il contient un explosif"], "a": "A", "e": "Instruction DPN-3.1.3, 2.1. (Source : Instruction DPN-3.1.3 (07/2017))"}, {"t": 13, "s": "Pour retrouver le propriétaire d'un objet abandonné dans une gare ou un centre commercial :", "o": ["on fait des annonces et des appels répétés, à la voix ou par haut-parleur", "on exploite la vidéoprotection du site", "on ouvre l'objet pour chercher des papiers d'identité", "on attend l'arrivée du déminage"], "a": "AB", "e": "La gestion relève de l'exploitant ou des primo-intervenants requis. (Source : Instruction DPN-3.1.3 (07/2017))"}, {"t": 13, "s": "Face à un individu peut-être porteur d'un engin explosif improvisé, les policiers :", "o": ["se tiennent le plus loin possible", "se mettent à couvert dès que possible", "respectent au moins 60 mètres à couvert", "s'approchent pour le maîtriser"], "a": "ABC", "e": "Un porteur peut transporter 2 à 10 kg d'équivalent TNT avec beaucoup de fragments. (Source : Instruction DPN-3.1.3 (07/2017))"}, {"t": 13, "s": "En cas d'usage d'un dispositif de détection, la zone d'isolement pour contrôler les suspects :", "o": ["est repérée à l'avance près du dispositif", "est placée au contact de l'entrée principale, au milieu du public", "est placée au cœur de la foule", "est inutile"], "a": "A", "e": "Le dispositif d'intervention est placé tout près du système de détection. (Source : Instruction DPN-3.1.3 (07/2017))"}, {"t": 13, "s": "Selon le glossaire tactique, une zone ou une pièce « reconnue » :", "o": ["ne doit plus contenir de danger (« clair »)", "a seulement été regardée de loin", "est encore dangereuse", "est réservée au déminage"], "a": "A", "e": "Voir aussi « éclairer ». (Source : Annexe DPN-3.1 – glossaire « Attentats »)"}, {"t": 13, "s": "Dans un aéroport, le « côté piste » :", "o": ["est une zone à accès réglementé", "n'est accessible qu'aux passagers et aux personnes autorisées", "est accessible à tout le monde", "correspond au parking"], "a": "AB", "e": "Le « côté ville » est accessible à tout le monde. (Source : Annexe DPN-3.1 – glossaire « Attentats »)"}, {"t": 13, "s": "Face à une tuerie de masse, si un engin explosif improvisé est identifié et que les distances de sécurité ne peuvent pas être respectées :", "o": ["le BBS peut protéger en plus contre les projections et le souffle", "il faut quand même ouvrir l'engin", "il faut quitter les lieux sans protéger personne", "aucune protection n'est possible"], "a": "A", "e": "PPI – tuerie de masse. (Source : PPI – tuerie de masse)"}, {"t": 13, "s": "Lors d'une opération dans un lieu public qui paraît trop risquée, il faut :", "o": ["ne pas hésiter à reporter l'intervention", "intervenir tout de suite quoi qu'il arrive", "demander l'avis du public", "s'en remettre à la sécurité privée"], "a": "A", "e": "TI FT n°20. (Source : TI FT n°20 – lieux publics)"}, {"t": 13, "s": "Lors d'un cambriolage en cours, si la surveillance s'éternise sans résultat, la visite du domicile :", "o": ["exige la présence d'un officier de police judiciaire", "peut être faite par un seul gardien", "n'est jamais possible", "exige l'accord du maire"], "a": "A", "e": "TI FT n°32. (Source : TI FT n°32 – cambriolage en cours)"}, {"t": 13, "s": "Selon la fiche cambriolage, un domicile suppose :", "o": ["une habitabilité concrète", "seulement une adresse postale", "que l'occupant soit propriétaire", "qu'il y ait une serrure"], "a": "A", "e": "Sans habitabilité, le lieu n'est qu'une adresse. (Source : TI FT n°32 – cambriolage en cours)"}, {"t": 12, "s": "Lors d'une palpation, il est recommandé d'éviter les gestes spectaculaires comme :", "o": ["faire lever les bras", "palper la personne", "lui parler calmement", "parler à la personne"], "a": "A", "e": "Sauf si le policier les subit (résistance) ; à faire à l'abri du regard du public si possible. (Source : TDI – Palpation de sécurité)"}, {"t": 12, "s": "La palpation de sécurité doit être réalisée :", "o": ["avec minutie et méthode", "sans agressivité ni violence", "dans un environnement sécurisé", "le plus vite possible, même en pleine rue"], "a": "ABC", "e": "Avec discernement et respect de la personne. (Source : TDI – Palpation de sécurité)"}, {"t": 12, "s": "Un incident pendant le menottage (par exemple une blessure de la personne) :", "o": ["est mentionné dans la procédure", "n'a pas à être noté", "est signalé seulement à l'oral", "est noté sur le registre de l'armurerie"], "a": "A", "e": "La personne menottée est sous l'entière responsabilité des policiers. (Source : TDI – Menottage)"}, {"t": 12, "s": "Selon la note DGPN (direction générale de la police nationale) du 13/09/2004, les mesures de contrainte comme le menottage :", "o": ["sont strictement limitées aux besoins de la procédure", "sont proportionnées à la gravité de l'infraction", "ne doivent pas porter atteinte à la dignité de la personne", "sont laissées à la libre appréciation de l'agent"], "a": "ABC", "e": "Rappel de l'instruction ministérielle du 11 mars 2003. (Source : Note DGPN 13/09/2004 – menottes)"}, {"t": 12, "s": "Dans le dispositif PLI (protection, liaison, interpellation) :", "o": ["chaque policier doit pouvoir tenir l'un ou l'autre rôle selon la situation", "la réussite dépend du respect des rôles", "chaque rôle est attribué une fois pour toutes", "seul le chef de bord peut interpeller"], "a": "AB", "e": "TI – PLI. (Source : TI – PLI)"}, {"t": 7, "s": "Le dispositif « Voyager-Protéger », en vigueur depuis le 1er janvier 2022 :", "o": ["permet aux policiers des trois corps actifs de voyager gratuitement sur certains réseaux SNCF", "couvre les trajets domicile-travail et les déplacements privés sur le réseau national", "oblige à se présenter au chef de bord et à porter son arme individuelle", "concerne aussi les personnels administratifs non armés"], "a": "ABC", "e": "Il contribue à la sécurité des trains. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Le cadre de l'article L. 435-1 du CSI (code de la sécurité intérieure) s'applique hors service :", "o": ["seulement quand le policier agit dans le cadre de ses fonctions", "jamais", "dans tous les cas, même pour un différend privé", "seulement en tenue"], "a": "A", "e": "Articles R. 434-19-1 du CSI et 113-32 du RGEPN (règlement général d'emploi de la police nationale). (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Même si toutes les conditions du port de l'arme hors service sont remplies, le chef de service peut s'y opposer :", "o": ["pour préserver l'intégrité physique et la santé de l'agent (R. 434-6-4 CSI)", "si l'agent n'a pas sa carte de transport", "par simple convenance", "jamais"], "a": "A", "e": "L'opposition est motivée par l'un de ces fondements. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Un policier ne peut pas justifier pourquoi il ne présente pas son arme. Quelles affirmations sont exactes ?", "o": ["Une enquête administrative est ouverte et peut aboutir à une procédure disciplinaire", "Tout est fait pour retrouver l'arme au plus vite", "L'affaire est classée sans suite", "Il reçoit tout de suite une nouvelle arme sans formalité"], "a": "AB", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Dans les meubles de dépôt sécurisés des armes individuelles :", "o": ["les armes de poing et leurs chargeurs sont rangés dans le même meuble, avec un registre des mouvements", "le rangement permet d'identifier facilement le détenteur", "seule la hiérarchie désignée peut les ouvrir", "chaque agent garde une clé"], "a": "ABC", "e": "En tenant compte des contraintes de nuit, de permanence et d'astreinte. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Le stockage des armes dans le local sécurisé d'un service partenaire armé (SUGE (surveillance générale de la SNCF), police municipale…) :", "o": ["fait partie des solutions prévues", "est interdit", "impose de prévenir le procureur", "n'est possible que chez la gendarmerie"], "a": "A", "e": "Instruction DGPN (direction générale de la police nationale) n°3/2024, 4.1.3. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 7, "s": "Pour le tir sportif avec l'arme individuelle (arrêté du 17 septembre 2024) :", "o": ["seules des munitions manufacturées à balles ordinaires chemisées sont utilisées", "dans la limite de 3 000 par an", "tout incident est signalé sans délai et par écrit à la hiérarchie", "les munitions rechargées sont autorisées"], "a": "ABC", "e": "Déclaration préalable d'intention de tir sportif. (Source : Instruction DGPN n°3/2024 – arme individuelle)"}, {"t": 8, "s": "Pour le HK G36, une habilitation qui n'est plus valable faute de recyclage :", "o": ["interdit de percevoir l'arme ou d'en être doté", "n'empêche pas de la percevoir pour une mission", "donne droit à une dotation provisoire", "est sans effet"], "a": "A", "e": "Instruction HK G36, 5.4.3. (Source : Instruction HK G36 (mars 2016))"}, {"t": 8, "s": "Pour garder l'habilitation HK G36, la formation continue reprend :", "o": ["le volet technique de l'habilitation", "un module de tir sportif", "une épreuve physique chronométrée", "seulement un tir de contrôle"], "a": "A", "e": "Le maintien de l'habilitation dépend du suivi et des résultats. (Source : Instruction HK G36 (mars 2016))"}, {"t": 8, "s": "Avec le PM (pistolet-mitrailleur) 9 mm, l'usage de l'arme après deux sommations à voix haute est prévu pour :", "o": ["défendre les lieux occupés ou les personnes confiées", "arrêter une personne qui cherche à échapper à la garde ou aux investigations", "la légitime défense immédiate", "le périple meurtrier"], "a": "AB", "e": "Article L. 435-1, 2° et 3° du CSI (code de la sécurité intérieure). (Source : Instruction DPN-1.9.2 – PM 9 mm)"}, {"t": 8, "s": "Le périple meurtrier (L. 435-1, 5° du CSI (code de la sécurité intérieure)) autorise l'usage de l'arme :", "o": ["dans le seul but d'empêcher qu'un ou plusieurs meurtres ou tentatives qui viennent d'être commis se répètent à bref délai", "si les policiers ont des raisons réelles et objectives de penser que cela va se répéter", "pour arrêter tout auteur de délit en fuite", "sans condition de proportionnalité"], "a": "AB", "e": "L'absolue nécessité et la proportionnalité restent exigées. (Source : Instruction DPN-1.9.2 – PM 9 mm)"}, {"t": 8, "s": "Alimenter le TSUA (traitement relatif au suivi de l'usage des armes) :", "o": ["est une obligation qui découle du devoir de rendre compte", "est facultatif", "ne concerne que les gradés", "est fait par le chef de service à la place de l'agent"], "a": "A", "e": "Article 18 du code de déontologie de 1986 et RGEPN (règlement général d'emploi de la police nationale). (Source : Instruction DGPN 19/12/2011 – TSUA)"}, {"t": 8, "s": "Pour les déclarations TSUA (traitement relatif au suivi de l'usage des armes) de ses subordonnés, l'autorité hiérarchique :", "o": ["peut les consulter à tout moment", "peut corriger le récit de l'agent quand elle le veut", "ne peut jamais retirer son visa", "peut réécrire le récit de l'agent"], "a": "A", "e": "Elle peut modifier les données qu'elle a saisies elle-même sur les suites judiciaires et administratives. (Source : Instruction DGPN 19/12/2011 – TSUA)"}, {"t": 8, "s": "Pour le TSUA (traitement relatif au suivi de l'usage des armes), les agents doivent :", "o": ["vérifier que leurs déclarations sont validées et donc clôturées", "permettre leur soumission sans délai au visa hiérarchique", "attendre la fin de l'enquête judiciaire pour déclarer", "déclarer seulement en fin d'année"], "a": "AB", "e": "Toutes les opérations sont tracées. (Source : Instruction DGPN 19/12/2011 – TSUA)"}, {"t": 8, "s": "Le contrôle de fonctionnement du pistolet Glock (manœuvre de la culasse, simple et double action…) sert à :", "o": ["vérifier que les mécanismes d'un cycle de tir fonctionnent", "nettoyer l'arme", "régler les organes de visée", "charger l'arme"], "a": "A", "e": "Règles générales de sécurité Glock 17/26. (Source : Instruction DPN-1.9.2 – PM 9 mm)"}, {"t": 9, "s": "Le superviseur placé à côté du tireur LBD (lanceur de balles de défense) :", "o": ["évalue la situation d'ensemble et les mouvements des manifestants", "vérifie que le tireur a compris les ordres", "désigne l'objectif à atteindre", "tire à la place du tireur"], "a": "ABC", "e": "Télégramme DGPN (direction générale de la police nationale) 2020. (Source : Télégramme DGPN 2020 – binôme superviseur-tireur)"}, {"t": 9, "s": "Pour les PA (policiers adjoints) et les réservistes, la dotation en AFI (arme de force intermédiaire) est décidée :", "o": ["sur instruction hiérarchique du chef du service d'affectation", "par le préfet", "par l'agent", "par le ministre au cas par cas"], "a": "A", "e": "Dans les conditions des articles R. 411-7 et suivants du CSI (code de la sécurité intérieure). (Source : Instruction DGPN n°15/2025 – AFI PA et réservistes)"}, {"t": 9, "s": "Selon le dernier télégramme sur les grenades à main à effet sonore, toute difficulté d'usage de cette arme est signalée sans délai :", "o": ["au pôle missions de police du cabinet du DGPN", "au fabricant", "au SGAMI", "au procureur"], "a": "A", "e": "Le régime transitoire du télégramme du 16 mars 2022 est abrogé. (Source : Télégramme DGPN – grenades à effet sonore)"}, {"t": 10, "s": "Avec le PIE (pistolet à impulsions électriques), il faut faire attention aux personnes particulièrement vulnérables, par exemple :", "o": ["une personne dont les vêtements sont imbibés de liquide ou de vapeur inflammable", "une femme enceinte", "une personne cardiaque", "une personne qui porte des lunettes"], "a": "ABC", "e": "Aussi les blessés qui saignent beaucoup. (Source : Instruction DPN-1.9.4.1 – PIE)"}, {"t": 10, "s": "L'emploi du PIE (pistolet à impulsions électriques) demande la même vigilance dans un lieu où l'on craint :", "o": ["un incendie", "une explosion", "une électrocution", "du bruit"], "a": "ABC", "e": "Par exemple une station-service. (Source : Instruction DPN-1.9.4.1 – PIE)"}, {"t": 10, "s": "Avec le PIE (pistolet à impulsions électriques), il faut éviter de multiplier les cycles d'impulsions car ils peuvent être :", "o": ["inefficaces", "plus efficaces à mesure qu'ils se répètent", "plus efficaces à chaque fois", "sans aucun effet sur la santé"], "a": "A", "e": "Instruction PIE. (Source : Instruction DPN-1.9.4.1 – PIE)"}, {"t": 10, "s": "Dans un local fermé, une diffusion massive de gaz lacrymogène :", "o": ["peut être inefficace", "peut être dangereuse", "est recommandée", "est sans risque"], "a": "AB", "e": "L'usage doit rester strictement proportionné. (Source : Instruction DAPN 2004/40 – produits incapacitants)"}, {"t": 10, "s": "Le gaz CS d'un aérosol lacrymogène provoque notamment :", "o": ["une forte irritation des yeux", "une perte de connaissance immédiate", "une paralysie des jambes", "une perte de connaissance durable"], "a": "A", "e": "Douleur et sensation de brûlure aux yeux. (Source : Instruction DAPN 2004/40 – produits incapacitants)"}, {"t": 10, "s": "Pour extraire les données d'utilisation des PIE (pistolet à impulsions électriques), le partage des moyens permet :", "o": ["aux services sans connexion internet ADSL d'extraire leurs données dans un service équipé", "de se passer de toute extraction", "d'envoyer l'arme au fabricant", "de transmettre les données par courrier"], "a": "A", "e": "Instruction PIE. (Source : Instruction DPN-1.9.4.1 – PIE)"}, {"t": 5, "s": "Un agent bénéficiant d'une décharge d'activité de service syndicale :", "o": ["informe à l'avance son service des congés qu'il compte prendre", "reste soumis à l'autorité hiérarchique", "fait transmettre chaque trimestre un état des ASA et congés pris, au plus tard le 10 du mois suivant", "n'a plus aucun lien avec son service"], "a": "ABC", "e": "État trimestriel avec justificatifs, transmis au chef de service d'affectation. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Il existe trois types de réunions syndicales :", "o": ["les réunions mensuelles d'information", "les réunions statutaires", "les réunions d'information spéciales pendant la période électorale", "les réunions de service hebdomadaires"], "a": "ABC", "e": "DocPro BC 2026. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Élu conseiller municipal, un agent du corps d'encadrement et d'application (CEA) :", "o": ["peut exercer son mandat tout en restant dans la police nationale", "doit démissionner", "doit être placé en disponibilité", "doit renoncer à son mandat"], "a": "A", "e": "L'officier (corps de commandement) doit, lui, choisir entre son mandat et ses fonctions. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 5, "s": "Un homme peut donner son sang total au maximum :", "o": ["6 fois par an, avec au moins 8 semaines entre deux dons", "4 fois par an", "12 fois par an", "24 fois par an, toutes les 2 semaines"], "a": "A", "e": "Les femmes : 4 dons de sang total par an. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 6, "s": "Un fonctionnaire stagiaire peut obtenir un temps partiel pour raison thérapeutique :", "o": ["oui, sauf si son stage comporte un enseignement professionnel ou se fait dans un établissement de formation", "non, jamais", "oui, sans aucune restriction", "seulement après titularisation"], "a": "A", "e": "Cette période compte en entier pour l'avancement à la titularisation. (Source : DocPro BC 2026 – gestion du temps de travail (avril 2026))"}, {"t": 4, "s": "Lors d'un congé bonifié, si le service le permet, l'agent peut y accoler :", "o": ["des congés annuels", "des jours ARTT", "des jours de CET", "des jours de formation syndicale"], "a": "ABC", "e": "Circulaire DGPN (direction générale de la police nationale) 26/01/2022. (Source : Circulaire DGPN 26/01/2022 – plan prévisionnel des congés)"}, {"t": 11, "s": "Selon le SNMO, à partir du 1er février 2022, pour toute manifestation importante :", "o": ["un référent formé et disponible est désigné au sein des forces", "un canal d'échange dédié avec les médias est ouvert pendant toute la manifestation", "chaque journaliste doit avoir une accréditation préfectorale", "le préfet commente l'opération en direct"], "a": "AB", "e": "SNMO, partie sur la communication. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, les engins lanceurs d'eau et les véhicules blindés :", "o": ["ont fait leurs preuves dans leur domaine", "doivent être renforcés en nombre ou renouvelés", "sont abandonnés", "sont réservés à la préfecture de police"], "a": "AB", "e": "Besoins évalués dans la programmation budgétaire. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 11, "s": "Selon le SNMO, chaque unité engageable en maintien de l'ordre doit être :", "o": ["formée, équipée et contrôlée", "composée uniquement de CRS", "commandée par un officier de gendarmerie", "engagée sans encadrement intermédiaire"], "a": "A", "e": "Le rôle de l'encadrement intermédiaire est primordial. (Source : Schéma national du maintien de l'ordre (déc. 2021))"}, {"t": 13, "s": "Lors des essais en conditions réelles, les DIVA (dispositif d'interception des véhicules automobiles) ont permis d'intercepter les véhicules :", "o": ["dans près de 80 % des cas", "dans 25 % des cas", "dans tous les cas", "dans moins de la moitié des cas"], "a": "A", "e": "Les échecs venaient d'un mauvais emploi ou de pneus à affaissement limité. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Lors des essais des DIVA (dispositif d'interception des véhicules automobiles), quelles affirmations sont exactes ?", "o": ["Aucun pneu n'a éclaté", "Les véhicules sont restés stables, même en situation extrême", "Les véhicules perdaient tout contrôle", "Les pneus éclataient à chaque passage"], "a": "AB", "e": "Même lors d'un démarrage en trombe ou d'un freinage brutal. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 13, "s": "Après le remplacement d'un élément abîmé d'un DIVA (dispositif d'interception des véhicules automobiles) à la suite d'un usage, la fiche d'inspection reçoit la mention :", "o": ["« Après usage »", "« Hors service »", "« Réformé »", "« Contrôle annuel »"], "a": "A", "e": "Comme lors de l'inspection semestrielle. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 12, "s": "Selon l'instruction DGPN (direction générale de la police nationale) n°2014-140-D, la palpation de sécurité peut être pratiquée :", "o": ["sur la base de considérations objectives tenant à la dangerosité possible de la personne", "sur la base de l'apparence physique", "de façon systématique lors de tout contrôle d'identité", "seulement avec l'accord de la personne"], "a": "A", "e": "TDI – palpation de sécurité. (Source : TDI – Palpation de sécurité)"}, {"t": 12, "s": "Lors d'un contrôle d'identité, le policier choisit les personnes à contrôler :", "o": ["sans se fonder sur une caractéristique physique ou un signe distinctif, sauf signalement précis", "selon leur apparence", "selon leur tenue vestimentaire", "au hasard des passants"], "a": "A", "e": "Article R. 434-16 du CSI (code de la sécurité intérieure). (Source : TDI – Palpation de sécurité)"}, {"t": 12, "s": "Pour relever une personne menottée allongée au sol, le policier :", "o": ["lui fait plier la jambe située de son côté", "la guide par la nuque dans un mouvement de rotation", "la fait passer par la position « à genou »", "la tire par les menottes"], "a": "ABC", "e": "Une légère pression vers le sol sur la nuque l'aide à pousser sur sa jambe. (Source : TDI – Menottage)"}, {"t": 10, "s": "Sauf impossibilité, la bombe lacrymogène ne doit pas être actionnée à moins de :", "o": ["1 mètre d'une personne", "10 centimètres d'une personne", "5 mètres d'une personne", "10 mètres d'une personne"], "a": "A", "e": "À bout portant, risque de choc oculaire dangereux ; si tir proche vers le visage, conduire la personne aux urgences au moindre problème. (Source : Instruction emploi des aérosols lacrymogènes)"}, {"t": 10, "s": "La plus grande prudence est recommandée dans l'usage du gaz lacrymogène envers :", "o": ["les femmes enceintes", "les jeunes mineurs", "les personnes âgées et les toxicomanes", "les personnes portant une casquette"], "a": "ABC", "e": "Personnes dont l'état de santé peut être fragile, notamment en local fermé (risque d'inhalation plus élevé). (Source : Instruction emploi des aérosols lacrymogènes)"}, {"t": 10, "s": "Concernant les produits lacrymogènes utilisables par les policiers :", "o": ["seuls les produits fournis par l'administration peuvent être utilisés", "utiliser un produit non référencé constitue une faute professionnelle", "certains produits du commerce contiennent un gaz propulseur inflammable", "tout produit acheté en armurerie est autorisé"], "a": "ABC", "e": "Les modèles administratifs n'ont pas de gaz propulseur inflammable. (Source : Instruction emploi des aérosols lacrymogènes)"}, {"t": 10, "s": "La personne visée semble tolérer le gaz lacrymogène. Le policier :", "o": ["recourt à un autre moyen de contrainte adapté", "augmente fortement la diffusion de gaz", "vide entièrement la bombe", "se rapproche à bout portant"], "a": "A", "e": "L'état psychologique ou la tolérance physiologique peut limiter les effets : il faut alors recourir à tout autre moyen de contrainte. (Source : Instruction emploi des aérosols lacrymogènes)"}, {"t": 11, "s": "En violences urbaines, pour échanger et partager les informations, le guide préconise :", "o": ["l'application TCHAP", "WhatsApp", "les SMS personnels", "les réseaux sociaux publics"], "a": "A", "e": "Le recours aux messageries instantanées comme WhatsApp est proscrit. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "Après des violences urbaines, un policier blessé est déclaré dans le TSBD (traitement de signalement des blessures graves et décès survenus au cours des missions de la police nationale) lorsque :", "o": ["une enquête judiciaire est ouverte et une ITT d'au moins 9 jours a été délivrée", "il a eu un simple arrêt de 1 jour", "il n'y a aucune enquête", "sa hiérarchie le décide sans condition"], "a": "A", "e": "Traitement de suivi des blessés de la police nationale : enquête ouverte + ITT (incapacité totale de travail) ≥ 9 jours. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "En prévention des violences urbaines, il est recommandé de faire retirer :", "o": ["les véhicules épaves et ventouses", "les conteneurs poubelles et le mobilier urbain", "les matériaux de chantier pouvant servir de projectiles", "les caméras de vidéoprotection"], "a": "ABC", "e": "Prévention situationnelle : supprimer ce qui peut servir de projectiles ou être incendié. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "Pour connaître le terrain avant des violences urbaines, il faut notamment :", "o": ["prendre connaissance de la monographie des quartiers sensibles réalisée par le SDRT", "identifier les points hauts, caves et sous-sols", "tenir à jour une liste de contacts utiles (bailleurs, transporteurs, police municipale…)", "attendre les premières violences pour repérer les lieux"], "a": "ABC", "e": "SDRT = service départemental du renseignement territorial. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "Une mesure de police prise pour prévenir des violences urbaines (interdiction des artifices, couvre-feu…) doit être :", "o": ["nécessaire, adaptée et proportionnée", "générale et absolue", "prise uniquement par le DGPN", "valable sans limite de durée ni de lieu"], "a": "A", "e": "Les mesures générales et absolues sont proscrites. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "En violences urbaines, les renforts sont sollicités :", "o": ["auprès de l'état-major départemental pour les renforts départementaux", "auprès de l'état-major zonal pour les renforts interdépartementaux", "directement auprès du RAID par le chef de patrouille", "auprès du maire pour les renforts interdépartementaux"], "a": "AB", "e": "Le RAID (Recherche, assistance, intervention, dissuasion) n'est engagé que sur décision du DGPN (directeur général de la police nationale). (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 11, "s": "Une intervention de police entraîne un décès ou une blessure grave dans un quartier. Il faut :", "o": ["le signaler au renseignement territorial, car c'est un fait potentiellement source de violences urbaines", "attendre de voir si des violences éclatent", "ne rien transmettre", "le signaler uniquement à la presse"], "a": "A", "e": "Le renseignement territorial (SDRT (service départemental du renseignement territorial) ou DRPP) est référent pour la détection des phénomènes de VU. (Source : Guide opérationnel des violences urbaines, PN 2025)"}, {"t": 13, "s": "Tuerie de masse : une personne sort de la zone d'exclusion. Les policiers :", "o": ["la dirigent si possible vers la zone contrôlée", "la considèrent comme un agresseur potentiel", "la contrôlent pour s'assurer qu'elle n'est pas armée", "la laissent partir sans contrôle car c'est une victime"], "a": "ABC", "e": "Puis recueillir les renseignements qu'elle peut fournir. (Source : PPI – Gestion tactique d'une tuerie de masse par des intervenants de 1er niveau)"}, {"t": 13, "s": "Tuerie de masse : quelles erreurs faut-il éviter ?", "o": ["précipiter l'intervention physique directe, au risque d'alimenter la tuerie", "se focaliser sur le secours aux victimes au point de mettre en péril le dispositif", "prendre en compte le risque de sur-attentat", "favoriser l'arrivée des renforts et des secours"], "a": "AB", "e": "Prendre en compte le sur-attentat et faciliter l'arrivée des renforts font partie de ce qu'il faut faire. (Source : PPI – Gestion tactique d'une tuerie de masse par des intervenants de 1er niveau)"}, {"t": 13, "s": "Tuerie de masse, progression : le « bond » :", "o": ["se fait sur une courte distance, à vitesse élevée, quand le cheminement à couvert est impossible", "s'effectue toujours sous la protection d'un soutien feu", "est annoncé au moins à son soutien feu", "se fait lentement, à découvert, sans prévenir personne"], "a": "ABC", "e": "« Pas un pas sans soutien ». (Source : PPI – Gestion tactique d'une tuerie de masse par des intervenants de 1er niveau)"}, {"t": 13, "s": "Le bouclier balistique souple (BBS) :", "o": ["sans plaques, protège comme un gilet pare-balles à port dissimulé (classe III A), ce qui est insuffisant", "avec plaques, atteint un niveau de protection de type IV", "pèse environ 20 kg avec les plaques", "offre une protection absolue contre toutes les munitions"], "a": "ABC", "e": "Certaines munitions perforantes traversent encore le niveau IV ; le BBS est toujours embarqué plaques montées. (Source : PPI – Gestion tactique d'une tuerie de masse par des intervenants de 1er niveau)"}, {"t": 13, "s": "Tuerie de masse : selon la fiche, la meilleure protection pendant la progression est :", "o": ["de ne pas être une cible, en cheminant hors de la vue des agresseurs", "le gilet pare-balles seul", "de courir à découvert le plus vite possible", "de rester groupés au contact, à découvert"], "a": "A", "e": "« Ne pas être une cible offrira toujours une protection plus importante qu'un gilet. » (Source : PPI – Gestion tactique d'une tuerie de masse par des intervenants de 1er niveau)"}, {"t": 13, "s": "Face à une personne porteuse d'un EEI (engin explosif improvisé) ou d'une arme d'épaule, la méthode d'intervention consiste à :", "o": ["détecter la menace et se protéger", "alerter/évacuer et rendre compte", "figer la situation par des injonctions, puis neutraliser le porteur pour éviter le déclenchement", "s'approcher pour arracher l'engin"], "a": "ABC", "e": "Détecter – se protéger – alerter/évacuer – rendre compte – figer – neutraliser. (Source : Fiche porteur d'EEI ou d'arme d'épaule)"}, {"t": 13, "s": "Les individus « kamikazes » transportent en moyenne :", "o": ["de 2 à 10 kg d'équivalent TNT, avec une fragmentation importante", "moins de 100 g d'explosif", "de 50 à 100 kg d'équivalent TNT", "aucun explosif"], "a": "A", "e": "Les membres de commandos, eux, portent 1 à 5 kg. (Source : Fiche porteur d'EEI ou d'arme d'épaule)"}, {"t": 13, "s": "Lors d'une perquisition au domicile, les policiers fouillent aussi :", "o": ["la cave et le garage", "le grenier et le cellier", "les véhicules garés dans la rue dont les clés ont été trouvées", "uniquement la pièce principale"], "a": "ABC", "e": "Même règles de sécurité partout ; un véhicule n'est pas un domicile, sauf aménagement lui donnant ce statut. (Source : TI FT n°42 – Perquisition)"}, {"t": 13, "s": "Objet découvert, mineurs présents : lors d'une perquisition, quelles règles sont exactes ?", "o": ["un objet découvert est représenté à la personne avant sa mise sous scellé", "des mineurs présents sont confiés à des majeurs désignés avec l'accord du parquet", "les deux témoins peuvent être des policiers", "l'objet est mis sous scellé sans être montré à la personne"], "a": "AB", "e": "Les témoins sont choisis parmi des personnes autres que les policiers. (Source : TI FT n°42 – Perquisition)"}, {"t": 13, "s": "Refus d'obtempérer : la circonstance aggravante (L. 233-1-1 C. route) est retenue lorsque le conducteur :", "o": ["expose directement autrui à un risque de mort ou de blessures pouvant entraîner une mutilation ou une infirmité permanente", "n'a pas son permis sur lui", "roule sans assurance", "refuse de présenter ses papiers à l'arrêt"], "a": "A", "e": "(Source : Instruction du 16/05/2025 – Refus d'obtempérer)"}, {"t": 13, "s": "Face à un véhicule qui refuse d'obtempérer, par principe, la poursuite :", "o": ["est engagée pour intercepter le véhicule et interpeller les auteurs", "est menée avec discernement", "est interdite", "n'est possible qu'avec l'accord du préfet"], "a": "AB", "e": "(Source : Instruction du 16/05/2025 – Refus d'obtempérer)"}, {"t": 13, "s": "Pendant une poursuite, le véhicule de police :", "o": ["garde une distance de sécurité en cas d'arrêt brutal du véhicule en fuite", "ne cherche pas à dépasser le véhicule poursuivi", "se colle au pare-chocs du fuyard", "double le fuyard pour lui barrer la route"], "a": "AB", "e": "(Source : Fiche mémo – Refus d’obtempérer et véhicules en fuite)"}, {"t": 13, "s": "À l'arrêt du véhicule en fuite, les policiers :", "o": ["descendent de manière concertée et coordonnée", "ne détachent la ceinture qu'après validation du chauffeur et/ou du chef de bord", "ne se placent jamais devant ou derrière le véhicule tant que le conducteur est au volant", "se placent devant le véhicule pour l'empêcher de repartir"], "a": "ABC", "e": "Devant et derrière : zones de danger. (Source : Fiche mémo – Refus d’obtempérer et véhicules en fuite)"}, {"t": 13, "s": "Concernant la pose d'un DIVA (dispositif d'interception des véhicules automobiles), quelles affirmations sont exactes ?", "o": ["il ne doit jamais être lancé depuis un véhicule de police", "il est déployé par des policiers en tenue ou porteurs d'insignes apparents", "il est placé si possible perpendiculairement à la trajectoire du véhicule", "le véhicule s'arrête toujours en moins de 10 mètres"], "a": "ABC", "e": "La distance d'arrêt est de plusieurs centaines de mètres. (Source : Instruction DGPN 2008 – DIVA)"}, {"t": 7, "s": "Les règles générales de sécurité (RGS) des armes imposent :", "o": ["de considérer toujours une arme comme étant chargée", "de garder l'index le long du pontet tant qu'il n'y a pas nécessité de tirer", "de diriger toujours le canon vers une zone de sécurité", "de garder le doigt sur la détente pour être prêt"], "a": "ABC", "e": "Elles sont affichées sur les lieux de stockage et de perception des armes. (Source : Fiche Pistolet automatique SP 2022 – Règles générales de sécurité)"}, {"t": 7, "s": "Lors de la mise en service du pistolet SP 2022, l'arme est approvisionnée avec un chargeur garni de :", "o": ["15 cartouches", "6 cartouches", "10 cartouches", "30 cartouches"], "a": "A", "e": "(Source : Fiche Pistolet automatique SP 2022 – Règles générales de sécurité)"}, {"t": 7, "s": "Mise en sécurité ou réintégration du pistolet SP 2022 : après le retrait du chargeur, le policier :", "o": ["retire la cartouche chambrée", "manœuvre la culasse à 2 reprises en vérifiant que la chambre est vide", "désarme le marteau avec le levier de désarmement", "garde le chargeur engagé"], "a": "ABC", "e": "Puis il met en place le témoin de chambre vide. (Source : Fiche Pistolet automatique SP 2022 – Règles générales de sécurité)"}, {"t": 7, "s": "Le pistolet SIG Sauer SP 2022 (9x19 mm) pèse, vide (sans chargeur) :", "o": ["de 800 à 830 g environ", "de 400 à 450 g environ", "de 1,4 à 1,5 kg environ", "de 2 à 2,2 kg environ"], "a": "A", "e": "Chargé, il pèse de 980 à 995 g environ. (Source : information donnée par Damien)"}, {"t": 7, "s": "Le pistolet SIG Sauer SP 2022 (9x19 mm) pèse, chargé :", "o": ["de 980 à 995 g environ", "de 600 à 650 g environ", "de 1,5 à 1,6 kg environ", "de 2 à 2,2 kg environ"], "a": "A", "e": "Vide, il pèse de 800 à 830 g environ. (Source : information donnée par Damien)"}, {"t": 15, "s": "Que signifie le sigle RC ?", "o": ["Repos compensateur", "Repos complémentaire", "Repos conventionnel", "Repos cumulé"], "a": "A", "e": "RC = Repos compensateur.\nPièges : « Repos complémentaire » est faux (« complémentaire » au lieu de « compensateur ») ; « Repos conventionnel » est faux (« conventionnel » au lieu de « compensateur ») ; « Repos cumulé » est faux (« cumulé » au lieu de « compensateur »).\nDans le cours : Repos accordé pour compenser un temps de travail particulier (nuit, dimanche, dépassement).\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle CET ?", "o": ["Compte épargne-temps", "Crédit épargne-temps", "Compte équivalence-temps", "Crédit équivalence-temps"], "a": "A", "e": "CET = Compte épargne-temps.\nPièges : « Crédit épargne-temps » est faux (« Crédit » au lieu de « Compte ») ; « Compte équivalence-temps » est faux (« équivalence-temps » au lieu de « épargne-temps ») ; « Crédit équivalence-temps » est faux (« Crédit » au lieu de « Compte », « équivalence-temps » au lieu de « épargne-temps »).\nDans le cours : Compte où l'agent épargne des jours de congés non pris pour les utiliser, se les faire indemniser ou les verser à la RAFP.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle RL ?", "o": ["Repos légal", "Repos libre", "Repos lié", "Repos local"], "a": "A", "e": "RL = Repos légal.\nPièges : « Repos libre » est faux (« libre » au lieu de « légal ») ; « Repos lié » est faux (« lié » au lieu de « légal ») ; « Repos local » est faux (« local » au lieu de « légal »).\nDans le cours : Repos hebdomadaire réglementaire auquel l'agent a droit.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle CA ?", "o": ["Congés annuels", "Congés administratifs", "Congés d'activité", "Congés d'ancienneté"], "a": "A", "e": "CA = Congés annuels.\nPièges : « Congés administratifs » est faux (« administratifs » au lieu de « annuels ») ; « Congés d'activité » est faux (« d'activité » au lieu de « annuels ») ; « Congés d'ancienneté » est faux (« d'ancienneté » au lieu de « annuels »).\nDans le cours : Congés annuels égaux à cinq fois les obligations hebdomadaires de service, soit 25 jours.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle ARTT ?", "o": ["Aménagement de la réduction du temps de travail", "Aménagement et répartition du temps de travail", "Ajustement de la réduction du temps de travail", "Ajustement et répartition du temps de travail"], "a": "A", "e": "ARTT = Aménagement de la réduction du temps de travail.\nPièges : « Aménagement et répartition du temps de travail » est faux (« et répartition » au lieu de « de la réduction ») ; « Ajustement de la réduction du temps de travail » est faux (« Ajustement » au lieu de « Aménagement ») ; « Ajustement et répartition du temps de travail » est faux (« et répartition » au lieu de « de la réduction », « Ajustement » au lieu de « Aménagement »).\nDans le cours : Jours de repos accordés en contrepartie d'un temps de travail supérieur à la durée légale ; ils sont réduits en cas de certaines absences.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle DGPN ?", "o": ["Direction générale de la police nationale", "Délégation générale de la police nationale", "Direction de la gestion de la police nationale", "Délégation de la gestion de la police nationale"], "a": "A", "e": "DGPN = Direction générale de la police nationale.\nPièges : « Délégation générale de la police nationale » est faux (« Délégation » au lieu de « Direction ») ; « Direction de la gestion de la police nationale » est faux (« de la gestion » au lieu de « générale ») ; « Délégation de la gestion de la police nationale » est faux (« Délégation » au lieu de « Direction », « de la gestion » au lieu de « générale »).\nDans le cours : Direction qui dirige la police nationale et fixe les instructions d'emploi des armes et du temps de travail.\nSource : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 15, "s": "Que signifie le sigle ASA ?", "o": ["Autorisation spéciale d'absence", "Autorisation statutaire d'absence", "Attestation spéciale d'absence", "Attestation statutaire d'absence"], "a": "A", "e": "ASA = Autorisation spéciale d'absence.\nPièges : « Autorisation statutaire d'absence » est faux (« statutaire » au lieu de « spéciale ») ; « Attestation spéciale d'absence » est faux (« Attestation » au lieu de « Autorisation ») ; « Attestation statutaire d'absence » est faux (« statutaire » au lieu de « spéciale », « Attestation » au lieu de « Autorisation »).\nDans le cours : Absences autorisées sans décompte de congés (événements familiaux, garde d'enfant malade, mandats…).\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle APORTT ?", "o": ["Arrêté portant organisation relative au temps de travail", "Arrêté portant organisation réglementaire du temps de travail", "Arrêté portant organisation relative au temps de service", "Arrêté portant organisation réglementaire du temps de service"], "a": "A", "e": "APORTT = Arrêté portant organisation relative au temps de travail.\nPièges : « Arrêté portant organisation réglementaire du temps de travail » est faux (« réglementaire du » au lieu de « relative au ») ; « Arrêté portant organisation relative au temps de service » est faux (« service » au lieu de « travail ») ; « Arrêté portant organisation réglementaire du temps de service » est faux (« réglementaire du » au lieu de « relative au », « service » au lieu de « travail »).\nDans le cours : Texte de référence qui organise le temps de travail dans la police nationale (durées, cycles, repos, services supplémentaires).\nSource : Présentation de l'Arrêté portant organisation relative au temps de travail (APORTT) (diaporama)"}, {"t": 15, "s": "Que signifie le sigle RGEPN ?", "o": ["Règlement général d'emploi de la police nationale", "Règlement général d'éthique de la police nationale", "Régime général d'emploi de la police nationale", "Régime général d'éthique de la police nationale"], "a": "A", "e": "RGEPN = Règlement général d'emploi de la police nationale.\nPièges : « Règlement général d'éthique de la police nationale » est faux (« d'éthique » au lieu de « d'emploi ») ; « Régime général d'emploi de la police nationale » est faux (« Régime » au lieu de « Règlement ») ; « Régime général d'éthique de la police nationale » est faux (« d'éthique » au lieu de « d'emploi », « Régime » au lieu de « Règlement »).\nDans le cours : Règlement qui fixe les règles d'emploi des policiers, dont de nombreuses règles de temps de travail et de congés.\nSource : Instruction DGPN (Direction générale de la police nationale) n°3/2024 – Instruction générale relative à l'arme individuelle ou de service"}, {"t": 15, "s": "Que signifie le sigle RPS ?", "o": ["Repos de pénibilité spécifique", "Repos de pénibilité supplémentaire", "Récupération de pénibilité spécifique", "Récupération de pénibilité supplémentaire"], "a": "A", "e": "RPS = Repos de pénibilité spécifique.\nPièges : « Repos de pénibilité supplémentaire » est faux (« supplémentaire » au lieu de « spécifique ») ; « Récupération de pénibilité spécifique » est faux (« Récupération » au lieu de « Repos ») ; « Récupération de pénibilité supplémentaire » est faux (« supplémentaire » au lieu de « spécifique », « Récupération » au lieu de « Repos »).\nDans le cours : Repos attribués pour compenser la pénibilité de certaines vacations (nuit, régimes particuliers).\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle PIE ?", "o": ["Pistolet à impulsions électriques", "Pistolet à impulsions électroniques", "Projecteur à impulsions électriques", "Projecteur à impulsions électroniques"], "a": "A", "e": "PIE = Pistolet à impulsions électriques.\nPièges : « Pistolet à impulsions électroniques » est faux (« électroniques » au lieu de « électriques ») ; « Projecteur à impulsions électriques » est faux (« Projecteur » au lieu de « Pistolet ») ; « Projecteur à impulsions électroniques » est faux (« électroniques » au lieu de « électriques », « Projecteur » au lieu de « Pistolet »).\nDans le cours : AFI à impulsions électriques (type Taser) employée en mode tir ou contact.\nSource : Instruction DGPN (Direction générale de la police nationale)/DGGN (Direction générale de la gendarmerie nationale) du 2/08/2017 – usage et emploi des AFI (armes de force intermédiaire)"}, {"t": 15, "s": "Que signifie le sigle DIVA ?", "o": ["Dispositifs d'interception de véhicules", "Dispositifs d'immobilisation de véhicules", "Dispositifs d'interpellation de véhicules", "Dispositifs d'identification de véhicules"], "a": "A", "e": "DIVA = Dispositifs d'interception de véhicules.\nPièges : « Dispositifs d'immobilisation de véhicules » est faux (« d'immobilisation » au lieu de « d'interception ») ; « Dispositifs d'interpellation de véhicules » est faux (« d'interpellation » au lieu de « d'interception ») ; « Dispositifs d'identification de véhicules » est faux (« d'identification » au lieu de « d'interception »).\nDans le cours : Matériels (herses, etc.) servant à stopper un véhicule, notamment en cas de refus d'obtempérer.\nSource : Instruction DGPN (Direction générale de la police nationale) 2008 – dispositifs d'interception de véhicules (DIVA)"}, {"t": 15, "s": "Que signifie le sigle LBD ?", "o": ["Lanceur de balles de défense", "Lanceur de balles de dispersion", "Lanceur balistique de défense", "Lanceur balistique de dispersion"], "a": "A", "e": "LBD = Lanceur de balles de défense.\nPièges : « Lanceur de balles de dispersion » est faux (« dispersion » au lieu de « défense ») ; « Lanceur balistique de défense » est faux (« balistique » au lieu de « de balles ») ; « Lanceur balistique de dispersion » est faux (« dispersion » au lieu de « défense », « balistique » au lieu de « de balles »).\nDans le cours : AFI de calibre 40 tirant des munitions de défense, dont l'emploi obéit à des règles strictes de distance et de zones visées.\nSource : Instruction DGPN (Direction générale de la police nationale)/DGGN (Direction générale de la gendarmerie nationale) du 2/08/2017 – usage et emploi des AFI (armes de force intermédiaire)"}, {"t": 15, "s": "Que signifie le sigle TSUA ?", "o": ["Traitement relatif au suivi de l'usage des armes", "Traitement relatif au signalement de l'usage des armes", "Traitement relatif au suivi de l'usage des armements", "Traitement relatif au signalement de l'usage des armements"], "a": "A", "e": "TSUA = Traitement relatif au suivi de l'usage des armes.\nPièges : « Traitement relatif au signalement de l'usage des armes » est faux (« signalement » au lieu de « suivi ») ; « Traitement relatif au suivi de l'usage des armements » est faux (« armements » au lieu de « armes ») ; « Traitement relatif au signalement de l'usage des armements » est faux (« signalement » au lieu de « suivi », « armements » au lieu de « armes »).\nDans le cours : Traitement informatique où est déclaré chaque usage d'une arme (arme à feu ou AFI) par un policier.\nSource : Instruction DGPN (Direction générale de la police nationale) n°3/2024 – Instruction générale relative à l'arme individuelle ou de service"}, {"t": 15, "s": "Que signifie le sigle PATS ?", "o": ["Personnels administratifs, techniques et scientifiques", "Personnels administratifs, techniques et spécialisés", "Personnels d'appui techniques et scientifiques", "Personnels d'appui techniques et spécialisés"], "a": "A", "e": "PATS = Personnels administratifs, techniques et scientifiques.\nPièges : « Personnels administratifs, techniques et spécialisés » est faux (« spécialisés » au lieu de « scientifiques ») ; « Personnels d'appui techniques et scientifiques » est faux (« d'appui » au lieu de « administratifs, ») ; « Personnels d'appui techniques et spécialisés » est faux (« spécialisés » au lieu de « scientifiques », « d'appui » au lieu de « administratifs, »).\nDans le cours : Personnels non actifs de la police, soumis à des règles de temps de travail propres.\nSource : Guide des principales règles de gestion du temps de travail (ARTT, CET (compte épargne-temps)…)"}, {"t": 15, "s": "Que signifie le sigle RTT ?", "o": ["Réduction du temps de travail", "Répartition du temps de travail", "Récupération du temps de travail", "Régime du temps de travail"], "a": "A", "e": "RTT = Réduction du temps de travail.\nPièges : « Répartition du temps de travail » est faux (« Répartition » au lieu de « Réduction ») ; « Récupération du temps de travail » est faux (« Récupération » au lieu de « Réduction ») ; « Régime du temps de travail » est faux (« Régime » au lieu de « Réduction »).\nDans le cours : Principe de réduction de la durée du travail qui fonde les droits ARTT.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle SGAMI ?", "o": ["Secrétariat général pour l'administration du ministère de l'intérieur", "Secrétariat général pour la gestion du ministère de l'intérieur", "Secrétariat général pour l'administration du ministère des territoires", "Secrétariat général pour la gestion du ministère des territoires"], "a": "A", "e": "SGAMI = Secrétariat général pour l'administration du ministère de l'intérieur.\nPièges : « Secrétariat général pour la gestion du ministère de l'intérieur » est faux (« la gestion » au lieu de « l'administration ») ; « Secrétariat général pour l'administration du ministère des territoires » est faux (« des territoires » au lieu de « de l'intérieur ») ; « Secrétariat général pour la gestion du ministère des territoires » est faux (« la gestion » au lieu de « l'administration », « des territoires » au lieu de « de l'intérieur »).\nDans le cours : Service gestionnaire (ressources humaines, logistique) des policiers au niveau zonal.\nSource : Instruction DGPN (Direction générale de la police nationale) n°3/2024 – Instruction générale relative à l'arme individuelle ou de service"}, {"t": 15, "s": "Que signifie le sigle RCSS ?", "o": ["Repos compensateurs pour services supplémentaires", "Récupérations compensatrices pour services supplémentaires", "Repos compensateurs pour services spéciaux", "Récupérations compensatrices pour services spéciaux"], "a": "A", "e": "RCSS = Repos compensateurs pour services supplémentaires.\nPièges : « Récupérations compensatrices pour services supplémentaires » est faux (« Récupérations compensatrices » au lieu de « Repos compensateurs ») ; « Repos compensateurs pour services spéciaux » est faux (« spéciaux » au lieu de « supplémentaires ») ; « Récupérations compensatrices pour services spéciaux » est faux (« Récupérations compensatrices » au lieu de « Repos compensateurs », « spéciaux » au lieu de « supplémentaires »).\nDans le cours : Repos accordés en compensation des services supplémentaires effectués.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle CEA ?", "o": ["Corps d'encadrement et d'application", "Corps d'encadrement et d'administration", "Corps d'exécution et d'application", "Corps d'exécution et d'administration"], "a": "A", "e": "CEA = Corps d'encadrement et d'application.\nPièges : « Corps d'encadrement et d'administration » est faux (« d'administration » au lieu de « d'application ») ; « Corps d'exécution et d'application » est faux (« d'exécution » au lieu de « d'encadrement ») ; « Corps d'exécution et d'administration » est faux (« d'administration » au lieu de « d'application », « d'exécution » au lieu de « d'encadrement »).\nDans le cours : Corps des gardiens de la paix, brigadiers et brigadiers-chefs.\nSource : Circulaire DGPN (Direction générale de la police nationale) du 26/01/2022 – plan prévisionnel annuel des départs en congés"}, {"t": 15, "s": "Que signifie le sigle AFI ?", "o": ["Armes de force intermédiaire", "Armes de frappe intermédiaire", "Armes de force individuelle", "Armes de frappe individuelle"], "a": "A", "e": "AFI = Armes de force intermédiaire.\nPièges : « Armes de frappe intermédiaire » est faux (« frappe » au lieu de « force ») ; « Armes de force individuelle » est faux (« individuelle » au lieu de « intermédiaire ») ; « Armes de frappe individuelle » est faux (« frappe » au lieu de « force », « individuelle » au lieu de « intermédiaire »).\nDans le cours : Famille d'armes (LBD, GMD, PIE, GAIL…) placées entre la force physique et l'arme à feu.\nSource : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 15, "s": "Que signifie le sigle GMD ?", "o": ["Grenade à main de désencerclement", "Grenade à main de dispersion", "Grenade modulaire de désencerclement", "Grenade modulaire de dispersion"], "a": "A", "e": "GMD = Grenade à main de désencerclement.\nPièges : « Grenade à main de dispersion » est faux (« dispersion » au lieu de « désencerclement ») ; « Grenade modulaire de désencerclement » est faux (« modulaire » au lieu de « à main ») ; « Grenade modulaire de dispersion » est faux (« dispersion » au lieu de « désencerclement », « modulaire » au lieu de « à main »).\nDans le cours : Grenade lancée à la main pour se dégager d'un encerclement ou d'un groupe menaçant.\nSource : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 15, "s": "Que signifie le sigle CSI ?", "o": ["Code de la sécurité intérieure", "Code de la sûreté intérieure", "Code de la sécurité individuelle", "Code de la sûreté individuelle"], "a": "A", "e": "CSI = Code de la sécurité intérieure.\nPièges : « Code de la sûreté intérieure » est faux (« sûreté » au lieu de « sécurité ») ; « Code de la sécurité individuelle » est faux (« individuelle » au lieu de « intérieure ») ; « Code de la sûreté individuelle » est faux (« sûreté » au lieu de « sécurité », « individuelle » au lieu de « intérieure »).\nDans le cours : Code qui fixe notamment le cadre légal de l'usage des armes et des sommations.\nSource : Instruction DGPN (Direction générale de la police nationale) n°3/2024 – Instruction générale relative à l'arme individuelle ou de service"}, {"t": 15, "s": "Que signifie le sigle CIC ?", "o": ["Centre d'information et de commandement", "Centre d'intervention et de commandement", "Centre d'information et de coordination", "Centre d'intervention et de coordination"], "a": "A", "e": "CIC = Centre d'information et de commandement.\nPièges : « Centre d'intervention et de commandement » est faux (« d'intervention » au lieu de « d'information ») ; « Centre d'information et de coordination » est faux (« coordination » au lieu de « commandement ») ; « Centre d'intervention et de coordination » est faux (« d'intervention » au lieu de « d'information », « coordination » au lieu de « commandement »).\nDans le cours : Salle qui centralise les appels et coordonne l'engagement des effectifs.\nSource : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 15, "s": "Que signifie le sigle DSO ?", "o": ["Directeur du service d'ordre", "Directeur du secteur opérationnel", "Délégué du service d'ordre", "Délégué du secteur opérationnel"], "a": "A", "e": "DSO = Directeur du service d'ordre.\nPièges : « Directeur du secteur opérationnel » est faux (« secteur opérationnel » au lieu de « service d'ordre ») ; « Délégué du service d'ordre » est faux (« Délégué » au lieu de « Directeur ») ; « Délégué du secteur opérationnel » est faux (« secteur opérationnel » au lieu de « service d'ordre », « Délégué » au lieu de « Directeur »).\nDans le cours : Autorité qui dirige le service d'ordre lors d'une opération de maintien de l'ordre.\nSource : Schéma national du maintien de l'ordre (déc. 2021)"}, {"t": 15, "s": "Que signifie le sigle GM2L ?", "o": ["Grenade modulaire 2 effets lacrymogène", "Grenade à main 2 effets lacrymogène", "Grenade modulaire 2 effets lumineux", "Grenade à main 2 effets lumineux"], "a": "A", "e": "GM2L = Grenade modulaire 2 effets lacrymogène.\nPièges : « Grenade à main 2 effets lacrymogène » est faux (« à main » au lieu de « modulaire ») ; « Grenade modulaire 2 effets lumineux » est faux (« lumineux » au lieu de « lacrymogène ») ; « Grenade à main 2 effets lumineux » est faux (« à main » au lieu de « modulaire », « lumineux » au lieu de « lacrymogène »).\nDans le cours : Grenade de maintien de l'ordre, assourdissante et lacrymogène, qui remplace la GLI-F4 depuis 2018.\nSource : précision de Damien ; Wikipédia « Grenade GM2L » (fr.wikipedia.org/wiki/Grenade_GM2L), BFMTV et franceinfo"}, {"t": 15, "s": "Que signifie le sigle DRCPN ?", "o": ["Direction des ressources et des compétences de la police nationale", "Direction du recrutement et des compétences de la police nationale", "Direction des ressources et de la carrière de la police nationale", "Direction du recrutement et de la carrière de la police nationale"], "a": "A", "e": "DRCPN = Direction des ressources et des compétences de la police nationale.\nPièges : « Direction du recrutement et des compétences de la police nationale » est faux (« du recrutement » au lieu de « des ressources ») ; « Direction des ressources et de la carrière de la police nationale » est faux (« de la carrière » au lieu de « des compétences ») ; « Direction du recrutement et de la carrière de la police nationale » est faux (« du recrutement » au lieu de « des ressources », « de la carrière » au lieu de « des compétences »).\nDans le cours : Direction des ressources humaines et de la formation de la police nationale.\nSource : Instruction (mars 2016) – emploi du fusil d'assaut HK (Heckler & Koch) G36 5,56 mm"}, {"t": 15, "s": "Que signifie le sigle RAFP ?", "o": ["Régime de retraite additionnelle de la fonction publique", "Régime de retraite auxiliaire de la fonction publique", "Régime de prévoyance additionnelle de la fonction publique", "Régime de prévoyance auxiliaire de la fonction publique"], "a": "A", "e": "RAFP = Régime de retraite additionnelle de la fonction publique.\nPièges : « Régime de retraite auxiliaire de la fonction publique » est faux (« auxiliaire » au lieu de « additionnelle ») ; « Régime de prévoyance additionnelle de la fonction publique » est faux (« prévoyance » au lieu de « retraite ») ; « Régime de prévoyance auxiliaire de la fonction publique » est faux (« auxiliaire » au lieu de « additionnelle », « prévoyance » au lieu de « retraite »).\nDans le cours : Régime de retraite où peuvent être versés des jours du CET (agents titulaires).\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle PP ?", "o": ["Préfecture de police", "Préfecture de Paris", "Préfecture de proximité", "Préfecture de zone"], "a": "A", "e": "PP = Préfecture de police.\nPièges : « Préfecture de Paris » est faux (« Paris » au lieu de « police ») ; « Préfecture de proximité » est faux (« proximité » au lieu de « police ») ; « Préfecture de zone » est faux (« zone » au lieu de « police »).\nDans le cours : Structure qui exerce les missions de police à Paris et en petite couronne.\nSource : Guide opérationnel des violences urbaines (PN, sept. 2025)"}, {"t": 15, "s": "Que signifie le sigle CF ?", "o": ["Crédit férié", "Congé férié", "Crédit forfaitaire", "Congé forfaitaire"], "a": "A", "e": "CF = Crédit férié.\nPièges : « Congé férié » est faux (« Congé » au lieu de « Crédit ») ; « Crédit forfaitaire » est faux (« forfaitaire » au lieu de « férié ») ; « Congé forfaitaire » est faux (« Congé » au lieu de « Crédit », « forfaitaire » au lieu de « férié »).\nDans le cours : Crédit d'heures ou de jours accordé en compensation des jours fériés en régime cyclique.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}, {"t": 15, "s": "Que signifie le sigle PACS ?", "o": ["Pacte civil de solidarité", "Pacte commun de solidarité", "Pacte civil de soutien", "Pacte commun de soutien"], "a": "A", "e": "PACS = Pacte civil de solidarité.\nPièges : « Pacte commun de solidarité » est faux (« commun » au lieu de « civil ») ; « Pacte civil de soutien » est faux (« soutien » au lieu de « solidarité ») ; « Pacte commun de soutien » est faux (« commun » au lieu de « civil », « soutien » au lieu de « solidarité »).\nDans le cours : Événement familial qui ouvre droit à une ASA.\nSource : DocPro (Documentation professionnelle) Examen professionnel Brigadier-chef 2026 – La gestion du temps de travail dans les services de la PN (police nationale) (avril 2026)"}]};